local addon = WoWKoreanClient
if not addon.active then return end
local text = addon.worldText.greeting
if not text then
    text = { values = {}, templates = {} }
    addon.worldText.greeting = text
end
local rows = text.values
rows["311:150572322"]="나는 그 질문에 답할 권리가 없다. 하지만, 조언해줄 수는 있지.$b$b브란 브론즈비어드를 찾아보아라.$b$b그는 이미 우리에 대해 많은 걸 알고 있을뿐더러 새로운 발견을 눈앞에 두고 있지. 브란 브론즈비어드를 돕는다면 분명 네가 원하는 지식을 구하는 데 도움이 될 것이다."
rows["311:1861893764"]="몸을 뒤집어보니 칼날과 마법에 의해 공격당한 상처가 선명하게 남아 있습니다. 방어구는 거의 다 산산조각났고 머리카락은 산발이 되어 있습니다.$B$B만크릭에게 들은 이야기를 떠올려 보니, 이 오크가 그의 아내인 것이 분명합니다.$B$B이 소식을 전해주면 애통해 하고, 분개할 것이 분명하지만, 그에게 진실을 알려주어야 한다는 생각이 듭니다."
rows["311:2003118148"]="아제로스 최고의 쇼에 오신 것을 환영합니다!$B$B어서 오셔서 마음껏 즐기세요. 다크문 유랑단이 이 드넓고 신비한 세계를 유랑하며 발견한 온갖 놀라운 물건들을 구경하시라니까요! 다양한 연령층의 어린이들이 모두 좋아할 만한 것들을 아낌없이 준비해 놓았답니다!"
rows["311:840110861"]="불타는 군단. 잔인한 악마들. 나는 그대 얼굴 앞에 들이민 손이 보이는 만큼 그들의 모습이 확실하게 보인다네. 그러니까 그들을 정확하게 볼 수 있었다는 말이지.$B$B불타는 군단이 돌아오면서 새로운 음모가 시작되었네. 정상적인 환경이라면 난 먼 곳에서도 악마의 존재를 느낄 수가 있지.$B$B<얼굴을 찡그리는 알트루이스>"
rows["312:1301510245"]="레아비즈는 코도처럼 예민하지! 웃기는 건 그가 자신이 그렇게 뻔뻔하지 않다고 믿는다는 사실이오. 주위에 보는 눈이 없다고 생각될 때 그가 나를 보는 눈길을 알고 있소.$B$B정말 소름이 끼치지. 어둠사냥꾼 덴자이가 우리를 함께 보내지 않았으면 좋겠소. 늪쥐 감시초소를 건설하는 일은 그와 떨어질 완벽한 기회였소."
rows["312:137040103"]="편히 앉게나. 얘기가 좀 길다네.$B$B우리가 실리더스에 처음 도착했을 때 여군주 마랄리스는 세나리온 요새의 나이트 엘프 중 가장 먼저 원정대에 참가했지. 우리는 지극히 평범한 일부터 진행했다네. 사라진 유물을 찾기 위해 곤충 집을 헤집을 조사단을 구성했지."
rows["312:341732747"]="벨그롬이 이 어리석은 동맹을 유지할 수 있도록 도와달라며 오그리마에 있는 우리를 이곳으로 보냈소. 하지만 그의 도박이 성공한다면 모든 호드에게 득이 될 거요.$B$B여자들을 즐겁게 해주려는 그의 욕심 때문에 이미 많은 오크들이 죽었지만, 그는 여전히 우리의 지휘관이고, 우린 명예 때문에 주어진 상황에서 최선을 다하는 수밖에 없는 거요."
rows["313:1362744087"]="오그리마를 파괴한 행위는 그냥 오크를 공격한 것이 아니라 호드 전체를 모욕한 거나 다름없네. 호드라는 존재 자체를 위협하는 공격이지!$B$B리치 왕은 공포가 싹트도록 씨앗을 심으려 했네.$B$B이 요새...$B$B<주변에 있는 요새의 벽을 가리키는 가로쉬>$B$B아서스가 벌인 전쟁 때문에 이런 요새까지 만들었네.$B$B호드는 아무것도 두려워하지 않네..."
rows["313:1971384357"]="수년 전 내 부하들과 나는 마법사 카드가와 성기사 투랄리온을 따라 이 세계로 왔다네. 우리의 유일한 목적은 오크들과 그들의 사악한 일족을 멸종시키는 것이었지. 하지만 마지막 전투의 순간에 뭔가가 단단히 잘못되었다네.$B$B결국 이 어둠의 세계는 산산이 찢기고 내 동료는 공허 속으로 사라졌지."
rows["313:747402485"]="이방인이여, 우리가 누군지 아십니까? 우리는 마그하르입니다. 당신들은 우리를 갈색 오크라고 부른다는 얘기를 들었습니다. 우리 마그하르는 생존자들입니다. 망한 왕국의 생존자, 붉은 천연두의 생존자, 파괴된 세계의 생존자...$B$B저는 킬로그의 아들 요린입니다. 피눈물 부족의 대족장인 데드아이 가문의 마지막 혈통입니다."
rows["313:899598950"]="무법항에 온 것을 환영하네, 친구. 드메자와 선원들은 너무 신경 쓰지 말게... 일 년에 한 번 있는 해적의 날만큼은 저 무법자들 마음대로 하게 놔둘 걸세. 그래야 우릴 귀찮게 하지 않고 남쪽 바다에서 노략질이나 하지 않겠나.$B$B그건 그렇고... 스팀휘들 무역회사의 충복인 이 몸께서 뭘 도와주면 되겠나? 아, 이렇게 말하는 게 더 낫겠군. 날 위해 자네는 뭘 해 줄 수 있나?"
rows["314:1412221054"]="우리는 모두가 가을 축제를 즐기기를 바랍니다. 몇 명이라도 가을 축제를 기억해준다면 힘이 될 거예요.$b$b이 고글을 쓰면 누구나 취한 것 같은 기분을 느낄 수 있습니다. 아무것도 안 마셔도요. 고글을 쓰기만 하면, 취한 거나 마찬가집니다! 벗으면 다시 말짱해지는 거고요!$b$b어때요, 갖고 싶지 않습니까?"
rows["314:2024476197"]="썬더콜러에 오신 것을 환영합니다!$b$b폭발이나 그 같은 것에 대해 불평하는 사람들에게 관심을 기울이지 마세요.$b$b보아라, 만약 선장이 배를 추락시키면 이해가 되겠지 22 또는 23 하지만 그보다 더 적은 것은 언급할 가치가 없습니다."
rows["314:672045136"]="제어장치에 다가가자 당신이 지니고 있는 장치 접근 수정이 부드럽게 진동하더니 빛과 함께 공명하기 시작합니다.$B$B수많은 정보의 물결이 머릿속으로 흘러들어오고 갑자기 마나괴철로의 에너지 생산 수치, 안정성, 다른 수송관으로의 출력 등을 알게 됩니다. 지금 당신 눈앞에 있는 제어장치가 명령을 기다리고 있습니다."
rows["314:878800463"]="엘룬의 은총으로 그대에게 텔드랏실 최고의 탈것인 밤호랑이를 보여 드리게 된 것을 진심으로 기쁘게 생각합니다. 오랫동안 파수대는 이 밤호랑이 친구를 믿고 의지해 왔습니다.$B$B맘에 드는 게 있는지 천천히 살펴보십시오. 결코 실망하시는 일은 없을 겁니다."
rows["315:1059723318"]="그 이후 우리 로서의 후예들은 이곳에 남아 싸우다 죽어 갔으며... 오늘 같은 날이 오게 해 달라고 기도했다네. 차원문이 열리고 우리 형제들이 우리를 고향으로 데려다 줄 그런 날을 말이지.$B$B정말 뛸 듯이 기쁘네만 아직 임무가 끝나지 않았다네. 이 세계를 떠나서 휴식을 취하기 전에 해야 할 일이 많네."
rows["315:1648205200"]="당신이 원하는 것은  ⁇ 은 혐오스러운  ⁇ 이라면 스트라톨메에 당신은  ⁇ 을  ⁇ 을 것입니다.$B$B전은 라이트브라이저의 고향이었는데 지금은 켈'투자드의 하자가 몰려들었다$B$B불타는 도시의 위험함을 용기있게 해내라, 고기를 먹는 혐오스러운 것들을 쳐내라. 그들의 보상을 받아라."
rows["315:294918655"]="<크게 소리 내어 웃는 란트레서>$B$B네가 지금 어디에 있는지 알고나 하는 소리냐? 이곳은 오우거의 땅이다. 오크와 드레나이가 있기 전부터 오우거들이 있었다. 그래, 너희의 요구를 들어주지 못하겠다면, 너희가 질 게 뻔한 전쟁을 시작하겠다는 뜻이냐? 돌주먹 일족은 너희를 부술 것이다. 돌주먹 일족이 너희를 없애버리지 못한다고 해도 전쟁망치 일족이 그렇게 할 것이야...$B$B너희 지도자도 이미 알고 있을 텐데..."
rows["315:445740641"]="내가 들었을 때 서부 몰락지대에 도착했습니다. 어쩌면 내가 유용하게 사용할 수 있다고 생각했습니다. 어둠 속에서 약간의 빛을 제공 할 수 있습니다. 하지만 이 땅은... 희망을 삼키고 있습니다. 내가 돌보는 모든 상처, 더 열려 있습니다. 모든 기도는 텅 비어있는 느낌. 어쩌면 나는 바보였습니다. 어쩌면 나는 그냥 스톰윈드에 돌아 가야합니다. 내 침대는 여전히 따뜻합니다. 내 양심... 조용합니다."
rows["315:803575095"]="우리가 아제로스에서 호드를 몰아낼 당시 나는 안두인 로서 경과 함께 싸웠소. 나는 메디브께서 남긴 유산의 계승자로서 거칠 것이 없었소.$B$B마침내 이 끔찍한 세계를 정벌하고 사악한 오크들에게 종말을 고하라는 명령이 내려왔을 때 나는 동료인 투랄리온, 알레리아, 다나스, 쿠르드란과 함께 전진했소."
rows["316:147226513"]="그래, 그대가 찾는 주술사를 본 적 있어. 마지막으로 목격한 게 아마 서쪽에서였지. 보통 서슬갈기 일족의 본거지가 내려다보이는 언덕에 숨어서 지낸다네. 머리를 좀 쓰면 포악한 가시멧돼지 무리와 맞닥뜨리지 않고도, 언덕 위 그녀의 집으로 가는 길을 찾을 수 있을 걸세. 여기서 북쪽으로 그리 멀지 않은 곳에 있으니까."
rows["316:1581254936"]="안녕하십니까, 이방인 친구. 야생이 살아 숨 쉬는 운고로 분화구에 온 것을 환영합니다! 저는 윌리덴 마샬이라고 합니다. 저와 제 여동생, 그리고 동료는 마샬 원정대를 구성하고 있습니다. 우리는 위대한 아제로스의 야생과 미지의 세계를 탐험하는 과학자와 탐험가들이죠."
rows["316:1747506513"]="발가드에 병력을 그렇게 많이 남겨 두는 게 아니었어. 켈러 부제독은 밉살스러운 이기주의자야!$B$B이 적은 병력으로 어떻게 명령을 수행하겠나? 여기는 물론 빌더바르 요새가 준비되면 거기도 지킬 수 있을 만큼 많은 인원이 필요하단 말일세!$B$B그나마 자네가 와 줘서 문제를 해결할 희망이 보이는군."
rows["316:2032266730"]="그대는 제정신이 아닌데다가 눈까지 멀었구려...$B$B나는 오래전에 어떤 땅에 도착하여 그곳을 지키는 데 실패했소. 그래서 한 문명이 사라졌고 그 기억을 죽어서도 지니고 있는 비참한 유령이라오.$B$B천 년 전에는 그대처럼 살과 뼈로 이루어진 존재였다오. 나는 이 땅의 왕자이자 용기수로서 꿈의 여왕 이세라의 축복을 받은 자요."
rows["317:1294108181"]="이거야말로 세계 최고이자 최신식 운송 수단이라고 할 수 있죠. 뭐? 노움이 만든 깊은굴 지하철이라고요? 이봐요, 잘 들으세요. 그따위 쓰레기를 믿느니, 차라리 가시덤불 골짜기에 날 기리는 동상을 세웠다는 말을 믿으시죠. 자, 그롬골까지 걸어서 가시겠습니까? 아니면 저희 최신식 비행선을 타고 가시겠습니까? 선택은 당신에게 달렸습니다."
rows["317:1338249239"]="잘하셨습니다, 모험가여. 격노한 윈터칠이 죽었으니 적들은 잠시 동안 진군을 멈출 수밖에 없습니다. 이 짧은 시간을 현명하게 사용하도록 하세요. 조만간 아키몬드가 훨씬 더 강력한 군대를 보낼 테니 상처를 치료하고 방어 태세를 점검해야 합니다. 내 빈약한 예비 군대가 전투가 다시 재개되면 그대를 지원할 것입니다."
rows["318:1071474679"]="마을 전체에서 비밀리에 투표가 붙여져 이름을 바꾸기 전까지 저는 이올롤이라고 알려졌던 사람이었습니다. 그 투표 결과는 이름을 바꾸던가 코르키와 같은 길을 가던가 하라는 거였지요. 당신도 이름을 바꾸는 쪽을 선택했을 것입니다. 새로 바꾼 제 이름 어떻습니까? 엄청나게 좋아졌다 생각 안하십니까?$B$B어쨌거나, 일거리를 찾고 있다면 게시판을 확인해보십시오."
rows["318:144949701"]="남쪽의 덩굴손은 개구리나 앵무새처럼 작은 생물을 먹는다. 우리 고릴라는 덩굴손을 먹는다. 그리고 공룡은 고릴라를 먹는다. 이 모든 게 고결하고 자연스러운 자연의 섭리다.$b$b하지만 인간과 오크는 고릴라를 사냥하고 가죽만 챙기고는 몸은 썩게 버려둔다. 그것이 우리가 인간과 오크를 공격하는 이유다."
rows["318:1525204201"]="렌드... 블랙핸드의 아들이자 검은바위 부족의 무능한 족장이지. 그만큼 고집이 센 자도 드물 걸세.$B$B2차 대전쟁이 끝날 무렵, 렌드와 그의 동생인 마임은 검은바위 첨탑의 산중 요새에 피신했지. 바로 그곳에서 렌드 녀석, 자기가 검은바위 부족의 대족장임을 선언했다네."
rows["318:559177414"]="이 추운 땅에서 신선한 얼굴이 있네 개개는 보이는 것보다 더 친절해 보군$B$B하지만 그 정도면 충분해. 왜 고생하는 거야? 문제를 찾아서, 아니면 그냥 피하려고?"
rows["318:969129299"]="데스윙 혈족... 이세라 님의 선행이 검은용군단의 지도자인 데스윙의 분노를 샀소. 검은용들은 밤을 틈타 우리를 공격했지! 첫 번째 공격에서 많은 이들이 죽었지만 녹색용군단이 우리를 보호하기 위해 나섰소.$B$B<섬 주변을 가리키는 왕자 토레스>$B$B한때 거대한 녹색용이었던 그들은 지금 뼈만 남아 있다오. 아무도 살아남지 못했지."
rows["319:1061559436"]="우린 마침내 그 비명의 원인이 뭔지 알게 되었어요. 도살자는 우리에게 우리가 존재하는지조차 모르던 극심한 고통을 주더군요. 그는 역병을 고안해 내기 위해 우리를 무수한 실험에 이용했어요.$B$B몇 주 동안이나 고문이 계속됐죠. 그 잔인한 녀석이 마법 수단을 사용해 우리를 계속 살려 두고 있지만 않았더라면 우린 아마 첫날 죽고 말았을 거예요."
rows["319:1201228444"]="이 예쁜 것들이 폐물처럼 보일지는 몰라도, 녀석들은 정면으로 돌진해서 적을 옆으로 날려버릴 수 있답니다. 전면에 달린 충각에는 초고용량 검전기식 축전기를 장착해서, 전기 충격을 발사할 수 있고요.$B$B심지어 포탑도 개조해서 대공 로켓을 달았지요. 저 파괴전차 나부랭이보다 훨씬 훌륭한 기계라고요."
rows["319:1379006296"]="물론 나는 그것을 가지고 있지 않다. 그건 바보 같은 짓이지. 여기는 이 저주받은 땅의 미개한 족속들이 날뛰는 곳이다! 채 다섯 걸음도 옮기기 전에 내 가죽을 노리고 미친 오크나 인간들이 서슬 퍼런 칼을 들이대고 무자비하게 마법을 난사한단 말이다. 때가 되면 너는 내 영혼과 언제든 대화를 나눌 수 있을 것이다.$B$B어쨌든... 그 조각은 내가 숨겨 두었다.$B$B어디있느냐 물어보아야 하지 않겠는가?"
rows["319:1487037788"]="망할 제데나르 악마 중 한 놈에게 발각됐습니다! 놈이 제 옆구리에 큰 상처를 남겼죠. 상처가 깊지만, 목숨을 위협하진 않을 겁니다.$B$B그보다 더 긴급한 문제가 있습니다. 어둠의 의회가 거친심장 거점에 있는 제 친구들에게 총공격을 펼치지 못하게 막아야 합니다. 전 싸울 상태가 못되니 그대가 저 대신 싸워주셔야겠습니다."
rows["319:831644708"]="안녕하세요! 검은창 부족의 존경과 호의를 얻고 싶다면 가난한 이들에게 귀한 자원을 기부하는 걸로 시작해 보십시오! 옷감이나 붕대가 하늘에서 뚝 떨어질 수는 없으니까요.$B$B모험을 하시면서 다양한 옷감을 구하실 텐데... 그냥 팔아버리는 것보다 좋은 일에 쓰는 건 어떻습니까?! 검은창 부족으로부터 인정도 받고 말입니다!"
rows["31:1030268385"]="이제 호드만이 우리를 구원할 수 있습니다."
rows["31:1140627733"]="내가 뭘 도와줄 수 있어?"
rows["31:1164134162"]="반드시 요새를 보호해야 하오."
rows["31:1208712321"]="영혼들의 가호가 있기를."
rows["31:1343141689"]="안녕하세요, 훈련 준비 됐어요?"
rows["31:1461736847"]="이 땅으로 데려온 건 뭐죠?"
rows["31:1495011934"]="어디로 가고자 하십니까?"
rows["31:1515754864"]="그것을... 잃어버리지... 말라."
rows["31:1549161146"]="준비는 잘 되고 있나요?"
rows["31:1589373569"]="나는 도끼의 달인 킬램이라고 하네."
rows["31:1611642070"]="어떤 상인을 찾고 계시나요?"
rows["31:1643014923"]="죄송합니다만, 전 도적만 가르칩니다."
rows["31:1647721343"]="우리 함께 새로운 역사를 씁시다!"
rows["31:1728934899"]="이방인이여, 우리 집에 온 걸 환영한다."
rows["31:1754389093"]="당장 떠나시오! 여긴 당신이 있을 곳이 아니오!"
rows["31:1777350028"]="가마솥에서 거품이 거칠게 부글거립니다."
rows["31:2028708699"]="로봇전사 NX-01은 현재 작동하지 않습니다."
rows["31:2082735900"]="<웅얼거리는 고버>$B$B나 은행원이다, 이제!"
rows["31:2108123597"]="뭘 도와드릴까요?"
rows["31:2144446196"]="코르그가 어떻게 도와드리면 되겠소?"
rows["31:220953871"]="어디로 날아갈까?"
rows["31:241682585"]="나는 그대를 훈련시켜줄 수 없소, 젊은이."
rows["31:278772176"]="내가 목재 때문에 죽지는 않겠어!"
rows["31:452203748"]="빛으로부터 어떤 가르침을 받길 원하십니까?"
rows["31:462752391"]="쉬이잇... 무슨 이상한 냄새가 나는 것 같지 않아요?"
rows["31:593612752"]="시간의 선술집에 오신 것을 환영합니다!"
rows["31:633697977"]="지금 낚시하고 있는 게 안 보이시오!"
rows["31:759438196"]="갈기갈기 찢어 주마!"
rows["31:839457366"]="옛날 얘기 하나 들어 보겠나?"
rows["31:841050485"]="어둠의 여왕의 가호가 함께하기를..."
rows["31:859255579"]="제가 낚시 기술을 가르쳐 드릴 수 있습니다."
rows["320:2083344829"]="무법항에 온 걸 환영하네, 친구. 우리 마을에 머무는 동안 아무 일 없이 즐겁게 지내길 바라네. 꼭 아무 일도 없이... 꼭! 마실 것이 필요한가? 일꾼이 필요한가? 말만 하게. 얼마든지 제공해 줄 테니까.$B$B그건 그렇고... 스팀휘들 무역회사의 충복인 이 몸께서 뭘 도와주면 되겠나? 아, 이렇게 말하는 게 더 낫겠군. 날 위해 자네는 뭘 해 줄 수 있나?"
rows["320:360698485"]="미쳤다는 게 무슨 말인지 모르는 건가? 정신이 나갔단 말일세! 그녀는 우리에게 미친 듯이 달려들었네. 평소에는 여자를 절대 때리지 않는 내가 그녀의 공격에 당해 잠시 의식을 잃었다 깨보니 무척이나 화가 나더군. 브란님과 프랭칼 그리고 나는 원숭이와 함께 온 힘을 다해 그녀를 제압했네! 사실 그녀를 제압했다는 자체가 기적이었다고 할 수 있지. 그녀는 마치 누군가에게 조종을 당하는 것 같았다네!"
rows["320:483822949"]="아서스는 스트라솔름의 주민을 모두 죽이라는 명령을 내립니다. 성벽 안에 있는 모든 이를 말이에요.$B$B그는 스컬지가 이 도시에 치명적인 역병을 퍼뜨렸다는 증거를 발견해 냈어요. 그 질병은 단순히 사람을 죽이는 걸로 끝나지 않습니다.$B$B역병 때문에 죽은 사람들은 영혼을 잃은 좀비로 되살아나 스컬지의 일원이 되고 말지요."
rows["320:592325433"]="다크문 카드는 야수, 축복, 정령, 원한, 열광, 차원문, 폭풍, 대장군의 여덟 종류가 있는데, 각각 A에서 8까지 8장으로 구성되어 있어요. 여덟 가지 중 어느 하나라도 8장을 모두 모으면 카드 한 벌로 바꿀 수 있는데, 그걸 학자 타데우스 팔레오에게 가져가면 강력한 장신구로 바꿔줄 거예요."
rows["321:1422054330"]="이 순간이동기는 자네를 던 모로 아래 깊숙이 자리 잡은 놈리건의 오염된 폐허로 순간이동시킬 거야.$B$B걱정 마. 자네를 여기로 돌려보내 줄 사람이 거기 있긴 하니까... 물론 이게 자네 피부를 뒤집어 놓거나 신체 장기를 유기질 폭탄으로 변이시키지 말아야겠지!$B$B뭘 머뭇거려? 어서 올라가!"
rows["321:1466856408"]="어허, 내 망토에서 손을 치우시오! 물론 이 망토를 갖고 싶어하는 당신 마음은 이해하오. 모두가 내 망토를 갖고 싶어하지. 양심도 없고 사회에서 지위도 낮지만 난 이 망토들을 팔아서 부자가 될 것이오. 이곳에서 아이언포지까지의 모든 이들이 이 바르톨로 진세티의 이름을 듣게 될 것이란 말이오. 모두들 진세티표 상품들을 몹시도 탐낼 것이오!"
rows["321:1683797890"]="렌드... 블랙핸드의 아들이자 검은바위 부족의 무능한 족장이지. 그만큼 고집이 센 자도 드물 걸세.$B$B2차 대전쟁이 끝날 무렵, 렌드와 그의 동생인 마임은 검은바위 첨탑의 산중 요새에 피신했지. 바로 그곳에서 렌드 녀석, 자기가 검은바위 부족의 대족장임을 선언했다네."
rows["321:175741165"]="전 스토나드에 도착하자마자 헬그럼을 제자로 삼았죠. 저의 매몰찬 교육 아래, 그는 전보다 더 뛰어난 추적자이자 제 하나뿐인 동반자가 되었어요.$B$B전 제가 강하다고 생각했어요. 그 무엇도 제 의지를 부술 순 없다고 믿었죠. 하지만 인간이 헬그럼... 제 짝에게 칼날을 박아 넣는 모습을 보았을 때... 제가 얼마나 잘못된 생각을 하고 있었는지 깨달았어요."
rows["321:1821545996"]="이 차가운 접대가 그리 놀랍지는 않습니다. 우리는 오랫동안 숨어 지냈고, 그 탓에 동족과 오랜 시간 떨어져 있었죠.$b$b그런 시절은, 이제 지나갔습니다. 이 어린 나무의 주민들이 우리를 받아들이건 그렇지 않건, 명가는 다시 빛 속으로 돌아오고 있습니다. 그리고 우리는 자신이 누구인지 부정하지 않을 것입니다."
rows["321:1965702270"]="얘기해 두지만, 여기서부턴 나중에 안 사실이에요. 전 그때 거기 없었으니까요.$B$B인부들이 막힌 펌프를 뚫으려고 조사해 보니, 펌프 안에 노움처럼 생긴 로봇 파편이 끼어 있었던 거예요! 물론 그 멍청이들은 우리한테 알리지도 않고 그걸 다시 조립하려고 밤낮으로 끙끙댔지요.$B$B채굴 현장과 연락이 끊어진 건 바로 그때부터예요."
rows["322:1028857782"]="나는 위대한 도시, 아이언포지의 드워프인 아다만트 아이언하트라고 하네. 내 제복을 보면 알겠지만 난 아이언포지 정예 경비병의 일원이었네. 그렇지, 나는 마그니 폐하의 오른팔이었다네! 뭐, 적어도 퇴역하기 전까지는 그랬지. 지금은 고고학을 연구하고 있네. 사실은 취미지만... 고고학이 세상을 보는 훌륭한 방법이라는 걸 깨달았지!"
rows["322:1196662397"]="이런 곳에서 새로운 분을 만나니 무척 반갑군요. 지금 우리는 적의 수가 너무 많아 간신히 버티고만 있습니다.$B$B우리를 없애려고 혈안이 된 적들에게 완전히 둘러싸였습니다. 북쪽으로는 사티로스, 동쪽으로는 전쟁노래 벌목기지의 오크, 그리고 악령불 언덕의 악마들까지...$B$B우리는 죽는 한이 있더라도 이곳을 되찾고 말 것입니다. 그런데 지금은 우리가 죽을 확률이 더 큰 것 같군요!"
rows["322:1552329678"]="트롬카! 노스렌드 전투에서 활약한 정예 부대원을 만나게 돼서 반갑소.$B$B대족장님께서는 내게 황혼의 고원을 공격할 최고의 정예 부대를 모으라고 명령하셨소.$B$B<당신을 위아래로 훑어보는 장군 크로그>$B$B당신이 우리에게 도움이 될지도 모르겠군. 오그리마에 계신 대족장님께 가서 뭔가 맡기실 일이 없는지 여쭤보시오."
rows["322:1779400757"]="소위 나를 숭배한다는 녀석들을 위해 만든 새로운 집이 마음에 드느냐?$B$B죽음의 모진 고통 속에서, 나는 그 모두를 저주했고 내가 만든 저승에 함께 끌고 왔지.$B$B녀석들이 영겁의 고통을 겪는 걸 보니 즐겁긴 하지만, 내가 진정 원하는 것은 내 옛 예언자 녀석에 대한 처절한 복수다!"
rows["322:640536829"]="이 밤호랑이는 나이트 엘프들과 그들의 동맹 사이에서는 유순하다는 소문이 있습니다. 그래서 더 가치 있는 사냥감이지요. 샤둠브라의 사냥길은 레인나무 은신처에서 바로 우리 서쪽 땅까지 이른답니다. 샤둠브라의 털은 송진빛이 돌며 그 속도를 절대 얕잡아 봐서는 안 됩니다."
rows["322:849733607"]="내 사업 파트너는 사물을 죽이고, 나는 그 본질의 일부를 소실히 소실한 것, 작은 조각도 빼놓을 수 없다.$B$B하지만 계약에 대한 제 몫을 하기 위해 에테레알 크레딧으로 지불합니다.$B$B이 신용을 내가 팔아먹는 물건으로 언제든지 환불할 수 있어"
rows["322:948950247"]="바가무일의 시선은 바다를 향해 떠돌아다.$B$B트롤은 인간으로부터 배들을 가져서 우리를 서쪽으로 이끌고 대해를 건너갔다. 폭풍은 거의 우리 모두를 몰아넣었다. 마침내 이 해안에 도착했을 때, 땅은 빨강하고 건조했고 태양은 해마처럼 부딪혔다.$B$B우리는 그 땅을 이름 붙여 듀로타, 워시프의 아버지에게, 그리고 우리는 그것을 우리의"
rows["323:1200051"]="쉿! 조용히 하세요. 전 여기 숨어서 멀록을 관찰하고 있단 말입니다.$B$B이 커다란 거북이 껍데기 속에 숨어 지내는 건 모두 연구를 위한 것이지요. 멀록이 여기에 있는 저를 발견하면 제 존재에 반응할 것이고 그럼 자료를 완성할 수 없거든요!$B$B탐험가 연맹에 가입한 최초의 노움으로서 저는 지금까지 어떤 드워프도 올라가지 못했던 자리까지 오를 겁니다!"
rows["323:1699417639"]="하루에 하나 이상의 암흑룬을 만들 수 있으면 좋겠지만 시간만 낭비하는 꼴일 거요. 간단히 물리적으로 불가능한 일이란 말이지. 게다가 이래 가지고는 암흑룬을 통계적으로 신뢰성 있게 만들어 낼 수가 없는 형편이라오.$B$B이곳에 도움을 줄 만큼 더 똑똑한 누군가가 있다면, 그들을 선발해서 필요한 만큼 많은 암흑룬을 얻을 수 있을 테니 우릴 믿으시오."
rows["324:1234380322"]="우리 잔달라 트롤들은 지금 이 세계에 닥친 위협을 묵인할 수 없어 머나먼 섬에서 이곳까지 건너왔네.$B$B원정대의 지도자인 몰소르 님은 가시덤불 골짜기 북부 해안에 있는 요잠바 섬으로 우리를 인도하셨고, 지금도 고대 트롤 도시로 들어가 모험을 감행할 용맹한 영웅들을 모으고 있지... 바로 줄구룹으로 갈 영웅들 말일세."
rows["324:1308627503"]="우리는 아제로스의 실력 있는 자들이 8가지 카드 종류 중 어느 한 벌을 완성할 수 있는지 시험해 보려고 전 세계에 다크문 카드를 뿌려 놓았습니다. 한 종류의 카드 8장을 모두 모으면 상급 다크문 카드 중 한 장을 보상으로 받게 될 겁니다. 이 카드는 강력한 장신구이자 다크문 축제로 연결해 주는 장치지요."
rows["324:1688206593"]="<소리가 더 높고 더 강해졌지만, 여전히 아무것도 없습니다. 자스퍼의 가슴은 느리고 리듬적인 움직임으로 올라와 떨어지고, 입은 약간 찢어집니다.>$B$B<일자고는  ⁇ 고 있는 콧물 때문에 침묵이 깨지고, 마치 순수한 무시를 제외하고는 전화를 응답하는 것처럼요.>$B$B분명히, 그를 깨우기는 몇 번의 외침이 더 필요하겠죠."
rows["324:2018904387"]="협상? 협상이라고 했나!$B$B우리 입장을 명확하게 얘기해 주지. 우리는 무엇이든 우리 의지대로 할 자유가 있다. 세나리온 원정대는 이 산맥의 주인이 아니라는 말이지.$B$B협상이란 있을 수 없네! 이제 그 드루이드들에게 가서 앞으로도 우리는 원하는 일을 그대로 진행할 것이라 전하게."
rows["324:482322402"]="그 끔찍한 기계를 정말 잘 처리해 주셨습니다. 이제 우릴 방해하는 건 별로 없을 거예요.$B$B저쪽 끝에서 절거덕거리는 로봇만 처리하고 나면 우린 울두아르 안에 있을 겁니다.$B$B불을 뿜어대는 거대한 원시비룡과 용암거인도 발견하긴 했습니다만, 울두아르 안으로 가는 길에 있는 건 아니에요. 원한다면 놈들은 피하실 수 있습니다."
rows["324:952062152"]="저는 불타는 군단 군주인 킬제덴과 그 수하들에게 사로잡힌 인간 아가씨를 구하러 동료와 함께 여기 왔습니다.$b$b저희는 캘타스가 태양샘 저 깊숙한 곳을 통해 불타는 군단 군주인 킬제덴을 소환하려고 한다는 걸 알았지요!$b$b이 세계를 지키려면 반드시 이를 막아야 합니다! 저는 이 끔찍한 계획이 실패했음을 확인할 사명을 지니고 있습니다."
rows["324:991329794"]="아직도 논란이 되는 그의 죽음 이후 로데론의 기사와 전사들은 고인이 된 영웅을 기리는 의미로 그와 비슷한 방어구를 만들어 입기 시작했소. 켈투자드를 상대로 모그레인은 목숨까지 바쳐 위대한 승리를 거두었고 그의 죽음으로 인해 촉발된 희생정신은 전쟁이 끝날 때까지 그칠 줄 몰랐소.$B$B한 명이 쓰러지자 수많은 사람이 들고일어났지..."
rows["324:996542878"]="\"순례자의 상\" 좀 더 \"무지한 바보의 미치광\"처럼$B$B수백 개의 화물 보관소에서 음식을 무료로 나눠주었습니다.$B$B하지만, 저는 제 조류 포트폴리오의 일부를 칠면조로 옮길 필요가 있다고 생각합니다."
rows["325:1027035279"]="천 년 전, 흐르는 모래의 전쟁이 끝났을 때 아나크로노스와 스태그헬름이 안퀴라즈를 봉쇄하는 동안, 우리 혈족 중 세 명이 자신을 희생하여 퀴라지를 이 전당 안에 가두었습니다.$B$B우리는 언젠가 스카라베 성벽이 무너지면 메리스라, 아리고스 그리고 캘레스트라즈를 구하자고 서로 맹세했습니다.$B$B드디어 성벽이 무너져... 우리가 온 것입니다."
rows["325:1135646823"]="십자군 전쟁 은 고위 장군 아베디스, 고위 인키시토르 이실리언, 고고로드 모그라인 이 세력 을 형성 한 전쟁 이다. 초기 에 십자군 전쟁 은 귀족 의 순위 이었다. 지금 보시는 광신 과 광신 의 열정이 존재하지 않았다. 그랜드 십자군 전쟁 의 고리가 등장 한 후 에 부패 의 고리가 움직임을 시작 하였다."
rows["325:1606775089"]="은행 같은 게 도대체 왜 필요한 건가? 뭐, 좋아. 브릴에서 남쪽, 로데론의 폐허로 깊숙이 들어가면 언더시티로 내려가는 승강기가 몇 대 있지. 그걸 타고 언더시티로 내려간 다음 언더시티 수호병 일을 하는 덩치 큰 누더기골렘 중 아무나 붙잡고 길을 좀 더 자세히 물어보도록."
rows["325:1611960851"]="인간 과 스컬지 같은 사람 들 이 알고 있는 육류 의 가장 훌륭 한 보존물 은 - 프로스트비스퍼 의 방자름물 이다. 모험가 이 를 발견 할 수 있는 한 곳 은 그 곳 에 가신 사람 은 그 곳 을 방문 하는 사람 에게도 그 물 의 이름 을 붙인 물체 이 너무 친절 하게 받아들이지 않을 것 이라고 생각 할 것 이다.$B$B하지만... 당신이 원하는 액체라면, 당신이 쫓아낼 수 있는 슐로만스라면..."
rows["326:1205663209"]="\"전문가\"가 뭐냐고 했나? 그건 내가 모든 것에 대해 연구한다는 뜻이다! 난 네가 생각해낼 수 있는 어떤 주제에 대해서도, 지금까지 네가 만나본 사람이나 앞으로 만나볼 사람, 그 누구보다 더 자세히 알고 있다.$B$B샤파르의 방을 통과하는 건 아무 것도 아니야. 몰팔리우스가 내 말을 들었더라면 어디 한 군데 긁히지도 않았을 것이다. 그 녀석은 언제나 자기 방식대로만 일을 하는 게 문제야."
rows["326:128343465"]="이거라면 어떤 배보다도 더 빨리 언더시티에 갈 수 있습니다. 경치는 또 숨이 막힐 정도로 아름답지요. 숨 얘기가 나와서 말인데, 비행선에서는 금연입니다. 화염 마법도 금지고... 사고라도 나면 헬륨 폭탄이 터지는 것에 비길 바가 아니니까요."
rows["326:183489645"]="전 한때 여사제였지만, 언제나 학자였어요. 잘 알지 못한 채 엄격한 수행을 하느니 명가에 대해 배울 기회를 얻는 게 더 소중하다고 생각한답니다.$B$B게다가 이곳의 수습생 대부분은 3차 대전쟁 동안 성년이 된 젊은이들이에요. 그들에겐 지도와 지혜가 필요하답니다.$B$B저를 친구라 부르곤 한 자들이 이해하기를 바랄 뿐이에요."
rows["326:2117731269"]="샤파르는 영리한 놈일세. 놈은 다른 에테리얼 무리가 들어오지 못하게 일종의 수호물을 사용해서 입구를 만들었지. 우리는 놈의 방어선을 뚫고 안으로 들어가서 우리 물건을 찾아오려고 노력 중일세. 최고의 에테리얼들이 쉬지 않고 작업 중이니 이제 금방 열릴 거야. 분명 그런 예감이 들어..."
rows["326:240663765"]="오래전 필멸의 종족들의 상상을 벗어난 우주의 한 차원에서 무언가 탄생했습니다. 탄생이란 표현이 맞는지는 모르겠지만... 어쨌든 엄청난 힘을 지닌 그 존재는 이 세상에 나타나 모든 현실을 뒤흔들었습니다.$B$B'울림'이라는 이름 외에는 알려진 것이 없는 이 존재는 바로 소리의 정수였습니다. 그리고 이 존재가 하는 말을 듣는 것은 곧 영원한 죽음을 맞이한다는 의미입니다!"
rows["326:599430155"]="동전을 충분히 모으면 맥주 사랑 동호회 회원이 될 수 있습니다. 맥주 사랑 동호회에 들어온다는 것은 일 년 내내 가을 축제를 벌이는 것이나 마찬가지지요!$b$b매달 소식지와 함께 시음용 맥주가 배달되거든요. 맥주가 입맛에 맞으면 오그리마 정기의 골짜기에 있는 검은장미 오두막으로 가서 더 사 마시면 되지요."
rows["326:791482699"]="일리단 휘하 최고의 악마사냥꾼 3명에게 훈련을 받은 지 1년이 되기도 전에 베레디스는 그들을 능가했네.$B$B베레디스는 그들에게 더 이상 배울 것이 없자 저주받은 이름의 책이라는 강력한 유물이 있다고 알려진 어둠의 의회로 침투했네. 그는 몰래 그 책을 읽고 모든 구절을 암기했지."
rows["327:676168468"]="무슨 말입니까? 장가르 습지대라니요? 제가 뭐하러 그곳에 가겠습니까?$B$B<생각에 잠긴 트리로스>$B$B오, 그렇군요, 장가르 습지대... 그곳에 있던... 우리 드루이드들은 수위가 낮아지는 원인을 거의 알아냈습니다. 그것이 모든 것을 파괴하고 있습니다!$B$B<광기가 돌아오는 교도관 트리로스의 눈>$B$B우리 모두를 죽인 겁니다! 그 밝은 빛이! 쾅!!"
rows["328:1024453190"]="잿빛 선고단은 칠흑의 기사단과 은빛십자군에서 가장 능력 있는 장인들을 모아 놓은 단체이다. 그들이 만들어내는 물건은 리치 왕과 그 하수인들에게 마지막 공격을 감행할 때 우리 군대의 단결을 상징한다.$B$B태고의 사로나이트를 마음대로 구부렸다 폈다 하는 법을 발견해낸 것도 잿빛 선고단의 노력 덕이다."
rows["328:1413745518"]="여어, 젊은이. 처녀의 몽상호에 온 걸 환영하네. 나는 렌치노즐 선장이고, 자네는 검은바다 해적단의 보호 아래 안전하게 항해할 걸세. 붉은해적단은 배에 저장해 둔 엄청난 양의 화약과 용맹한 우리 선원들이 무서워서 가까이 오지 않을 테니 말이야. 알겠지만, 일종의 보험이라고.$b$b질문이 있다면, 젊은이, 내가 대답해 주지."
rows["328:23363301"]="감히 그 누구에게도 비교할 수 없는 마법과 어둠의 지식을 갖춘 그 생존자는 이 세상에 알려지지 않은 존재들의 영혼을 사냥하여 자신의 소환술을 강화했습니다.$B$B그러나 그와 공모자들이 울림을 소환하기 위해 개발한 영혼의 장치는 모든 문명을 집어삼키고 말았습니다."
rows["328:370636152"]="그대가 첫 번째로 해야 할 일은 던홀드 요새의 포로수용소 안에 있는 통에 화염 폭탄을 설치하는 것입니다. 폭탄 5개가 폭발하고 적의 주의가 흐트러지면 던홀드의 지하 감옥에 있는 스랄을 찾아서 풀어 주십시오. 이후로 그를 따라다니면서, 절대 그가 죽지 않게 보호해 주셔야 합니다!$B$B준비가 되면 브레이즌이 그대를 던홀드까지 데려다 줄 겁니다."
rows["328:385922794"]="좀 어수선해도 신경 쓰지 마세요. 아직 자리 잡는 중이니까요.$B$B그 때문에 즐기지 못해서야 되겠어요? 긴장 푸세요, 돈도 좀 쓰시고요... 환전업자와 세탁소부터 이국적인 마실거리와 상급 낚시꾼까지 다 있으니까요.$B$B누구 때문에 골치가 아프신가요? 그냥 '제게만' 살짝 알려 주세요. 처리해 드릴게요.$B$B저는 모두... 처리하는 미다거든요."
rows["328:920946504"]="대해를 건너야 하나 본데, 제대로 찾아오셨군. 여기는 처녀의 몽상호가 정박하는 곳이거든. 이 망망대해를 건너기에는 가장 편리한 여객선이지. 배가 도착하면 그냥 올라타기만 하면 돼. 언제 그 넓은 바다를 건넜는지도 모르게, 가시덤불 골짜기의 해변에 도착해 있을 거라네."
rows["329:1365959288"]="여행자여, 고룡쉼터 사원에 온 것을 환영하오.$B$B이곳은 위대한 선조의 유골 사이에서 용군단이 서로 평화롭게 회담하는 장소라오.$B$B최소한 푸른용군단이 사원을 습격하기 전까지는 평화로운 곳이었소.$B$B들어오시오. 우리의 축복과 함께 들어오되, 여기서는 그 어떤 폭력도 용납되지 않음을 명심하시오."
rows["329:1702426054"]="그 저주받은 기사는 한때는 은빛 성기사단의 일원으로서 동료 성기사들과 같은 영웅이었지만 저주를 받았죠. 붉은십자군 수도원에서 미쳐가면서, 그는 자기가 살아 있고 나머지가 다 죽은 이들이라고 믿기 시작했어요.$B$B이제 그의 열정은 빛을 향해 있지 않아요. 할로윈 축제가 다가오면 그는 아제로스의 여러 마을에 암흑과 불길을 몰고 온답니다."
rows["329:249761969"]="어이! 바다 깊숙이 잠수해본 적 있나? 내가 비밀 하나 알려줌세. 물속으로 깊이 들어가면 거품 균열이 있네. 그 근처에 있으면, 물속에서도 숨을 쉴 수 있지. 이건 우리끼리만 알고 있자고, 알았나? 가재 잡는 데 경쟁자가 생기는 건 싫으니까 말일세. 무슨 말인지 알겠지?!"
rows["329:363172250"]="종자는 기사의 오른팔이다. 너도 잘 알겠지만, 팔은 물건을 들 때 가장 쓸만하지. 그러므로 내가 이 땅에 정의를 행할 동안 넌 내 물건, 장신구, 그리고 이런저런 소지품들을 날라라. 잡다한 물건들을 들고 다니는 건 기사의 품격을 떨어뜨리니 말이다."
rows["329:630155122"]="시로나스 님께서는 어떤 에레다르가 자신의 종족을 만아리로 변하게 할 수 있는 능력이 있다고 주장하셨습니다. 드레나이는 한때 에레다르였고 시로나스 님께서도 강력한 에레다르입니다.$B$B<소리 내어 웃는 첩보원>$B$B저 불쌍한 짐승들이 한때 강력한 악마들이었다는 사실을 믿을 수가 있습니까? 어떤 바보가 그렇게 강력한 힘을 거부하겠습니까?"
rows["329:770362098"]="대해를 건너야 하나 본데, 제대로 찾아오셨군. 여기는 처녀의 몽상호가 정박하는 곳이거든. 이 망망대해를 건너기에는 가장 편리한 여객선이지. 배가 도착하면 그냥 올라타기만 하면 돼. 언제 그 넓은 바다를 건넜는지도 모르게, 가시덤불 골짜기의 해변에 도착해 있을 거라네."
rows["32:1088778772"]="약간 춥군요, 안 그렇습니까?"
rows["32:1252963531"]="난 즉시 이곳을 떠나야 한다!"
rows["32:1394482490"]="어디 가면 그 자식이 없는지는 얘기해줄 수 있지..."
rows["32:1434442859"]="철나무로 돌아가야 돼"
rows["32:1649734634"]="이 몸은 주인님을 섬기기 위해 살 뿐입니다."
rows["32:1650003613"]="훈련받을 준비가 되었소, 전사여?"
rows["32:1736534547"]="엘프가 사라질 때까지 일하지 않을거야!"
rows["32:1769329750"]="더러운 스컬지 녀석, 내게서 떨어져라!"
rows["32:1781349643"]="만나서 반갑습니다. 도움을 주러 오셨나요?"
rows["32:1809101566"]="오그리마는 그 어느 때보다도 강합니다!"
rows["32:1824480324"]="어디로 가고자 하시오?"
rows["32:1868749104"]="갑판을 청소하며 햇볕을 쬐어서 구루병이 다 나았어요!"
rows["32:2048958282"]="<의식을 잃은 SI:7 요원>"
rows["32:24390892"]="<수렁피 감독관이 투덜거립니다.>"
rows["32:306633677"]="여기가 어디죠? 절 도와주러 오셨나요?"
rows["32:31203418"]="이제 가세요. 더는 보여드릴 게 없답니다."
rows["32:342068765"]="어딜 저렇게 뛰어가는 거죠?!"
rows["32:382455914"]="타우라조 학살자는 죗값을 치르게 될 거요."
rows["32:427297127"]="좋습니다. 그새 실력이 향상되셨길 빕니다!"
rows["32:429859249"]="오늘은 어떤 물품을 공급해 드리면 되겠소?"
rows["32:516975444"]="자네는 학생 같아 보이지 않는데..."
rows["32:668794891"]="대체 문제가 뭐죠?!"
rows["32:803081937"]="호드 전쟁 기계가 당신을 필요로 합니다!"
rows["32:980733683"]="<고개를 끄덕이는 대영주 다리온 모그레인>"
rows["330:105501860"]="그렇죠, 정말 이상한 일이죠! 브란 님과 루트거 그리고 저는 티탄의 두 종족인 바니르와 에시르의 언어까지 모두 38가지나 되는 언어를 알고 있는데 정말 이해할 수 없었어요. 물론 그 말은 원숭이의 언어도 아니었죠.$B$B그러니까 그녀가 무슨 말을 하는지는 몰랐지만 분명한 건 그곳에 저희 외에 다른 사람은 없었다는 겁니다. 그런데 그녀가 고개를 끄덕이더니 갑자기 공격을 시작하더군요! 그것도 저희를 완전히 죽일 둣이 말입니다!"
rows["330:1512838114"]="세상의 끝 선술집에서 파는 것들은 견줄 수도 없을 만큼 훌륭한 물건이 있답니다. 전 제가 파는 물건에 관심을 보이는 손님들이 어떤 유형이고, 또 어떤 분야에 특히 마음이 끌려 하는지 발견해냈죠.$B$B제가 주로 취급하는 물건은 멀리 광활한 세계에서 입수한 진귀한 기술용품입니다. 때때로 아주 희귀한 물건을 한두 가지쯤 내놓기도 하지요.$B$B그런데 어떤 물건을 찾으시는지요?"
rows["330:306042037"]="기나긴 전투를 치르면서 고대 신들의 육체는 점점 쇠약해져 자신들이 손수 창조한 세계의 지하에 갇히게 되었고, 티탄 창조주의 타락이 온 지상에 퍼지면서 고대 신들을 욕되게 했습니다.$B$B바로 그때 주인님의 형제들이 배반을 하여, 오천 년 동안 이 세계의 심장부에서 전쟁이 일어난 것입니다."
rows["331:1757035190"]="우리에게는 언제나 공포심이 가장 강력한 무기였네. 언제나 혼란과 의심 속에서 모든 전쟁을 치르며 승리하고 또 패배했지. 그럼 공포를 모르는 적과는 어떻게 싸워야 하는가?$B$B<고개를 젓는 사울팽>$B$B우리가 노스렌드에서 싸우는 상대는 스컬지뿐만이 아닐세. 저들이 우리를 산산조각 내기 전에 정신을 다잡도록 스스로와 싸워야 하네..."
rows["331:2140215488"]="드디어 증원군이 왔군요! 경비병들로는 푸른용군단의 침입을 그리 오래 버티지 못합니다! 제 경비병들을 도와 당신이 할 수 있는 한 오래 방어선을 지켜 주셔야겠습니다. 방어 체계에 사용할 수 있는 마력이 좀 남아 있습니다. 상황이 악화되면 요새 주위에 있는 활성화 수정을 사용하여 마력을 유포하십시오."
rows["331:562710595"]="우리들 중 한 명입니다. 우리들의 숫자가 너무 빠르게 증가하는 것을 보고 기쁘습니다.$B$B그 멍청한 트롤은 내가 마녀들의 이미지를 깨끗하게 하고 우리가 그의 종인 걸 증명하기 위해 열심히 일한다고 생각해요 불타는 군단 이 세상이 완전히 소실되면"
rows["332:1529121165"]="그렇죠, 정말 이상한 일이죠! 브란 님과 루트거 그리고 저는 티탄의 두 종족인 바니르와 에시르의 언어까지 모두 38가지나 되는 언어를 알고 있는데 정말 이해할 수 없었어요. 물론 그 말은 원숭이의 언어도 아니었죠.$B$B그러니까 그녀가 무슨 말을 하는지는 몰랐지만 분명한 건 그곳에 저희 외에 다른 사람은 없었다는 겁니다. 그런데 그녀가 고개를 끄덕이더니 갑자기 공격을 시작하더군요! 그것도 저희를 완전히 죽일 둣이 말입니다!"
rows["332:1547013753"]="아, 아, 거 참 서두르지 마시오! 방금 얘기하려던 참이었단 말이지!$B$B그렇게 그분이 오크 핏덩어리를 뒤집어 쓰고 서 있는데 누군가 나타났소...$B$B바로, 검은무쇠 부족이었지! 내 얘기를 듣기는 한 거요?$B$B뭐, 어쨌든 검은무쇠 녀석들은 검은바위 부족보다 지략이 좀 뛰어난 편이오. 정렬이 잘 맞춰진 300명의 부대가 몰려왔지. *딸꾹* 실례..."
rows["332:25582015"]="그런 것 같지는 않소. 대부분 지역 특색에 따라 다른 것 같은데 어떤 종족들은 그걸 수액괴물이라고 부르고, 어떤 종족들은 진흙괴물이라고 부른다오. 대체로 취향의 문제인 것 같소.$B$B수액괴물이나 녹괴물, 진흙괴물을 접할 때마다 겉모양은 기본적으로 다 똑같은 생물들이었소. 환경에 따라 차이가 있는 것이기에 순수한 견본이 필요한 거요."
rows["332:410585737"]="이거라면 어떤 배보다도 더 빨리 언더시티에 갈 수 있습니다. 경치는 또 숨이 막힐 정도로 아름답지요. 숨 얘기가 나와서 말인데, 비행선에서는 금연입니다. 화염 마법도 금지고... 사고라도 나면 헬륨 폭탄이 터지는 것에 비길 바가 아니니까요."
rows["332:866779046"]="내 아들이 여기 있다는 이야기를 들었네. 그가 이제는 강력한 죽음의 기사로 리치 왕을 섬긴다고 말이야. 정말 이 얘기가 사실이라면, 그 목숨을 끊을 자는 나일 걸세.$B$B이제 내 임무는 오그림의 망치호를 얼음왕관 성채 꼭대기로 이동하여 우리 길을 막는 모든 스컬지를 처치하는 것이네. 자네와, 함께하는 동맹이 준비되면 떠나겠네."
rows["332:954899596"]="사랑하는 내 형제들이 여기서 이 순간을 저와 함께한다면 정말 좋으련만. 이 엄청난 발견을 그들은 상상도 못 할 겁니다!$B$B심판관은 바로 이 방에 가득 찬 티탄의 자료를 관리하는 사서라고요!$B$B보십시오! 바닥 아래 자료가 가득합니다! 서둘러야 합니다. 드워프의 가장 위대한 발견이 눈앞에 있어요."
rows["333:1069348747"]="이 친구는 내 조수일세.$B$B우리처럼 한 번도 역병에 걸려본 적 없던 녀석이었지, 하지만 이번에 확실히 역병에 걸리고 말았다네. 이 친구도 실바나스 님께 무릎을 꿇었지, 자네나 나처럼 말이지.$B$B이건 우리 둘만의 비밀인데... 솔직히 말하면, 어둠의 여왕님은 이 친구가 방에 들어가기도 전부터 이미 무릎을 꿇은 상태였다고 생각하셨을 거야!"
rows["333:1095185267"]="일단 기기를 만들면, 그냥 Toshley's Station에 운반될 수 있도록 기기를 활성화시켜야 합니다. 몇 명의 사람들이 닭으로 변신했다고 보고했지만, 저는 그들이 과장했다는 것을 확신합니다!$B$B가능하다면 다른 사람이 사용할 때 기기를 사용하지 않으려고 노력하겠지만, 당신이 할지라도 잘 될 것입니다!"
rows["333:1445838793"]="제 동생은 이 무역로로 큰 돈을 벌 수 있다고 말했지만, 저 쪽에 사는 사람이 될 것이라고 말하지 않았습니다. 제펠린에 타고 이쪽으로 돌아와면, 먹을 것을 가져오실 수 있나요? 오그리마에서 가장 좋은 고기를 팔고 있는데,"
rows["333:1915993178"]="불타는 칼의 씨가 무너진 후, 우리는 우리들, 래의 지배로부터 우리 자신과 우리 사람들을 해방시키기로 맹세했습니다.$B$B이 일은 가능하지만, 제 명예는 여전히 불만족입니다.$B$B저는 호드 내가 전투에서 영광스럽게 죽을 때까지 다른 전사들을 훈련시켜야 한다$B$B훈련 준비 됐어?"
rows["333:2063227588"]="그래, 그래. 그거 아주 흥미로워. 하지만, 보다시피 우린 생사가 달린 전투를 하는 중인데다 동굴 안에 있는 것과 비교해보면 소인족은 별문제도 아니란 말이야!$B$B쓰잘데기 없는 조수는 꼭 필요할 때마다 어디 가는 거지? 아마 어딘가에서 빈둥거리거나 오늘 하루 어떻게 보냈는지 아무도 묻지 않는다며 투덜거리고 있겠지..."
rows["333:481930529"]="바시르 수정괴철로는 에펙시스 결정을 불안정한 마술사의 영약으로 변환하는 데 쓰입니다. 이 영약을 마시면 지능이 향상되고 원기가 왕성해지며, 공격력과 치유 능력이 증가합니다.$B$B그렇지만 1개의 영약을 만드는 데 필요한 10개의 결정을 지니고 있지 않아서 이 괴철로를 작동시킬 수 없는 것 같습니다."
rows["334:1213904491"]="이 녀석들은 다른 어떤 기계와도 달리 불을 그야말로 뿜어댄다고. 우린 여기에 보조 대포랑 갈고리까지 달고는 수동 연료 주입 시스템을 더했지. 기계노움에게서 얻는 액화 황철석을 이용하면, 고밀도 폭발물을 쏘거나 전차를 확 가속할 수 있다고.\010\010탐험가 연맹의 얼간이들이 이걸 넘어설 수 있는지 한번 보자고!"
rows["334:1582975128"]="이 녀석들은 다른 어떤 기계와도 달리 불을 그야말로 뿜어댄다고. 우린 여기에 보조 대포랑 갈고리까지 달고는 수동 연료 주입 시스템을 더했지. 기계노움에게서 얻는 액화 황철석을 이용하면, 고밀도 폭발물을 쏘거나 전차를 확 가속할 수 있다고.\010탐험가 연맹의 얼간이들이 이걸 넘어설 수 있는지 한번 보자고!"
rows["334:178075515"]="저흰 놈들의 존재를 눈치채지 못했습니다... 놈들은 갑자기 고원 전역을 한꺼번에 공격했지요. 땅에서 불쑥 솟아나오고 공중을 휩쓸었습니다. 그리핀 편대 대부분이 흩어졌고, 너무나도 많은 훌륭한 드워프가 목숨을 잃었지요.$B$B키건이 우리를 이렇게 이끌어 주지 않았다면 우리에겐 전혀 희망이 없었을 겁니다. 전 그에게 목숨을 빚졌어요. 적어도 지금은 조금이나마 희망이 있으니까요."
rows["334:293935707"]="이제야 말귀를 좀 알아듣는구먼. 귀라도 좀 후비지 그러쇼. 거 답답해서 무슨 얘길 하겠소?!$B$B그래서, 검은무쇠 녀석들은 윈저님을 생포해갔지. 콧대가 하늘을 찌를 만큼 거만한 우두머리, 타우릿산인가 뭔가 하는 녀석이 무쇠폭군을 빼앗아 가져갔소. 내가 마지막으로 윈저 님을 본 게 그때요. *딸꾹* 쩝, 실례..."
rows["334:72593517"]="이봐요 이봐, 잊지 말고 가을 축제 기념품 챙기세요! 전통 축제 의상에서 시원한 맥주가 담긴 꼬마 술잔까지 뭐든지 있습니다. 블릭스 픽스위젯과 얘기만 하면 다 되는데, 그 대신 가을 축제 상품 교환 동전은 잔뜩 가지고 있어야 합니다... 그래야 기념품을 구입할 수 있으니까요! 가을 축제 광장 주변에서 이것저것 돕다 보면 동전을 얻게 되실 겁니다."
rows["335:497051166"]="안녕하세요, 영웅$B$B저는 여러분의 모험을 맞춤화하기 위해 두 가지 서비스를 제공합니다.$B$B경험 보너스: 저는 모든 보너스 경험 원천을 비활성화 할 수 있습니다. 경험의 음료를, 경험의 아우라와 친구에게 추천합니다. 그래서 기본 비율로 진행됩니다.$B$B오픈 월드 스케일링: 저는 오픈 월드에서 존재들을 여러분의 수준에 맞추어 일관된 도전을 할 수 있습니다."
rows["335:92315243"]="마우아리의 부적은 많은 비밀을 간직하고 있지... 그 부적을 만드는 데 사용한 얼음 조각의 빛나는 표면은 반사 성질이 있어, 다른 존재들의 힘을 자기 자신에게 반사해 빨아들일 수 있네.$B$B부적을 소지하고 있으면 자신이 싸워 이긴 야수들의 영혼 에너지인 에코를 모을 수 있을 거야. 에코를 찾으면 이 마우아리에게 가져오게."
rows["335:980020372"]="자네는 나보다 쇠의 비밀을 더 많이 알고 있군. 좋은 일이야. 쇠의 비밀이란 꼭 손에 넣어야 할 가치있는 것이지. 자네는 이제 인간 영토 남쪽에 있는 밀림으로 가게. 무법항이라는 고블린 도시를 찾아. 그곳에 브리크 킨크래프트라고 하는 고블린이 있을 것이네. 별로 마음에 들지 않지만 쇠의 비밀에 대한 지식은 내가 아는 어느 누구하고도 비교할 수가 없을 정도지."
rows["336:141722673"]="내가 원하는 것은 창조자들이 울덤 복합에 접근할 수 있도록 하는 것입니다.$B$B현재 디스크 세트에는 Uldum의 플레이트가 포함되어 있지 않습니다. 입력의 주요 조건은 Uldum의 플레이트가 존재하는 경우만 액세스 할 수 없습니다."
rows["336:1871312101"]="용사님, 진심으로 유감스럽게 생각합니다만, 십자군 사령관의 시험에 도전할 기회를 다 쓰셨습니다. 이미 아시겠지만 십자군 사령관의 시험은 일주일에 한 번만 치르실 수 있습니다. 이번 주에 얻으신 교훈이 스컬지에 대한 진정한 승리의 밑거름이 되길 빕니다!"
rows["336:1934310681"]="아무튼 좋다... 넌 아케이나이트 부표를 만들어 바다 속에 던져야 한다. 그러면 분출되는 마력에 의해 내 작은 물고기가 이끌려 올 것이다. 그 녀석이 부표 가까이 오면... 꽝! 신비한 힘이 폭발하여 그녀석을 원래 모습으로 되돌릴 것이니라. 그리고 한 가지 더, 너는 넵튤론의 분노를 살 수도 있고 그렇지 않을 수도 있다. 확률은 반반이다."
rows["336:27204489"]="니비, 바보, 방해하지 마! 난 네 뼈의 고기를 찢고 네 뼈골을 코트 랙으로 사용하겠다. 이제 내가 어디 있었을까? 오, 그래, 그래서 크로시우스는 평범한 지옥보다 거의 10배 더 오래 살았어. 나는 왜인지 확실하지 않지만 충분한 연구로, 나는 알아낼 수 있다고 확신한다.$B$B크로시우스의 지옥핵을 되찾아야 해"
rows["337:1098909397"]="가을 축제는 끝내주는 축제지요! 그런데 말입니다... 곤란한 게 딱 하나 있는데, 바로 검은무쇠 드워프의 공격입니다. 거의 30분마다 몰려온다고요!$b$b녀석들의 목표는 바로 공짜 맥주를 받아 마실 수 있는 맥주통입니다! 양조사들이 친절하게 베푸는 진짜 좋은 맥주라고요!$b$b보세요, 검은무쇠 드워프가 나타났을 때 주위에 계시거든, 공짜 맥주 지키는 데 손 좀 빌려 주시죠!"
rows["337:1281485501"]="오멘은 엘룬아라 호수의 깊은 곳에 잠들어 있습니다만 스톰레이지 지하굴 근처, 남동쪽 비탈에서 소환될 겁니다. 거기에서 그대는 특별한 연발탄 발사대를 찾게 될 겁니다...$B$B발사대에서 폭죽을 사용하면 오멘의 부하들이 올 겁니다. 폭죽을 대략 30개 정도 더 발사하거나 엘룬의 양초를 오멘의 부하들에게 발사하면 곧 오멘이 깨어날 겁니다."
rows["337:1959459812"]="저는 초보자의 상승책이고, 당신이 레벨 20에 도달할 때까지 당신의 주문과 능력을 순서대로 분류하는 데 도움을 줄 수 있습니다. 또한 초보자의 탐구선 승천의 길에 대한 안내자입니다! 레벨 20에서는 당신의 능력을 순서대로 분류할 수 없지만 다른 플레이어에게 소유된 상승책을 사용하거나 스스로 구입할 수 있습니다!"
rows["338:1550542392"]="듀로 마나괴철로는 폭풍우 요새에서 가장 가까운 시설이기 때문에 물량의 대부분을 처리합니다.$B$B아시다시피 마나괴철로에 과부하가 걸리면 수송관에서 마나가 새기 마련이지요. 예기치 않은 사실이지만 그곳에서 발산된 기운에 마나 생명체들이 이끌리고 있습니다. 마나가 유출된 곳곳에서 마나 생명체들이 떼를 지어 튀어나오고 듀로 마나괴철로는 치명적인 타격을 받고 있습니다.$B$B하지만, 아직 폭발하지는 않았습니다."
rows["338:2109279741"]="바로스 클라우드스트라이더와 그의 반지 보호자들은 두 번째 반지를 보호합니다. 당신의 드레크는 반지 보호자와 더 이상 일치합니다. 하지만 바로스는 오클루스의 에너지로부터 만들어진 непроницаемых 방패 뒤에 서 있습니다."
rows["338:357701139"]="인정하기는 싫지만 곰이 나보다 한 수 위군. 무지막지하게 큰 곰이야!$B$B저 곰을 때려눕힐 수 있을 정도면 자랑스러워할 만하지! 녀석 때문에 골치깨나 앓은 사냥꾼이 한둘이 아니거든.$B$B<당신의 등을 철썩 치는 마렉>$B$B그 곰을 잡으면 자네를 우리 원정순찰대 오두막 정식 회원으로 받아주지."
rows["338:61146211"]="바로 여깁니다. 한때 커다란 비극이 벌어진 곳임을 느낄 수 있습니다. 아직도 극심한 고통이 저 안에서 메아리치는군요. 저 너머의 공포가 이곳을 지배한 것이 분명합니다.$B$B이 세상으로의 침입을 완전히 막아내려면, 먼저 완전히 열어야 합니다. 이곳으로 오려는 존재를 저지하는 데 당신의 힘이 필요할 듯하군요.$B$B준비는 되셨습니까?"
rows["339:1199877430"]="물론 자네가 할 일이 있지! 우린 항상 솜씨 좋은 $c|1을;를; 찾고 있다네. 우리가 엑소다르로 다시 돌려보낼 드레나이들보다는 자네가 더 뛰어나길 바라네. 엑소다르를 돌아가는 드레나이는 생명이 다해 매장하려고 보내는 것이니 말이야...$B$B<소리 내어 웃는 옥테온>$B$B하하, 농담이라네! 자네 표정 정말 가관이로군. 그들은 경미한 상처를 치료하려고 엑소다르로 가는 거라네. 금방 나을 가벼운 상처지..."
rows["339:1703803337"]="저는 이 세계의 생명체를 세 가지로 분류합니다. 경쟁자, 고객, 그리고 일꾼... 경쟁자는 무자비하게 제거하고, 고객의 욕구를 만족시키고, 일꾼들은 엄격히 감독해야죠.$B$B개인적으로 계약을 맺고 일하는 자들은 믿을 게 못됩니다. 일꾼들보다 많은 보수에 고객처럼 대접받기를 원하더군요. 그런 자들은 절대 믿지 마십시오."
rows["339:2025257608"]="이세라 님에 대해 들어 보지 못했소? 자연의 수호신이나 꿈의 위상으로도 불리는 그분 말이오. 이세라 님께선 모든 녹색용의 보호자와 같은 존재요! 그렇소이다, 내 왕국에 녹색용군단을 선물한 것도 바로 이세라 님이셨지. 우리는 고귀한 존재들과 어깨를 나란히 했으며, 적과 싸울 때 녹색용들은 우리가 자신들의 등에 올라타도록 허락했소. 수 세기 동안 모든 것이 순조로왔지... 그 일이 있기 전까지는..."
rows["33:1038260920"]="가끔 저는 저 자신에게도 깜짝 놀랍니다!"
rows["33:1048811869"]="네가 필요한 걸 가지고 있다고 생각하니?"
rows["33:1264646107"]="바쁘니까 방해하지 말게."
rows["33:1341905319"]="선원 노릇 하기엔 제 이름이 좀 불길하죠?"
rows["33:1349270579"]="당신이 좋아요! 함께 멋진 일을 해낼 수 있을 거예요."
rows["33:1362889862"]="마스터로부터 배우러 왔어?"
rows["33:1421597937"]="시킬 일이 있으신가요, 대장님?"
rows["33:1431992920"]="잘 계신 걸 보니 기쁩니다."
rows["33:1485168131"]="내 길을 보내줘..."
rows["33:1515941847"]="<장화를 닦고 있는 머드럼프>"
rows["33:153316730"]="주인님이 너를 찾으신다."
rows["33:1548448178"]="시간을 낭비해선 안 된다, 여행자여."
rows["33:1553897006"]="넌 $T 민간인: 민간인;"
rows["33:1665589935"]="훈련을 받으러 왔습니까?"
rows["33:1700105482"]="길드를 창설하도록 도와드리겠습니다."
rows["33:1869641856"]="이건 차 차는 아냐, 클렘"
rows["33:1916889140"]="반갑습니다! 무엇이 필요하신가요?"
rows["33:1927442578"]="승객분과 대화를 나눌 시간이 별로 없습니다. 죄송합니다."
rows["33:2017933535"]="그렇다면 아키몬드가 설쳐 대는 모습을 지켜보도록 할까요?"
rows["33:2083228327"]="한 명 더 있을 수 있어?"
rows["33:2139066176"]="저... 이 옷 입으니까 뚱뚱해 보이지 않나요?"
rows["33:2139307641"]="몸서리 햇빛 아래 있어서 행복하다."
rows["33:317544965"]="배우고 싶은 게 있으면 언제든 오게."
rows["33:346828138"]="다음 스테이지를 진행할까요?"
rows["33:404214451"]="<기대에 찬 눈빛으로 당신을 쳐다보는 브란>"
rows["33:442260513"]="알도르에게 도움을 주기 위해 왔소?"
rows["33:481452779"]="마텍, 같이 갈 수 있어?"
rows["33:570292782"]="너희 스컬지는 실패할 것이다."
rows["33:650919067"]="대단하신 분이 오셨군요! 제가 도와드릴 일이 있으면 무엇이든지 말씀하십시오."
rows["33:685439714"]="개구리와 가죽공을 팔고 있어요!"
rows["33:690648175"]="우욱...$b$b기분이... 좋지 않아요..."
rows["33:708124510"]="물러나지 않으면 두 동강 내 주겠소."
rows["33:738257898"]="녹색용군단이 그대에게 빚을 졌군요."
rows["33:818735960"]="언젠가, 레이제크 강한 전사 될 거다."
rows["33:856113768"]="데락 나이트폴이라 하오. 무엇이 필요하시오!"
rows["33:881843626"]="카엘 다로우에 오신 것을 환영합니다, 이방인이여."
rows["33:923824998"]="트롤식 술래잡기를 할 시간이군요, 친구!"
rows["340:1103272225"]="왕립 연금술 학회를 대표해서 우리 포세이큰의 동지에게 최고로 훌륭한 탈것을 제공하게 되어 기쁘군. 우리는 이놈들을 고된 훈련을 통해서 더 강하게 길렀지. 직접 살펴보면서 확인하게."
rows["340:436511501"]="난 오염된 식물을 네 가지 보았습니다. 노래꽃, 바람꽃, 채찍뿌리, 그리고 어둠용풀이죠. 악령숲에서 노래꽃과 바람꽃은 쉽게 찾을 수 있지만 채찍뿌리와 어둠용풀은 그리 흔하지 않을 겁니다. 하지만 모두 악령숲 생태계에 없어서는 안 될 식물들이지요."
rows["340:461711853"]="스컬지 내 직업의 남자 들 이 자기 적을 사냥하고 죽이는 이천적인 능력 을 연구 하고 자랑 한다. 나 자신 은 이 세상 을 구하기 위해 제 십자군 전쟁 에서 수천 개의 짐승 을 죽였습니다.$B$B저는 그 비참한 성격 때문에 암호 악마를 싫어하지만, 그 능력은 존경할 수 밖에 없습니다."
rows["341:2114140236"]="스톰윈드에 오신 것을 환영합니다! 저는 인구조사국에서 시민을 위해 일하고 있는 공무원입니다. 찾는 사람이 있다면 제가 도와드릴 수 있을 겁니다. 저는 마법과 고도로 단련된 정신력을 이용하여 이 기록들을 조사할 수 있거든요.$B$B제게 용건이 있으시면 언제든지 말씀해 보십시오!"
rows["341:31031107"]="놀랍군요! 아네테론이 그대에게 패한 덕분에 아키몬드의 계획이 지연되었고, 우리는 승리에 그만큼 가까워졌습니다. 하지만 저와 제 병사들은 몹시 지친 상태라 철수해야 합니다. 그대의 힘이 약해지지 않았다면 동쪽에 있는 스랄의 야영지로 가세요. 그곳에서 우린 또다시 항쟁을 벌일 것입니다. 부디 무사하시길."
rows["341:571249295"]="전투대장 이미야르, 선택받은 알가르가 이 감옥 북동쪽에 있는 고통의 성물함에서 바르굴 군대를 이끌고 봉기했다.$B$B나바리우스 왕자는 여기서 동쪽에 있는 죽음의 들판 건너편에 있다. 줄드락 2층으로 올라가는 커다란 계단 근처이다.$B$B스림이 있는 곳은 아직은 파악되지 않았다. 그 덩치를 고려한다면 의아한 일이지.$B$B이 모두 다 처리해야 할 일이다!"
rows["341:770597306"]="흠. 미스릴 형틀은 다 떨어져서 하나도 없어요. 에이미를 고치는 데 그것만 있으면 되나요? 아, 그러면 정말 좋겠네요!$B$B문명이 발달한 곳에서라면 미스릴 형틀을 그리 어렵지 않게 구할 수 있답니다. 솜씨 좋은 기술자에게 하나 만들어 달라고 해보세요. 미스릴 주괴가 몇 개 필요할 테지만 절 도와주신다면 아주 후하게 보상해 드리겠어요!"
rows["342:1139540968"]="무한의 용군단이 아서스 메네실 왕자의 운명을 뒤바꿔 놓으려 합니다.$B$B당신은 그를 리치 왕으로 알고 있겠지만, 지금 이 시대에 있는 그는 왕국을 구하고자 안간힘을 쓰는 로데론의 왕자랍니다.$B$B아서스는 오늘 자신의 운명을 결정하는 선택을 합니다. 우리 시간의 수호자는 이런 사건이 벌어지는 때를 시간의 길 굴절점이라고 부르지요."
rows["342:718338828"]="여관에서 무엇을 할 수 있느냐고요?$B$B여관에서는 아주 편하게 쉴 수 있기 때문에 야외에서 보다 훨씬 빠르게 피로를 회복할 수 있답니다. 피로를 회복한 상태에서 사냥을 하면 경험치를 더 많이 얻을 수 있답니다.$B$B또한 여관주인에게 귀환석을 받을 수도 있는데 이 귀환석을 사용하면 필요할 때 여관으로 되돌아올 수 있습니다."
rows["342:802183307"]="누더기골렘의 이용은 시로나스 님의 생각이셨습니다... 누더기골렘은 사실 그들의 것이었지요. 그는 삼두연합이라던가 뭐라던가 좌우간 그 비슷한 이름을 가진 드레나이 행정 조직의 고위 계급의 일원이었습니다.$B$B누더기골렘의 정체가 무엇이건 간에 그것은 거대하고, 강력하고, 분노로 가득 차 있습니다. 누더기골렘이 근처에 있는 한 벡터 코일에 공격은 대부분 실패로 돌아갈 것이 확실합니다."
rows["342:828447850"]="첫 번째 재료는 고대 학카리 휘장이요. 학카르 부족의 가장 강력한 지휘자인 진도와 혈군주에게서 얻을 수 있지.$B$B두 번째는 구멍 난 부두 인형인데, 타락한 이 땅의 이곳저곳에 버려진 쓰레기 더미를 뒤져보면 찾을 수 있을 거요. 특히 불길한 흑마술 더미 안을 눈여겨 보시오.$B$B이 두 가지 재료를 모두 가져오면 당신에게 강력한 마법을 허락하겠소!"
rows["343:1509702714"]="<억지로 웃음을 짓는 사로잡힌 태양매 첩보원>$B$B걱정하지 마십시오, 동지여. 차원문 제어기는 아직 많이 있고 문을 설치하기에 적합한 장소도 많으니까요. 시로나스 님께서 빠른 시일 내에 새로운 문을 여실 겁니다. 이 파란 피부의 잡종들은 이 세계에 그리 오래 머물지 못할 테니까요. 시로나스 님과 누더기골렘이 태양매 군대가 남기고 간 것을 모조리 쓸어 없애실 겁니다."
rows["343:205895247"]="저는 성벽 위에서 일하는 알도르 사제회의 모습을 쭉 지켜봤어요. 그들은 도시 전체를 재건할 거예요.$B$B늙은 현장감독 오슬로가 호숫골에 있는 집을 재건했을 때보다 훨씬 더 빠른 속도로 작업하고 있어요. 그는 늘 연장을 호수에 빠뜨리거나 놀에게 보급품을 빼앗기곤 했죠.$B$B알도르 사제회에 그를 도와줄 일손을 좀 보내달라고 부탁해야겠어요. 알도르 사제회에서 그 다리를 수리했다면 순식간에 끝났을 거예요."
rows["344:108016146"]="스톰윈드의 친구여, 스톰윈드에서는 당신의 도움과 관대한 마음을 필요로 하고 있습니다!$B$B한때 그 많던 옷감 재고가 위태로울 정도로 바닥나 버렸습니다. 스톰윈드에서는 옷감과 붕대 생산을 위해 그 재고량을 다시 보충하기 위해 여러 각도의 노력을 기울이고 있습니다! 옷감을 기부하면 스톰윈드에 큰 도움이 될 뿐만 아니라 시민들의 존경도 받게 될 것입니다!"
rows["344:1132956675"]="<당신 앞에 꿈과 같은 이세라의 환영이 떠 있습니다. 그녀의 주의는 분산된 상태입니다. 잠시 후, 그녀가 당신을 보며 입을 엽니다.>$B$B오랫동안 아비아나는 내 꿈의 주위를 배회했다. 그녀가 과연 우리에게 돌아올지 확신할 수 없었지. 시간이 지나면서 그녀의 영혼이 혹시 어둡게 물든 건 아닐까 두렵구나...$B$B하지만 지금은 하이잘 산의 운명을 결정할 더 중요한 일들이 우릴 기다리고 있다."
rows["344:1264596405"]="<웃음 짓는 대모 게야>$B$B물론 아니라네, 젊은이. 하지만, 믿음을 가져야 할 쪽은 내가 아니야...$B$B가로쉬는 강하고 현명하여 마그하르를 이끌 수 있다네. 모든 정령도 그를 인정하고 말이야. 지금 가로쉬가 자기 자신을 믿으면 돼. 그는 두려움이 너무 많아... 자기 자신을 풀어주면 분노가 자신뿐만 아니라 주변의 모든 것을 집어삼켜 버릴까 봐 두려워하고 있다네."
rows["344:1413588683"]="이중 전문화란 두 개의 활성화된 특성 설정을 유지할 수 있도록 도와주는 기능입니다. 이중 전문화를 사용하여 두 특성을 손쉽게 전환할 수 있습니다. 1특성에서 2특성으로 전환하면 그에 따른 문양, 행동 단축바를 사용할 수 있습니다. 전투 중에는 특성을 전환할 수 없으며, 특성을 전환하면 사용할 수 있는 마나, 분노, 룬 마력, 기력 등이 소모됩니다."
rows["344:1477894292"]="여군주 실바나스 님께서 잴라, 그리고 용아귀 부족과 호드 사이의 연락을 총괄하라고 내게 직접 지시를 내리셨네. 추측건대 실바나스 님과 새 대족장 가로쉬는 둘 사이에 생긴 골을 메우려고 애쓰는 것 같네.$B$B어쨌든, 우리를 위협하는 황혼의 망치단을 완벽하게 끝장내야 하네. 가장 중요한 건 초갈이 궁극의 무기를 만들지 못하게 막는 것이지."
rows["344:380273283"]="성공입니다! 탐지기를 지옥불 성채의 마력에 맞춰서 조정했습니다. 정말 강력한 힘이군요!$B$B그곳에는 타락한 오크들이 헤아릴 수 없이 많습니다... 하지만, 그게 전부가 아닙니다! 성벽 안에서 악마의 힘이 느껴집니다...$B$B당신이 마음을 열면 제가 당신의 정신을 붙잡아서, 간단히 말해서 당신을 조종해서 양피지에 예언 결과를 적어드리겠습니다."
rows["344:572832149"]="이 얘기도 하면 안 되는 건데, 황야의 땅에 있는 짐승과 괴물을 모조리 물리칠 수만 있다면 이글거리는 협곡에 갈 수 있습니다.$B$B맞아요! 황야의 땅 말입니다. 카르가스 근처에 오크들이 닦아놓은 뒷길 같은 게 있어요. 우리가 상대하는 적이 얼마나 바보인지 아시겠죠! 지옥으로 들어가는 뒷문이라니? 도대체 생각이란 게 있는 족속들인지..."
rows["344:581958211"]="나는 돌아가신 수호자 메디브 님의 제자였던 카드가라고 하오. 당신도 그분의 이름을 들어본 적은 있을 거요.$B$B메디브 님이 악마 살게라스의 지배를 받고 있으며 이 세계와 아제로스를 연결하는 어둠의 문을 열었다는 사실을 밝혀낸 것이 바로 나요. 정말 존경했지만 그분의 고통받는 영혼을 구원하려면 스승님을 죽일 수밖에 없었소."
rows["344:691446647"]="\"타우렌어?\"$B$B타우렌 드루이드가 기대에 가득 찬 눈길로 당신을 바라보지만, 그녀와 의사소통을 할 수는 없는 게 분명합니다. 하지만 그녀는 아무렇지 않은 듯 손가락으로 자신을 가리키며 미소를 지어 보이더니, 이번에는 당신을 가리키며 한 번 더 미소를 지어 보입니다. 그리고 마지막으로 남쪽으로 난 길을 여러 번 가리킵니다.$B$B혹시 이 길을 따라가면 언어가 통하는 드루이드가 있다는 뜻일까요?"
rows["344:709448891"]="성난발톱 투르라고 하는 펄볼그였다. 여기 펄볼그가 아니었지.$B$B그는 남쪽 대륙에서 왔었다. 나무구렁 부족에 속한 자였지.$B$B그는 내 아버지, 우르속을 보고 싶어했다. 타락한 볼드랏실을 정화해 아버지를 구해낼 수 있다고 생각하는 것 같더군.$B$B그런 희망을 품다니 어리석기 그지없다. 아버지를 변하게 한 암흑이 어떤 것인지 안다면, 너도 내 말에 동의할 게다."
rows["344:829337757"]="잠깐, 어딜 그리 바삐 가시오? 그대는 물건을 전달해야 하지 않소? 일은 해야지... 그러면 되지 않겠소? 용아귀 부족의 줄루헤드라고? 물건이 그에게 갈 거요. 일리단 님께는 해그늘 블러드 엘프들이 성심껏 협조해서 명령 수행에 큰 어려움이 없었다고 말씀드려 주시오.$B$B내가 직접 암흑의 인도자 루울을 보내서 조각을 전달하겠소!$B$B루울, 내 말 잘 들었지?"
rows["345:1363571504"]="내가 마지막으로 전당에 있었을 때 갈퀴대왕 이키스가 권력의 상징인 테로크의 깃창을 가져갔습니다.$B$B내 형제 흑마술사 시스는 우리의 의식이 진행되는 동안 테로크의 가면을 쓰고 있었습니다.$B$B테로크의 전설의 경우에는 정확하게 어디에 있는지 알아낼 방법은 없지만 보통 둥근 지붕의 대전당 안에 있는 룬 마법진 중 한 곳에 보관했습니다."
rows["345:1586150470"]="<웃음 짓는 대모 게야>$B$B물론 아니라네, 젊은이. 하지만, 믿음을 가져야 할 쪽은 내가 아니야...$B$B가로쉬는 강하고 현명하여 마그하르를 이끌 수 있다네. 모든 정령도 그를 인정하고 말이야. 지금 가로쉬가 자기 자신을 믿으면 돼. 그는 두려움이 너무 많아... 자기 자신을 풀어주면 분노가 자신뿐만 아니라 주변의 모든 것을 집어삼켜 버릴까 봐 두려워하고 있다네."
rows["345:1741854875"]="<고위검사 페어뱅크스는 머리를 흔들고>$B$B아니... 그는 뒤에서 서, 죽은 무사들의 군대가 우리 위에 내려오는 것을 지켜보고 있었습니다. 얼마 지나지 않아, 제 힘이 마쳤어요. 나는 먼저 쓰러졌어요. "
rows["345:1820925200"]="이봐요, 척 보니 제게 미스릴 주괴를 가져다 주려고 여기 오셨군요. 안퀴라즈의 실리더스 사막에서 벌어질 격전이 임박했어요. 우리와 얼라이언스 모두 벌레들을 막기 위해 총력을 다하고 있죠. 모두들 여기 모인 이유도 바로 그것 때문이죠.$B$B호드는 제게 $2009w개를 모아 달라고 부탁했는데 제가 가지고 있는 건 $2008w개밖에 없어요. 그러니 절 좀 도와주셔야겠어요. 안 도와주실 건가요?"
rows["345:2036018795"]="육체의 소유자여, 에테리얼에 대해서 뭘 알고 있소?$B$B서로 다른 종족 간의 전쟁임에도 불구하고 당신은 우리를 모두 같은 시각으로 바라보는군.$B$B이제 소개를 할 시간이 된 것 같군. 나는 자유연합의 사령관 야미르라고 하오. 또한 이 지역에 있는 공허의 생물과 에테리움을 처리할 수 있는 유일한 희망이기도 하지."
rows["345:678781048"]="나는 비명을 지르고 싶었지만 단지 헐떡거리는 낮은 소리만이 내 입술 밖으로 새어 나왔을 뿐이다. 나의 이런 반항적인 행동은 즉시 폭력으로 다스려졌다. 바닥에 쓰러져 있을 때 나는 사루안의 시체 앞을 걸어다니는 마티스의 모습을 볼 수 있었다. 그는 분명 걱정이 있어 보였다. 그는 만약 사루안이 구타 때문에 죽은 것이면 시로나스인지 시로나인지 하는 자가 자기를 뼈만 남도록 벌을 줄 거라고 했다."
rows["346:1435884279"]="\"타우렌어?\"$B$B타우렌 드루이드가 기대에 가득 찬 눈길로 당신을 바라보지만, 그녀와 의사소통을 할 수는 없는 게 분명합니다. 하지만 그녀는 아무렇지 않은 듯 손가락으로 자신을 가리키며 미소를 지어 보이더니, 이번에는 당신을 가리키며 한 번 더 미소를 지어 보입니다. 그리고 마지막으로 남쪽으로 난 길을 여러 번 가리킵니다.$B$B혹시 이 길을 따라가면 언어가 통하는 드루이드가 있다는 뜻일까요?"
rows["346:1923864930"]="수천 명으로도 모그레인 님을 상대하기엔 역부족이었소.$B$B<잠깐 웃었다가 생각에 잠기는 페어뱅크스>$B$B수천 명이 달려들었지만 모두 모그레인 님의 손에 쓰러지고 말았지! 위대한 빛의 힘으로! 달려드는 족족 그분의 검에 쓰러져나갔소. 그 아비규환의 와중에 난 모그레인 님의 아들이 먼 곳에서 지켜보고 있다는 걸 알게 되었소. 난 그에게 소리쳤지. \"르노, 어서! 아버지를 도와야 하지 않는가!\""
rows["346:431259119"]="용의 입은 여기 황야의 땅에 얼라이언스가 거점 확보를 위해 처음으로 자리 잡은 장소입니다. 스톰윈드와 던 모로 사이에 있음에도 황야의 땅은 예전부터 호드의 영토였지요.$b$b이제 변화를 가져오려면 우리의 의지를 확고히 다져야 해요. 신 카르가스를 공격 중인 용들도 우리가 목적을 달성하는 데 방해가 되지는 않습니다."
rows["346:465033036"]="진심으로 묻는 거요? 정말 모른단 말이오?$B$B겁이 많은 편이라면 불타는 평원과 이글거리는 협곡에 사는 생물들에서 검은무쇠 조각을 찾는 것이 좋을 거요.$B$B유혈이 난무하는 모험을 즐기는 편이라면 검은바위 첨탑과 검은바위 나락의 던전으로 가시오. 엄청난 양의 검은무쇠 조각을 얻을 수 있을 것이오."
rows["347:12823777"]="<노인의 숨은 가슴에 떨고 있지만 의자에 대한 잡힘은 여전히 철로 만들어졌습니다.>$B$B또 다른 젊은이가 늙은 제킨스를 보러 왔어요? 스톰윈드 오크가 왔을 때 그리고 그 이후의 모든 전쟁에서$B$B내같은 사람들에게는 끝이 조용하게 다가오고 싶어"
rows["347:1540628376"]="먼저, 한 개의 다크월 게임 토큰을 대가로 펠렛 총을 줄게요$B$B그 다음엔 발광하는 표적을 쏴요$b$b발광 직후 목표물을 타는 데 충분히 빠르면 승점도 더해집니다.$b$b만약 당신이 그 시간까지 점수 한계를 달성하지 못하거나, 상자에서 벗어나면 걱정하지 마세요. 점수는 다음 경기에 전달됩니다."
rows["347:1562529600"]="젊은 $c|1이여;여;, 아는 것이야말로 진정한 힘입니다. 그대는 현명하니 앞으로도 많은 것을 배울 수 있을 것이며, 그대보다 아는 것이 많은 이들에게도 귀를 기울일 줄 알게 될 겁니다.$B$B태양샘이 파괴되기 전, 우리는 어리석게도 완벽한 문명의 정점에 도달했다는 자만심에 빠져 있었습니다. 그 때문에 스컬지에게 무릎을 꿇고 말았죠. 어떤 면에서 보면 현실에 눈을 뜨는 계기가 되었지만요."
rows["347:182661443"]="어둠의 문이 열리면서 우리 종족의 운명에 대한 소식을 들었어요. 어떤 면에서는 추방당한 덕분에 종족과 함께 몰락하는 것을 피한 셈이죠. 하지만, 원정순찰대가 캘타스와 한 패가 된 모습을 볼 때면...$B$B한때는 나의 형제였던 자들이 그런 일을 할 수 있으리라고는 정말이지 꿈에도 생각하지 못했어요.$B$B제가 꿈꾸던 귀향은 결코 없을 거예요. 이 숲이 저의 마지막 안식처입니다."
rows["347:212569020"]="비극적이게도, 악마의 군주와 그 부하들의 결속을 봉해버린 것은 스랄의 지혜였지. 여기에 트레보르의 군대가 악마의 군주와 어둠혈맹, 그리고 오우거들을 단결시키는 역할을 했어. 스랄은 지도자들에게 무한한 힘과 불멸의 습격 부대를 주겠다는 것을 미끼로 삼아 거래를 피로 봉했다네."
rows["347:252978774"]="하지만 그것으로도 부족했지.$B$B<페어뱅크스가 기억에 잠긴 듯 잠시 씁쓸하게 웃습니다.>$B$B천 명이 몰려왔고 천 명이 죽었다. 빛이시여! 모그레인의 힘이여! 놈들이 달려드는 족족 베어 넘겼지. 혼란 속에서 난 젊은 모그레인이 아직 멀찍이 서 있는 걸 봤다. 난 외쳤어. \"도와라, 르노! 네 아버지를 도와, 이 녀석아!\""
rows["347:611382472"]="그의 이름은 베레디스였네. 훈련의 일부인 잔혹한 통과 의례를 수행하는 데 성공했을 뿐만 아니라 경험이 더 많은 악마사냥꾼을 상대로 강력한 통솔력을 발휘하자 일리단은 깜짝 놀랐네.$B$B베레디스의 잠재력을 깨달은 일리단의 명령으로 전문 악마사냥꾼 셋이 그의 훈련을 전담하게 됐지."
rows["348:1848917538"]="저 옆에 스카이리는 정말 아릅답지 않나? 우리 사령관님의 믿음직한 그리핀이지. 쿠르드란께서는 성채에서 접견 중이시지. 쿠르드란께서 바쁘실 때는 내가 스카이리를 돌보고 있지. 스카이리는 강하면서 거친 정말 멋진 생물이야. 스카이리는 쿠르드란 님을 위해서라면 제 목숨이라도 바칠 걸세. 이렇게 충성심이 강한 녀석은 처음 본단 말이야.\010\010스카이리를 돌보는 것은 명예로운 일이라네. 암, 그렇고말고."
rows["349:1643672999"]="저 옆에 스카이리는 정말 아릅답지 않나? 우리 사령관님의 믿음직한 그리핀이지. 쿠르드란께서는 성채에서 접견 중이시지. 쿠르드란께서 바쁘실 때는 내가 스카이리를 돌보고 있지. 스카이리는 강하면서 거친 정말 멋진 생물이야. 스카이리는 쿠르드란 님을 위해서라면 제 목숨이라도 바칠 걸세. 이렇게 충성심이 강한 녀석은 처음 본단 말이야.\010스카이리를 돌보는 것은 명예로운 일이라네. 암, 그렇고말고."
rows["349:1732257076"]="카엘타스에게 복수를 치겠습니다. 키린 토르에 대한 분노를 위해요.$B$B심판이 있을 것이라$B$B<아크마지스는 시원하게 진부하며, 전망에 만족하지 않는다.>$B$B카엘타스는 단순한 악당 마법사일 뿐 아니라 내가 탑에서 해방되면, 라반드루와 나는 그를 반대하는 모든 사람을 도울 것이다."
rows["349:1897652667"]="끔찍해요! 전 이렇게 쓸모없이 앉아만 있어서는 안 됩니다. 할 일이 얼마나 많은데! 노스렌드에서 이 팔을 다치지만 않았다면... 하긴, 그런 생각에 빠져 있을 필요는 없겠죠! 당신이 상처를 꿰매고 치료해 주실 테니까요. 그동안 우리는 이 근처에 도움의 손길을 펼치겠지요. 전방에 있지 않다고 도움을 제공할 방법이 없는 건 아니니 말입니다."
rows["349:340322351"]="하이잘 산의 계곡과 봉우리를 넘고, 실리더스의 흐르는 모래를 지나... 우리는 불타는 군단의 무서운 악마와 싸워 왔소. 우리는 이름도 없고 얼굴도 알려지지 않은 얼라이언스의 아들딸이라오. 빛과 얼라이언스의 이름으로, 우리는 최초의 공격을 감행할 것이며, 적들은 최후의 일격 속에 죽어갈 것이오.$B$B우리는 7군단이오."
rows["349:632996263"]="\"다르나서스어?\"$B$B나이트 엘프 드루이드가 기대에 가득 찬 눈길로 당신을 바라보지만, 그녀와 의사소통을 할 수 없다는 것이 명백합니다. 하지만 그녀는 아무렇지 않은 듯 손가락으로 자신을 가리키며 미소를 지어 보이더니, 이번에는 당신을 가리키며 한 번 더 미소를 지어 보입니다. 그리고 마지막으로 북쪽으로 난 길을 여러 번 가리킵니다.$B$B혹시 이 길을 따라가면 얘기를 나눌 수 있는 드루이드가 있다고 얘기하는 것일까요?"
rows["34:1044463950"]="나의 상관에게서 올 명령서를 기다리는 중이오!"
rows["34:114429794"]="<지구들은 미묘한 에너지로  ⁇ 니다>"
rows["34:1171672064"]="아드릴리아 여인을 만나러 왔나요?"
rows["34:1194181119"]="파이너스는 당신이 원하는 거 갖고 있어요."
rows["34:1202032539"]="여관에서 푹 쉬시면서 지친 몸을 달래시기 바랍니다."
rows["34:1314638921"]="네.$b$b그거 정말 좋은 생각이네요."
rows["34:1351287384"]="하르거스에게 물건을 사러 오셨군요, 그렇죠?"
rows["34:1408318913"]="바쉬르로 돌아가시겠습니까?"
rows["34:1478460675"]="안녕하세요!! 도움이 좀 필요합니다만…"
rows["34:1617925024"]="우리에게 남은 건 아무것도 없습니다."
rows["34:164713960"]="나에게서 떨어져, 이 괴물아!"
rows["34:1663583492"]="꽤액! 널빤지 흔들어! 흔들어!"
rows["34:1684309937"]="청동용군단이 빚을 잔뜩 져버렸네요."
rows["34:172156342"]="몸서리는 항상 농부 되고 싶었다."
rows["34:1848401965"]="오늘 고대로부터 이어져 온 원한이 풀릴 겁니다."
rows["34:1933175763"]="즐겁고 풍족한 명절 되라고!"
rows["34:1939554153"]="암흑의 시기가 모습을 드러내고 있습니다, 이방인이여..."
rows["34:1982684482"]="오늘 모르고르의 독재는 끝납니다."
rows["34:2009274641"]="<당신의 손을 쪼아대는 바위매>"
rows["34:2037432634"]="다시 잃지 마"
rows["34:251933552"]="요청해야 할 물품이 있으시오?"
rows["34:314802635"]="누구라고! 내 눈앞에서 꺼져라!"
rows["34:35597271"]="감독님께서 여기 계시다고요?! 따로 작전이 있나 보네요."
rows["34:393146883"]="스톰윈드와 린 폐하께 영광 있으라!"
rows["34:480889829"]="아니, 당신과는 얘기할 생각이 없어요!"
rows["34:671091685"]="헬스크림 님께서 우리 모두를 지켜보신다!"
rows["34:717187500"]="누구... 시죠? 너무... 추... 추워요."
rows["34:727012947"]="우리... 아이들을... 구해줘..."
rows["34:886688309"]="젊은 용사여, 브웸바는 언제나 당신을 지켜봅니다."
rows["34:950807311"]="아제로스를 구해주지 않겠나?"
rows["350:1131793880"]="하이브레갈에 다시 가 달라고 했다네! 브란 님은 한동안 말이 없다가 군대의 지원 없이는 하이브레갈에 들어갈 방법이 없다고 하셨지. 그때는 하이브레갈이 더 위험한 곳으로 변해 있었으니 말이야. 그 끔찍한 벌레들의 수가 우리가 처음 들어갔을 때보다 3배는 많아진 것 같았지.$B$B그 말을 듣자마자 나탈리아가 갑자기 미쳐 버렸네!"
rows["350:1147737201"]="순례자의 보물을 최적화하는 데 필요한 물적 요소는 매우 놀랍습니다. 수많은 원료, 많은 노동, 수천 개의 상자, 수천 개의 완성품이 여기 저기 그리고 모든 곳에서$B$B솔직히, 저는 꽤 인상적이어서 배고프네요... 난  ⁇ 두파이의 냄새를 맡을 수 있어요."
rows["350:121937137"]="난 내 아버님을 위해 일하고 그분의 계획을 존중하오... 하지만 나 자신의 정의를 위해 일한다오. 난 수천 권의 책을 채울 정도로 내 검은바위 형제들이 벌인 배신행위를 충분히 봐 왔소이다. 그리고 이제 그들은 붉은마루를 공격하려고 하오. 눈먼 토지 점유욕에 지나지 않는 이유로 말이지.$b$b배신행위는 이쯤에서 끝나야 하오. 이제 결말을 내야 할 때란 말이오. 그 결말이 좋게 끝나진 않을 거요."
rows["350:189094390"]="총, 다이노amit, 폭탄, 폭발하는 양... 사랑하지 않는 것은 무엇입니까? 무역의 머리의 이러한 그리고 다른 많은 흥미로운 도구를 만드는 방법을 배우기 위해 언더시티, 브릴 남쪽의 로데론의 유적 아래. 유적의 뒷부분에서 엘리베이터를 가져. 도착하면 언더시티 보호자 중 한 명에게 트레이너가 정확히 어디에 있는지에 대해 이야기하십시오."
rows["351:1308968881"]="멍청한 녀석, 그건 힘이다.$B$B<노기를 띠고 째려보는 마타우스>$B$B예전의 영광을 되찾는 일에만 급급한 여기 바보들은 너같은 멍청이를 낙스라마스로 보낼 모양이야. 모독받은 그 갑옷을 되찾아 정화할 셈이겠지...$B$B<침을 뱉는 마타우스>$B$B그런 멍청한 생각을 하다니 참을 수가 없군.$B$B나 역시 그 갑옷을 찾아봤지만 아주 사악하고 더러운 상태였다."
rows["351:1573284756"]="*말하기 전에 티라시스는 당신을 위로 내려다보며*$b$b 내가 누군지는 중요하지 않습니다. 우리가 협상할 수 있다면 중요한 것은...$b$b 하지만 방영하지 마세요, 저는 극히 제한된 재고로 에더에서 새로운 물건을 하루에도 여러 번 끌어내려요."
rows["351:1607016854"]="이 웅장한 멜리호에 타신 것을 환영합니다. 저는 이 배의 선장인 토골리라고 합니다.$b$b이 배와 관련해서 궁금하신 게 있으시다면, 편하게 말씀하십시오. 더 하실 말씀이 없으시다면, 부디 이번 여행을 즐겨 주시기 바랍니다. 제가 늘 즐겁게 여행하듯이 말이죠... 제가 좋아하는 구절 하나 말씀드리자면 이렇습니다.$b$b배에 대한 경험이란 그 위에 올라 세상을 흥미롭게 발견해 나가는 것이다. 무언가가 없어도 완벽히 해나갈 수 있음을 발견하는 것이다."
rows["352:273156698"]="브루페스트에서 더 많은 배가 필요해$b$b내 개인적인 양떼 중 한 마리에게 줄임수를 빌려줄게$b$b매번  ⁇ 을 가져오면, 몇 개의 토큰을 줄게 되는데,  ⁇ 을 더 오래 사용하게 해 줄게 되죠.  $B$B일단 시작하면 내일까지 다시 할 수 없을 거야$B$B이 일을 할 준비가 됐는지 확신하십니까?"
rows["352:725833873"]="그대가 처음으로 들어온 곳인 제 뒤쪽에는 뜨거운 공기를 위로 올려보내 이곳 밖으로 내보내는 커다란 열기 배출구가 있습니다. 배출구 맨 위에 서서... 뛰어오르십시오! 도약의 여력으로 충분히 꼭대기까지 올라갈 수 있습니다.$b$b아, 하나 더 말씀드릴 게 있습니다. 동료 드루이드의 보고로는, 꼭대기로 빠져나갈 때 머리를 부딪치지 않도록 조심하라더군요."
rows["353:933872544"]="죄송하지만, 저는 스톰윈드의 왕국에 적어도 높이 평가받지 않은 개인에게 말을 팔지 않겠습니다. 이 말들은 어디서나 찾을 수 있는 가장 훌륭한 말들입니다. 그리고 우리는 확실히 그들을 우리의 적들의 손에 넣고 싶지 않습니다.$B$B네, 네, 네. 네, 네. 스톰윈드 그리고 나서 사업을 할 수 있습니다."
rows["354:1004473658"]="세상을 파괴한 그 대재앙 이후 남은 것은 이 책뿐입니다. 무한한 힘을 가진 우주의 존재를 지배하려던 어리석은 자들...$B$B이 책을 얻은 당신도 그들과 같은 전례를 반복할 것입니까?$B$B이 부정한 책에 조심스럽게 언급된 울림 또는 또 다른 강력한 존재를 소환할 방법이라도 고안해 냈습니까?$B$B두고보면 알겠지요."
rows["354:1248800002"]="왜 자꾸 죽었다고 하는 거요? 죽었다고 누가 그랬소? 난 그분이 죽었다고 말한 적 없소이다. 실종된 것뿐이오.$B$B우리는 분명 오크와 검은무쇠 드워프 간에 벌어진 전쟁에 휘말려 든 것 같았소. 그 망할 놈의 오크 녀석들은 일찌감치 당신도, 나도 이해하지 못할 덫을 놓고 사악한 함정을 파고 있었던 거요."
rows["354:201375936"]="보석은 주로 보석 추출을 통하여 얻을 수 있습니다! 보석 추출을 하려면 여러분의 마법책의 전문 기술란에 있는 보석 추출 기술을 눌러 소지품에 있는 광석 5개에 사용하면 됩니다. 흔히 볼 수 있는 어떤 광석이든 가능합니다!\010\010좋은 광석을 사용하면 더욱 귀한 보석을 추출할 수 있습니다. 따라서 구리 광석보다는 철 광석에서 더욱 희귀한 보석을 얻을 수 있습니다."
rows["354:322921359"]="우리 중 일부는 로아의 사제였네. 바로 잘라제인처럼 전엔 의술사였지...$B$B<젠타브라의 시선이 남쪽으로 향하면서 그녀의 얼굴이 굳어집니다.>$B$B우린 영혼들이 우리에게 화가 났다고 생각했네. 잘라제인이 영혼들에게서 우릴 서서히 단절시키고 있다고 의심하지 못했네. 우린 그가 강하다는 걸 알았지만, 그리 강하리라곤... 그의 부두교 마법이 다른 섬에 영향을 미칠 무렵이 되었을 때, 우린 전혀 그를 막을 수가 없었네."
rows["354:327341976"]="자원 수집이 완료되어 마지막까지 모은 물자를 세나리온 요새로 수송 중인 걸로 알고 있어요. 마지막 수송은 $2113w일 내로 완료될 거고요. 우리 군대와 모든 장비가 그곳에 집결하면 흐르는 모래의 홀을 가진 이가 안퀴라즈 근처에 있는 징을 울려 성문을 열 거예요. 전쟁이 시작되는 거죠."
rows["354:471548820"]="감히 우리에게 도전하다니, 멍청한 악마 같으니. 불타는 군단은 놈의 부패한 시체를 보며 이 일리단 스톰레이지의 강력함을 느낄 것이야.\010$b어둠장막 마법이 약해져서 더는 우리 몸을 숨길 수가 없구나. 숨어다니는 것도 재미있었지만, 사실 난 적에게 죽음을 안길 때 좀 더 거침없이 접근하는 걸 선호하지.\010$b잘 싸워줬다. 하지만 지금부터는 나 혼자 가야 한다."
rows["354:91929976"]="한 가지만 더 말씀드리겠습니다. 자신을 영웅이라고 생각하는 것 같은데, 그렇다면 황야의 땅을 지나 그렇게 소원하는 이글거리는 협곡으로 들어가십시오. 단, 당신의 용맹함을 입증할 증거를 가지고 오도록 하세요. 그러면 생각해보고 당신에게 열쇠를 드릴 수도 있죠.$B$B이글거리는 협곡의 남동쪽 구석에 나만큼이나 힘센 여자가 있어요. 난폭한 마르골이라고 하는데, 가서 한번 만나 보세요."
rows["354:989526629"]="대족장님께서는 내게 모든 종류의 무기와 방어구에 대해 연구하라고 지시를 내리셨소. 타우렌과 오크의 문화가 만나는 이곳 불모의 땅으로 나를 보내, 이 땅의 문화에 대해서 배우고 가능한 한 다양한 여행자를 접해보라고 하셨지.$B$B대족장님께서는 가시멧돼지나 켄타우로스처럼 하찮은 짐승들의 문화에서도 배울 게 있다고 생각하시오."
rows["355:1563195927"]="네, 보네스카이트, 우리 테너인 돈 줄리오라는  ⁇ 이랑이 이 모든 일을 시작하게 해줬어 로데론도누리오는 많은 흥미로운 기술을 습득했습니다. 그 중 하나는 쓰러진 사람들의 뼈를 스컬지 그리고 치명적인 가죽 장갑으로 만들죠. 살인범에게 적합합니다."
rows["356:1354946386"]="우리 Shadowglen의 많은 사람들은 마술을 이용하지만, 저는 그렇지 않습니다.$B$B하지만 제가 여러분에게 한 가지 말씀드리겠습니다. 이 고대 숲을 보호하는 방법은 하나 이상의 방법이 있습니다.$B$B다른 사람들은 미스터리한 힘을 불러오지만 저는 활을 숙달했고 나무를 가로지르는 그림자처럼 움직일 수 있었습니다.$B$B만약 여러분이 순찰자의 길을 찾고 있다면, 저는 자연이 어떻게 여러분의 가장 위대한 동맹이 되는지를 보여드릴 수 있습니다."
rows["356:1572975758"]="여기 임무 하나를 맡으시면, 산양을 한 마리 빌려드립니다. 그냥 빌려드리는 거라서 계속 탈 수 있는 게 아니랍니다. 산양이 좀 느린 것 같이 보일 수도 있지만 그럴 때는 고삐를 조금 늦추면 제 속도를 낼 겁니다.$B$B우리 산양은 사과를 좋아한답니다. 길에 사과가 담긴 통을 몇 개 놨으니 지나가면서 꼭 챙겨가십시오. 사과를 먹이면 녀석은 피곤한 것도 모르게 될 겁니다."
rows["357:1475651601"]="네, 멜리호가 바로 이 배의 이름입니다, 정말 좋은 배죠.$B$B아시겠지만 이런 배는 여러 가지를 배우게 된답니다. 어떤 훌륭한 시인이 이런 말을 했었죠. '밤에 움직이는 배는 신호 하나만을 켠 채 어둠 속에서도 들리는 목소리만 가지고 멀리서 서로 지나쳐갈 때 대화를 나눈다.' 삶의 바다라는 것도 그렇지요. 누군가와 스치고 지나가고 대화를 나누지만, 보기만 하고 목소리만 듣는 거지요. 그리고 그 후에는 다시 어둠이, 침묵이 밀려오는 거랍니다."
rows["357:1682272112"]="솔직히, 이들처럼 계속 붙잡히는 것도 능력이라고 봐. 정말 엄청난 집단 무능력 말이야. 진심으로 그렇게 생각해!$B$B고블린이라는 게 부끄러울 정도지.$B$B부끄러움 얘기가 나와서 말인데, 게을러빠진 우리 조수는 어디 있어? 어딘가 철퍼덕 앉아서 아무것도 안 할 게 뻔해.$B$B아, 정말이지 천재란. 우리 모두 이 궁지에서 벗어날 방법을 생각해내는 건 나 혼자만의 몫인가 봐."
rows["357:17517139"]="그렇다네. 자네가 약초채집 기술이 있다면 더 큰 보람을 얻을 수 있을 걸세. 귀한 씨앗을 기르고 재배하는 일은 도끼나 휘두르고 지나가는 그림자에 대고 손짓 발짓하는 일과는 다르거든. 늘푸른 주머니만 있으면 아무리 둔한 자라도 뭔가 길러낼 수 있긴 하지만, 약초학에 소질이 좀 있다면 더욱 풍성한 수확을 거둘 수 있을걸세."
rows["357:859034259"]="뭘 하는 것처럼 보입니까? 우리가 이주할 땅을 손보는 중입니다. 전부 다 제 손으로 직접 말이죠!$B$B이 숲 속에 작전 기지를 만들어 놓으면 샤트라스, 알레리아, 돌망치, 세나리온의 드루이드들이 무슨 계획을 꾸미고 있는지 한결 쉽게 알아낼 수 있겠죠. 아킨둔의 기지에서는 몹시 불편할 거예요.$B$B그런데 우리가 아는 사이였나요?"
rows["358:1002455865"]="보석은 주로 보석 추출을 통하여 얻을 수 있습니다! 보석 추출을 하려면 여러분의 마법책의 전문 기술란에 있는 보석 추출 기술을 눌러 소지품에 있는 광석 5개에 사용하면 됩니다. 흔히 볼 수 있는 어떤 광석이든 가능합니다!\010좋은 광석을 사용하면 더욱 귀한 보석을 추출할 수 있습니다. 따라서 구리 광석보다는 철 광석에서 더욱 희귀한 보석을 얻을 수 있습니다."
rows["358:1004975521"]="그 곰은 갈퀴자국 토굴길 근처의 길을 서성거린답니다. 갈퀴자국 토굴길은 미스트랄 호수와 실바람 산장에 있는 얼라이언스 전초기지 서쪽에 있지요. 그 곰은 잿빛 골짜기 사냥 대회의 동물 세 마리 중에서 가장 쉬운 녀석입니다. 그러니 당신은 녀석과 꼭 한 번은 만나겠지요. 쉽게 볼 놈은 아니란 걸 기억하시고 조심하시기 바랍니다. 사실 그 녀석은 잿빛 골짜기와 돌발톱 산맥 사이를 오가는 여행자들에게 위협이 되는 존재이거든요."
rows["358:1539687713"]="애송이 녀석, 나는 허세 따위는 부리지 않는다. 그런 암흑의 갑옷을 지니고 있으면 우리 둘을 해치우는 건 일도 아니란 말이지. 가격이 아주 비싼 것도 바로 이 때문이다. 만약 내가 죽어 대신 갑옷을 차지하는 녀석은 아주 부자가 되겠지.$B$B사실, 네가 어떻게 죽든지 놀의 침 방울만한 눈물도 흘리지 않을 테지만, 시키는 대로만 해! 내가 말하는 재료를 가지고 와라. 그럼 우리 모두 이득을 보게 되는 거야. 이미 말했다시피 불복종은 곧 죽음이다..."
rows["358:1892978715"]="저는 자유연합의 공격대장 세이드라고 합니다. 옆에 서 있는 병사들은 저의 복수자들입니다. 우리는 공허의 수송관을 파괴한 육체의 소유자의 명령을 기다리고 있습니다. 그의 명령에 따라 우리는 디멘시우스의 둥지로 진군하여 최종 공격 명령을 기다릴 것입니다!$B$B이 시간이 오기까지 아주 오랜 시간이 흘렀습니다만... 곧 공허의 군주는 우리의 단합된 힘에 맞서야 할 것입니다!"
rows["359:1564394874"]="골드린은 고대 늑대정령이다. 호드어로는 \"로고쉬\"로 알려져 있는데, 그의 강인함은 전설적이지.$B$B세계수 서쪽에 분지가 하나 있는데, 그곳에 그를 기리는 제단이 있다. 그런데 전쟁이 시작된 뒤로는 제단을 지키던 자들에게서 아무런 소식이 없구나.$B$B우리가 앞으로 나아가려면 먼저 제단을 구해내야 한다. 늑대 고대정령의 행방을 찾아보고, 그의 적을 물리치거라."
rows["359:1782613674"]="자네가 가져온 독극물 견본을 보니 비전 촉매제 하나, 골성 교반기 6개, 그리고 룬무늬 옷감 4개가 필요할 것 같군. 유리질 집중기를 가지고 가면 이곳 역병지대에 있는 해골 언데드에게서 골성 교반기를 구할 수 있다네.$B$B이 물건들을 다 찾으면 그 가마솥에 반작용 물질을 투입할 수 있을 것이야."
rows["359:1932638600"]="안녕하세요, 얼라이언스의 일원이시군요!$B$B저는 가젯잔의 공식 대표로서 이곳에 흩어져있는 가난한 노움들과 스팀휘들 고블린들이 함께 잘 살아나갈 수 있도록 하는 역할을 맡고 있어요! 호드의 새로운 고블린 친구의 존재조차도 마음을 열어 관대하게 대할 수 있을 거고요.$B$B당신이 도와준다면 우리 모두 적절한 합의점을 찾을 수 있을 거예요!"
rows["359:805443155"]="나이트 엘프에 대해 내가 알고 있는 지식에는 한계가 있소. 하지만, 일전에 들은 바로는 오래전 나이트 엘프가 아직 비전 마법의 성스러움을 지키고 있을 당시, 아즈샤라가 그중 가장 뛰어났다고 하오. 그들은 이 아름다운 여인을 여왕으로 받들었소. 하지만 비전술에 중독이 되어버린 여왕은 역사상 가장 파괴적인 사건의 주인공이 되어버렸소이다."
rows["35:1041037415"]="칼을 휘둘러! 모두 베어라!"
rows["35:1051173240"]="뭐야, 좀 바쁘네요"
rows["35:1067093828"]="뭔가? 일하느라 바쁜 거 모르겠나?"
rows["35:1109072121"]="성스러운 빛의 가호가 함께하길."
rows["35:1227500453"]="마지막 기둥 파편은 찾으셨습니까?"
rows["35:1283612347"]="행복한 겨울맞이 축제 되세요!"
rows["35:131535013"]="미안해요, 난 도움말 안해요"
rows["35:1429613154"]="나랑 놀이 하나 할래, 말썽꾼 양반?"
rows["35:1452597982"]="당신 어머니처럼 아름다운 반짝이예요!"
rows["35:1489254479"]="부서진 거라면 이 슬래그트리가 뭐든 고칠 수 있소!"
rows["35:1501123580"]="그렇다면, 불타는 군단이 마음껏 까불도록 놔둬 볼까!"
rows["35:1603890897"]="누구죠? 도대체 원하는 게 뭡니까?"
rows["35:1657267681"]="사냥꾼이여, 훈련을 받으러 온 건가?"
rows["35:1823148984"]="제발 조용히 해라! 우리 아가들 잠들었다!"
rows["35:1843692329"]="오늘은 정말 기나긴 하루로군요."
rows["35:1884906519"]="우와! 너 정말 우리 술 사는 거야?"
rows["35:1887794005"]="이 소란스러운 사태를 도와주러 왔는가?"
rows["35:1973019349"]="비치 돕는다. 고기 사라. 천막에서 쉬어라."
rows["35:2027437066"]="아, 내 달콤한 브랜디, 너무 그리워!"
rows["35:2088674574"]="당신은 훈련을 받을 수 없습니다."
rows["35:2105365875"]="이 이교도은 깊은 트랜스..."
rows["35:248986582"]="왈트의 작업대를 사용할 수 있습니다."
rows["35:256570515"]="전 자라면 무두장이가 될 거예요!"
rows["35:349187541"]="어두운 기운이 돌발톱 봉우리를 사로잡았습니다."
rows["35:465616753"]="꽤액! 그 녀석 배 밑으로! 배 밑으로!"
rows["35:499539210"]="난 고아원에 돌아가고 싶어!"
rows["35:562803474"]="저는 헤그너 럼블샷이라고 합니다. 말씀만 하십시오!"
rows["35:622668263"]="우서 경의 징표를 찾는 일은 잘 돼가고 있소?"
rows["35:858517268"]="멋지고 행복한 연휴되시길 바랍니다!"
rows["35:937124333"]="유니스 버치? 상업 지구!"
rows["35:9969837"]="맛있는 맛을 먹을 수 있는 건 뭐죠?"
rows["360:19274595"]="난 제자들에게 새로운 것을 가르치기 위해 아주 고된 재훈련을 통해서 이전에 배운 것들을 다 잊게 한 적이 많이 있었다네. 이건 매번 할수록 점점 더 어려워지는 일이기 때문에 재훈련을 할 때마다 비용이 점점 더 많이 들지. 내가 자네가 배운 특성을 다 잊어 버리게 해 주길 바라나?"
rows["360:769055613"]="심원의 영지는 평화롭고 여유로운 곳이었다. 항상 생명이 넘쳤지. 천천히 움직였고, 절대 서두르는 법이 없었다. 이 시기에 난 대지와 하나가 되기로 했고, 어느 정도 성공하게 되었지.$B$B시간이 지나, 대지의 수호자가 부상을 당한 채 이곳에 돌아왔다. 처음에 그는 이곳의 균형을 깨지 않았다. 그는 이곳에 머문 적이 있었고, 우리도 그를 알고 있었으니. 본격적인 변화는 황혼의 망치단이 데스윙과 합류하면서 시작되었다."
rows["361:1850165155"]="조그마한 자여, 넌 누구지? 강대한 나 토림에게 와서 이런 말을 하다니...$B$B널... 박살내 버리겠다!$B$B하지만 넌 망연자실한 내 마음에 구원을 주었다. 이곳에 네가 나타난 게 바로 그 신호다!$B$B내가 널 시프와 혼동했던 건 우연이 아니었다. 그녀가 날 기억해 낼까? 전투를 준비해야겠구나.$B$B내 형제의 광기에서 티탄들의 성스러운 땅을 해방하고 시프의 죽음에 대한 복수를 해야겠다!"
rows["361:404920075"]="<눈을 감고 머리를 흔드는 젠타브라>$B$B볼진 님께서 모든 이들에게 도망치라고 하셨지. 우... 우린 부족원들을 너무나 실망시켰기에 볼 면목이 없었네. 그래서 우린 남쪽 야생의 정글 섬으로 도망쳤지.$B$B도망친 첫 번째 밤 우리 중 일부는 야생동물에게 목숨을 잃었네. 우린 도망친 섬의 중앙에 있는 깊은 동굴에서 안전을 찾았지만, 내 꿈은 평화롭지 않았네. 환영을 보았다는 말이네!"
rows["363:1103660911"]="키린바르 마을은 20년 동안 수많은 오크의 공격을 견뎌냈지만 결국 캘타스의 군대에게 무너졌소이다. 자칭 키린 토의 일원이라던 자가 한 명만 빼고 우리 모두를 살해한 것이오.$B$B캘타스는 살아남은 대마법사 바르고스를 보랏빛 탑에 가두고 키린 토 일원은 아무도 접근할 수 없도록 마법을 걸었소이다."
rows["363:1435646473"]="생각보다 상황이 훨씬 좋지 않습니다. 우리 동맹인 포세이큰은 공동의 적 스컬지와 싸우려고 이곳에 왔습니다.$B$B제 말을 믿으셔야 합니다. 포세이큰이 없었다면 유령의 땅은 벌써 사라졌을 것이며 스컬지는 지금쯤 영원노래 숲 전역을 한바탕 휩쓸고 있을 것입니다!$B$B영광스러웠던 과거에 우리 영토였던 땅을 되찾으려면 무엇보다도 그대의 도움이 필요합니다."
rows["363:1535991632"]="미안해, 너...$B$b<크로우의 시선은 죄책감으로  ⁇ 은 사람이 보는 것 같다>$B$b잠시 동안, 나는 당신을 고구려 애통으로 생각했어요.$B$b내가 내 마음대로 수도원에 와서 내 죄를 고백하고, 내 죄의 형벌은 무엇인지 모르겠지만, 내가 한 행위에 대한 형벌은 죽음뿐만이 충분하다는 것을 알고 있습니다.$B$b내가 빼앗은 생명으로"
rows["363:1954156439"]="이 캠프 북동쪽에는 크로시우스라는 강력한 지옥이 있습니다. 니비가 여기 있는 이유입니다. 크로시우스라는 더 큰 지옥입니다. 예상보다 더 오래 지속되었습니다."
rows["363:2094288795"]="감정 따윈 없소. 도덕 따위도 없소. 광신자 따위도 없소.$B$B오로지 빛의 결사단만이 존재할 뿐.$B$B빛의 수호자 우서 경이 은빛 성기사단에 입단한 바로 이 교회에서 나, 빛의 용사 코팩스가 공포를 용기로 바꿀 것이오.$B$B그 무엇도 내 분노를 억제할 수 없소. 붉은십자군도, 은빛 여명회도, 우리 형제들도, 심지어 당신이라고 해도 마찬가지요."
rows["364:1539580294"]="한때 텔레도르는 드레나이 사제들과 순례자들의 피난처였소. 그곳에 살던 사제들을 찾아오는 이들은 거의 없었지.$B$B오크들이 드레나이의 정착지를 공격하자 난민들이 대규모로 도착하기 시작했소. 수도자인 아후른과 다른 이들이 텔레도르를 신전에서 안전한 피난처로 바꿔놓았다오. 나를 포함한 많은 드레나이들이 살아남을 수 있었던 것도 그의 노력 덕분이오."
rows["364:32994330"]="어린 주인님께서 얼마나 야단법석을 하시던지... 꼭 세계의 운명을 그대로 어깨에 짊어지기라도 하신 것 같았을 것이오. 우리 세계에 대해 그런 비뚤어진 관점을 가질 수 있는 건 평범한 필멸의 생명체들뿐이지.$B$B안타깝게도 주인님이 남겨 주신 거라곤 이 빈약한 마법 비밀뿐이라오... 고서나 말도 안 되는 것들뿐이지. 나한테는 이런 시시한 마법이 필요 없지만 당신이라면 흥미가 있을지도 모르겠군."
rows["365:1907321436"]="골두니 오우거 부족은 페랄라스의 숲 상당 부분을 지배하고 있습니다. 그들의 사악한 마법이 주위의 자연에 스며들어 주변 환경은 물론 그곳에 사는 생명체들에게도 해를 끼치고 있답니다.$B$B혹시 페랄라스로 갈 생각이라면 이 오우거들을 조심하세요. 상당히 간악한 데다 강력한 어둠의 마법을 부릴 줄 아는 녀석들이 많으니까요."
rows["365:1915288155"]="스케티스에 있는 반역자 사촌들이 우리에게서 경전을 훔쳐가 조각조각 내서 그들의 초라한 도시에 파묻어버린 이후 충실한 신도들은 수치심 속에 살고 있단다!$B$B내 아들아, 까마귀 신께서 그것을 되찾아오는 자로 너를 지목하시길 빌어라. 얘야, 항상 믿음을 갖고 경전의 말씀을 새기고 예언을 잊지 말려무나. \"까마귀 신께서 적들의 꿈속에서 일어나 세상 밖으로 나오시리라.\""
rows["366:1240942792"]="뭣 때문인지 몰라도 검은무쇠 드워프가 굉장히 화가 났어요. 거의 30분마다 나타나서 맥주통을 다 부수고는 도망간다니까요!$b$b물론 당신과 무슨 상관이냐고 묻고 싶으시겠지요?$b$b이유를 말씀드리죠... 왜냐하면 녀석들이 부수는 맥주통은 공짜 맥주를 제공하는 맥주통이니까요! 제대로 들으셨지요? 공짜 맥주라고요!$b$b그러니 저 드워프 녀석들이 나타났을 때 주위에 계시거든, 맥주통 지키는 데 시간 좀 내 달라고요."
rows["366:871227137"]="이봐, 나도 몰라, 응? 모른다고!$b$b그냥 누가 공기 중에 퍼지는 화학 물질이 담긴 로켓을 만들어 달라고 의뢰하기에, 돈 받고 일했을 뿐이라고. 일은 이미 끝났어. 포장해서, 보내버렸지. 그리고 돈 받아서 기분 좀 내 보려는데 갑자기 자네가 동네방네 나를 쫓아다닌 거야. 나는 그 화학 물질이 뭔지도 모르고, 남은 것도 없어."
rows["367:1077523775"]="내게는 선택의 여지가 없었소. 아니, 적어도 그렇게 생각했었지. 타우릿산이 파괴되는 것을 참고 견디며 우리 국왕 폐하와 그의 백성의 곁을 지키려고 했었소.$B$B라그나로스의 지배를 받은 제왕 다그란 타우릿산은 이 산의 중심부를 뜯어내 버리고 검은바위 첨탑을 세웠소. 우리는 과거 또는... 미래의 그 어느 도시나 요새보다도 강한 드워프 도시를 짓기 위해 쉬지 않고 일했소."
rows["367:1176277133"]="블래스텐하이머 5000 울트라 캐논은 최첨단 단인 발사 장치입니다.$b$b용의 속도에 가까운 속도로 운반되는 이 대포는 항공기 및 연연력으로 세계적으로 유명한 블래스텐하이머 가족의 자랑과 기쁨입니다!$B$B만약 당신이 하늘을 날아다니는 새처럼 자유롭게 날아다니고 싶다면, 맥시마 블래스텐하이머를 찾아라."
rows["367:773856131"]="록타르 오가르! 승리가 아니면 죽음뿐! 바로 우리를 호드로서 묶어주는 말이다. 호드의 모든 용사들에게 있어 가장 신성하고 중요한 믿음이기 때문이다.$B$B나는 내 피와 육체를 호드에 바칠 것이다. 나는 대족장님의 뜻을 실천하는 도구가 될 것이다. 나는 대족장님의 명령을 따르는 무기가 될 것이다.$B$B지금 이 순간부터 내 최후의 순간까지, 나는 이 목숨을 다 바칠 것이다. 호드를 위하여!"
rows["367:784870685"]="매주 낚시왕 선발대회가 열리는 무법항에 오신 걸 환영합니다!\010\010대회가 시작되면, 가시덤불 골짜기 전역의 낚시터에서 맛둥어를 낚을 수 있습니다."
rows["367:886416922"]="우리 형제들은 강하다. 하지만 소극적이지.$B$B변화라는 것은 행동, 논쟁, 그리고 폭력 없이는 일어나지 않는 법이다. 우리 적들이 이를 이해하는지는 모르겠으나, 어쨌든 그들은 이에 맞게 행동한다. 하지만 우리 형제들은 소극적인 본성 때문에 이 새로운 적 앞에서 약해지고 있지.$B$B나는 그렇지 않다. 나는 변화가 두렵지 않다. 나는 대지를 가르고 산을 옮길 것이다. 변화를 받아들일 것이다."
rows["368:1028148825"]="<크게 웃는 아이트리그>$B$B젊은이, 그 땐 세상이 원래 이처럼 어지러운 곳이 아니었다네. 그때는 스컬지가 들이닥치기 전이었고 로데론이 역병지대로 불리기도 전이었지.$B$B그곳에서 스랄 님은 내 목숨을 구해주셨고 그 일을 계기로 나는 새로운 호드의 일원이 되었지. 이런, 엉뚱한 얘기를 하고 있군. 이런 역사 이야기는 다른 때나 해야지. 그래, 어쩌면... 다음에 말이야..."
rows["368:1469087095"]="아, 거기 여행자, 안녕하신가? 여기 이 선량한 고블린이 뭐 도와줄 일이 없을까?$b$b난 여기 은빛십자군 사람들처럼 스컬지를 끔찍이도 싫어해서 희망의 빛 예배당에 머물고 있다고. 비행선이 추락해서 부끄럽게 여기로 도망친 건 절대로 아니야! 아무렴!$b$b아이고, 또 말실수를 하기 전에 그만 입을 다물어야겠어!"
rows["368:34623181"]=" ⁇ 이키에게 도움이 될 거야. 그는 생각 중이야. 우리는 아안키라지 전쟁에 대비하기 위해 불꽃 약물의 엄청난 양을 필요로 할거야. 호드'Pele'keiki, 우리한테 $2051w 불꽃잎의 발자국과 함께$B$B펠레키키가 지금 말해, 그는 단지 $2050w 불꽃, 하지만 당신은 곧 그것을 추가 할거야, 맞지?"
rows["368:49320742"]="서쪽의 정찰 임무를 진행하는 동안 와이번을 여럿 잃었소. 스컬지들은 첩자로 보이는 자들을 무자비하게 공격한다오.$B$B다행스럽게도 조련사의 목숨만 걸면 되는 방법이 있다오. 이 방법으로 나삼의 평원을 건넌 자들 중 30% 정도는 살아남았소이다. 와이번을 이용했을 때보다 생존율이 30%나 증가한 거지!"
rows["369:1071079692"]="이 해안에 서린 안개는 스컬지 때문에 생긴 것이 아닙니다. 스컬지들이 여기로 오지 않는 것을 보면 놈들도 이 안개를 두려워하는 것 같습니다.$B$B보다시피 이 안개는 살아 있지요. 저 꿈틀거리는 대기 속에는 죽음이 도사리고 있습니다... $B$B당신도 저 속으로 들어갔다간 사라져버리고 말 겁니다. 안개에 먹혀버릴 거란 말입니다!$B$B저 안갯속으로 들어갔다가 살아 돌아온 자는 한 번도 보지 못했습니다."
rows["369:1339159402"]="너무 추워서 배고프다$B$B내 가난한 친구, 네가 평화를 찾았으면 좋겠어$B$B넌 거기 있어 제발 날 도와줘요. 한 명은 열쇠를 가지고 있어, 찾을 수 있어? 내가 알아, 그들이 가지고 있어."
rows["369:15861470"]="이런 곳에서 새로운 분을 만나니 무척 반갑군요. 지금 우리는 적의 수가 너무 많아 간신히 버티고만 있습니다.$B$B우리를 없애려고 혈안이 된 적들에게 완전히 둘러싸였습니다. 북쪽으로는 사티로스, 동쪽으로는 전쟁노래 벌목기지의 오크, 그리고 악령불 언덕의 악마들까지...$B$B우리는 죽는 한이 있더라도 이곳을 되찾고 말 것입니다. 그런데 지금은 우리가 죽을 확률이 더 큰 것 같군요!"
rows["369:1589658955"]="오래전, 마지막 대전쟁이 발발하기 전에 우리 아버지께서는 북마루 벌목지를 운영하셨습니다. 그건 아버님의 삶이었고 아버님은 그 일에 헌신하셨지요. 그러던 중 전쟁이 일어나자 우린 스톰윈드로 도망쳐야 했습니다. 아버님의 고통은 이루 말할 수 없었지요.$B$B그 당시 우린 많은 친구와 가족을 잃었고, 붉은십자군이 벌목지를 장악해서 그들 멋대로 이용하고 있다는 사실에 난 견딜 수가 없었습니다.$B$B그래서 내가 돌아온 겁니다."
rows["369:1618476159"]="이 모든 혼란의 원인은 당신일 겁니다.$b$b제 이름은 세리트라이고, 이 음악당은 성원의 엘프들이 모여서$b$b모든 것 이 마법 이 있듯이, 모든 마법 은 음악 이다. 음악 은 모든 것 의 비밀적 인 조화 를 지배 하기 때문 이다. 우리 의 많은 사람 들 에게 노래 를 듣는 것 은 종교적 경험 이 될 수 있는 이유 는 이 이다."
rows["369:1672358839"]="아, 거기 여행자, 안녕하신가? 여기 이 선량한 고블린이 뭐 도와줄 일이 없을까?$b$b난 여기 은빛십자군 사람들처럼 스컬지를 끔찍이도 싫어해서 희망의 빛 예배당에 머물고 있다고. 비행선이 추락해서 부끄럽게 여기로 도망친 건 절대로 아니야! 아무렴!$b$b아이고, 또 말실수를 하기 전에 그만 입을 다물어야겠어!"
rows["369:1695557414"]="우리 형제는 실바나스 여왕님에게 헌신하기로 다짐했소. 가장 힘든 시기에 그분은 한 줄기 빛과 같은 분이셨소. 우리에게 닥친 운명을 극복하기 위해, 아침 저녁으로 희생하고 있소.$B$B우리가 언제나 약하게만 머물러 있지는 않을 거요. 우리가 마땅히 받을 자격이 있는 것은 받아내고, 우리가 겪은 고통은 열 배로 되갚을 거요. 얼굴에 차디찬 미소를 머금은 채로... 반드시 그렇게 하고야 말 거요."
rows["369:2011418870"]="에코란 모든 생물이 가지고 있는 힘을 말하지. 자네에게 만들어 준 부적을 몸에 지니고 있으면 그 힘을 얻을 수 있네.$B$B난 에코를 부적으로 변화시키는 주문을 알지.$B$B그러면 마우아리의 부적을 사용해 그 힘을 자신에게 반사시킬 수 있어.$B$B어때? 한번 해 보는 게. 에코를 이 마우아리에게 가져오면 한번 재미있게 놀아볼 수 있을걸."
rows["369:2027171501"]="보라고, 투자개발회사의 새 벌목기가 내 최신 벌목기보다 더 뛰어나단 말이야! 손도 바꿀 수 있고 조종 손잡이도 훨씬 간편해!$B$B상부에서 엄격하게 최종 기한을 정해 놓았는데 내 부하 직원들과 나로선 아무것도 할 수가 없었어.$B$B제대로 작동하는 게 하나도 없었으니까. 그래서, 결국 저들의 원형을 하나 \"빌리기로\" 했지. 위즐크랭크에게 진흙 늪으로 가서 하나 훔쳐 오라고 시켰는데 아직까지 돌아오지 않는군!"
rows["36:1080361693"]="물론이지요! 엘룬의 축복이 그대의 여행에 깃들기를 빕니다."
rows["36:1100315461"]="혹시 해적용 물품이 필요한가?"
rows["36:1190724118"]="우리 아름다운 땅에서 뭔가를 찾고 있나요?"
rows["36:1205673880"]="독이... 속이 아파 죽겠어요..."
rows["36:1223727960"]="그래, 얼마면 되겠어요? 여기 5천 골드면 되겠어요?"
rows["36:1410711991"]="신호탄을 모두 발사했습니다."
rows["36:1423085577"]="내가 가지고 있는 물건을 좀 볼 텐가?"
rows["36:1429835309"]="알았다! 룸프 네가 원하는 거 모두 분다!"
rows["36:1496305511"]="저리 가... 난 여기서 잘래."
rows["36:1520632702"]="머리 위로 에펙시스 유적이 나타납니다."
rows["36:1525210131"]="네, 왜 테렌디온으로 왔어?"
rows["36:1602911998"]="이보시오, 날 좀 아래로 내려주겠소?"
rows["36:1638686412"]="펜구스가 너 거칠게 만들어 주지! 미친 것처럼! 크아악!"
rows["36:1732591633"]="내가 여기 바쁘다는 걸 안 보십니까?"
rows["36:1773088899"]="좋은 의상이군. 맡은 역할에 딱이야!"
rows["36:1806506498"]="스컬지는 줄드락에 발을 들여놓지 못한다!"
rows["36:1999699733"]="왕자가 혼자 떠나 버렸네. 큰일이야!"
rows["36:201776508"]="이봐요, 낯이 있군요. 우리 만난 적이 있나요?"
rows["36:202159168"]="그게 우리 주위를 맴돌아. 아니 내 머릿속에 있어!"
rows["36:2037005483"]="제 흉포한 테로나방이 복수할 겁니다!"
rows["36:207611541"]=" ⁇ 치 연습을 하고 싶니?"
rows["36:2103746184"]="지금 얘기할 시간이 없어요"
rows["36:2105510712"]="여기 맥주 맛 좀 한 번 봐요."
rows["36:2114271680"]="뭐야? 난 굉장히 바쁘다고."
rows["36:30047425"]="<킁킁> 냄새가 나는데요, 친구."
rows["36:439703634"]="<넋이 나간 듯 멍하니 당신을 바라보는 여배우>"
rows["36:632496857"]="아제로스 각지의 수제 장난감 팔아요!"
rows["36:637913874"]="어이! 손가락 뼈다귀 한 판 하러 왔나?"
rows["36:704322872"]="다시 보니 정말 기쁘군, 친구여."
rows["36:760337366"]="우리가 받고 있는 벌은 축복이기도 하지."
rows["36:841668145"]="장로 오한지는 군드락에 있다네."
rows["370:738578605"]="드디어 왔구나.\010$b이곳에선 내일이면 세계의 분리가 일어난다. 영원의 샘이 무너지고 대륙이 여러 개로 분리된 사건 말이지.\010$b여기서 용의 영혼을 손에 넣어야 한다. 이 시간의 안개 속으로 영영 사라지기 전에...\010$b일단 아즈샤라를 따르는 명가 놈들이 만든 보호의 수호물을 찾아서 없애라. 궁전 안에서 찾을 수 있을 터. 난 그 이후를 탐색해 보마.\010$b행운을 비노라!"
rows["370:997258897"]="지금 이 지도자에게 계획대로 진행되는 상황을 보고하고 있습니다. 몇 주 더 걸릴 때만 이 곳은 다시 정형이 될 것입니다.$B$B하지만 그림자 협의회는 오크들로만 마을을 구성해 줄 수 있어 조상들의 주장을 할 수 있고 비밀리에 일할 수 있을거야$B$B잠깐, 내가 당신을 알고 있나요?"
rows["371:1132204320"]="밤의 축복이 함께하기를! 저는 여기 잿빛 골짜기를 책임지고 있는 은빛날개 파수대의 병참장교 문블레이즈라고 합니다. 우리 은빛날개 파수꾼을 위한 싸움을 통해 그대의 실력을 증명하신다면 전쟁노래 협곡에서만 사용할 수 있는 좋은 물건들을 보여드리겠습니다. 거기다 장비 수리 서비스도 제공하고 있으니까 고칠 물건이 있으시면 언제든지 찾아주십시오."
rows["371:1163629365"]="난 이 도시의 공무를 보고 있네. 언더시티의 인구를 조사하는 업무를 맡고 있지. 스컬지에게 해방된 후로 우리는 인구를 정확하게 기록해 두려고 노력하고 있지. 난 마법과 고도로 단련된 정신력으로 그걸 조사해 기록할 수 있다네. 용건이 있다면 말해 보게. 내게 용건이 있는지 없는지 정도는 알겠지?"
rows["371:121697518"]="게시판에 눈길을 끄는 두 개의 전단이 붙었는데 하나는 휠러 아저씨가, 다른 하나는 로켓발사단장 퓨즐라지가 올린 것입니다.$B$B휠러 아저씨는 기계 부품을 구하는 전단을 올렸습니다. 로켓발사단장은 거대한 산악거인의 목에 현상금을 걸었습니다!$B$B두 전단의 자세한 내용은 깨알같이 작은 고블린 글씨로 적혀 있어서 알아보기 매우 어렵습니다."
rows["371:1396325626"]="최전선에는 방어를 지휘하는 적의 부대장이 여섯이 있는데, 먼저 그들을 처치해야 하오! 사제들이 쓰러진 놈을 부활시키면 곤란해지니까 속전속결로 끝내 버리시오!$B$B순식간에 부대장을 모두 해치워버리면 최전선의 사기가 떨어지겠지! 전의를 상실한 부대원들은 겁에 질려 도망칠 테고, 그러면 나머지 병사들은 지원군도 없이 싸우다 비참한 죽음을 맞이할 것이오."
rows["371:329072636"]="이런 비밀을 너 같은 필멸의 존재에게 밝히는 일은 신성 모독에 가깝지만, 선택의 여지가 없구나.$B$B티탄들의 딸인 프레이야가 나를 이곳에 남겨 놓았을 때부터, 나는 절대 실패해서는 안 되는 임무를 하나 맡았다. 생명은 어떤 대가를 치르더라도 보호받아야 한다.$B$B이곳과 매우 흡사한 장소를 연결하는 차원문이 있다. 우리가 찾는 무기를 발견할 수 있는 곳이 바로 거기이다."
rows["372:276652181"]="울두아르... 난 울두아르를 지켜내겠다고 맹세했었다.$B$B창조주의 거처를 지켜내겠다고 맹세했었지.$B$B서릿결 부족과 한 계약을 지켜내겠다고 맹세했었다.$B$B하지만 난 실패했다! 내 형제가 날 속이게 내버려뒀다. 내 형제가 내 동맹과 등을 돌리도록 내버려뒀다. 내 형제는 나를 속여 시프의 죽음을 내 절친한 친구이자 서리 거인의 왕인 아른그림의 탓으로 돌리도록 했다.$B$B내가 무슨 짓을 했는지 깨달은 후... 난... 자포자기했다."
rows["372:97299761"]="안녕하세요, 여행자님. 이곳은 거의 1천 년 전, 퀴라지가 칼림도어를 건너 파괴의 행진을 시작한 곳입니다.$B$B전쟁 중에 수천 명이 목숨을 잃었는데, 그 대부분은 첫 번째 침략 당시 이 저주받은 사막에서 숨을 거뒀지요.$B$B저는 몇 안 되는 생존자 중의 한 명이며, 과거와 현재의 속박에서 벗어나지 못하는 불쌍한 영혼이랍니다. 제가 여기 남아 있어야 하는 이유는 알지 못하지만 그럴 수밖에 없다는 것은 알고 있습니다."
rows["373:1389999407"]="다시 만나게 돼서 반갑네!$B$B스톰하트 왕께서는 잠시 휴가를 떠나시겠다고 말씀하셨네... 아마도 불쾌한 기억 때문에 풀어야 할 일이 있으신 모양일세. 혼자 지내겠다고 완강히 주장하시기에, 언제나 그렇듯 그분의 뜻을 존중하기로 했네.$B$B하지만 그동안은 내가 부족을 지키는 일을 맡게 되었다네. 물론 우리 부족은 언제든지 자네를 환영하네."
rows["373:277339464"]="난 그들의 손에 마지막으로 희생되었소이다. 내 육신에서 영혼이 빠져나가는 게 느껴졌을 때 나는 피의 맹세를 했소.$B$B<고개를 흔드는 왕자 토레스>$B$B이 세계를 위해 내 모든 피를 바치겠다는 맹세와 함께 나와 이 대지 사이에 계약이 맺어졌지. 오직 나만이 우리 종족의 역사를 보존하고 있는 것이오.$B$B로레스아란의 용기수에 대한 이야기가 시간이 흘러도 잊혀지지 않는다는 사실을 확인하기 전에는 잠들 수가 없다오."
rows["374:1897092036"]="그 질문을 들으니 뭘 좀 먹어야 할 것 같군... 듣자하니 얼라이언스가 지금까지 모은 전투 식량은 무지개날개다랑어 구이 $2093w개 중 $2092w개, 랩터 숯불구이는 $2099w개 중 $2098w개, 점박이놀래기 구이는 $2103w개 중 $2101w개가 준비되어 있다네. 실리더스의 세나리온 요새로 수송할 때까지 포장된 상태로 냉장고에 보관할 거라는군. 음..."
rows["374:2131309200"]="여관에서 무엇을 할 수 있느냐고요?$B$B여관에서는 아주 편하게 쉴 수 있기 때문에 야외에서 보다 훨씬 빠르게 피로를 회복할 수 있답니다. 피로를 회복한 상태에서 사냥을 하면 경험치를 더 많이 얻을 수 있답니다.$B$B또한 여관주인에게 귀환석을 받을 수도 있는데 이 귀환석을 사용하면 필요할 때 여관으로 되돌아올 수 있습니다."
rows["375:291005734"]="부티 베이에는 남해에서 가장 좋은 클램  ⁇ 이 있습니다. 요리에 관심이 없습니다. 그럼 내가 먼저 당신을 환영 할 수 있습니다. 마이든스 펀시, 동부 왕국과 칼림도어 사이 여행하는 가장 훌륭한 여객 배. 그녀는 곧 다시 라치에 여행 할 예정입니다. 그래서 그녀가 도착할 때까지 편안하게하십시오."
rows["375:341354265"]="그게 다라고요? 겨우 하나? 지금 농담하시는 겁니까? 곰 발바닥 모으는 일이라도 없습니까? 예를 들어 당신이 살짝 환각을 유발하는 물약을 마시고 위대한 신의 계시를 받아야 하니 그 재료인 희귀한 꽃을 찾아와라, 뭐 그런 식의 일도 없는 겁니까? 요즘 성질 더러운 땅다람쥐들이 슬슬 나대기 시작해서 지역 주민에게 점점 불만이 쌓이는 상황인데도, 이들에게 정의의 심판을 내리지 않겠단 말씀이신가요? 정말입니까?"
rows["376:1280879664"]="검은바위 오크들은 내 친족들일세. 내 아버님께서도 검은바위의 일원이셨고 내 아버님의 아버님께서도 그러셨네. 내 어머님도 검은바위의 일원이셨지. 그리고 나도 검은바위의 일원일세.$b$b다른 무엇보다도 난 오크일세. 그 말은 명예가 무엇보다도 중요하단 말일세.$b$b나의 대족장께서는 이곳 불타는 평원에서 나의 임무를 마치라고 하셨네. 그리고 난 이곳의 검은바위 오크들이 그들 방식의 잘못을 깨닫기 전까진 떠나지 않을 걸세."
rows["376:162974386"]="자네가 가져온 독극물 견본을 보니 비전 촉매제 하나, 심령 공명체 4개, 그리고 룬무늬 옷감 4개가 필요할 것 같군. 유리질 집중기를 가지고 있으면 이곳 역병지대에 있는 망령이나 유령 언데드에게서 심령 공명체를 구할 수 있다네.$B$B이 물건들을 다 찾으면 그 가마솥에 반작용 물질을 투입할 수 있을 것이야."
rows["376:1760101044"]="트롤베인 혈족의 영웅담은 전설적이지요. 저는 한 남자를 숭배했습니다.$B$B그리고 이곳 아웃랜드에서 그가 살아있다는 것을 확인하고자...$B$B<당신 뒤쪽을 바라보는 로무스>$B$B그를 처음 만났을 때 저는 거의 기절할 뻔했지요. 엄청난 충격이 아닐 수 없었습니다. 그의 앞에 무릎을 꿇었을 때 저는 눈물을 삼켜야만 했습니다.$B$B로서의 후예들을 무사히 지킬 수만 있다면 제가 할 수 있는 것은 뭐든지 할 겁니다."
rows["376:230908259"]="우리는 이 탑을 하나만 건조하기 전에 세웠고, 여기서 한 경비자가 도로와 언덕과 파도를 동시에 볼 수 있고, 저는 이 보드에 많은 시계를 세웠습니다.$B$B바다는 조용하지 않았습니다. 쿨 티란 선박이 지평선을 지나고 프라우드무어의 군인들은 우리가 만든 것을 태웠다. 그들의 탑은 여전히 해안에서 서 있습니다."
rows["376:763437336"]="친구여, 옆에 와서 무릎을 좀 굽혀주겠습니까? 마지막 기습 공격 도중 그만 총에 맞고 말았습니다.$B$B<자세를 바꾸려다가 고통에 신음하는 갠. 그의 왼쪽 손은 상처를 움켜잡고 있으며 떨리는 손가락 사이로 피가 흘러내립니다.>$B$B드워프가 처음 불모의 땅을 침략했을 땐, 놈들의 굴착기를 공격하거나 장비를 망가뜨리며 스스로 만족하곤 했습니다. 기회가 있을 때 치명타를 날렸어야 했는데 말이지요."
rows["377:1898436675"]="대장장이? 우리 마을에 마지막으로 남아있던 대장장이는 정신 나간 스컬지로 변해버렸지. 하지만, 언더시티에는 한 명 있으니 마을 남쪽으로 가보게. 언더시티는 로데론의 폐허 밑에 있다네. 언더시티라, 아주 딱 맞는 이름 아닌가? 폐허 안쪽에 있는 승강기를 타고 내려가서 언더시티 수호병 중 아무나 한 명 붙잡고 물어봐. 길을 가르쳐 줄 거야."
rows["377:2024916818"]="자네가 가져온 독극물 견본을 보니 비전 촉매제 하나, 체세포 강화물질 5개, 그리고 룬무늬 옷감 4개가 필요할 것 같군. 유리질 집중기를 가지고 가면 이곳 역병지대에 있는 좀비나 구울 언데드에게서 체세포 강화물질을 구할 수 있다네.$B$B이 물건들을 다 찾으면 그 가마솥에 반작용 물질을 투입할 수 있을 것이야."
rows["377:2087514885"]="저는 고난의 거리를 대표하여 아킨둔에서 어둠의 의회 일당을 뿌리 뽑아야 한다는 제안을 하려고 왔습니다. 그러니까, 우리의 희망찬 미래를 위해서라도 해골 무덤보다 더한 재앙이 일어날 가능성을 미리 방지하자는 거지요!$B$B우리 백성은 이미 많은 고통을 겪었습니다. 저는 그 고통을 멈추고자 여기 왔습니다!"
rows["377:2125424391"]="가을 축제에서 맥주와 소시지 다음으로 인기 있는 거라면 단연 기념품입죠! 전통 축제 의상부터 맛난 맥주가 담긴 꼬마 술잔까지, 갖가지 가을 축제 관련 상품을 벨비 퀵스위치에게서 구입하실 수 있답니다. 가을 축제 상품 교환 동전만 넉넉히 챙겨오세요. 그래야 물건을 사실 수 있으니까요! 가을 축제 광장 주변에서 도움의 손길을 뻗으시면 교환 동전을 얻으실 수 있습니다."
rows["377:559601888"]="아, 그래, 우리 공격 호드 타우라조 시. 그 결정의 영향에 대해 고민했습니다.$B$B타우라조는 '무소 한 목표'라고 할 수 있는 곳이었는데, 주로 사냥꾼 들 의 수용소 였지만, 그 는 수 년 동안 호드 보병 을 모집 하고, 장비를 갖추고 훈련 시키기 위해 사용 되었다.$B$B스카우들이 타우라조의 가장 위험한 부대가 사냥을 하고 있다고 보고했을 때 우리는 빨리 행동해야 했습니다."
rows["377:918274972"]="안녕하세요, 친구 순찰자난 야라야, 깊은 야생의 추적자이자 사냥꾼입니다.$B$B몇 년 동안 저는 고대 숲을 지나서 조용한 길을 걷고 야수와 칼의 비밀을 배웠습니다.$B$B사막은 듣는 법을 아는 사람들에게 말하고 - 나는 당신의 말을 들을 수 있습니다 순찰자이 땅을 지나가는 방식에 심장이 있습니다.$B$B오, 난 당신에게 턱과 손톱, 활과 칼의 방법을 가르쳐 줄게."
rows["378:1108831390"]="저주받은 자들의 교단은 세력이 커져서 호드와 얼라이언스 모두의 수도에서 작은 촌락과 오두막까지 이교도들이 일반 시민들 속에 숨어 있다네.$B$B이교도들은 의식을 위해서만 제복을 입으니까 그렇게 놀라지 말게. 자네가 여행을 하는 동안 만난 적이 있었는데도 전혀 모르고 지나쳤을 가능성도 꽤 있지."
rows["37:1013381933"]="불타는 평원 - 일곱 현자의 서판"
rows["37:1021018496"]="잡담할 시간 없어요. 난 일해야 한다고요!"
rows["37:1182924650"]="모양을 잡아야 할 철이 있으신가요?"
rows["37:1197536832"]="연말의 풍요로움과 평화를 그대에게!"
rows["37:1216506085"]="흉터가 봉인되었습니다! 세나리우스에게 감사를..."
rows["37:1351887430"]="림피 조, 당신이군. 정말 당신이야!"
rows["37:1398525976"]="아아, 통증이... 너무 심해요..."
rows["37:142819405"]="어디로 인도해 드릴까요?"
rows["37:145131518"]="마리 홀드스턴을 구해봐"
rows["37:1481826711"]="전 아무것도 몰라요! 다른 일꾼하고 얘기하세요."
rows["37:1550596523"]="안녕하세요, 친구! 무엇을 도와 드릴까요?"
rows["37:1603555597"]="모두 정상이고 작동 준비가 되었다네."
rows["37:1621384253"]="한참 즐기는 중인데 귀찮게 하지 마시오..."
rows["37:1638746848"]="작업을 시작할 준비 됐는가?"
rows["37:168427027"]="자네, 배달할 짐이 있지 않던가?"
rows["37:1695539075"]="안녕하십니까. 조합의 친구여."
rows["37:172461467"]="내놔, 코치, 난 싸울 준비가 돼 있어!"
rows["37:172983328"]="내 이름은 몬티. 쥐들은 내 사냥감이지."
rows["37:1749327151"]="꽤액! 그만해, 더러운 해적놈! 그만해!"
rows["37:1927302672"]="이 늙은이는 제발 그냥 내버려두게나."
rows["37:1980651975"]="그건 귀여운 네 얼굴을 더 잘 보기 위해서지."
rows["37:1983046327"]="어서 와.$B$B잃어버린 동료를 찾으러 온 거야?"
rows["37:1994569453"]="어느 차가 가장 빠를까요? 경주의 승패를 그 누가 알겠습니까?!"
rows["37:2001626407"]="어떤 무기가 배우고 싶어서 왔나요?"
rows["37:2011706109"]="이 땅의 축복이 당신과 함께하길..."
rows["37:2049248555"]="타우렌 성기사가 성스러운 빛을 받들면 소기사가 되나요?"
rows["37:2052605369"]="어쩌다 이런 일에 휘말리게 되었을까요?!\010"
rows["37:25653559"]="작은 자여, 무슨 일로 여기까지 왔나?"
rows["37:262844713"]="유령울음늑대를 해치우다니! 아주 훌륭하십니다!"
rows["37:271410517"]="키린 토의 고향에 온 것을 환영하오."
rows["37:324349506"]="방금 들었나? 이게 무슨 소리지!"
rows["37:425423435"]="당신이 찾는 지식은 내게 없습니다."
rows["37:453649144"]="어서 오세요. 뭘 도와드릴까요?"
rows["37:562072893"]="나는 삼두연합행정부의 세 번째인 아에솜이라고 합니다."
rows["37:638814569"]="코르부스에게 무슨 볼일이오?"
rows["37:665529825"]="천리안을 찾아야 해!"
rows["37:769027642"]="당신은 제 취향이 아니에요."
rows["37:821444457"]="어서 오시게. 나는 핏빛 감시초소의 수장 애드미티우스라고 하네."
rows["37:841470455"]="옛날 왕이 죽었어? 어, 그럴 리가!"
rows["37:871937721"]="할 말이 있으면 어서 말해보게!"
rows["37:874990745"]="여기저기 방황하지 마십시오. 할 일이 있으니까요."
rows["37:957414469"]="고고학을 훈련하러 왔습니까?"
rows["37:991006409"]="미용사 말인가? 어둠의 틈에서 힘의 골짜기로 가게를 옮겼지. 예전에 과일 상인이 있던 자리라네."
rows["380:1206019584"]="나마리엔은 \" 환영합니다\"라는 뜻입니다.$b$b<엘프의 목소리는 계곡 자체에서 탄생한 것 같습니다. 강의 음악과 함께 흐르고 숲을 안개로 장식하는 폭포처럼 내려갑니다. 그러나 그 모든 아름다움에도 불구하고, 그 아래에 산-암이 있으며, 발이 손상되지 않은 순결이 있습니다. 흰하고 먼 정상에 눈이처럼.>$b$b당신 은 우리 의 게으름 을 누릴 수 있습니다."
rows["380:1619217367"]="아, 어린이 전사의 부탁인 게로군! 그대도 어린이 주간 중 자원봉사를 하고 있는 모양이지? 솔선수범해서 다른 이들에게 좋은 본보기가 되고 있다니 나의 시린 무릎이 다 따뜻해지는구나.$B$B그대와 그 어린 소년의 부탁을 기꺼이 들어주겠다. 흠... 그런데 그 아이에게 어떤 조언을 해주는 게 좋을까? 영혼의 소리에 귀를 기울이거라? 그래... 편식하지 말고 반찬을 골고루 먹거라... 특히 채소를 말이지..."
rows["380:344006757"]="이런 어려운 시기에는 옷감 같은 단순한 걸 기부하는 일만으로도 형편이 어려운 이들에겐 큰 힘이 되지. 붕대나 옷을 만들 수 있는 옷감이야말로 전시에 아주 중요한 물건이고 말고!$B$B오그리마의 오크족에게 옷감을 기부할 생각이 있다면 기꺼이 받겠어. 그리고 자네도 마땅한 대우와 인정을 받을 수 있을 거야.$B$B호드를 위하여!"
rows["381:153046723"]="당신을 해칠 생각은 없어요. 나는 가시멧돼지들을 염탐하면서 녀석들의 동태를 살피고 있어요. 동료가 이 지역에서 뭔가 이상한 암흑의 기운이 뿜어져 나오는 것이 느껴진다고 해서 조사하러 왔는데, 우려할만한 사실을 알아냈어요.$B$B마법에 능한 언데드 외교관이 있는 것 같아요. 포세이큰은 아닌 것 같고... 그보다 더 악한 자라고 생각돼요."
rows["381:1828519290"]=" ⁇ , 당신은 야만전사의 길을 찾고 있습니까?  ⁇ 라카진은 그 방법을 잘 알고 있습니다. 호랑이들이 경고없이 돌고 다니고 뱀이 공격하는 깊은 숲에서, 나는 가장 강한 사람이만 살아남는 것을 배웠습니다. 내 부족은 폭풍의 분노와 고대 나무의 인내와 싸워야 가르쳐 주었다. 당신은 훈련에 필요한 야만적인 마음을 가지고 있습니까? 또는 당신은 다른 부드러운 피부 도시 거주자입니까?"
rows["381:1909975119"]="나는 수석땜장이 오버스파크라고 하오. 현대 노움 기계공학 원리를 설계한 중심 인물이라고 할 수 있지. 내 임무는 노움의 만능 스패너를 이용해 발명의 역사에 길이 남을 눈부신 기계를 만드는 거요.$B$B혹시 쓸만한 방사선 제거용 설계도를 찾게 되거든 우리에게 가져와 주시오. 요새 그게 필요하거든."
rows["381:483223234"]="우린 놈리건에서 떠날 수밖에 없었던 사태 때보다 훨씬 더 큰 곤경에 빠져 있어요! 좀 도와 주지 않을래요? 옷감이 모자라요!$B$B재고를 보충할 여분의 옷감이 있거든 좀 가져오세요. 남는 옷감을 기부하면 어딜 가나 우리 노움들의 신뢰와 존경을 받게 될 거예요. 그건 돈으로도 살 수 없는... 결국 옷감으로 사는 게 되겠지만, 지금 그게 중요한 게 아니니까..."
rows["381:660950046"]="안녕하세요! 아이언포지 드워프들의 존경을 한몸에 받고 싶다면 귀중한 물건을 기부하는 선행으로 시작해 보십시오! 아이언포지에서는 붕대나 옷을 만들 옷감이 턱없이 모자라요. 그런 귀한 물건들이 하늘에서 뚝 떨어지는 게 아니니까요!$B$B당신 같은 모험가라면 세상 곳곳을 여행하면서 다양한 옷감을 모으시겠죠?! 그냥 팔아 버리기보다는 기부를 통해 뜻 깊은 일에 쓰시는 게 어떠신가요?! 아이언포지 드워프 주민들의 존경과 인정을 받을 수도 있고 말이죠!"
rows["382:1264492204"]="노르간논의 쐐기돌에 대한 단서를 찾았습니다. 그 쐐기돌은 울두아르 기록에 접근 여부를 관리하는 역할을 하지만, 티탄들이 둘로 나누어 비밀리에 숨겼지요.$B$B그중 한 조각은 쐐기돌의 껍질인데 북쪽 해안에 있는 발명가의 도서관 안에 보관되어 있어요. 바로 울두아르에서는 남쪽이죠. 당신이 가장 먼저 해야 할 일은 도서관 수호병에게서 접속 원반 조각을 되찾아 오는 일입니다."
rows["382:1536879863"]="노르간논의 쐐기돌에 대한 단서를 찾았습니다. 그 쐐기돌은 울두아르 기록에 접근 여부를 관리하는 역할을 하지만, 티탄들이 둘로 나누어 비밀리에 숨겼지요.$B$B그중 한 조각은 쐐기돌의 껍질인데 북쪽 해안에 있는 발명가의 도서관 안에 보관되어 있어요. 바로 울두아르에서는 남쪽이죠. 당신이 가장 먼저 해야 할 일은 도서관 수호병에게서 접속 원반 조각을 되찾아 오는 일입니다."
rows["383:1413573155"]="가마솥에 침투했으니 이제 주변에 반작용 물질을 투입할 수 있게 됐습니다. 이렇게 하면 스컬지가 자신들이 퍼뜨린 역병에 되려 당하게 되는 겁니다!$B$B연금술사 디더스와 대화하여 가마솥에 사용해야 할 재료에 대한 정보를 얻도록 하세요. 스컬지에게 역병을 역이용하는 것에 대한 전체적인 상황 보고 정보는 모두 제가 처리할 겁니다."
rows["383:44307481"]="이 속임수로 우리를 모욕하는 사람들을 신뢰해야 할까요?$B$B우리는 그들이 우리를 구출하려는 것을 알고 있지만, 내 사람들은 그들의 구제를 원하지 않습니다. 우리는 우리 스스로 서있을 수 있습니다. 그리고 우리는 자랑스럽고 분리된 민족으로서 우리의 운명을 추구할 것입니다."
rows["383:540230317"]="울담의 판은 창조자들에 의해 합성된 디스크로 울담 화합물에 접근할 수 있게 해줍니다. 이 디스크들은 여기에 창조자들의 활동에 관련된 특정 데이터를 보관하고 있습니다.$B$B물리적으로, 그들은 현재 소유한 디스크 집합과 둘레로 거의 동일합니다. 그러나 그들의 표시는 울담 복합과 달리 울담에 대한 정보와 직접적으로 관련이 있습니다."
rows["384:1206722461"]="이야, 이런 곳에서 다른 모험가를 만나리라고는 상상도 못 했군요!$B$B여기 계신 여러분은 제가 심판장에 가는 걸 도와주시겠지요? 이 장소에 대한 제 연구가 옳다면, 드워프 창조와 관련된 정보가 여기 있을 겁니다!"
rows["384:1999244081"]="이건 섬세한 일이야, 빨리 할 수 없어, 아니면 뭔가 깨질 가능성이 높지$B$B마치  ⁇ 체 머리처럼!$B$B제 로봇을 생각해봐요, 저는 항상 Mk.I를 만들고 있습니다. 그리고 Mk.II는 뇌가 열광을 당하기 전에$B$B저는 III와 IV를 건너뛰기로 결정했고, 바로 Mk. V로 갔습니다."
rows["384:2045780081"]="교활한 마법사 군주 우롬이 세 번째 고리를 보호하고 있습니다. 놈은 무방비 상태로 홀로 있는 것처럼 보이지만, 겉모습에 속아서는 안 됩니다! 우롬은 실체 없는 생물 군단을 지휘하는 강력한 요술사입니다. 위쪽에서 그를 찾아보십시오. 난 그대에게 붉은용군단 비룡을 소환할 수 있는 능력을 줄 수 있습니다. 청동용군단이나 녹색용군단의 힘을 빌리고 싶다면 이터노스나 베르디사와 이야기하십시오."
rows["384:295298292"]="우리는 우리가 할 수 있는 모든 것을 해야 합니다 데피아즈단우리 대부분은 전투가 아니지만 농장과 전선에서 충분히 시간을 보냈습니다.  ⁇ 을 검으로 대체하는 방법을 바보에게 가르쳐주었습니다. 신병들을 돕고 싶거나, 자신만의 연습을 하고 싶다면 자유롭게 하세요. 그렇지 않으면 대령 다누벤에게 보고하세요."
rows["384:31893239"]="하 하룸! 먹을 것? 우린 부드러운 건 몸에 나빠서 먹지 않아, 친구. 바위와 돌과 대지를 먹지. 아삭거리는 뼈다귀는 가끔 양념으로 맛있게 먹지만 말이야.$B$B<거대한 한쪽 손으로 바위를 들어 올려 당신이 가져온 시체를 내리치고 기쁜 듯이 우르렁대는 고르문간.>"
rows["384:364583244"]="저들은 이곳에서 자랐다네. 우리는 그들을 안전하게 보호하고 건강을 되찾아주기 위해 최선을 다해 간호했지. 죽은 오크도 많지만, 그보다 많은 어린이들이 강하게 성장했다네. 가로쉬처럼...$B$B<한숨짓는 대모 게야>$B$B알다시피 그는 마음에 크게 상처를 받았네. 가로쉬는 내가 자신을 잡아주는 존재라고 말하지. 내가 없었다면 그의 아버지를 데려갔고 우리 종족에게 저주를 내린 피에 대한 굶주림이 자기를 집어삼킬 것이라고 말이야."
rows["384:723357044"]="안타깝게도, 세상 일이 늘 그런 것 같소이다. 나를 비롯한 세나리온 의회의 다른 이들도 모두 고대의 전쟁 중에 밀리의 덩굴이 파괴되었을 거라 추측했었지... 이제야 알게 된 사실이지만 전혀 그렇지 않았던 거요.$B$B풍요의 열매는 살아남았소... 이제는 악령덩굴이라 불리고 있지만... 엘드레탈라스에 거처하는 칼날바람 알진이라는 악마 군주에 의해 타락하고 있었던 것이오."
rows["384:780038382"]="그건 모릅니다.$B$B하지만 살아남은 검은무쇠 드워프들은 산으로 올라가 그들의 도시를 재건하기 시작했습니다.$B$B타우릿산의 잿더미 위에 검은바위 첨탑이 세워지고 새로운 검은무쇠 제국이 탄생한 것이죠. 이글거리는 협곡 내에서 용광로라는 곳의 방비를 더욱 강화했답니다.$B$B그런데 그때부터 검은무쇠 제국을 지배한 고대 악령에 대한 이야기가 나돌기 시작했어요."
rows["384:811222324"]="가마솥에 침투했으니 이제 주변에 반작용 물질을 투입할 수 있게 됐어요. 이렇게 하면 스컬지가 자신들이 퍼뜨린 역병에 되려 당하게 되는 거죠!$B$B연금술사 알빙턴과 대화하여 가마솥에 사용해야 할 재료에 대한 정보를 얻도록 하세요. 스컬지에게 역병을 역이용하는 것에 대한 전체적인 상황 보고 정보는 모두 제가 처리할 겁니다."
rows["384:976451049"]="안녕하시오, 친구여... 괜찮다면 잠시 시간을 내서 이야기를 들어주시오.$B$B우린 텔드랏실을 일으켜 세우는 데 많은 고난과 시련을 겪어 왔소. 계속되는 고난으로도 모자라 이제는 옷감까지 부족하구려. 혹시라도 여분이 있다면 부디 기부해 주시오. 우리를 도와 주면 어디서든 나이트 엘프의 친구로 대접받게 될 것이오!"
rows["385:1184804973"]="불모의 땅 변두리에 인간들이 그늘 쉼터라는 이름의 여관을 하나 지었지만 몇 주 전에 불타 버렸소.$B$B내가 왜 신경 쓰냔 말이오? 신경쓰지 않소. 인간들에 대해서는 신경도 쓰지 않는단 말이오. 그 여관에 심어놓은 첩자가 있소. 난 그의 죽음이 대답 없는 일로 묻히도록 두진 않을 것이오. 누가 이런 일을 했는지 알아야 하오$B$B도울 의사가 있다면 타고 남은 그늘 쉼터 여관으로 가 보고 뭔가 단서를 찾으면 내게 알려 주시오."
rows["385:473794356"]="사랑하는 내 형제들이 여기서 이 순간을 저와 함께한다면 정말 좋으련만. 이 엄청난 발견을 그들은 상상도 못 할 겁니다!$B$B심판관은 바로 이 방에 가득 찬 티탄의 자료를 관리하는 사서라고요!$B$B보십시오! 바닥 아래 자료가 가득합니다! 서둘러야 합니다. 드워프의 가장 위대한 발견이 눈앞에 있어요."
rows["385:644396886"]="교활한 마법사 군주 우롬이 세 번째 고리를 보호하고 있습니다. 놈은 무방비 상태로 홀로 있는 것처럼 보이지만, 겉모습에 속아서는 안 됩니다! 우롬은 실체 없는 생물 군단을 지휘하는 강력한 요술사입니다. 위쪽에서 그를 찾아보십시오. 난 그대에게 붉은용군단 비룡을 소환할 수 있는 능력을 줄 수 있습니다. 청동용군단이나 녹색용군단의 힘을 빌리고 싶다면 이터노스나 베르디사와 이야기하십시오."
rows["386:1227944105"]="전쟁동의 둥근 홀. 레이첼 그린힐은 섬 중간에 있는 브릿지의 한 개 위에 야만인들을 훈련시킵니다. 외부 링에서 죽음의 경호자 솔러는 북쪽 입구에서 경호자들을 훈련합니다. 엑소로트의 기사들 가그리모르트, 성전의 죄 없는 벤자민, 스타콜러들 파알아도르 야닐, 종예주의들의 꿈꾼 비타라스 등이 홀 주변에서 서 있습니다."
rows["386:1248893763"]="가즈란카를 낚으려면 특별한 진흙노린재 미끼가 필요할 겁니다. 내가 직접 만드는 물건이지요!$B$B일반 미끼로는 안 됩니다. 진흙노린재가 필요해요... 미끼에 꿰어서 그 지독한 썩은 내를 풍겨야 하거든요!$B$B진흙노린재를 잡으면 줄구룹에 있는 페이글의 낚시터로 가서 미끼를 던진 다음... 술이나 한 잔 들이켜며 기다리세요... 하지만 너무 오래 기다릴 필요는 없을 겁니다. 틀림없이 가즈란카가 소란을 떨며 나타날 테니까요!"
rows["386:1318275929"]="<왜란 여성은 눈을 감고 서서 바람이 얼굴을 닦고  ⁇ 은 머리카락으로 놀고 있습니다.>$B$B미안해, 내가 알아차리지 않았어.$B$B난  ⁇  카자드의 유언의 보호자 에르그라인 타터사일이야 내가 머리가 깨끗해졌어 더 이상 아무것도 없어서 오랜 책 속에 묻혀있는 시간을 보내면"
rows["386:1482820528"]="이 곳에는 말할 수 없는 공포가 살고 있습니다. 아제로스 우리가 알고 있는 것처럼$B$B메리트라는 천년 전에 카엘레스트라스와 아리고스와 함께 자신을 희생시켰습니다. 왜냐하면 그들은 또한 이것을 알고 있었기 때문입니다. 우리는 그들을 위해 돌아온 맹세 때문에 여기 있습니다."
rows["386:1542871806"]="수년간의 충성에 대한 보답으로 일리단은 캘타스의 전사 5명을 받아서 훈련시켜 주기로 약속했네. 블러드 엘프가 악마사냥꾼 훈련을 받은 일은 이게 처음일 거야.$B$B훈련은 가혹했지. 일리단은 제 아무리 뛰어난 악마사냥꾼이라도 성공하기 어려운 일을 캘타스의 전사들에게 시켰네.$B$B캘타스의 부하 중 3명은 훈련 도중 사망했고 1명은 정신이 나가버렸네.$B$B그리고 단 한 명만 성공했지."
rows["386:1665131801"]="느껴지세요?$B$B망자의 날에 우리 곁으로 다가오는 영혼의 세계가 말이에요. 떠나 버린 사랑하는 이들의 무덤을 꽃과 촛불, 공물로 장식하는 이유가 바로 이거랍니다. 잠깐이라도 그들이 돌아오는 걸 축하하는 거죠.$B$B어서 오세요! 저랑 춤추시죠! 우리 곁을 떠났지만 이제 영혼이 되어 다시 나타난 이들을 추억하고 공경해요. 그들은 먹고 마시며 웃고, 우리가 그들을 사랑함을 느낄 거예요."
rows["386:1699252723"]="이방인이여, 전 나이트 엘프입니다. 그대는 우리 종족에 대해 아는 게 없겠지만 우린 그대와 그대의 선조에 대해 잘 알고 있답니다. 그대들은 스스로 에레다르라고 부르지 않을지도 모르지만, 겉모습만 보면 비슷한 점이 많습니다.$B$B제 동맹을 도와주신 점에 대해서는 감사를 드립니다. 하지만, 지금으로서는 그대들을 완전히 믿을 수가 없군요. 때가 되면 의심도 풀리고 제 걱정도 사라지겠죠."
rows["386:1971383651"]="저 석상이 참 골치를 썩이네요. 저는 기중기와 폭탄을 적절히 사용하면 물 밖으로 꺼낼 수 있을 거로 생각했어요. 그런데 현장감독은 이 경사로로 굴리는 방식으로 옮겨야 안전하다고 우겼죠.$B$B근데 이걸 보세요... 각도가 다 틀어졌어요. 그래요, 저 위로 옮겼다고 쳐요. 그다음엔 뭘 어떻게 하겠다는 거죠?$B$B아무래도 여기 오래 있을 것 같은 불길한 예감이 들어요. 아주 오래 말이에요..."
rows["387:877042007"]="오, 맞아요. 담즙 얘길 하고 있었죠. 놀라운 물질이더군요. 담즙과 함께 적당한 촉매만 사용하면 무엇이든 간에 말 그대로 불멸의 존재로 변한답니다. 그간 새로 프로그래밍한 담즙로봇 800으로 담즙을 모아서 실험했는데, 이번엔 정말 제대로 된 혼합액을 만들었다고 자부해요. 이제 혼합액을 적당한 생명체에게 실험해 보기만 하면 돼요. 자원자가 필요한데, 혹시 생각 있으세요?\010<갑자기 목소리가 작아지는 핑클> 아, 위에서 정의한 \"불멸의 존재\"에게는 특정한 제한 조건이 따른다는 점 유의하시고요..."
rows["388:113167387"]="미니어 탱크, 또는 우리가 똑똑하게 이름 붙인 토닉, 내가 기억할 수 있는 한, 페어 좋아하는.$b$b우리는 2개의 경기장을 토크 전투에 전용하고 있습니다.$b$b한 경기장은 시계를 향해 달려가서 목표를 파괴하고 적의 기구를 피하는 것입니다.$b$b다른 아레나는 자신의 탱크나 미니제프를 이용해 친구들을 싸울 수 있는 곳입니다."
rows["388:1201619134"]="<병은 숨쉬고, 그의 손잡이가 검의 손잡이를 거의 꽉 차 있지 않고, 그의 팔은 상처에서 여전히 튀어나오는 화살표의  ⁇ 에 의해 깨끗하게  ⁇ 어진 어깨에서 쓸모없는 걸려있다.>$b$b북녘골 밸리는 조용한 포스트가어야 했지...  ⁇  행운의 날라!$b$b<그분께서는 그의 쓴맛을 땅에 뱉고  ⁇ 어:>$b$b저게 망할 거야, 난 여기서 죽지 않을거야"
rows["388:969374338"]="아비아나는 사라진 하늘의 수호자이자 만 년 전에 악마의 무리와 싸우다 전사한 새의 여신이다. 놀드랏실 남서쪽에 그녀를 기리는 제단이 있다. 거대한 나무가 감싸고 있는 곳이지.$B$B갈퀴발톱의 드루이드들이 그 안에 근거지를 두고 있는데, 우리는 그들의 지원이 필요하다. 그래서 그들을 도와야 한다. 아비아나도 도와 주거라. 그녀가 이 세계로 돌아올 수 있도록..."
rows["389:1069581195"]="폭풍우 봉우리 안에 있는 돌의 전당은 77에서 79 레벨의 플레이어가 공략할 수 있는 던전으로 지금 시험해볼 수 있습니다. 던전 안으로 순간이동하기 전에 파티를 맺은 상태여야 합니다. 만남의 돌은 아직 사용할 수 없습니다. 돌의 전당에서 나오려면, 던전 안에 있는 입구로 빠져나오면 됩니다. 그러면 바로 여기로 돌아오게 되지요. 죽어서 영혼이 빠져나갔다면 다시 NPC와 대화하여 순간이동해야 합니다."
rows["389:978251985"]="저는 상인이에요. 이 도시는 분명히 더 좋은 시대를 보았지만 전쟁도 기회입니다. 이 지역의 광산에 투자할 좋은 시간입니다. 스카데일드 산맥은 관대합니다.$b$b네, 내가 잠시 여기서 머물게 될거야. 내 아내가 여정을 할 때까지 스톰윈드그럼, 내가 생각하기에, 우리는 함께  ⁇  카자드로 돌아갈 것입니다. 이 모든 시간이 지나서 너무 그리워합니다."
rows["38:117082088"]="지금 훈련 중이야 잠깐 기다려줄래?"
rows["38:1181582758"]="마음 속에서 말하는 소리를 들어요?"
rows["38:1233119000"]="안녕하세요! 저는 지나라고 해요! 당신은요?"
rows["38:1241234407"]="어떤 직업을 배우려고 하는 건가요?"
rows["38:1258620679"]="어서 오십시오, 감독관님. 공격 준비는 됐습니까?"
rows["38:1292836613"]="이제 더 이상 말해줄 게 없다. 여길 떠나라."
rows["38:1333271339"]="나는 구로크, 헬스크림 선봉대원이네."
rows["38:1336157992"]="계속 움직여야 하네. 준비됐나?"
rows["38:1346091376"]="멋진 사냥 친구가 생겨서 좋아."
rows["38:1380948865"]="멜리호는 세상에서 제일 멋진 배지요!"
rows["38:1413099756"]="테론 고어핀드라고? 그래... 그를 알지."
rows["38:1514451478"]="아훈이 일어날 때, 우리도 준비되어 있겠지요?"
rows["38:1518046576"]="경매장 여기 있어. 도시 중앙에 있는 원 쪽에."
rows["38:1525167198"]="우리 납골당에서 시체들이 일어나고 있습니다!"
rows["38:1540652047"]="브룬힐다르의 영광을 위해!"
rows["38:1550756730"]="저희 야영지에 잘 오셨습니다. 무엇을 도와드릴까요?"
rows["38:1575694615"]="<한숨>...$b$b좀 도와주실 수 있겠어요?"
rows["38:1650665748"]="그건 네 귀여운 목소리를 더 잘 듣기 위해서란다."
rows["38:1671665498"]="이 차원문으로 들어가면 톨 바라드로 갈 수 있습니다."
rows["38:1674310436"]="손을 대자 기계가 살아난 듯이 움직입니다."
rows["38:1729149190"]="하늘은 위험한 곳이오. 조심하시오!"
rows["38:1808705982"]="흥! 난폭한 타우렌 따위 전혀 무섭지 않습니다."
rows["38:187771610"]="반갑습니다, 엘룬의 빛이 그대와 함께하시길..."
rows["38:1926681681"]="이끼걸음골록의 부상이 심각한 것 같습니다."
rows["38:1931438050"]="제가 이 사후 세계에서 어떻게 도와드릴까요?"
rows["38:1976322402"]="조심스럽게 포장된 선물 더미가 있습니다."
rows["38:1979354340"]="기분이 별로 안 좋으세요? 체리 파이 좀 들어보세요. 금방 기분이 좋아질 거예요."
rows["38:2133427789"]="푸른용군단에 무슨 청을 하러 오셨나요?"
rows["38:295669802"]="내가 어디 있어?"
rows["38:338310682"]="당신 누구요? 나한테 뭘 원하는 거요?"
rows["38:409552564"]="우리의 확고한 동맹이여, 원하는 물건이 있으신가요?"
rows["38:413183142"]="여기, 누가 이 개구리 좀 잡아 주세요!"
rows["38:52318313"]="머리가 없는 승마자는 겁에 질렸어!"
rows["38:683823298"]="여기서부터는 조심하시오, 이방인 친구."
rows["38:696337783"]="이봐요! 절 트롤 형제들한테 데려다 주십시오!"
rows["38:737200716"]="아, 저와 같은 순찰대 소속이로군요. 무슨 일이십니까?"
rows["38:787807276"]="몇 초라도 쉬게 해주십시오."
rows["38:849557810"]="<위엄 가득한 어깨를 퍼덕거리는 플라스카타우르스>"
rows["38:945672083"]="아는 건 다 말했다고. 이제 가버려!"
rows["38:95058081"]="다음으로 어떤 기름을 선택하겠습니까?"
rows["390:1174644236"]="군인은 숨쉬고, 그의 손잡이가 검의 손잡이를 거의 꽉 잡고, 그의 팔은 상처에서 여전히 튀어나오는 화살표가  ⁇ 어있는 어깨에서 쓸모없는 걸려있다.\010\010북녘골 밸리는 조용한 포스트가어야 했지... \"부재한 행운\"이라고 그들은 말했지, 나를 여기 배치하게 해줬기 때문이었어!\010\010<그분께서는 그의 쓴맛을 땅에 뱉고  ⁇ 어:>\010\010저게 망할 거요, 난 여기서 죽지 않을 거예요."
rows["390:757657808"]="제 동족 대부분은 호드가 야만적이라며 경멸합니다. 저도 한때 그런 이들 중 하나였지요. 그래서 습기 차고 향기로운 이곳으로 이동하라는 명령을 처음 받았을 때는 제 운명을 얼마나 원망했는지 모릅니다.$b$b그런데, 여기서 연구를 하던 중에 제가 처한 환경에 감사하게 되었지요. 독특한 매력이 있는 곳입니다. 그렇지 않습니까?$b$b...마법사가 아니니 제가 어떤 연구를 했는지 궁금하시지는 않겠죠?"
rows["390:982684810"]="스카데일드의 마녀들은 에알디르가 서로 목을 찢지 않고 헤드 타이틀을 얻기 위해 함께 있는 지름길입니다. 스톰윈드 첫 번째 돌을 세웠지만, 저는 옛 아내들의 이야기에 대해 별로 신경쓰지 않습니다."
rows["391:1408825621"]="세나리온 의회의 요원들이 엘드레탈라스의 현재 상황과 관련해 우려할 만한 정보를 알아냈소. 벼랑 끝에 매달린 상황이라 분명 힘깨나 쓰는 이들의 도움이 필요할 테지.$B$B하지만, 엘드레탈라스에서 제대로 행동을 취하려면 풍요의 열매라고 알려진 물건에 대해서 잘 알아 둬야 하오."
rows["391:1790478928"]="당신을 여기로 보내 주신 여신께 감사를! 클로와 나는 이곳을 조사하던 중 늪군주 뮤즐레크의 습격을 받았소.$B$B안타깝게도 클로는 곰으로 변신한 상태에서 붙잡혀, 뮤즐레크의 소환수 신세가 되었다오.$B$B클로를 구하려면 그와 싸워야 할 거요."
rows["391:377802007"]="이 계곡에 모든 사람들이 환영합니다. 첫발의 발걸음이 얼마나 무작위로 또는 잘못 인도되었는지 상관없이.$b$b<페일리라의 파란 눈은 울빈과 울프릭에 잠시 머물고 있습니다>$b$B이 땅 에 처음 발을 디딘 때, 저는 그 들 과 그렇게 다르지 않았습니다. 저도 마술을 타오르는 나무나 기름처럼 보았어요."
rows["392:520129030"]="무너진 태양 공격대가 쿠엘다나스 섬 외곽 지역에서 상황을 크게 진척시켰습니다. 킬제덴의 군대는 밀려나는 중이며, 나는 혼란스러운 틈을 타 소규모 정찰단을 이끌고 태양샘 고원 안으로 갔습니다. 우리 부대는 무리해 광장을 통과할 때 태양칼날단 소속 블러드 엘프 무리 몇몇을 발견하고 전투를 벌였습니다. 그리고 그 전투는 곧 엄청난 재앙으로 돌변하고 말았지요."
rows["393:1748671623"]="나는 그대와 같은 젊은 드루이드를 강화시켜 주기 위해서 존재한다. 그대가 내게 힘을 얻으러 왔으니 가르침을 내려 주겠다. 그대가 내 말을 귀 기울여 듣고 이해할 준비가 되었다면 나... 거대한 곰의 혼에 대한 모든 것을 배울 수 있다.$B$B그리고... 그대의 영혼에 의지한다는 것이 무슨 의미인지 알려면, 정신의 힘뿐만 아니라 육체적 힘의 중요성도 이해해야 한다."
rows["393:414690574"]="흠, 흠... 젊은 친구가 강력한 재료를 찾는군. 얼라이언스의 이름으로 자네는 많은 적을 처치하겠지만, 거대한 순환의 고리에서 탄생은 죽음만큼 강하다는 걸 명심하게나.$B$B<천천히 자기 머리 위로 고개를 들고 눈에 잘 안 띄는 도토리를 따더니, 느긋하고 침착하게 당신에게 팔을 내리는 오누>$B$B이 도토리는 대단히 강력하다네.$B$B뽐내는 소리로 들리길 원치 않았는데... 사과하겠네."
rows["393:638343028"]="황천날개 벌판의 동쪽 경계으로 가면 용아귀 요새가 펼쳐져 있지. 바로 그곳에서 잔인한 용아귀 오크들이 비룡을 조련하려고 고문을 하고 있다. 많은 비룡이 용아귀 부족의 명령을 듣느니 차라리 희망을 버리고 말았지. 나머지 비룡들은... 용아귀 오크들에게 사로잡혀 요새로 끌려갈까 두려워 다시는 땅으로 내려오지 않았다."
rows["394:1625278620"]="카자마이트란... 알겠지만, 전설 속의 그 물건 덕분에 고블린 종족 전체가 연금술과 기계공학 분야에서 궁극의 대가로 발전할 수 있었다지?!$B$B그 때문에 우리는 압제하던 정글 트롤을 거꾸러뜨리고 케잔을 다스릴 수 있었어. 케잔이 영원히 평안하길. 존재하는 모든 것 중에 가장 값진 광석이란 말이야!$B$B이봐, 이 원숭이들에게 어떤 영향이 있는 것 같지 않아? 안 그래?"
rows["394:1801729268"]="입대신청서를 쓰거나 할 필요는 없지만, 어쨌든 그와 함께 싸워야 합니다.$B$B반드시 아서스가 스트라솔름을 파괴하고 말가니스를 처치하게 이끌어야 해요. 우서와 제이나가 곁에 없으니 아마도 손이 모자라겠지요.$B$B아서스에게 말을 걸면 말가니스의 부대를 격파하라는 임무를 줄 거예요. 무한의 용군단에서 꾸미는 수작이 뭔지 내가 알아낼 때까지 계속 그를 따라다니셔야 해요. 더 자세한 정보를 얻으면 다시 연락하겠어요."
rows["394:2005711087"]="그래? 그렇다면, 하이 엘프들이 사용하는 트롤 주술이 아주 약하고 형편없다는 것도 알고 있소?$B$B하이 엘프들은 자신들의 마력과 비슷한 트롤 주술에 왜 맞설 수 없는지 의아해 했지만, 트롤 주술이란 허여멀건 얼굴의 하이 엘프 놈들 따위는 절대로 이해할 수 없는 것이오. 결국, 트롤 주술의 흉내만 내는 하급 마법을 사용하는 데 그치고 말더군. 놈들은 그걸 '영석'이라고 부르는 모양이오."
rows["394:851891164"]="[질문을 한 후 꽤 오래 시간이 지난 후...]$B$B현재 요청하신 정보는 본 정보 저장소의 자료에서 찾을 수 없습니다. 원하시는 정보를 제공하지 못한 데 대해 진심으로 사과 드립니다.$B$B본 정보 저장소의 자료 주기가 경신된 후에 요청하십시오. 아제로스에 있는 다른 정보 저장소에서 요청하실 수도 있습니다."
rows["395:1114864757"]="이 거리가 너무 빈 거리가 너무 조용해 시장을 너무 조용해$B$B트롤 공격, 엘더의 함락... 정말 그렇게 나쁘다고 믿기 힘들어요. 상황이 이렇게 끔찍하다면, 그들은 군대를 파견했을 겁니다.$B$B<브리나는 머리를 옆으로 흔들고 팔을 접는다.>$B$B그래이스키에 머무는게 좋으면 좋겠어요"
rows["395:1383811195"]="그날따라 윈저 님은 완고했소. 그 정도도 아주 대단한 성과였지, 정말이오. 윈저 님께서는 계속 \"뭔가 느낌이 좋지 않다\"라고 말씀하셨는데 그 말이 맞아떨어진 거요!$B$B검은바위 산 중턱에 있을 때 끔찍한 짐승들에게 습격을 당한 거요. 그 짐승이란 물론 오크를 말하는 거요. 내 말에 집중 좀 해주겠소? 녀석들이 돌진해 오는데, 으르렁대는 소리와 쇠 부딪히는 소리 때문에 바람도 잠잠해질 지경이었다오."
rows["395:181812752"]="이곳이 바로 굴단이 오크와 정령 사이의 연결 고리를 제거한 장소라오. 힘에 대한 그의 끝없는 갈증은 드레나이의 전멸로도 채울 수가 없었지. 굴단은 드레노어도 멸망시켰는데, 대지를 파괴해 그 힘을 모조리 흡수하여 전쟁에 사용했소.$B$B이제 남은 것이라고는 그의 광기밖에 없소.$B$B$r|1이여;여;, 제단을 보시오. 대지에서 분노한 넋들이 끝없이 출몰하고 있소이다..."
rows["395:894126816"]="<하워톤은 눈 ⁇ 을  ⁇ 니다>$B$B'사격'이라는 용어를 사용하지 않기를 더 좋아하지만, 예, 공격은 무결히 진행되었다. 우리는 타우라조를 방정식에서 제거하고, 그 의 의 무기를 압수하고, 그 의 금기 시설을 파괴했습니다. 공격은 우리 의 군대에 상당한 호흡 공간을 제공했고, 적 의 균형을 잃게 했습니다.$B$B하지만, 공격 중에, 저는 제 부하들에게 우리의 선에 구멍을 놔두고..."
rows["396:1313791147"]="역겨움이 밀려왔어. 의식이 끝난 후 난 아이들이 있는 집으로 달려갔네. 양팔에 들 수 있는 만큼만 짐을 챙겨서 아이들과 함께 떠났지. 우리는 언덕으로 가서 숨었네. 정말 다른 선택의 여지가 없었거든...$B$B하루라도 끊어진 연결 고리에 대해 생각하지 않은 날이 없었네. 정령들과 연결 고리를 회복하는 데 20년이 걸렸고 정령들이 치유를 시작하는 데 또 20년이 걸렸지."
rows["396:1825278508"]="청동용군단 말일세. 그들이 죽음의 가장자리에서 나를 잡아 올려 그들의 주인인 노즈도르무에게 데려갔네. 노즈도르무 말로는 청동용군단이 나를 지켜보고 있었다면서 내가 하던 여행을 계속하길 원한다더군. 노즈도르무는 내게 감시자로서 영원한 생명을 주고 그의 부하로서 아제로스의 역사를 지켜보라는 임무를 부여했네.$B$B그래서 나는 목격자 자란타우르라네. 그리고 아제로스의 진짜 역사가 잊히지 않도록 보존하는 것이 내 임무일세."
rows["396:979896467"]="작동 중지된 태양칼날단 파수병을 이용하십시오. 태양칼날단 정찰병이 그대를 발견하면, 근처에 있는 태양칼날단 파수병을 다시 작동시키려 할 것입니다. 그러지 못하도록 재빨리 정찰병을 처치하십시오. 그 블러드 엘프 정찰병을 처치한 다음에 파수병에 있는 근접 감지 장치를 건드리지 않으면, 싸우지 않고도 파수병 옆을 지나칠 수 있습니다. 그러면 시간과 노력을 많이 절약할 수 있을 것입니다."
rows["397:384525274"]="창조주들은 자신들이 사용할 목적으로 울둠의 원반을 여러 개 만들어두었습니다. 원반을 세계 각지에 배포하는 건 그들의 일입니다. 아제로스 방문 일정이 변경되었고 결과적으로 그때 원반이 추가로 배포될 수 있는 것입니다.$B$B기존 원반은 보안 권한이 있는 자들에게 이미 모두 배포된 상태입니다."
rows["398:1062979734"]="저는 여러 곳을 여행하면서 위습망토 만드는 법을 익힐 수 있었습니다.$B$B이 망토는 체력과 주문력, 지능과 마나 회복률을 높이는 주문 시전자용 영웅급 망토로서 제작할 수 있습니다. 이 도안을 가르쳐 주어도 좋을 만한 이를 찾고 있었지요.$B$B노스렌드에 있는 모든 일반 던전을 섭렵하고 \"노스렌드 던전 전문가\" 업적을 달성한 사람이라면 위습망토 만드는 법을 배울 자격이 있다고 생각합니다."
rows["398:1319279820"]="악마의 룬 가슴보호갑을 만드는 데 사용하는 벼리지 않은 룬문자 가슴보호갑을 갖고는 도망쳐버렸지. 영혼도 주지 않고 날랐어. 하지만 난 바보가 아니지... 벼리지 않은 룬문자 가슴보호갑은 악마의 룬을 모르면 아무 쓸모도 없거든.$B$B혹시... 검은바위 첨탑에 틀어 박혀서 악마의 룬 가슴보호갑을 만들려고 하는 게 아닐까? 거기서 떠날 배짱이 없는 건 알거든!"
rows["398:455051508"]="내가 보여요? 아무도 날 볼 수 없었는데! 내가 여기서 얼마나 외로웠는지 모르실 거예요. 마침내 말동무가 생기다니 얼마나 즐거운지 몰라요!$B$B나의 옛 용병군단 중 살아남은 누군가가 보냈겠죠. 맞죠? 당연히 맞겠죠!$B$B새로 생긴 말동무와 많은 대화를 나누고 싶지만 어서 이 사태부터 바로잡아야 해요. 군주 발타라크에게 그의 영혼을 돌려주려면 우린 할 일이 너무 많아요!"
rows["399:1074997921"]="내 앞에서 비켜라, 꼬마야! 내가 훈련 중인 게 안 보이느냐? 그래, 너는 다음 대의 전쟁망치 용사가 될 수 있을 것이다.$B$B맞다, 나는 오래된 웃는 해골 폐허의 북쪽에 있는 피의 투기장에 참가할 준비가 거의 끝났다. 하지만 꿈도 꾸지 말거라, 꼬마야. 너는 아직 너무 약하다. 투기장 진행자인 굴그토크는 네가 그곳에서 싸우는 것은 고사하고 훔쳐보는 것도 허락하지 않을 것이다.$B$B이제 녀석이 널 때려눕히기 전에 때려눕혀라."
rows["399:1541759550"]="드디어 이 감옥에서 해방이 됐군!$B$B나는 이곳 은빛소나무 숲에서 아루갈이 언데드를 어떻게 상대하고 있는지 조사하라는 키린 토의 지시를 받고 달라란에서 왔습니다. 아루갈이 미쳐버린 줄은 아무도 몰랐지요.$B$B즉시 이 사태에 대해 보고를 해야 합니다! 하지만 떠나기 전에 안마당 문에 걸린 마법 자물쇠를 풀어 드리지요.$B$B당신은 레실고어를 물리쳤으니 아마 이 문 너머 세상에서도 살아남을 수 있을 겁니다."
rows["39:1014816517"]="만찬에 초대된 손님은 좀 더 격식을 갖춰야 합니다!"
rows["39:1060992382"]="내가 지도에 표시해주겠네."
rows["39:1107630266"]="그렇게 저를 계속 뚫어지게 봐도 제가 예뻐지지는 않아요."
rows["39:1117856848"]="더글라스 님이 보냈다고요? 매운맛 좀 보라는 게죠."
rows["39:1127758501"]="나가를 향한 공격에 참여하고 싶으신가요?"
rows["39:1353759479"]="소인족 때문에 수입이 자꾸 준답니다!"
rows["39:1404154971"]="비상 탈출용 차원문입니다."
rows["39:1420265801"]="도적 지구 내곽에 있다."
rows["39:1424599196"]="제가 도와드릴 일이라도 있습니까?"
rows["39:1437777456"]="난 내 모든 것을 바쳤어 호드..."
rows["39:1454114247"]="대지 고리회 화톳불에 도착했습니다!"
rows["39:1583217791"]="마르텍, 내가 아는 가장 용감한 오크야"
rows["39:1586211837"]="음? 뭔가?$B$B시간 없으니 빨리 말해 보게!"
rows["39:1634171769"]="훈련을 받으려고 오셨나요, 사냥꾼이여?"
rows["39:1716097899"]="얼음발 곰이 평온하게 누워 있습니다."
rows["39:1721339908"]="<킁킁거리며 냄새를 맡는 펄볼그>"
rows["39:1726757955"]="내랑 싸울 준비가 돼있지?"
rows["39:1739319241"]="몹시 피곤해 보이시는군요. 뭔가 잘못됐습니까?"
rows["39:1761532797"]="내가 할 일이 있어"
rows["39:1893860613"]="이 길이 맞습니까, 친구?"
rows["39:1904622318"]="저랑 한판 하고 싶으신 눈친데요..."
rows["39:1950041485"]="위질 슬립섀도, 위장의 대가!"
rows["39:2129431147"]="제게 돈을 내고 배우실 게 있나요?"
rows["39:221561657"]="뭘 망설이세요?! 모두에게 한 잔씩 돌려 보아요!"
rows["39:480292574"]="안녕하신가, 나는 너울소나무 일족의 늙은 사냥꾼인 무르도라고 하네."
rows["39:584442633"]="[펄볼그어] 밀로크 킥스 아일핀 오 움토르..."
rows["39:638586327"]="자네를 보게 되어 영광이로군."
rows["39:655474136"]="우리 친구이신 당신을 위해 먹자판을 벌려 드리지요."
rows["39:773384608"]="리본 스틱에 춤을 췄어?"
rows["39:873030448"]="가자 트로스프로켓을 구해봐"
rows["3:1798545"]="안녕하세요"
rows["3:1799086"]="음?"
rows["400:2049229713"]="주문각인을 배우면 마법 두루마리, 문양, 고서, 다크문 카드와 다른 기술에 필요한 도안 등을 만들 수 있습니다.\010주문각인에 필요한 재료 대부분은 약초를 빻아서 만들 수 있기 때문에 주문각인과 약초채집은 좋은 짝을 이룹니다.\010주문 각인에 필요한 숙련자의 필기구와 그 외에 양피지 등의 재료는 주문각인용품 상인에게서 살 수 있습니다."
rows["400:734904535"]="오래전, 내 드리아드 자매들과 나는 내 숙부 재타르의 고통받는 영혼을 풀어 드리기 위해 이 동굴에 들어왔었네. 하지만 우리도 곧 이 동굴에 이미 퍼져 있던 타락에 제압돼 쓰러져 버렸지.$B$B우리는 이 길에서 방황할 운명을 맞게 되었고, 우리의 정신에는 독이 퍼지고 있었어...$B$B이제 내 영혼은 쉴 수 있게 됐지만 내 임무는 실패한 것이라는 걸 아네. 내가 짊어져야 할 큰 슬픔이지..."
rows["401:1926462093"]="첫 번째로 만든 무쌍의 전투장비는 붉은십자군 대영주 모그레인만을 위한 것이었소. 대영주가 무쌍의 전투장비를 입고 있으면 황천 깊숙이 있는 악마와 다름없는 모습이었지.$B$B그렇소, 모그레인이 파멸의 인도자를 높이 들고 백 명의 스컬지에게 뛰어들었다가 반대편에서 먼지와 화염 구름을 뚫고 나오는 모습은 정말 장관이었소. 적들은 그의 발아래 재로 변했지."
rows["401:199453848"]="대모의 의무는 귀를 기울이는 것이라네. 바람과 물과 불, 그리고 대지의 소리에 귀를 기울이는 것이지. 온기를 지키기 위해 지푸라기를 모으는 짐승들처럼 부족을 위해 정보를 모으는 것이야. 나는 영혼들과 대화를 하지... 꿈속에서 대모 카슈르는 예전에 그녀와 대화하던 영혼들처럼 내게 말을 건다네... 내가 죽으면 나도 이런 식으로 드라키아와 켈레스틴에게 이야기를 들려줄 걸세.$B$B<빙그레 웃는 대모 게야>"
rows["401:2104136867"]="우리 민족은 이 수용소에서 인간에게 노예로 잡혀있었고, 저는 이 교두방에 갇혀 있었고, 내 형제들이 이 줄기 속에 갇혀 있고, 그 목에 매달려있음을 보았습니다.$B$B우리 모두의 리더 오그림 둠햄러가 뒤에서 칼을 찔러 죽었음을 봤어요. 그의 피가 우리가 서 있는 땅을 검은색으로 지게 했습니다.$B$B이제 우리 모습을 보세요. 이것이 우리의 유산입니다. 우리는 모든 것을 잃었고,"
rows["401:717961797"]="무역연합은 수개월 동안 이 작업을 계획해 왔다! 우리는 세계에서 가장 큰 다이아몬드라고 알려진 오슈군을 캐려고 했다.$B$B하지만, 채굴을 시작하려고 했을 때 연합왕자 하라매드께서 작업을 중단하라는 명령을 내렸다. 황천의 폭풍에서 정치적인 문제가 해결될 때까지 기다리라는 것이었다. 그래서 당분간 밀수한 보석을 모아서 파는 일을 하고 있는데 이것이 점점 수익을 갉아먹지 뭔가..."
rows["401:841552210"]="창조주 또한 본 저장소에 보관된 정보가 방대하다는 사실을 인식하고 있습니다. 노르간논의 원반만 맞춘다면 이곳에 저장된 자료의 복사본을 이용하실 수 있습니다.$B$B이제 당신은 본 정보를 이해하기 위한 최소한의 요구 사항은 모두 갖추었습니다. 원하시는 때 노르간논의 원반에 접속해 원반을 조합하기만 하면 됩니다."
rows["402:1091468908"]="넌 그 사람들 중 한 명 아냐, 엘프야$b$b<어떤 이유로, 기둥은 당신을 보고 편안해 보인다.>$b$b예, 예, 그들은 매우 예쁘고, 다른 것을 말하지 않을 것입니다. 어쩌면 그것이 나를 너무 불안하게 합니다. 다라란의 부풀어 오르는 앵무새와 대우를 익숙해짐에 따라, 이 엘프들은..."
rows["402:1110947518"]="첫 번째로 만든 무쌍의 전투장비는 붉은십자군 대영주 모그레인만을 위한 것이었소. 대영주가 무쌍의 전투장비를 입고 있으면 황천 깊숙이 있는 악마와 다름없는 모습이었지.$B$B그렇소, 모그레인이 파멸의 인도자를 높이 들고 백 명의 스컬지에게 뛰어들었다가 반대편에서 먼지와 화염 구름을 뚫고 나오는 모습은 정말 장관이었소. 적들은 그의 발아래 재로 변했지."
rows["402:1351361922"]="또 다른 방황자가 내 겸손한 캠프를 찾습니다.$B$B< 포세이큰의 움직임은 거품으로 튀어나오는 모습입니다. >$B$B우리처럼 자유의지를 가진 아가만드 죽은 자 - 무의식적인 인형들을 연구하는 것 포세이큰.$B$B왜 우리가 다른가? 왜 우리가 리치 왕의 통제에서 해방되었는데 그들이 노예로 남아있었는가?$B$B암흑의 여인은 우리의 연구를 격려하지만 난 언더시티에서 호기심을 가진 눈을 떠나고 일하는 것을 선호한다."
rows["402:442498169"]="여행자여, 반갑소. 나를 만난 걸 행운으로 여겨야 할 거요. 동부 왕국에서 나를 만난 자는 아주 드무니까 말이오.$B$B내 이름은 리베른... 여명의 설원 눈호랑이를 탈것으로 훈련시킨다오.$B$B이 눈호랑이는 가장 사납고 다루기 어려운 맹수 중의 맹수요. 신뢰와 확고한 동맹으로 인정받는 자만이 탈 수 있다오.$B$B아무에게나 팔지는 않을 뿐 더러 열심히 노력해서 나뿐만 아니라, 눈호랑이에게서도 인정받아야만 하오."
rows["402:732236350"]="보너티 테이블은 5개의 순례자 보너티 음식으로 각 의자에 하나씩 배치되어 있습니다.$B$B의자 에 앉아 있을 때, 그 음식 을 원하는 만큼 먹을 수 있고, 그 음식 을 다른 의자 들 에게 전달 할 수 있습니다.$B$B만약 여러분이 한 음식으로 충분히 섭취한다면, 그 음식에 대한 특유의 혜택을 얻을 수 있습니다.$B$B또한, 모든 음식을 충분히 먹으면 공유의 정신을 얻게 될 것입니다!"
rows["403:1074731761"]="주문각인을 배우면 마법 두루마리, 문양, 고서, 다크문 카드와 다른 기술에 필요한 도안 등을 만들 수 있습니다.\010\010주문각인에 필요한 재료 대부분은 약초를 빻아서 만들 수 있기 때문에 주문각인과 약초채집은 좋은 짝을 이룹니다.\010\010주문 각인에 필요한 숙련자의 필기구와 그 외에 양피지 등의 재료는 주문각인용품 상인에게서 살 수 있습니다."
rows["403:108387016"]="저는 순금 서판에다 양심의 가책, 부끄러움, 후회, 그리고 슬픔을 새겼습니다. 그런데 그 서판을 발견한 황혼의 망치단은 제게 신성 모독자라는 낙인을 찍었습니다. 엘룬께 올리는 기도문을 완성하지도 못한 채 그 자리에서 처형되고 만 것이지요. 이제는 영혼이 이 세계에 구속되어 황천으로 갈 수도 없게 되었습니다. 황혼의 망치단을 배신하는 자들에 대한 경고로 이 우리에 갇히게 되었습니다."
rows["403:1736583797"]="전쟁 은 전장에서 승리 하지만 전선 에서 멀리 떨어진 곳 에서 승리 합니다. 그것은 검 으로만 치지 않고, 책, 아바쿠스, 편지, 지도 로 치른다.$B$B이 요새가 여전히 남아 있는 이유는 우리 군인들의 용기와 민간인의 참여 때문인데, 그들 없이는 안드라스테의 전투 근육은 빠르게 소모될 것입니다."
rows["403:487284833"]="경쟁의 영을 아세요?$B$B두 년 마다 그들은 필사적 영역에 가까워진다. 그러한 시간 동안, 얼라이언스 과 호드 의 구성원들은 서로 물리치고 그들의 호의를 얻기 위해 경쟁자 타바드를 전투장에 착용합니다.$B$B난 이런 혼란스러운 시대를 기억하는 기념품을 저장해두고 있어"
rows["404:1634648774"]="우리는 여군주 마랄리스를 지휘관님께 데리고 갔네. 세나리온 의회의 드루이드라면 그녀를 고칠 수 있을 거로 생각했기 때문이지. 역시 드루이드는 뭔가 다르더군. 그들 덕분에 여군주 마랄리스는 정신을 차렸네. 다행히 그녀도 회복하고 해서 우리는 다시 조사를 시작할 수 있을 거라 생각했지.$B$B그 후 몇 주 동안은 브란 님도 돌아오실 예정이었고 해서 조직도 정비해 가며 별문제 없이 지냈지. 그러던 어느 날 뜻밖에 그녀가 우리 야영지에 찾아왔네."
rows["405:1313212806"]="장가르 습지대에 가본 적이 있으면 다니엘스라는 친구를 만나봤을 걸세. 거 왜 있잖나... 이상한 보호모를 쓰고 \"전문가\"에게만 대답하는 친구 말일세.$B$B아, 물론 내가 그에게 모든 것을 가르쳤지.$B$B그 친구의 휘황찬란한 옷에 현혹되지 말게. 마음속으로 아직 난 도적이지. 다니엘스와 나는 많은 시간을 함께 일했지만 그 시절은 내가 은퇴하기 전이지. 내가 알기로 그 친구는 주위 사람들을 못 배기게 하면서 아직도 활동하고 있다네."
rows["405:1473242341"]="여하튼, 여길 건설하는 데 모래와 연료가 많이 필요했죠. 마침 근처에 있던 웅덩이가 재료를 구하기에 딱 좋았어요.$B$B어떤 모래에는 마법적인 속성까지 깃들어 있었거든요... 뭔가 얽힌 얘기가 있을 것 같죠? 하지만 그 얘기는 일단 접어두고...$B$B그래서 우린 물을 모조리 퍼내고 그 한가운데에 채굴 현장을 차렸지요. 주 흡입관이 막혀버리기 전까진 일이 아주 잘 풀렸어요."
rows["406:1696205670"]="하하! 그들의 지도자를 제외하고 - 사타이르, 바잘란, 마녀 제고시 - 네, 그들 모두. 그래서 나는 끊임없이 Thrall의 숭배자를 그들에게 보내. 그것은 그의 위대한 도시의 내장에서 악을 제거하고 있다는 인상을 Thrall를 제공합니다. 승리는 실제로 두 가지: Thrall의 신자들을 죽이고 그들이 정말로 나에게 합류할 가치가 있는지 확인하기 위해 세어링 블레이드에있는 사람들의 힘을 테스트."
rows["408:1212389824"]="셴드랄라는 아즈샤라 여왕의 가장 신임받는 비전술사였어요. 온통 성벽으로 둘러싸인 바로 이곳에서 여왕이 맡긴 중요한 일들을 비밀리에 처리했지요.$B$B영원의 샘이 파괴되고 그로 인해 나이트 엘프 명가를 비롯한 모든 계층이 권태에 빠지자 엘드레탈라스의 왕자 토르텔드린은 서쪽 전당에 흩어져 있는 수정탑들을 짓기 시작했답니다."
rows["408:1385825785"]="블러드 엘프가 악마사냥꾼으로서 잠재력이 매우 강력하다는 사실은 그리 놀랄 일이 아닐세. 그러니까, 신도레이는 나이트 엘프들처럼 악마의 마법에 혐오감이 없네.$B$B하지만, 성공할 자가 많지는 않을 거야. 베레디스를 포함한 대부분이 자신만을 위해 힘을 추구하고 있거든. 그 힘에 오히려 압도당하고 말 거야. 왜냐하면, 그들에게는 진실한 악마사냥꾼의 가슴에서 불타올라야 하는 순수한 열정이 없기 때문이지."
rows["408:574371880"]="<목을 가다듬는 카란>$B$B우린 이글거리는 협곡의 지하도를 지나 파괴된 황무지로 들어섰었소. 지금 생각해 보면 소름이 돋을 정도로 조용했소이다. 지나가는 길에 부닥친 것이라고는 그 지역의 야생동물들뿐이었고 내 부하들이 손쉽게 해치웠지.$B$B우리는 그나마 쉽게 검은바위 산에 이르러 아무런 일도 없이 돌다지 건물들을 지나갔소."
rows["408:747801649"]="<노인들의 시선은 구름이 흐른 하늘 어딘가에 사라져 있습니다. 한 손으로  ⁇ 을  ⁇ 습니다. 그가 당신의 존재를 알아차렸을 때, 그는 손을 들어주고, 당신을 기다려야 한다고 요청합니다.>$b$b< 몇 초 후에 그는 이렇게 말합니다>$b$b자연은 그녀의 아름다운 작품들과 연결되었습니다$b내 안에서 달린 인간 영혼$b그리고 생각하면서 마음이 슬퍼했습니다$b인간이 인간을 어떻게 만들었는가?$b$b어떻게 생각하시나요? 빛은 시에 대한 영감을 줄 수 있다고 생각했습니다."
rows["409:54435775"]="글쎄요, 당신이 어떤 동료를 얘기하는지에 따라서 할 말이 달라지지요. 몇 년 동안 많은 동료를 만났다 헤어져서 말입니다. 버드 네드렉의 전설에 어떻게든 끼여 보려는 사람이 한둘이겠습니까?!$b$b제 지난 동료 대부분이 부자가 되어 은퇴했다는 사실은 믿어도 됩니다. 다만 그 길이 제가 가고 싶은 길은 아닐 뿐이죠. 전 항상 세계의 위대한 신비를 밝혀내는 일을 해야 한다고 생각해왔습니다. 이거 참 귀찮지만, 제가 아니면 누가 하겠습니까?"
rows["409:567636973"]="그나마 네파리안은 적합하지 않은 실험 대상은 즉시 없애버리라고 명령했지만, 이 천벌 받을 괴물들은 죽을 때까지 끔찍한 고문을 가했어요.$B$B놈들은 우리를 철저하게 '망가뜨린' 후 목숨이 붙어 있는 자와 죽은 자를 모두 모아 이 악당들에게 던져주었지. 녀석들은 우리의 몸을 가지고 온갖 더러운 놀이를 했어요. 용암 속에 던져 넣기도 하고, 피에 굶주린 병사들에게 던져주기도 했죠."
rows["40:1073223154"]="나와 함께 말가니스를 상대할 준비가 되었는가?"
rows["40:1145745265"]="원장님! 저 나쁜 아저씨가 우릴 잡아먹는 건가요?"
rows["40:1274830741"]="못 보던 얼굴이네요. 여기 처음이신가요?"
rows["40:1510428822"]="돈을 벌고 싶으신가요?"
rows["40:1511689052"]="홀도르의 영혼을 위해 기도하러 왔어?"
rows["40:1556229183"]="또 새로운 자인가? 흥, 당신은 해내지 못할 것이야..."
rows["40:1636384624"]="어떤 직업 상급자를 찾으십니까?"
rows["40:1656995647"]="어떤 무기에 특별히 관심이 있으신가요?"
rows["40:1740251272"]="오! 저를 도와주러 오신 겁니까?"
rows["40:1748174559"]="응급치료 기술을 가르쳐 드리죠."
rows["40:1753339105"]="트롤의 역사에 있어서 어둠으로 가득한 나날이 아닐 수 없네."
rows["40:184913564"]="뭘 원하나? 타락한 오크치고는 냄새가 이상하군..."
rows["40:1931945873"]="뭔가? 지금 바쁜 게 안 보이나?"
rows["40:1991511504"]="누가 감히 총사령관을 방해하느냐?"
rows["40:2015529989"]="<강령사의 몸에서 물결치는 듯한 어둠의 마력이 느껴집니다.>"
rows["40:206748875"]="승급하는 데 필요한 보급품이 거의 없소."
rows["40:2069365667"]="여자애들한테는 예쁜 인형, 남자애들한테는 예쁜 구더기!"
rows["40:2115962160"]="저들을 화나게 한 것 같네."
rows["40:2118859940"]="안녕하세요, 젊은  ⁇ 아, 무엇을 찾고 있습니까?"
rows["40:2129398557"]="인생이란 정성 들여 짠 양탄자와 같습니다."
rows["40:220235419"]="<창조된 물의 정령이 물보라를 일으킬 준비를 마쳤습니다.>"
rows["40:227496631"]="그 아이를 찾기 전까진 아무 데도 가지 않을 거예요!"
rows["40:268173051"]="헤헤헤! 이거 정말 재미있을 겁니다, 친구!"
rows["40:30845134"]="저는 바쁩니다. 대화는 나중에 요청해 주세요."
rows["40:334491627"]="상업 지구 위층에 박쥐 조련사 있다."
rows["40:340157967"]="난 여기서 죽을거야 난 그냥 알아"
rows["40:372379048"]="더 좋은  ⁇ 은 아제로스에서 찾을 수 없습니다."
rows["40:500764909"]="사로나이트... 이 안엔 무언가 있어!"
rows["40:519176385"]="가르침을 받고 싶으신 모양이지만, 저는 당신을 도울 수 없습니다."
rows["40:707035361"]="바위 트로그... 이곳의 기생충 같은 놈들이지."
rows["40:76065209"]="엘룬의 축복이 있기를. 뭘 도와드릴까요?"
rows["40:910024052"]="무슨 일이죠? 지금 바쁜 거 안 보입니까?"
rows["410:1027177773"]="십자군이라...$B$B<고개를 젓는 리븐데어>$B$B녀석들은 확실히 인간 중에서도 독특한 놈들이지. 내 생각엔 녀석들의 뇌는 상황을 논리적으로 파악하고 결과를 낸다는 고등한 기능은 수행하지 못하는 것 같다. 빛을 들먹거리기만 하면 녀석들은 잔뜩 바람이 들어서 전투 준비를 하지. 그러고는 자신의 안위는 완전히 무시하고 망설임도 없이 전투에 뛰어든단 말이야."
rows["410:1304944917"]="저는 제 사촌을 만나게 되어 있었습니다 아이언포지  ⁇  카자드에서 굽은 염소들을 먹으러 갔는데, 킹스웨이에서의 혼란은 통로가 없어서$b$b만약 그들이 트램이라고 부르는 거칠고 난 장난감을 타고 오기를 기대한다면, 또 다른 일이 올 겁니다. 그 물건은 쥐들로 가득하고 있고, 저는 그것에 조금도 신뢰하지 않습니다."
rows["410:1693013739"]="은빛십자군은 그저 옛날 집단이라고 말하는 자들이 있지. 나도 그들과 같이 말하는 사람이지만, 스컬지가 쓰러졌기 때문은 아니오.$b$b아니... 그들의 고집스러운 방식 때문이지. 그들은 자신들이 버린 교회의 방식으로 너무 많이 흘러갔소. 너무 엄격하고, 명예와 명령에 너무 좌지우지하지. 어떻게 해서든 내가 바돌로매에게 말하려고 하는 게 바로 이거요.$b$b물론 약간 강경론적으로 들릴 순 있지만, 좋은 논쟁거리는 될 거요."
rows["410:177785867"]="<설사제를 의심스럽게 바라보며 코를 킁킁대더니, 화난 표정을 짓고 설사제를 뭉개 고블린 모양으로 만드는 고르문간>$B$B네 작은 녹색 친구들이 네게 소용없는 짓을 시켰구나. 우리 거인은 녀석들의 장난에 놀아나지 않는다고 설명해줘라.$B$B<자신의 뜻을 보여주기 위해 초콜릿 고블린 조각의 머리를 비틀어버린 후 돌려주는 고르문간>"
rows["410:1899728225"]="혼자 평생 먹고 남을 아이스크림을 만들 수 있을 만큼 많은 갈래물풀을 모을 능력이 있는 분이로군요. 그런데 어쩌죠... 우리는 필요한 갈래물풀을 충분히 모은 것 같은데... 어쨌든 그렇다고 얘기를 들었어요. 하지만 여기서 다른 물자를 모으고 있는 이들 중 도움을 필요로 하는 이가 있을 거예요. 그래도 갈래물풀을 모으는 것만큼 재미있는 일은 없다는 걸 알게 되실 겁니다요."
rows["410:192314970"]="나는 곁에서 라그나로스의 타락이 검은무쇠 제국의 가슴과 정신에 스며드는 것을 지켜보았소. 한때는 명예로웠던 검은무쇠 부족은 이제 광기와... 악으로 치달아 버리고 만 거요.$B$B검은바위 첨탑 건설이 끝나자 나는 내 종족과 함께 더 이상 살고 싶은 생각이 없어졌지. 나는 새로운 검은무쇠 제국에서 영웅으로 떠올랐고 사람들은 내가 계획하고 건설한 도시의 입구인 이곳에 무덤을 지어 내 노고를 칭송한 거요."
rows["410:1988053290"]="햇볕에 시들어 버린 이 도시는 그 유별난 무자비함과 암흑 신비술로 악명 높은 성난모래 트롤들의 고향입니다. 트롤 전설을 보면 질풍의 술트라제라는 강력한 검 이야기가 나옵니다. 아무리 끔찍한 적에게라도 공포와 나약함을 주입시킬 수 있는 무기라고 합니다. 오래전 이 검이 두 조각이 났다고 하는데, 들리는 소문에 따르면 이 두 조각이 줄파락 성벽 내 어딘가에 있다고 합니다."
rows["410:347254940"]="내부와 외부의 세력이 세계의 원동력을 파괴하면 창조주들은 이 세계를 방문해 그들이 씨를 뿌린 세계에 대한 지배력을 회복하려고 할 것입니다. 이때를 가볍게 보고 넘겨서는 안 됩니다.$B$B이 세계의 방문 예정에 관한 정보는 해당 자료 저장소를 찾아보시기 바랍니다. 이곳에서 창조주의 방문 일정을 계획할 때 고려하는 사항이 처리되고 있습니다."
rows["410:670673009"]="에메랄드 비룡은 적을 중독시키는 동시에 스스로 치유하는 능력이 뛰어나지요. 착취 독을 사용하여 적의 체력을 빨아들인답니다. 이 독을 반복해서 사용할수록 그 효과가 높아지지요. 악몽 접근 기술을 사용하여 상대의 꿈속에 접근하면, 에메랄드 비룡은 생명의 기운 일부를 강력한 공격으로 전환하여 대상을 약하게 하고 대상의 공격력을 일시적으로 낮출 수 있답니다."
rows["410:68142718"]="요즘처럼 힘든 전시에 포세이큰을 돕는 게 자네에게도 큰 득이 될 걸세. 난 같은 말을 되풀이하는 걸 좋아하지 않으니 잘 듣게나.$B$B지금 우린 옷감이 몹시 부족한 상태라 붕대와 옷을 만들 수 없다네... 그래서 줄어만 가는 재고를 채우기 위해 기부를 받고 있네. 착한 일을 했다고 금전적인 보상을 바라지는 말게나. 기부란 원래 그런 거니까 말이야. 그렇다고 자네의 도움을 완전히 무시하겠다는 얘기는 아니라네."
rows["410:689746707"]="도둑맞은 보급품이라고요? 어디 생각 좀 해볼게요...$b$b다리아라는 사제가 지난주 미사가 끝나고 남은 포도주를 모두 가져갔었는데, 제가 부탁한 대로 그것들을 다 버리지 않았던 건 알아요. 하지만 곧 반성할 거라고 믿어요.$b$b<당신에게 한쪽 눈을 깜박이는 알푸스>$b$b그리고 마법사 중 한 명이 이번 주에 비정상적으로 많은 양의 고해성사를 했다는 말을 들었어요... 이름이 뭐라고 했더라? 크리스프? 리스프? 하여튼 이것 비슷한 이름이었어요.$b$b자, 이제 그만 가 보세요."
rows["410:798328635"]="지난 몇 년 동안 펄볼그에게는 끔찍한 일들이 일어났소. 수많은 전투에서 피해를 입었지. 하지만 그 부족이 왜 그렇게 되었는지는 잘 모르오. 악령숲에 퍼진 역병으로 인해 타락했을 수도 있고, 한때는 평화로웠던 자기 종족에게 생긴 일이 화가 나서 지나치게 자기방어적으로 변한 걸 수도 있지. 이유야 어떻든 녀석들은 그 지역에 들어오는 모든 자들에게 아주 공격적이오."
rows["410:820101996"]="물론이지! 곤충 집에는 온갖 실리시드가 득실거렸고 우리를 보면 바로 달려들었네.$B$B하이브레갈에서 이상한 문자가 새겨진 수정을 발견하기 전까지는 사실 별문제가 없었지. 그런데 여군주 마랄리스가 그 수정을 보자마자 뭔가에 홀린 듯 가까이 다가갔네. 마치 불을 보고 달려드는 나방 같았지! 그 작고 고운 뺨을 수정에 갖다 대더니 갑자기 기절했네. 우리는 깜짝 놀라 여군주 마랄리스를 둘러업고 최대한 빨리 그곳을 빠져나왔네!"
rows["411:1778416619"]="파멸의 암호는 카라보르에 있는 굴단의 비밀 방에 20년 동안 보관되었네. 참, 그렇지... 자네는 카라보르가 뭔지 모르겠군. 안 그런가?$B$B검은 사원...$B$B지금은 일리단 스톰레이지의 본부가 돼버린 곳이지.$B$B일리단은 검은 사원을 점령했을 때 파멸의 암호를 발견했어. 그는 이 세계가 이미 피해를 입었지만 훗날을 위해 파멸의 암호를 잘 보관해두는 것이 좋겠다고 생각했지."
rows["411:2073413895"]="<Zerin'dai에 접근하면 그가 정말 어색한 액체로 가득한 가두를 바로 그 곳에 배치하려고 하는 것을 볼 수 있습니다.> Ayyy mon! 나를 괴롭히지 마! 들어요?! ♪ 영들이 당신이 원하는 것에 대해 말 ⁇ 을 듣고있을 경우 ♪ ♪ 들지 않을 것입니다! 오, 당신은 'da voodoo mon의 방법'을 훈련하려고 찾고 있습니다? 당신은 나에게 약간의 mojo를 제공하고 내가 당신에게 약간의 지식을 줄 것입니다!"
rows["411:2133990286"]="헤아릴 수 없이 오랜 세월을 이 숲은 불타고 있네. 고대의 마법으로 불타는 이곳은 원시비룡 여왕과 그녀의 배우자가 짝짓기를 하는 장소이기도 하다네.$B$B하지만 오래전에 잊힌 악마가 다시 깨어나, 자신의 목적을 이루고자 여왕의 아이들을 또다시 노예로 삼으려 한다네.$B$B이 브리쿨 무리가 일으키는 혼란 때문에 숲이 넓어지고, 자네 동족들이 위협받는 것이네."
rows["411:441994733"]="수도원은 한때 학문과 계몽의 중심지였습니다. 3차 대전쟁 당시 언데드 스컬지가 봉기하자 이 평화로운 수도원은 광신적인 붉은십자군의 요새로 바뀌었습니다. 붉은십자군은 인간이 아니라면 동맹이나 소속에 관여치 않고 관용을 보이지 않습니다. 그들은 외부인이라면 누구나 잠재적인 언데드 역병 보균자로 보고 그들을 처치해야 한다고 믿습니다."
rows["411:676493679"]="물론이지! 곤충 집에는 온갖 실리시드가 득실거렸고 우리를 보면 바로 달려들었네.$B$B하이브레갈에서 이상한 문자가 새겨진 수정을 발견하기 전까지는 사실 별문제가 없었지. 그런데 여군주 마랄리스가 그 수정을 보자마자 뭔가에 홀린 듯 가까이 다가갔네. 마치 불을 보고 달려드는 나방 같았지! 그 작고 고운 뺨을 수정에 갖다 대더니 갑자기 기절했네. 우리는 깜짝 놀라 여군주 마랄리스를 둘러업고 최대한 빨리 그곳을 빠져나왔네!"
rows["412:2130309526"]="랩터 소굴을 탈출하려고? 난 이 초소를 지키고 탈출하는 자들을 막으라고 명령받은 상태지만... 네가 탈출하려는 이유를 조금은 알 것같군.$b$b좋아. 떠나도 좋아. 하지만 그 전에 조건이 있어.$b$b보아하니 트롤들이 랩터 음식을 가지고 다닌다더군. 난 며칠째 음식을 못 먹고 있고... 싸운다면 네가 맥없이 질 게 뻔하지만 그 작은 몸을 활용해 천막에 잠들어 있는 트롤에게서 음식을 훔쳐와 줄 순 있겠지?"
rows["412:217781661"]="제 동족 대부분은 호드가 야만적이라며 경멸합니다. 저도 한때 그런 이들 중 하나였지요. 그래서 습기 차고 향기로운 이곳으로 이동하라는 명령을 처음 받았을 때는 제 운명을 얼마나 원망했는지 모릅니다.$b$b그런데, 여기서 연구를 하던 중에 제가 처한 환경에 감사하게 되었지요. 독특한 매력이 있는 곳입니다. 그렇지 않습니까?$b$b아, 제가 어떤 연구를 했는지 궁금하시겠군요. 저는 여기로 순간이동하는 마법을 연구했습니다. 가르쳐 드릴까요?"
rows["413:1126841071"]="먼저 게임 토큰 하나 줘서 스팀톤을 조종하게 되죠$b$b전투장에서 목표물을 폭발시킬 시간이 제한되어 있습니다. 파괴하는 목표마다 1점으로 얻을 수 있습니다.$b$b하지만 조심하세요. 전투장에는 적의 탄기와 제펠린도 있습니다.$b$b당신의 점수는 한 톤에서 다른 톤으로 전달될 것입니다. 그래서 당신이 폭발하면 걱정하지 마십시오."
rows["413:802465843"]="이야기의 홀에 오신 것을 환영합니다. 일주일에 한 번, 해가 내려갈 때, 우리는 이야기를 듣거나 이야기하기 위해 여기에 왔습니다.$b$b당신 은 이 세상 의 많은 부분을 본 것 인가? 어느 날 당신 이 그렇게 마음 을 기울인다면, 저는 여기 있는 많은 사람들이 당신 의 여행 에 대해 듣고 싶어 할 것 이라고 확신 합니다. 어쨌든, 당신 은 항상 앉아 듣고자 합니다. 성당 의 장로 들 은 곧 알게 될 것 처럼, 끝없는 이야기 의 샘물 입니다.  "
rows["413:837834977"]="옛 전쟁 시절에는... 그 전쟁 말고, 다른 전쟁 말입니다. 오크가 용을 탔을 때 말이죠? 저와 위슬러는 체리 그로그주를 마시고 눈이 벌게져서 울퉁불퉁한 소나무로 만든 나룻배를 타고 남녘해안에서 메네실 항구로 가던 중이었습니다.$B$B그리고 한 삼 분의 일쯤 와서 보니, 주변에 바다 말고는 아무것도 보이질 않아 꽤 많이 온 듯한데 발이 점점 축축해지는 게 느껴지더란 말입니다."
rows["413:891091258"]="네더윙. 그들은 우리에게 이야기 합니다. 그들은 우리에게 평화와 보호를 제공했습니다. 부진한 사람들은 결코 진정으로 느끼지 못했던 것. 우리는 그들의 제안을 받아들였고, 토라나쿠에게 이 광산의 생물들을 깨우는데 큰 개인적인 비용을 지불했습니다. 많은 형제들은 이 공격에 목숨을 바쳤습니다. 우리는 광산을 살 수 없게 만들려고 노력했습니다."
rows["413:91721159"]="고고르드는 십자군 전쟁 의 린치 피드 이었다. 예, 모그라인 은 리치 왕 의 군대 와 대 한 그의 전력 때문 에 애쉬브링거 라고 불리 었습니다. 칼 과 믿음 을 가지고만 있으면서 모그라인 은 무사 의 전단 들 을 걸고 무해 로 나오게 되었으며 - 그의 적 들 의  ⁇ 은 그 들 의 존재 를 단 한 가지 증거 로 그 들 의 존재 를 알 수 있었다."
rows["414:1454098788"]="첫 번째 재료는 고대 학카리 휘장이요. 학카르 부족의 가장 강력한 지휘자인 진도와 혈군주에게서 얻을 수 있지.$B$B두 번째는 구멍 난 부두 인형인데, 타락한 이 땅의 이곳저곳에 버려진 쓰레기 더미를 뒤져보면 찾을 수 있을 거요. 특히 불길한 흑마술 더미 안을 눈여겨 보시오.$B$B이 두 가지 재료를 모두 가져오면 당신에게 강력한 마법을 허락하겠소!"
rows["414:686794278"]="그렇다면 좋아요! 전 용암 방열복의 성능을 시험해 보려고 작열하는 교각의 용암 구덩이에 갔어요. 모든 게 잘 되고 있었지요. 그 속에서 한 군데도 화상을 입지 않고 헤엄칠 수 있을 정도로 말이에요!$B$B그곳에서 볼일도 보고 배영도 하면서 있는데 난데없이 녀석이 나타나서 날 통째로 집어삼키지 뭐예요! 용암 방열복이랑 그 안에 내장된 자동 음식 공급기가 아니었으면 전 그대로 끝장이었을 거라고요!"
rows["414:782498414"]="티탄들이 하룻밤 만에 갑자기 생명을 창조해내지는 않았다. 창조 작업은 서서히 진행됐으며 수도 없이 실험하고 되풀이해야 했지.$B$B그래서 숄라자르 분지처럼 철저하게 안전한 장소가 생겨난 것이다.$B$B실험했던 장소를 안전하게 지키고자, 티탄들은 수호 장치를 만들었다. 그 파괴력은 비할 데 없을 정도로 강력하지만, 여기서 내 뜻을 성실하게 따르겠다고 맹세하지 않으면 더는 밝히지 않겠다."
rows["414:930462786"]=" ⁇ 로망스가 세워진 땅은 바로프 가문이 켈'투자드에게 주었다. 이 땅 대가로 - 저주받은 사람들의 숭배가 스컬지의 불쾌한 마술을 배울 수 있는 장소 - 켈'투자드는 죽은자를 통해 바로프의 불멸을 부여했다.$B$B그림자보존에서 그림자의 피부와 그 소유자인 이루시아 바로프 여인을 찾을 수 있습니다.$B$B헛된 사람들, 죽은 사람들, 더 나은 거울은 존재하지 않았습니다."
rows["415:1051116765"]="호드는 많은 위험을 무릅쓰고 아웃랜드로 건너왔네. 자원, 인력, 심지어 우리 땅의 전략적 방어선조차 위태로운 상황이네. 이런 악조건에도 불구하고 스랄께서는 이 황량한 땅의 약속을 믿고 계시다네. 요즘 스랄 님의 눈에서 이상한 광채가 보이네. 마치 우리 눈에는 보이지 않는 어떤 놀라운 사실을 발견하기라도 하신 듯 말일세.$B$B하지만 그분은 여전히 대족장이며 내 형제라네. 나는 지옥 끝까지라도 그분을 따를 것이네."
rows["415:1684740444"]="무슨 일이 없지?$B$B세계 각지의 숙소 주인은 모두 트릭 오브 트레이트 선품 을 배포 하고 있으며, 많은 도시 들 은 시즌 에 맞게 장식 되어 있다! 또한, 사우스셔 에 있는 하트먼 장교 는 포세이큰 와 그 들 의 위커먼 축제 에 대항 해 도움 을 필요로 한다.$B$B또 한 가지 더 들어봤습니다. 스톰윈드년 고아원에서 병든 소년이 휴가 기념식에서 감자품을 모으는 데 도움을 주고 싶어한다는 것을요."
rows["415:1837613260"]="이런포에에, 전설적인 오크가 죽이는 해마어? 그래, 그래, 그건 윈저의 해마어였어. 그는 그 해마어를 프랭클론 포워라이트가 자신의 큰, 큰, 큰 할아버지에게 직접 만들었다고 말했다."
rows["415:2001438576"]="'탈론 킹' 이키스는 제 형제인 다크웨이버 사이트와 함께 세테크의 지도자 중 한 명입니다.$B$B스케티스에서 오치윈의 유적지로 세테크크의 탈출을 이끌었던 이들은 처음엔 이키스는 카리스마적인 지도자였지만 그는 미쳤어요.$B$B이제 그는 자신이 테로크라고 공개적으로 선언합니다 되살아난 자아라코아족이 그를 통치자로 무릎을 꿇길 바라고"
rows["415:2003910183"]="바보요, 당신? 여기까지 오면서 뼈만 앙상한 해골들이 경관을 망치고 있는 꼴을 못 본 건 아니겠지?$B$B<한숨을 쉬는 로한>$B$B밖에서 활동하는 걸 좋아한다면 동부와 서부 역병지대 전역에서 놈들을 찾을 수 있소. 날 믿으시오. 꼭 당신 눈에 띌 테니까. 놈들은 당신을 절대 놓치지 않으려 할 거요.$B$B던전을 좋아한다면 스트라솔름과 스칼로맨스로 가시오. 해골 조각을 찾기에 아주 좋은 장소요."
rows["416:1138847290"]="육체의 힘이란 민첩하고도 강한 동작을 말한다. 그대는 육체적으로나 정신적으로 항상 최적의 상태를 유지해야 한다. 전투에서 가장 위협적인 요소는 바로 힘이다. 곰은 그 거대함으로 힘을 확연히 드러내지만 그 안에는 유연한 민첩성과 날카로운 정신이 감춰져 있다. 이 점을 잘 이용하면 상대방을 완전히 제압할 할 수 있지.$B$B할퀴기의 도를 완전히 익히려면 곰의 육체적 힘을 믿어야 한다."
rows["416:1143371544"]="불모의 땅 변두리에 인간들이 그늘 쉼터라는 이름의 여관을 하나 지었지만 몇 주 전에 불타 버렸소.$B$B내가 왜 신경 쓰냔 말이오? 신경쓰지 않소. 인간들에 대해서는 신경도 쓰지 않는단 말이오. 그 여관에 심어놓은 첩자가 있소. 난 그의 죽음이 대답 없는 일로 묻히도록 두진 않을 것이오. 누가 이런 일을 했는지 알아야 하오$B$B도울 의사가 있다면 타고 남은 그늘 쉼터 여관으로 가 보고 뭔가 단서를 찾으면 내게 알려 주시오."
rows["416:1243416715"]="수정탑은 자료를 다른 곳으로 전송하는 것처럼 보입니다.$b$b수정탑을 더 자세히 조사해보니 작은 탁자에 붉은, 푸른, 녹색 수정이 일정한 구조를 이룬 듯 배열되어 있습니다.$B$B커다란 원형을 이룬 붉은 수정의 양쪽으로는 푸른 수정과 녹색 수정이 각각 작은 원 모양으로 배열되어 있습니다.$B$B당신은 조심스럽게 눈앞의 광경을 적으며, 이 발견을 매우 흥미로워할 어떤 사람을 떠올립니다."
rows["416:1330656258"]="한때 검은무쇠 드워프들의 수도였던 이 화산 미궁은 이제 불의 군주 라그나로스의 권력 중심지로 쓰이고 있습니다. 돌에서 생명체를 만들어 내는 비밀을 알아낸 라그나로스는 그 누구도 멈출 수 없는 골렘 군단을 만들어 검은바위 산 전체를 정복하는 데 이용하려는 음모를 꾸미고 있습니다. 네파리안과 그의 용 부하들을 물리칠 생각에 사로잡힌 라그나로스는 최후의 승리를 달성하기 위해서라면 그 어떤 극단적인 수단도 가리지 않을 겁니다."
rows["416:1410335053"]="순진하군. 불타는 칼날단이 바로 어둠의 의회야! 어둠의 의회에는 많은 종파와 단체가 있지만 다 한통속이지. 내가 불타는 칼날단을 이끈다고 해도 어둠의 의회에서 보면, 일원에 불과할 뿐이야. 다 한 식구란 말이야...$B$B그런데, 이글거리는 칼날단을 한번 생각해 보게. 자기들이 어둠의 의회를 대신할 강력한 흑마법사 군단으로 떠오를 거라고 떠들고 다니지. 어리석은 것들."
rows["416:2095330318"]="한마디로 마법이라고$b$b책임 없는 필사자들은 그들의 짧은 생애에 대해 그들의 행동의 지속적인 영향에 대해 전혀 생각하지 않습니다.$b$b미묘한 에너지들은 너무 자유롭고, 세계의 균형을 방해해 왔습니다. 만약 이런 일이 계속될 수 있다면, 아제로스은 곧 멸망할 것입니다.$b$b이 부분에 대해서는 양측 모두 동의하지만, 협의회가 임명되기 전에 마일고스는 자신의 계획을 실행했습니다.$b$b우리는 그를 대면하는 것 외에는 선택의 여지가 없었습니다."
rows["418:1065857140"]="악령숲에는 세나리온 식물 고약을 바르면 오염된 성분을 정화할 수 있는 식물들이 있습니다. 나는 몇 가지 재료를 이용해 그 고약을 만드는 방법을 알고 있습니다. 당신이 갖고 있는 기술에 따라, 여러 가지 방법으로 날 도와줄 수 있습니다.$B$B그 일을 하려면 세나리온 등불이 필요할 거요. 그 등불을 이용하면 육안으로는 놓치기 쉬운 자연의 타락과 오염을 볼 수 있습니다."
rows["418:442833701"]="좋습니다, 친구. 본 대로 말씀드리죠...$b$b사방이 조용했습니다. 그런데 어느 순간 마치 나무 사이를 스치는 바람 같은 소리가 나더니, 이 아마니 트롤과 놈들의 애완동물한테 둘러싸여 있지 뭡니까! 그러고는 기억이 없어요. 깨어났을 땐 여기 우리 안에 갇혀 있었습니다.$b$b밤낮으로 포로들이 하나씩 죽어나갔습니다. 한 명 죽을 때마다 저 곰처럼 생긴 트롤 녀석은 더 강해지는 것 같았고 말입니다.$b$b저 우리 안에서 알 수 있었던 건 그 정도뿐입니다."
rows["418:467754902"]="그 역겨운 짐승들은 어디에나 있습니다.$B$B야외에서 사냥하는 걸 즐긴다면 역병숲과 테러데일 근처에서 놈들을 찾아보십시오. 그리고 동부 역병지대에 있는 거의 모든 스컬지 야영지에도 놈들이 나타납니다.$B$B던전 탐험을 즐기는 편이라면 스트라솔름으로 가십시오. 지하마귀가 사는 지역을 찾을 수 있을 겁니다. 그리고 스칼로맨스에서도 다양한 종류의 소생한 지하마귀를 찾을 수 있을 겁니다."
rows["418:752021550"]="아제로스 최고의 쇼에 다시 오신 것을 환영합니다! 다시 뵙게 돼서 정말 기뻐요!$B$B어서 오세요! 다시 한번 마음껏 즐기시기 바랍니다. 다크문 축제에는 항상 새롭고 신나는 것들이 늘어만 가고 있으니 구석구석 둘러보세요! 그동안 발견한 온갖 놀라운 물건들을 구경하세요! 어린이라면 모두 좋아할 만한 것들을 아낌없이 준비해 놓았답니다!"
rows["419:1333764402"]="좋아요, 그럼 일단 앉으세요. 다 얘기하려면 시간이 좀 걸릴 테니까요.$B$B이 얼어붙은 지옥에 처음 왔을 무렵, 용맹의 성채에 있는 알로스 장군이 저와 이 용감한 비행 부대에 특명을 내렸지요. 얼라이언스의 작전 수행을 위해 전진 비행기지를 세우라는 거였어요.$B$B그래서 세워진 것이 이 비행장이지요. 분명히 말하건대, 사방에 짐승들이 득실대고, 땅은 얼어서 바위처럼 단단한지라 작업하는 데 아주 고생이 많았다고요! 하지만 우린 해냈지요. 그것도 아주 빨"
rows["419:238815851"]="우리 술집에 오신 것을 환영합니다.  ⁇ 셔에서 신선한 빵, 치즈, 윈스웨프트에서 우유.$b$b<델리라는 눈을 낮추고 목소리가 흔들린다>$b$b미랄다가 이 상황을 걱정하고 싶어서 떠나고 싶어서... 가까이... 스톰윈드로 가... 하지만 이 곳은 내 집이다. 스카데알드가 흔들리면도, 나는 그것을 포기하지 않을 것이다."
rows["41:1053750289"]="우리 아름다운 도시 어디를 가고 싶으세요?"
rows["41:1080733765"]="지금 여기서 뭐 하는 건가? 어서 나가!"
rows["41:1119887571"]="우리 전사들이... 모두 잡혀가 버렸네."
rows["41:1152577641"]="저 여자들은 그냥 아는 친구일 뿐이에요, 자기."
rows["41:1183980403"]="우린 전쟁으로 왔어$B$B우리한테 줬어"
rows["41:1210296448"]="모험가여, 희망의 빛 예배당에 오신 것을 환영합니다."
rows["41:1249351969"]="트롬카! 뭘 찾고 있는 것이오, 이방인 친구?"
rows["41:1285288845"]="콰앙!$b$b마지막으로 기억나는 건 그것뿐입니다..."
rows["41:1323433428"]="이 호박 머리가 불길한 일을 예감하듯 연기를 피웁니다..."
rows["41:1416477834"]="어떻게 해야 여기서 빠져나갈 수 있을까요?"
rows["41:1426894269"]="크면 마부가 되고 싶어요!"
rows["41:1433452595"]="로봇전사 NX-01은 현재 미작동 상태입니다."
rows["41:1515389594"]="<지렁이를 보자 배고픈 듯 울어대는 바위매>"
rows["41:1591615429"]="윽!$b$b한 번이라도 쉽게 좀 풀리면 안 되겠느냐고!!"
rows["41:1641612774"]="우리 부대원들은... 모두 붙잡혔습니다."
rows["41:1701882382"]="우리가 사냥하는 동물의 어떤 부분도 낭비해서는 안 되오."
rows["41:17229577"]="아, 이 다르나서스 옷감이 최고라니까!"
rows["41:1764338530"]="찾아 주다니 영광일세."
rows["41:1802052127"]="다른 모든이들이 실패했을 때 자연이 자네를 인도할 걸세."
rows["41:1962846268"]="겔카크의 열쇠를 빈 홈에 넣으니 꼭 들어맞습니다."
rows["41:1984299552"]="광산에 대해 가르칠 수 있어"
rows["41:2117541481"]="우리는 힘을 합쳐 불가능한 일을 해냈습니다."
rows["41:2118902094"]="서리 표범이 평온하게 누워 있습니다."
rows["41:216818853"]="필멸의 존재여... 나를 귀찮게 하지 마라!"
rows["41:230471227"]="안녕하세요, 멋진 분. 같이 일하게 되어 좋군요!"
rows["41:30705688"]="당신을 향한 제 마음, 알고 계시죠?"
rows["41:316968108"]="준비된 광산 수레를 움직일 수 있습니다."
rows["41:429612566"]="안녕하세요! 그대가 정말 좋아지고 있어요."
rows["41:466249749"]="모르고르를 끌어내리는 걸 도와주러 왔소?"
rows["41:577649583"]="<매리언이 비명을 지르며 당신을 노려봅니다.>"
rows["41:579630551"]="파이 맛이 정말 죽인답니다. 한입 드셔 보시겠어요?"
rows["41:619126213"]="케켁이 $g형:누나; 사냥에 데려가 준다. 좋은 미끼다."
rows["41:624839986"]="알도르 라이즈에 오신 것을 환영합니다."
rows["41:768289903"]="어떤 전장에 관심이 있으신가요?"
rows["41:780949233"]="필요한 게 있거든 빨리 말씀하십시오."
rows["41:844250248"]="구경이라도 났소? 가던 길이나 계속 가시오."
rows["420:489959725"]="토리움 형제단에 대해 들어본 적 있나요? 검은바위 나락하지만 믿으세요, 우리는 그들처럼 전혀 없습니다.$b$b그 악당들은 너무 깊게 파묻고 지금은 더 어두운 세력에 봉사하고 있습니다. 라그나로스, 불의 주인. 우리는 의지와 목적에 대해 더 독립되어서 행복하지만 대부분의 경우 우리의 목적은 그들이 초래하는 모든 문제를 예방하는 것입니다."
rows["420:727991870"]="루비 비룡은 피해량을 줄여 아군을 보호하는 능력이 뛰어납니다. 불타는 격노로, 이 대상 저 대상으로 옮겨 다닐 때마다 피해가 점점 더 증가하는 액화 불길을 내뿜을 수 있습니다. 비룡이 적의 공격을 받을 때마다 회피력이 충전됩니다. 이 회피력으로 교묘한 회피를 시전하여 날아드는 공격이나 마법을 피할 수 있습니다."
rows["420:863843696"]="수정탑은 자료를 다른 곳으로 전송하는 것처럼 보입니다.$b$b수정탑을 더 자세히 조사해보니 작은 탁자에 노란, 붉은, 녹색 수정이 일정한 구조를 이룬 듯 배열되어 있습니다.$B$B커다란 원형을 이룬 노란 수정의 양쪽으로는 붉은 수정과 녹색 수정이 각각 작은 원 모양으로 배열되어 있습니다.$B$B당신은 조심스럽게 눈앞의 광경을 적으며, 이 발견을 매우 흥미로워할 어떤 사람을 떠올립니다.\010"
rows["420:991471165"]="좋아요, 그럼 일단 앉으세요. 다 얘기하려면 시간이 좀 걸릴 테니까요.$B$B이 얼어붙은 지옥에 처음 왔을 무렵, 용맹의 성채에 있는 알로스 장군이 저와 이 용감한 비행 부대에 특명을 내렸지요. 얼라이언스의 작전 수행을 위해 전진 비행기지를 세우라는 거였어요.$B$B그래서 세워진 것이 이 비행장이지요. 분명히 말하건대, 사방에 짐승들이 득실대고, 땅은 얼어서 바위처럼 단단한지라 작업하는 데 아주 고생이 많았다고요! 하지만 우린 해냈지요. 그것도 아주 빨리!"
rows["421:1674135233"]="마력의 보물은 강력한 구루바시 제국의 모조일세. 우리 잔달라 부족은 반드시 그 모조를 찾아야만 하네. 혈신이 우리를 파멸시키지 못하도록 말이야.$B$B줄구룹에는 세 가지 종류의 보물이 있다네. 주화, 장신구, 그리고 고대 전투 장비들을 찾게나. 이것들이 바로 보물이라네.$B$B지금 줄구룹으로 가서 적을 쓰러뜨리고 마력의 보물을 구해 우리 부족에게 가져다주게나. 그러면 우리의 존경과 전투 장비, 그리고 진정한 힘을 얻게 될 것이야."
rows["421:536791377"]="지옥의 종을 불러내는 비밀을 가르쳐야 한다면, 당신은 크로시우스를 파괴하고 그의 화상 유해에서 지옥의 핵을 가져오셔야 합니다. 하지만, 이것은 들릴 만큼 쉬운 일이 아닙니다. 크로시우스는 거의 완전히 태워버렸습니다. 당신은 그의 시체를 다시 불태우고 그 잔해에서 그를 부활시켜야 합니다.$B$B내 임프시, 임프시, 당신을 당신의 길로 인도할 것입니다."
rows["422:1047757883"]="어떤 사람들은 그들의 행동으로 경험의 쌓을 것을 멈추고, 지금 있는 힘의 수준에서 영원히 유지되고, 더 강해지지 않으려고 합니다.$B$B저는 이것을 가능하게 할 수 있습니다. 물론 수수료에 대 한.$B$B하지만 이 사실을 이해해줘, 일단 돈을 지불하면 더 이상 경험은 없어$B$B만약 당신이 나중에 생각을 바꾸고 다시 경험을 쌓고 싶다면, 같은 수수료로 그 과정을 취소할 수 있습니다."
rows["422:15562186"]="수정탑은 자료를 다른 곳으로 전송하는 것처럼 보입니다.$b$b수정탑을 더 자세히 조사해보니 작은 탁자에 푸른, 노란, 녹색 수정이 일정한 구조를 이룬 듯 배열되어 있습니다.$B$B커다란 원형을 이룬 푸른 수정의 양쪽으로는 노란 수정과 녹색 수정이 각각 작은 원 모양으로 배열되어 있습니다.$B$B당신은 조심스럽게 눈앞의 광경을 적으며, 이 발견을 매우 흥미로워할 어떤 사람을 떠올립니다."
rows["422:1988912500"]="당신도 알고 있지 않습니까. 제가 알고 있다는 걸... 지금 저는 쓸데없는 말을 하고 싶지 않으니 당신도 그렇게 하는 게 좋을 것입니다.$B$B당신이 여기 온 이유는 분명 아탈라이의 가라앉은 사원에서 얻은 그 물건이겠지요. 그게 어떤 이유로 당신을 여기로 이끌었는지 궁금하겠지요. 그건 바로 저의 동지이자... 형제에게 안식을 주기 위해서입니다. 그는 에메랄드의 꿈속에서... 악몽에... 갇혀 혼자서는 빠져나올 수 없으니 말이지요."
rows["422:409243524"]="간단해요! 제게 다크문 게임 동전을 주시면, 제가 당신을 대포 안으로 던져 넣고 심지에 불을 붙이는 거죠.$B$B일단 대포가 발사되면 몸이 잠깐 붕 뜨게 될 거예요. 하지만 제가 지금 달아드릴 날개가 떨어지면서 빠르게 하강하게 될 거랍니다.$B$B당신은 판잣길 바로 근처 바닷가에 떠 있는 과녁을 향해 발사될 거예요.$B$B땅 위에 있을 때 날개를 떼어내지만 마세요... 아니면... 뭐... 하여튼 생명 보험 같은 건 없어요!"
rows["423:1064978564"]="마크루라의 습격을 받은 후, 우리는 용맹호가 또다시 공격을 받으면 버텨내지 못할 것임을 알았다. 그래서 나와 살아남은 선원들은 배를 버렸다.$B$B이제 바닷가에 왔으니 곧 나이젤의 야영지로 갈 생각이다. 하지만 그 길에는 너무나 많은 위험이 도사리고 있다. 잊혀진 땅이 우릴 집어삼킬까 두렵다.$B$B언젠가 어느 영웅이 이 곤경을 알고, 우리를 이 지경으로 만든 물귀신 놈들에게 복수해 주길 바라는 마음에서 이 글을 남긴다."
rows["424:108762235"]="[클래스 트레이너]는 특정 클래스에 전문화되어 그 클래스에서 주문을 순위화하고 많은 도시와 수도에서 찾을 수 있습니다. [기기자 책 상승]은 또한 15 수준까지 모든 주문을 순위화하는 데 사용될 수 있습니다. 또한 [ 상승의 책]을 경매 집, Tiraxis 또는 웹 상점에서 얻을 수 있습니다. 이것은 휴대용 동반자 및 모든 주문과 모든 클래스 [ 클래스 트레이너]입니다."
rows["424:1500484710"]="흐음, 진짜 전문가는 제 스승님이시기는 한데, 제가 아는 것이라도 알려 드릴게요.$b$b저건 새가 아니에요. 물론 날기도 하고, 깃털 같은 게 날개에 달려 있는데다가, 또 우리가 매라고 부르기까지는 해도 새와 비교하는 건 거기까지죠. 사실은 용과 더 비슷한 점이 더 많아요. 불과 관계가 많고, 고독한 성격에다가... 또 우리가 관찰한 바로는 지능도 약간 있고 말이죠."
rows["424:1776034214"]="그런 곳은 동부 왕국에서는 절대 찾을 수 없소.$B$B칼림도어 어딘가에서 찾아야 하겠지만 호드를 비롯한 다른 모든 종족에게서 멀리 떨어진 곳이라야 하오. 대륙 분리의 영향도 받지 않아야 하니, 나이트 엘프 문명 근처는 아니겠지.$B$B아마 자연적으로 보호되는 곳일 거요. 골짜기라든가 분화구라든가... 음, 잘 모르겠소. 단지 내 추측일 뿐이니, 더 도움이 되지 못해서 미안하오."
rows["424:305747871"]="우리는 확실하지 않습니다.$b$b우리는 타이탄들의 자녀들이고, 암석과 돌의 후손들이고, 우리의 정신은 흰색 봉우리와 검은 암수와 불가분의 결속되어 있습니다.$b$b말해주세요: 산이 무너지면 어떻게 될까요? 강이 건조하면 어떻게 될까요?$b$b그래서 여기 온 겁니다. 이 챔피언의 용기를 기르는 정신을 기억하고 존중하기 위해서죠."
rows["425:339909786"]="내 뒤로 보이는 건 우리 잔달라 부족의 성소인 잔자의 제단일세. 혈신 학카르와 전쟁을 준비할 때 이곳에서 기원을 올리고 결의를 다지지.$B$B줄구룹 내에서 찾을 수 있는 학카리 장신구 중 아무것이나 가져와 이 제단에서 파괴하여 스스로 자네의 가치를 우리 부족에게 입증해 보이도록 하게나. 또 줄구룹에서 찾을 수 있는 일련의 주화들을 가져오면 우리 잔달라 명예 징표와 교환해 주지. 내가 찾고 있는 주화들을 가져오면 반드시 보상을 하겠단 말일세!"
rows["425:561254889"]="놈리건 작전은 여러 단계로 나누어져 있다네.$B$B첫 번째로, 관제탑을 되찾아야 하네! 관제탑만 확보하면 공중 지원을 받으면서 놈리건 정문으로 진격할 수 있을 걸세.$B$B또한 입구 근처에 있는 한 건물에서 다량의 기계화 전투중장갑이 발견됐네. 이 중장갑만 있으면 우리의 입구 공격을 막을 수 없을 거야.$B$B자, 그럼 텔마플러그가 있는 놈리건 심장부로 출발하세!"
rows["425:983266902"]="아직도 믿기지가 않아... 매일 하던 정찰 임무로 중앙 비무장지대 위를 날던 중 변을 당했지 뭔가. 난 이크만과 실도르 모두 호드 편대사령관 멀베릭에게 당하는 모습을 목격했네! 그래서 홧김에 혼자 동료를 벗어나 그 잘난 척하는 멀베릭 녀석을 격추시켜 버렸지. 그런데 녀석이 떨어지기 전에 내 그리핀에 상처를 입히는 바람에 불행히 나도 추락했고, 이렇게 이 야만족 녀석들에게 포로로 붙잡힌 신세가 됐다네.$B$B꼭 요새로 돌아가야 하니 도와주게!"
rows["426:205256649"]="걱정 마, 내가 보이는 것 같지 않아$B$B내 이름은 아크리도스트라스스, 아크리드라고 부르지만 여왕이 네파리아인을 막으러 보내줬는데, 내가 맡은 일이 끝날 때까지 쉬지 않을거야.$B$B이 모든 것을 없애는 데 도움이 되시면 알렉스스트라즈의 호의를 받을 것입니다. "
rows["426:2110902811"]="지하감옥은 스톰윈드의 운하 지역 아래에 숨겨진 경비가 삼엄한 교도소입니다. 델워터 교도소장이 감독하는 지하감옥은 삼류 사기꾼, 정치적 반역자, 살인자, 그리고 이 땅에서 가장 위험한 범죄자 수십 명이 모여 있는 곳입니다. 최근, 죄수들이 폭동을 일으켜 지하감옥은 아수라장이 되었고, 경비병들은 쫓겨나고 죄수들이 마음대로 활보하고 있습니다."
rows["426:257969195"]="뭐라?\010\010여기 아무것도 없어 죽은 작물, 죽은 사람들, 너무 많은 사람들이 죽었어\010\010천연병은 모든 것을 빼앗아갔고, 지구도 그것을 느끼고, 그 그림자는 독처럼 땅에 침투하고 있습니다.\010\010미니랑 나만 남았는데...\010\010빛은 우리 둘을 구해줄 거야"
rows["427:428811417"]="<웃는 젠타브라>$B$B다른 로아들 특히 시르밸라는 그 계획을 그리 신경 쓰지 않았네. 그들은 우리가 영혼들 모두와 함께가 아니라 한 번에 하나의 영혼과 함께하길 바랐지. 하지만 공크는 그들에게 강요했고, 그들은 잘라제인이 군림하는 동안 섬을 살릴 수 있는 유일한 방법은 그것뿐이라는 걸 알았지.$B$B공크도 다른 로아들을 그리 신경 쓰지 않았다고 생각하네. 그는 항상 우리가 그들에게 가르침을 받는 동안 다른 로아들을 괴롭혔네."
rows["427:660175446"]="내 말을 듣고는 있는 거요? 아니오. 켈투자드가 지팡이를 복원했다면 우리는 이런 대화를 다시 나눌 필요도 없지 않겠소. 그는 머리 부분을 지니고 있소이다. 그리고 그의 부하들에게 아티쉬의 조각 40개가 있지. 마지막 조각인 아랫부분을 찾은 것은 브란 브론즈비어드였소. 그의 모습이 마지막으로 목격된 곳은 실리더스 사막이오. 보나 마나 켈투자드가 이 세계로 보낸 무자비한 추적자들의 눈을 피하기 위해 그곳에 숨어 있을 것이오."
rows["428:1211068895"]="칼리사... 다 됐다. 사암 벽돌이 이미 마력으로 가득 차 차원문의 힘을 전환하고 있다. 몇 년 전부터 알던 대로 넌 아직 수영 실력이 뛰어나겠지? 악마의 무리나 저 \"친애하는\" 여왕께서 벽돌을 발견해서는 안 된다.$B$B호수 밑바닥으로 헤엄쳐 가라, 칼리사. 그리고 가운데 움푹한 곳 깊숙이 벽돌을 묻어라. 악마의 침략자들이 호수를 둘러싼 사원을 파괴해도 벽돌은 찾을 수 없도록 말이다. 가거라!"
rows["428:1828571767"]="저는 어두운 곳곳을 탐험하면서 죽음의 한기 망토 만드는 법을 익혔습니다.$B$B이 망토는 주문력과 주문 가속력, 그리고 치명타율을 높이는 주문 시전자용 영웅급 망토로서 제작할 수 있습니다. 이 도안을 가르쳐 주어도 좋을 만한 사람을 찾고 있었지요.$B$B노스렌드에 있는 퀘스트 대부분을 섭렵하여 \"노스렌드의 현자\" 업적을 달성한 사람이라면 죽음의 한기 망토 만드는 법을 배울 자격이 있습니다."
rows["428:1847709428"]="네, 말로른 님은 나이트 엘프가 \"엘룬\"이라고 부르는 달의 여신의 배우자였어요. 둘 사이에서 모든 드루이드의 수호신이자 아제로스를 거닌 생물 중 가장 강력한 존재였던 세나리우스 님이 태어나셨지요.$B$B제가 너무 장황하게 이야기를 늘어놓고 있군요.$B$B말로른 님은 믿어지지 않을 만큼 강한 자연의 힘을 지니고 계시지만, 정말 심각한 위기가 찾아왔을 때만 필멸의 종족과 대화를 나눠요. 고대의 전쟁에서 말로른 님이 하셨던 일에 대해 들어보셨나요?"
rows["428:367013450"]="그날 아비아나 님은 전사하셨지만, 남은 고대정령과 필멸의 종족은 결국 승리를 거두었습니다. 첫 번째 드루이드들이 참혹한 전장에서 그분의 유해를 거두어, 여기 산 높은 곳으로 운반해 왔습니다.$B$B그분은 이 제단 밖, 성스러운 원형 돌무덤에 안치되셨습니다.$B$B그하니르의 씨는 세계수를 심는 데 사용됐습니다. 세계수는 신성한 세계의 유일한 흔적입니다. 잘못했으면 아비아나 님의 죽음과 함께 영영 사라질 뻔한 것이죠."
rows["428:550096783"]="울둠은 창조주의 연구 시설로서 아제로스의 생활 수준을 향상시키기 위한 노력의 일환으로 만들어졌습니다. 울둠의 작업에 대한 자세한 내용은 울둠의 원반이 있는 분에게만 공개하도록 제한되어 있습니다.$B$B울둠 내 정보 저장소는 특수한 실험 결과를 처리하도록 프로그램되어 있습니다. 자세한 내용은 이 정보 저장소를 참조하시기 바랍니다."
rows["428:929082511"]="아직도 믿기지가 않아... 매일 하던 정찰 임무로 중앙 비무장지대 위를 날던 중 변을 당했지 뭔가. 난 이크만과 실도르 모두 호드 편대사령관 멀베릭에게 당하는 모습을 목격했네! 그래서 홧김에 혼자 동료를 벗어나 그 잘난 척하는 멀베릭 녀석을 격추시켜 버렸지. 그런데 녀석이 떨어지기 전에 내 그리핀에 상처를 입히는 바람에 불행히 나도 추락했고, 이렇게 이 야만족 녀석들에게 포로로 붙잡힌 신세가 됐다네.$B$B꼭 요새로 돌아가야 하니 도와주게!"
rows["428:955193532"]="그럴 줄 알았네. 언젠가 자네가 내 오랜 친구에게 소식을 전해줄 수 있을지도 모르겠군. 그 친구는 아직도 그 숲에서 지낸다는 소식을 들었다네.$B$B<마치 기도를 하듯, 잠시 고개를 숙이는 아이트리그>$B$B렌드 얘기를 하고 있었지... 그래. 렌드와 그 동생 마임은 검은바위 첨탑을 지배하며 계속해서 검은무쇠 드워프와 대립했지. 도시 위에 있는 드워프를 몰아내는 데는 성공했지만 그러는 과정에서 용이 쳐들어왔고 마임이 죽어버렸다네."
rows["429:1056492251"]="네, 아니, 지금은 악마일 수도 있지만 티루스 블랙홀은 한때 밤의 엘프였죠.$B$B그는 그의 주인 패배 후 포로로 잡혔고, 여기 정상에 갇혔습니다. 그의 불멸의 형태는 신성한 에너지로 묶여있죠.$B$B하지만 아마도 그의 영혼의 가장 희미한 빛은 여전히 불타는 것 같지만 적어도 우리가 확실히 알아내야 합니다."
rows["429:1320888069"]="친구, 내가 가진 건 이같은 돌파구인데, 아직까지 볼 수 없는 걸로 팔아먹는 거야$b$b보시다시피, 나는 완벽한 사람을 찾기 위해 타버너에서 돈을 쓰는 것을 지쳤어요. 그래서 나는 이 안경을 만들었습니다. 그리고 이제 모든 사람이 순수한 완벽처럼 보입니다.$b$b이거 좀 시도해 주면 좋겠소"
rows["429:1491447922"]="보다시피 난 덩치만 좋고 실력은 부족한 수습기사일 뿐이오. 라그나로스가 지배하는 검은무쇠 드워프와 그 야수들을 나 혼자 무찌른다는 것은 말도 안 되는 일이지. 하지만 당신처럼 용감하고 야심 찬 분이라면 용광로의 적을 문제없이 처치할 수 있을 거라는 확신이 드는군. 날 도와주면 꿈에서도 얻지 못할 부와 명예를 얻게 해주겠소."
rows["429:446332811"]="당신은 병사들에게 싸우는 법을 가르칠 수는 있겠지만, 싸우고 싶어하는 법을 가르칠 순 없을 겁니다. 이 아래서라면 걱정하지 않아도 되는 일이지요. 제 부하들 하나하나가 모두 나가의 만행에 이를 갈고 있으니까 말입니다. 저 역시 별반 다르지 않고요.$b$b물 밖 세상과 접촉할 방법을 찾아야 합니다. 하지만 그 전에, 이 나가들과 \"접촉\"하고 싶군요. 앙갚음할 친구들이 좀 있지요."
rows["42:104110903"]="이런 불모의 황무지는 예전에 본 적이 없습니다."
rows["42:1149781381"]="그대가 상관할 일이 아니오. 갈 길이나 가시오."
rows["42:1209835034"]="이 주변은 정말 지저분하군요."
rows["42:1263418517"]="가시덤불 골짜기를 떠날 준비가 되셨습니까?"
rows["42:1304267591"]="남은 우리 종족은 전부 저 아래에 있어요!"
rows["42:1365778144"]="내 시간을 낭비하지 마"
rows["42:137150475"]="의술을 배우는 학생이신가요?"
rows["42:1384936475"]="지금이 기회입니다! 절 이 우리에서 꺼내주십시오!"
rows["42:141191837"]="난 널 훈련시킬 거야, 하지만 넌 전사 아냐"
rows["42:141359966"]="<조용히 당신을 바라보는 그림자 감시자>"
rows["42:1417433634"]="이 일에 참여하고 싶니?"
rows["42:1420248622"]="저희가 보유한 물건을 제공해 드릴 수 있어 기쁘군요."
rows["42:1659739605"]="아... 여기까지 오지 말았어야 했는데!"
rows["42:1776804581"]="설마, 우릴 잡으러 온 건 아니겠죠?"
rows["42:1800407950"]="관심이 있다면 연금술을 가르쳐드릴 수 있는데 어떠신가요?"
rows["42:1822553429"]="탈단이 죽기 전 그의 마지막 음료를 판 곳입니다."
rows["42:1875541405"]="이 탁자엔 관심이 가는 게 없습니다."
rows["42:1899374793"]="아이, 무서워! 그 방어구 보니까 정말 겁나요... $g형:누나;, 무서운 분이에요?"
rows["42:1952421012"]="고맙게도 내가 만든 덫 안으로 기어들어와 줬구나!"
rows["42:2001969296"]="이 틈은 치유되지 않는 것 같습니다."
rows["42:2051220589"]="장로 파무야는 전쟁노래 요새 바로 바깥쪽에 있다네."
rows["42:2092085443"]="어떻게든 비전 보호막을 유지해야 해."
rows["42:2110250521"]="어떤 직업 상급자를 찾고 있습니까?"
rows["42:281585567"]="내 랩터는 물건이고 사람이고 파괴하지 못하는 게 없지!"
rows["42:285068065"]="어서 오십시오. 무얼 도와드릴까요?"
rows["42:292737775"]="그 보급품 상자들을 되찾아야 합니다!"
rows["42:319477425"]="뭐야, 거리의 부랑아 같은 모양을 해 가지고는!"
rows["42:320928447"]="내가 당신에게 팔을 수 있는 것은 아무것도 없어요."
rows["42:322415836"]="저들은 도전에 임하는 중입니다. 인내심을 가지고 기다리십시오."
rows["42:386731373"]="제게는 음... 뜨는 문제가 있는 것 같아요."
rows["42:471432350"]="그대의 집이라고 생각하고 앉아서 편히 쉬십시오."
rows["42:678523240"]="안녕하세요, 털이 없는 이방인을 만나게 되다니... 전 용감한 굴프라고 합니다!"
rows["42:688491362"]="이 저주받은 땅에 무슨 볼일로 오셨나요?"
rows["42:730209991"]="<지팡이가 신비로운 기운에 휩싸여 진동합니다.>"
rows["42:732341688"]="죄송하지만 당신께 가르쳐 드릴 수 있는 게 없어요."
rows["42:787739982"]="나는 크롬가르 부대에 물품을 조달한다네."
rows["42:819359224"]="사실 난 저 노움 녀석이 단 한 번도 마음에 들지 않았단 말이지..."
rows["42:83326460"]="나는 크라토크라고 하네. 이 대장장이들을 감독하고 있지."
rows["42:875003827"]="보석공업에 대해 알고 싶은 것은 무엇일까요?"
rows["42:890494104"]="그럼 소식을 전해주지 않으시겠어요?"
rows["430:2134742594"]="이봐! \"팔찌를 나눠요\"라는 운동에 대해 들어본 적 있나?$B$B나같은 공식 왕관화학회사 행사 마스코트는 아름다운 장식 수집가 도구를 배포할 수 있다고.$B$B아름다운 장식을 모으면 아름다운 장식 팔찌를 만들 수 있는데, 이건 친구나 연인에게 줄 수도 있고 사랑의 상인에게 가져가서 사랑의 징표로 바꿀 수도 있지!$B$B요새 유행은 팔찌를 만들어서 자기가 가장 좋아하는 수장에게 바치는 거라지? 고마움과 사랑을 표시하려고 말이야..."
rows["430:269796897"]="반갑다, 어린 자여. 고귀한 영혼을 다시 보니 기쁘구나.$B$B혈투의 전장, 과거에 엘드레탈라스라고 불렸던 이곳은 속속들이 부패했다. 나는 어둠과 혼돈의 세력에 형제들이 쓰러지는 모습을 보았다. 그 공포를 영원히 없앨 수만 있다면 많은 이가 이곳을 잿더미로 만드는 쪽을 택하겠지.$B$B그러나 필멸의 존재여, 혈투의 전장은 살릴 가치가 있는 곳이다. 나를 도와다오. 함께라면 이곳에서 자취를 감춘 엄청난 힘을 선한 목적으로 불러일으킬 수 있을 것이다. 그 옛날과 마찬가지로 말이다."
rows["431:240360773"]="안녕하세요! 지금 이 작업장의 주인은 제가 아니지만 언젠가 수련을 마치고 훌륭한 발명가가 될 거랍니다. 제 영웅이신 마본 리벳시커씨처럼 말이죠.$B$B들어본 적도 없다고요? 그럴 수도 있겠죠. 얼마 전 늘 말씀하시던 어느 고대 트롤의 유적지를 조사하러 떠났거든요. 비행선을 타고 갔는데... 정확히 어디로 갔는지는 잘 모르겠어요.$B$B타나라신? 텡케리스? 타네라니사니?$B$B<고개를 가로 흔드는 리브>$B$B아니, 그게 아닌데..."
rows["432:198511238"]="한때 넬타리온이라는 이름으로 불린 데스윙은 세계의 힘을 보유한 위상이었지요. 이 필멸의 세계에 대한 거의 무한한 권한을 만물의 창조주, 카즈고로스라는 티탄에게서 받았습니다.$B$B타락한 그는 배반과 속임수로 다른 위상들이 자신들의 힘으로 악마의 영혼이라는 물건을 만들도록 설득했고 그 물건으로 한때 위대했던 위상들을 약하게 하여 갈라놓은 것입니다."
rows["432:669059798"]="왜 이 햇볕 따사로운 해안과 푸른 바다를 떠나려고 하는지 모르겠습니다. 여기는 낙원 같은 곳이라고요. 하지만 제 동생 자페타에게는 그런 말 하지 마십쇼. 티리스팔에 온종일 처박혀 있게 돼서 기분이 상당히 안 좋으니까요. 이 비행선은 다행히 오그리마에서 서니까 그 녀석의 불평불만을 들을 일은 없을 겁니다. 하지만 혹시라도 티리스팔에 가면 녀석 성질 돋우는 짓은 안 하시는 게 좋을 걸요."
rows["433:1169646851"]="어둠해안 북부로 가면 악령숲이라고 하는 땅에서 흘러내려 오는 폭포수 강이 있어요. 폭포수 강이 안개 해안으로 들어가는 곳에서 북쪽으로 가면 수심이 아주 깊어지죠. 거기에는 모양이 발톱 같다 하여 돌발톱이라는 이름이 붙은 바위 지형이 있는데 당신이 찾는 게 거기 있답니다.$B$B조심하세요. 돌발톱 바위 근처에 모여 있는 트레샤돈은 자기 영토에 들어오는 자는 모조리 공격하거든요."
rows["433:680475044"]="토르텔드린 왕자는 불멸의 삶과 무한한 힘을 위해 주민들을 살해했습니다. 한 때는 수천 명이 함께 나누던 마력을 이제는 토르텔드린 왕자와 셴드랄라 광신도들이 독점하고 있지요. 소수의 생존자들이 이몰타르를 계속 가두어 놓기 위해 수정탑에 직접 마력을 불어넣고 있습니다.$B$B그 악마가 풀려나기라도 한다면 한때는 위대한 비전술의 보루였던 이곳의 유적들은 완전히 파괴될 거예요."
rows["434:1457618006"]="그녀는... 너?$b$b<성통의 물결이 그의 놀라움을 끊는다.>$b$b그 여자 를 죽였어. 네가 거절 할 수 없었나? 도망할 수 없었나? 그녀를 구하지 못했을까? <그 목소리는 모든 말 에 올라가고 슬픔과 분노 로 붓고 있다. 최후 에, 그는 반 움직임을 하고 마치 너를 때리고, 철을 그리는 것처럼, 그러나 아무것도 발견하지 못하다. 결국 그의 어깨는 패배로 무너진다.>$b$b가세요, 제발 머리 좀 낮추세요."
rows["434:704062707"]="대마법사 바르고스 님께서는 제게 자신의 지팡이를 맡기면서 블러드 엘프의 공격을 피해 보랏빛 탑에서 달아나라고 하셨습니다. 저는 그분께서 말씀하신 대로 알클론의 오래된 드레나이 정착지에 피신하려고 했었지요.$B$B하지만 그것도 잠시뿐이었습니다. 저는 불타는 군단의 선발대와 마주쳤답니다. 악마들에게 지팡이를 뺏겼지만 가까스로 도망쳐 목숨을 건질 수 있었지요.$B$B주인님은 아직 이 사실을 모르고 계시지만 저는 아직도 수치심에서 벗어나지 못하고 있습니다."
rows["435:101128655"]="믿을 수가 없군요. 강력하고, 치명적이며, 끝내주는 역병으로 뒤범벅이군요! 잠시만, 제가 이 신선한 견본을 채취하도록 해 주세요. 동료 여러분께 남은 감염도 제거해 드리고 의술의 이름으로 용감하고 희생적인 당신에게 보상해 드리겠어요. 계속할 준비가 되면 말씀해 주세요. [진행하기 전에, 성취에 대한 공로를 함께 인정받을 수 있도록 '모든' 공격대원을 가까이 오도록 하십시오.]"
rows["435:1444681443"]="모든 사람이 여기 오신 것을 환영합니다. 그들이 원한다면 피 엘프들조차도. 우리는 이 집을 고대 하이보른 유적 위에 지내는 비밀의 계곡에서 지위가 관대하고 마법이 풍부합니다. 일부 하이 엘프들은 인간들 사이에서 사는 것을 선호합니다. 스톰윈드 또는 다라란 같은 도시들은 많은 사람들을 환영했습니다. 다른 사람들은 몇 명, 사막에서 외로운 삶을 영위하고 있으며, 그들은 그곳에서 Quel'Lithien 또는 Quel'Danil 주민처럼 남아 있습니다."
rows["435:256947357"]="입대신청서를 쓰거나 할 필요는 없지만, 어쨌든 그와 함께 싸워야 합니다.$B$B반드시 아서스가 스트라솔름을 파괴하고 말가니스를 처치하게 이끌어야 해요. 우서와 제이나가 곁에 없으니 아마도 손이 모자라겠지요.$B$B아서스에게 말을 걸면 말가니스의 부대를 격파하라는 임무를 줄 거예요. 무한의 용군단에서 꾸미는 수작이 뭔지 내가 알아낼 때까지 계속 그를 따라다니셔야 해요. 더 자세한 정보를 얻으면 다시 연락하겠어요."
rows["435:471239067"]="또 다른 전사가 원시 분노의 길을 찾고 있소? 난 그레린 아이언베어드이고, 네가 태어나기 전부터 아이언포지 ⁇ 이 가장 뜨겁게 타는 곳, 진정한 힘은 다리와  ⁇ 에서 나오는 것이 아니라 모든 왜자의 심장에서 불타는 야만적인 불에서 오는 것을 배웠습니다."
rows["435:957576266"]="특히 냄새가 나기 쉬운 물고기 들 은 열대 해수 를 좋아하는 물고기 들 이다. 그 중 가장 냄새가 나기 쉬운 물고기 들 은 줄루브의 증기 물 에서만 발견 될 수 있다.$B$B쥬리아의  ⁇ 스쿠크들은 가흐란카를 그 곳으로 끌어들였다고 생각합니다. 트롤들은 아마 그가 그들의 신 중 한 명이라고 말할 것입니다.$B$B믿으세요, 하지만 제 명단을 지으세요. 제 매력을  ⁇ 리안  ⁇ 스 ⁇ 스랑 채워주세요. 그 늙은이가 올 겁니다."
rows["436:1739147242"]="아, 자에터 <셀레브라스>은 눈을 돌린다$B$B내 아버지 레무로스는 그를 막으려고 노력했어요$B$B자에타르는 거침없는 사람이었고, 흙의 초자연 공주에게 사랑에 빠졌을 때, 아버지는 그들의 연합이 저주된 것을 알았지만, 자에타르는 듣지 않았다.$B$B켄타우르는 그의 실수로 태어났습니다. 그들은 변형되어 증오가 많았어요. 제 삼촌 자에타르는 그의 친척들에 의해 살해당했습니다.$B$B악의 왕자녀 테라드라스는 여전히 그의 유물을 크리스탈 동굴에서 보호하고 있습니다."
rows["436:400660144"]="그렇죠? 그런데 수명으로 비교해 보면 용과 불꽃매는 엄연히 다르답니다. 우리 세계에서의 용은 수천 년을 살 수 있지만, 이 불꽃매는 알을 깨고 나와 성년이 되어 죽기까지의 생이 아주 짧아요.$b$b스승님께서 우리가 연구하는 것에 감성적인 면을 가지는 것에 대해 경고하셨지만, 가끔 불꽃매들이 불쌍하게 느껴지는 건 어쩔 수 없답니다. 살아 있을 때는 너무나 밝게 빛나지만... 죽을 때는 너무나 빨리 바뀌고 잊히니까요."
rows["436:529018685"]="파멸자 라젤리크는 대전쟁 당시 군주 카자크의 부관 중 가장 두려운 존재였지. 불타는 군단이 패하고 카자크가 타락의 흉터로 밀려났을 때 라젤리크는 카자크로부터 저주받은 땅을 확보하라는 임무를 받았네.$B$B얼라이언스와 호드가 저주받은 땅 밖의 영토를 놓고 사소한 싸움을 벌이고 있을 때, 라젤리크는 어둠의 의회를 결속시키고 흉포한 우레망치 오우거들을 모으고 있었네."
rows["436:676188744"]="여기 태양샘 고원에 있는 킬제덴 수호자들은 우리가 섬 바깥에서 마주쳤던 그 어떤 존재보다도 강력하더군요. 불타는 군단은 우리 비전 수호병 기술 체계를 악의 기운으로 왜곡시켜 훨씬 더 사악한 존재를 만들어 냈습니다. 태양칼날단 파수병 단 하나가 엄청난 수의 우리 병사를 처치하는 걸 보고는, 신속히 퇴각하라고 명령을 내렸습니다. 지금은 태양샘 고원에서 부대가 완전히 빠져나왔기를 바랍니다만, 어쨌든 적이 추격을 그만두었다는 말에는 놀라지 않을 수 없었습니다."
rows["437:1054586005"]="어둠해안 북부로 가면 악령숲이라고 하는 땅에서 흘러내려 오는 폭포수 강이 있어요. 폭포수 강이 안개 해안으로 들어가는 곳에서 북쪽으로 가면 수심이 아주 깊어지죠. 거기에는 모양이 발톱 같다 하여 돌발톱이라는 이름이 붙은 바위 지형이 있는데 당신이 찾는 게 거기 있답니다.$B$B조심하세요. 돌발톱 바위 근처에 모여 있는 트레샤돈은 자기 영토에 들어오는 자는 모조리 공격하거든요."
rows["437:1241687741"]="저주의 제단에서 서서 저주받은 자들의 영혼들이 기도하며 무릎을 꿇는 것을 보면, 내가 구단 옆에 서 있는 것을 보지 못합니다.$B$B오로노크가 주면$B$B내가 많은 걸 알고 있다고 말했잖아 그 중 하나가 구단 중위였어$B$B난 평생 끔찍한 일을 해왔어 남녀를 죽였어$B$B오로노크는 그의 말들로 질식한다."
rows["437:1586766831"]="최후의 순간이 왔다. 여기에서 일어나는 일은 세대를 거듭하여 전해지리라. 결과가 어떻든간에 우리가 명예롭게 싸웠음을 알리라. 자유와 우리 백성을 위해 싸웠음을!$B$B기억하게. 공포는 이 저주받은 전당에서 가장 위험한 적이네. 마음을 굳게 하면 그대들의 영혼은 천 개의 태양보다 더 밝게 빛날 걸세. 적들은 그대들 앞에 기가 꺾이겠지. 정의의 빛이 감쌀 때 모두 쓰러질 걸세!"
rows["437:648435764"]="메아리 섬에 있는 동료들의 도움이 필요하네.$B$B젠타브라는 오랫동안 섬에 있는 동물들을 관장하고 있네. 그녀와 동물들의 도움이 필요하네.$B$B브원삼디는 메아리 섬의 죽은 자들을 다스리는 강력한 로아라네. 우리의 작전이 성공하려면 그의 협조가 필수적이지.$B$B이들이 우리와 함께하기만 한다면, 잘라제인과 그의 조종을 받는 트롤들을 무찌르는 건 시간문제네! 그건 즉, 메아리 섬이 검은창 부족의 품으로 돌아온다는 말이지!"
rows["437:724641569"]="메아리 섬에 있는 동료들의 도움이 필요하네.$B$B젠타브라는 오랫동안 섬에 있는 동물들을 관장하고 있네. 그녀와 동물들의 도움이 필요하네.$B$B브원삼디는 메아리 섬의 죽은 자들을 다스리는 강력한 로아라네. 우리의 작전이 성공하려면 그의 협조가 필수적이지.$B$B이들이 우리와 함께하기만 한다면, 잘라제인과 그의 조종을 받는 트롤들을 무찌르는 건 시간문제네! 그건 즉, 메아리 섬이 검은창 부족의 품으로 돌아온다는 말이지!"
rows["437:807088334"]="후회?$b$b오델은 화려하고 도전적인 미소를 대답으로 내놓는다.$b$b죽음은 이상해요. 그 시선을 더 오래 붙잡으면 더 유혹적이죠.$b$b목에 걸려있는 시체, 굶주린 비참한 사람들이 그레이스키의 벽에서  ⁇ 에 매달려, 마을이 불꽃에 탔습니다. 무고한 사람들이 피에에 불타게 된 것입니다.$b$b당신들이 내 형제 자매들의 삶에 어떤 가치를 부여했습니까?$b  "
rows["437:828402724"]="에테리움은 내 고향인 크아레쉬의 지배자들이었지. 비극적이게도 우린 공허의 군주 디멘시우스가 공허의 군대를 끌고 와 모든 것을 파괴하기 전에 대피를 해야만 했소. 이런 이유로 에테리움은 복수를 맹세했지. 그 후로 그들은 디멘시우스를 추적하였소...$B$B그러나 우리 자유연합은 디멘시우스 때문에 뭉치게 된 것은 아니오. 우리는 에테리움을 막기 위해 조직되었소."
rows["438:1294760044"]="불모의 땅이 한때 우거진 숲이었다는 걸 알고 계셨습니까? 수천 년 전, 처음 세계가 분리되기 전에는 칼도레이의 보호 아래 신록의 땅으로 번창했지요. 하지만 대륙이 갈라지고 이곳 역시 칼림도어라 불리는 대륙으로 분리되면서, 자연의 계곡은 태양에 혹독하게 그을린 평원으로 변했습니다.$B$B이 사실을 처음 알았을 때는 커다란 비극이라 생각했습니다. 그리고 숲을 다시 한 번 자라게 할 방법을 찾겠다고 결심했습니다."
rows["43:101834522"]="저에게는... 아니, 우리 모두에게... 시간은 별로 남아있지 않아요."
rows["43:1067277438"]="시간 낭비하지 맙시다! 언데드가 코앞에 있어요."
rows["43:1115709061"]="날개 없는 파리들을 벼룩이라고 부르나요?"
rows["43:1182337384"]="새의 영혼이여, 우리 신전에 와주었구려. 환영하오."
rows["43:1214152212"]="친구여, 당신에게 나루의 가호가 있기를."
rows["43:1221568328"]="화산 바위입니다! 화산 바위 사가세요!"
rows["43:1226684246"]="바다 속은 아주 평온해요."
rows["43:1280074442"]="들쥐로 만든 스튜는 대단히 맛있다오."
rows["43:1340327313"]="여기서 절 데리고 나가실 수 있겠어요?"
rows["43:1361500489"]="< ⁇ 은  ⁇ 이 너한테 굴러오네>"
rows["43:1381284934"]="용건을 밝히시오. 최대한 간단하게."
rows["43:1511826871"]="우리가 이 전쟁에서 이길 수 있을까요? 시간이 지나면 알 수 있겠죠."
rows["43:157316138"]="대지의 자손이여, 어떻게 도와드릴까?"
rows["43:1949010423"]="5분만 더 자게 해주십시오..."
rows["43:1950671787"]="<대족장 블랙핸드가 좌중을 내려보며 서 있습니다.>"
rows["43:1968210053"]="그대를 훌륭한 사냥꾼으로 훈련시켜 주겠소."
rows["43:1985643533"]="나 고블린 여자가 오우거랑 친구 하는 거 도와준다."
rows["43:1988795169"]="여기에서 주문각인 숙련자를 찾을 수 있습니다."
rows["43:2095336695"]="...팬에 살짝 튀기고, 기름을 가득 넣고 튀기고, 휘저어 가며 튀기고..."
rows["43:2102931274"]="오늘 아주 예쁘게 보이네요, 마르텍"
rows["43:2106638243"]="오, 얼마나 신성한 장소가 무너졌는가!"
rows["43:2137890353"]="피부를 벗겨줄 수 있어"
rows["43:216255568"]="시간 있나? 수네가 좋은 노래를 가르쳐 주겠다!"
rows["43:349037839"]="당신 때문에 물고기가 겁나서 도망갔잖소! 원하는 게 뭐요?"
rows["43:390038869"]="반갑습니다, 친구여! 어떤 물건을 보고 싶은가요?"
rows["43:531258982"]="솜씨가 있는지 없는지 어디 한번 보세!"
rows["43:707002013"]="다섯 가지를 모두 선택했습니다."
rows["43:707004679"]="쉬이이잇! 목소리 좀 낮추세요! 당신 때문에 들통 나겠어요."
rows["43:721996903"]="아, 오늘도 우리의 아름다운 섬의 날씨가 참 좋군요."
rows["43:895327420"]="날 도와줘야만 해! 내 불쌍한... 불쌍한 첼시..."
rows["43:897239096"]="여행자여, 가서 편히 쉬게. 따뜻한 우리 모닥불을 자네 것처럼 생각하게나."
rows["440:51935106"]="뭘 해야 하냐고요?$B$B축제 기간에는 전 세계의 모든 여관주인들이랑 \"사탕 하나 주면 안 잡아먹지!\" 놀이를 할 수 있어요. 그리고 여러 마을에 예쁜 장식이 달리니까 구경하러 한번 가보세요! 그리고 매일 저녁에는 언더시티 밖에서 밀짚인형 축제가 열려요."
rows["440:853903201"]="마법진이 이몰타르에게서 흡수한 힘이 명가의 마력을 유지시켜 주었고, 엘드레탈라스 성벽 안에 사는 이들이 갖고 있는 마법에 대한 끝없는 갈망을 충족시켜 주었습니다.$B$B그런데, 수천 년이 지나면서 엘드레탈라스의 생명력을 유지하면서 이몰타르를 가두어 두는 데 필요한 마력이 필요하게 됐어요. 이몰타르를 가두어 둠으로써 얻는 힘보다 그를 가두는 데 더 많은 마력이 필요해진 것이죠. 즉, 흑자에서 적자로 바뀐 겁니다."
rows["441:1813220602"]="송곳니 군주들이 죽었소! 아직 희망이 모두 사라진 건 아니오! 하지만 자각의 의식은 꽤 복잡하여 혼자서는 할 수 없소.$B$B필요한 준비는 내가 모두 할 테니 당신은 나를 지켜주어야 하오. 에메랄드의 꿈을 통해 나랄렉스 님의 여행에서 소환된 몽마들은 상당히 위협적이오. 당신이 도와주지 않는다면 이 임무는 실패할 거요.$B$B나를 지켜줄 줄 준비가 되거든 말해주시오. 그러면 나랄렉스 님의 안식처로 안내하겠소."
rows["441:1931845049"]="안녕하세요! 모험을 즐기시는 분이시군요. 혹시 도전할 만한 일을 찾고 있다면 한 가지 제안이 있어요.$B$B지금 저는 열심히 드루이드들을 돕고 있어요. 제가 발명한 고성능 자동부화기로 히포그리프들을 구하려고요. 히포그리프들에게 페랄라스의 폐허에 사는 골두니 오우거들이 나쁜 영향을 미치고 있습니다. 때문에 그 수가 점점 줄어들고 있어요.$B$B그래서 저는 여러 종류의 알을 모은답니다. 저를 도와 알을 좀 찾아주시겠습니까?"
rows["442:1206624026"]="전혀 이해하지 못하는군. 내가 원하기만 했다면, 싸워서 스스로 동굴에서 빠져나갔을 것이다.$B$B내 아버지 우르속이 문제다. 아버지는 죽음에서 되돌아왔지... 하지만 이전과는 다르다.$B$B아버지는 수천 년 전에 일어난 고대의 전쟁에서 목숨을 잃었다. 수세기에 걸쳐 아버지를 숭배한 펄볼그는 아버지를 부활시킬 방법을 찾고자 노력했지.$B$B마침내 그들은 버려진 세계수 볼드랏실을 다시 길러, 그 마법으로 아버지를 되살리려고 했다."
rows["442:1602334969"]="자네가 할 일은 킬소로우 요새의 오크들이 그들의 기지를 전쟁망치 오우거들이 공격했다고 믿게 한 후, 전쟁망치 오우거들은 킬소로우의 오크들이 그들의 기지를 공격했다고 믿게 하는 작전을 수행하는 것일세.$B$B이 작전이 성공하면 우리 문제가 모두 해결될 것이다.$B$B돌주먹 일족은 영토를 되찾을 수 있고 너희 종족은 돌주먹 일족, 전쟁망치 일족, 어둠의 의회의 공격으로부터 자유롭게 될 것이네."
rows["442:291762482"]="힘 있는 자들조차 그 존재의 말이 두려워 벌벌 떨었습니다.$B$B그럼에도 자기 멋대로 종교를 만들어 신봉하던 위선자들과 허풍선이들은 자신들의 '신'을 통제하기 위해 발버둥을 쳤습니다. 이 어리석은 자들에게 아무 관심도 없고 어떠한 배려도 없었던 울림은 하품 한번으로 그들을 영원히 소멸시켰습니다.$B$B그러나 그중 한 명이 살아남아 이 세상에 울림을 소환하는 방법을 알아냈습니다."
rows["442:35875920"]="저 너머에 부서진 함정이 보이나? 오우거들은 너무 멍청해서 부서진 함정을 고칠 생각은 꿈에도 못하지. 분명히 수선 작업이 필요하단 말이야. 함정을 고치면, 오우거 경비병 슬립킥을 그쪽으로 꾀어내어 사로잡을 수 있다고!"
rows["442:444032780"]="어둠해안의 젊은 나이트 엘프였던 시절, 저는 황혼의 망치단이라는 불미스러운 작자들과 만나게 되었습니다. 그들과 어떻게 어울리다 보니 친해졌고, 젊은 혈기에 부끄럽게도 엘룬에 대한 신앙을 저버리고 황혼의 망치단을 따르게 되었지요.$B$B꿈속에서 엘룬 여신님의 환영을 만나고서야 스스로 그릇된 길을 가고 있음을 깨달았습니다. 그 이후, 저는 고대 신을 섬기는 자로 다시 태어났습니다.$B$B그리고 회개의 뜻으로 엘룬께 올리는 기도문을 만들기 시작했습니다."
rows["443:1818098204"]="헤멧은 제가 아는 가장 위대한 사냥꾼입니다. 우리는 몇 달 전 아제로스 뒤편에 있는 여명의 설원 언덕에서 우연히 만났지요. 우리는 라크쉬리라고 하는 거대한 호랑이를 같이 추적하고 있었지요.$B$B우리는 그 사냥감을 놓고 서로 싸우는 대신 내기를 했습니다. 내기인즉슨, 눈호랑이 가죽을 구하는 자의 요구를 들어주는 것이었습니다. 정말 부끄러운 일이지만 이게 바로 제가 피츠라는 별명을 얻게 된 계기입니다."
rows["443:188184279"]="우리 는 약 6 개월 동안 이렇게 하고, 그 집 이 끔찍한 변화 를 겪는 동안 지켜봤습니다. 불쾌 한 괴물 들 은 마음대로 숙소 를 돌아다니고 있었습니다. 어두운 종파 들 은 의식 과 희생 에 관한 여러 가지 물건 들 을 매장 했습니다. 우리 는 더 이상 숨길 수 없다는 걸 알고 있었습니다.$B$B그들이 예상대로 우리를 발견하고 잡았고, 우리 옷을 벗고 피를 흘린 채로 내놓았고, 우리는 며칠 동안 헐벗고 공포를 떨고 앉아 있었습니다."
rows["443:2020429781"]="우리는 누구의 원인을 지지하지 않습니다. 아무도 우리의 원인을 지지하지 않습니다. 에알디르가 전쟁 이외의 모든 것에 대한 마음을 가진 지 오래되었습니다. 우리를 기억하는 사람은 거의 없습니다. 여전히 더 적은 사람들이 우리를 존중합니다. 우리는 한때 지도자, 보호자였습니다. 그러나 우리는 마녀에게 지시한 날이 먼 것입니다. 우리는 에알디르에게 바람과 강과 돌을 듣도록 가르쳤을 때. 스카데일은 그들을 우리로부터 쫓아냈고. 스카데일은 그들의 생각을 어두워졌습니다. 그리고 그것은 그녀와 시작되었습니다. 그것은 모르그웨나와 시작되었습니다."
rows["443:948067774"]="당신이나 나나 영혼이 육체에서 억지로 찢겨나갈 때의 고통은 상상도 할 수 없을 거요. 우리 병사들은 완전히 죽은 것도, 살아있는 것도 아닌 상태... 그 상태로 이 세계에 그들을 묶어둔 자들의 노예로 살아가야 했던 거요.$B$B바로 이 땅을 지배하는 악마 군주 라젤리크의 노예가 돼버린 것이오. 라젤리크는 그중 아홉 명을 어둠의 문 근처 봉인석에 배치하고 있소. 그리고 나머지 아홉은 자기 부하들에게 나눠주었소."
rows["444:1367038748"]="오그릴라에 온 신인인으로서, 당신은 이 곳의 크리스탈에 충분히 노출되어 있지 않아서 그 모든 혜택을 누릴 수 있습니다.$B$B반면에 우리는 아주 오래 전부터 이곳에 왔습니다. 그래서 여러분이 상상할 수 있듯이 우리는 많은 것들에 대해 꽤 잘 알고 있습니다.$B$B최근 우리는 동조 수용소들의 악마에 대해 많은 관심을 가지고 있습니다. 더 구체적으로, 우리는 그들을 영원히 없애는 방법을 생각해냈습니다.$B$B적어도 이론은 이렇습니다."
rows["444:2016959442"]="난 발랑트 선장의 우리시스 랙모어이고, 이건 내 운명된 배의 마지막 날들의 기록입니다.$B$B우리는 재료를 한 배로 피더문 강성으로 항해하고 있었는데 나가들이 갈랑트의 부위를 공격하면서 그들을 몰아냈지만 그들이 돌아올 줄 알았어요. 가장 소중한 사물들을 잃는 것을 두려워해서"
rows["444:753133470"]="이 이론은 당신이 어디에 있든 거대한 폭발로 완전히 파괴하고 그 입자를 차원적 찢어지기를 통해 보내다가 여기에 기계에 다시 삽입한다는 것입니다. 인스턴트 운송! 그것은 항상 작동하지 않을 수도 있지만, 당신은 어떤 종류의 괴뢰 엔지니어입니다! 생존이 당신의 최우선 과제로 있다면 당신은 결코 진정한 괴뢰 엔지니어가 될 수 없습니다!$B$B여기 이 지형 찢어지기 만들 수 있는 레시피가 있습니다."
rows["445:162108509"]="약 5개월 전, 투자개발회사의 가시덤불 지부에서는 무법항에 있는 크랭크 피즐버브라는 수상한 상인에게 특수한 독을 받기로 계약을 했소. 피즐버브는 잔질에게 독을 훔쳐온 게 분명하오!$B$B그래, 추방자 잔질 말이오. 그 트롤은 강령술 실험을 하곤 했는데, 그 때문에 부족에서 영원히 추방당하고 말았소.$B$B그들은 독을 받은 후 서로 시험해 보기 시작했고 그 결과는 실로 참담했소."
rows["445:2006093641"]="그러려면 우선 그대가 준비됐는지 확인해야 한다. 가장 현명하고 성숙한 드루이드라고 해도 최종 시험에 대해 완벽하게 준비가 됐다고는 할 수 없는 법이지.$B$B내 말을 새겨들었으면, 쉬지 말고 전진하라. 내가 가르쳐 준 교훈을 유념해라. 그대의 힘을 시험할 때가 곧 올 것이다. 곰과 같은 육체와 정신의 힘으로 적과 맞서라. 실전을 통해 배워라. 나의 축복이 그대와 함께할 것이다."
rows["445:999439336"]="바람은 내게 비밀, 힘, 그리고 진실에 대해 말해 주었지. 성스러운 빛은 뒤틀린 드레나이를 저버린 게 아니었네! 오래전 오크들이 드레나이를 상대로 휘둘렀던 사악한 마력이 우리에게 주입되어, 성스러운 빛에 우리의 목소리를 전하거나 빛의 목소리를 들을 수 있는 능력을 상실하게 했지. 우리 육체가 약해진 것도 같은 이유라네.$B$B하지만, 우리 영혼은 온전했고 바람은 나의 백성들을 인도할 또 다른 희망의 길을 제시해 주었다네."
rows["446:1200216802"]="이곳은 오크와 인간이 처음으로 서로의 피를 본 장소에요. 남쪽으로 1Km도 안 되는 곳에 스토나드가 있어요. 오크가 우리 땅을 침략하기 위해 최초로 결집한 곳이죠.$B$B우리가 오크의 존재도 모르던 시절에 놈들은 여기서 병력을 모았지요. 서쪽의 작은 얼라이언스 마을 공격을 시작으로, 최초의 세 전쟁이 시작된 곳도 바로 여기고요.$B$B그곳은 제가 자란 마을이었어요. 저를 구하기 위해 부모님이 목숨을 바친 곳이죠.$B$B하지만 저는 한을 풀기 위해 이곳에 온 게 아니에요... 바로 전쟁에서 이기기 위해 이곳에 온 거예요."
rows["446:1487252861"]="난 천둥군주 부족의 옛문화를 연구하려고 이곳에 왔네.$B$B원래 나약한 존재였던 그들은 만노로스의 피를 마시고 타락한 오크로 변하는 조건으로 힘을 얻었지.$B$B그 부족의 책은 모두 읽어 보았네. 우리가 칼날첨탑 오우거들을 격파하고 놈들의 요새로 후퇴시켰을 때 사라진 유물과 북, 화살, 그리고 서판을 되찾는 일에 특히 관심이 많이 가더군."
rows["446:1608193218"]="단순하게 말하자면 그렇습니다.$B$B토석인의 신체는 신장이 작은 인간형 생물과 비슷하지만, 토석인을 이루고 있는 것은 아제로스에 있는 여러 가지 바위의 핵심 성분입니다. 토석인은 지적 처리 능력을 크게 떨어뜨리지 않고도 체력을 극대화하는 방식으로 설계되었습니다. 피부와 근육조직은 물리적 손상에 거의 영향을 받지 않으며, 아주 사소한 개조 단계만 거치면 마력에 대해 놀라운 저항 능력을 보입니다."
rows["448:2051182195"]="이 운고로 분화구에 서식하는 라바사우루스는 불모의 땅에 서식하는 랩터와 분명히 어떤 관련이 있는 듯하오. 아주 지능이 높고 포악할 뿐 아니라 행동 지침 같은 것도 있소. 지금까지 내 눈으로 본 중에서 라르코르위라는 녀석이 가장 거대한데 그 어떤 짐승보다 위험한 녀석이오... 타우렌어로 라르코르위란 '뾰족한 발톱'이란 뜻인데, 그 말만으로는 녀석을 제대로 설명할 수 없지.$B$B라르코르위를 사냥할 생각이라면 녀석을 과소평가하지 마시오. 그리고 내가 힘닿는"
rows["448:2110494301"]="드워프는 한동안 우리에게 피난처를 마련해 주었지. 그에 대해서는 감사하게 생각하네. 하지만 반역자 텔마플러그가 언제까지 이렇게 놈리건을 차지하게 놔둘 순 없지. 놈리건은 우리의 빗나간 계획 때문에 방사능 아래에서 너무 오랫동안 고통받고 있네. 방사능 폭탄이 폭발하면서 도시를 떠날 수밖에 없었지만, 이제 우리에겐 놈리건을 되찾을 기술이 있네!$B$B반드시 우리의 것을 되찾고, 텔마플러그에게 정의의 심판을 내릴 걸세!"
rows["448:413115081"]="빛의 본질은 미스터리입니다. 현재는 언제나 우리의 유일한 방패가 믿음입니다. 어리석은 사람만이 빛를 땅이나 물과 같은 다른 물질이라고 생각할 것입니다. 어떤 사람들에게는 이성이 없는 공감력입니다. 우리처럼, 여긴 수도원에서, 그것은 훨씬 더 많습니다. 그것은 지능입니다. 현실을 주축하는 건축 원칙입니다. 다른 철학자들이 '동동이없는 운동자'라고 부르는 창조적 충동입니다."
rows["449:1223888761"]="사냥꾼과 마찬가지로 소환수도 전문화를 선택할 수 있습니다. 살쾡이 같은 야성 야수는 적에게 피해를 많이 주지만 받는 피해도 많지요. 거북이 같은 끈기 야수는 좀 더 방어력이 좋고, 당신이 멀리서 공격할 수 있도록 적의 주의를 끄는 데 능합니다. 거미 같은 교활 야수는 공격적인 특성과 방어적인 특성이 혼합되어 있으며, 전장이나 투기장 같은 곳에서 특히 유용하지요.$b$b각 소환수는 처음 길들였을 때 기본으로 설정된 전문화를 지니고 있습니다. 하지만, 원한다면 언제든지 전문화 분야를 바꿀 수 있지요."
rows["449:1224135830"]="아, 내가 너무 앞서간 것 같군. 라스 프로스트위스퍼는 그 학교의 감독관일세. 그들의 모든 어둠의 세력들을 양성해 내는 장본인이자 켈투자드의 부관 겸 수제자지. 그는 한때 스트롬가드의 이탈 마법사였다네. 달라란에서 정식 훈련을 받은 적이 없는 이단마술사였지.$B$B켈투자드가 교단을 창단했을 때 라스는 가장 먼저 입단한 자들 중 하나였네. 암흑 마법을 통해 영생을 얻을 수 있음을 알고 있었던 것이지."
rows["449:1572696660"]="이 운고로 분화구에 서식하는 라바사우루스는 불모의 땅에 서식하는 랩터와 분명히 어떤 관련이 있는 듯하오. 아주 지능이 높고 포악할 뿐 아니라 행동 지침 같은 것도 있소. 지금까지 내 눈으로 본 중에서 라르코르위라는 녀석이 가장 거대한데 그 어떤 짐승보다 위험한 녀석이오... 타우렌어로 라르코르위란 '뾰족한 발톱'이란 뜻인데, 그 말만으로는 녀석을 제대로 설명할 수 없지.$B$B라르코르위를 사냥할 생각이라면 녀석을 과소평가하지 마시오. 그리고 내가 힘닿는 데까지 도와주겠소이다."
rows["449:2097579902"]="아름다운 아비아나, 새들의 주인! 아제로스의 날개로 된 모든 생물들은 그녀의 충성을 빚어졌어요. 특히 우리는 타롱의 드루이드입니다. 그녀의 은혜로 우리는 형태를 변화시키고 하늘을 향해 나아갈 능력을 부여 받았습니다.$B$B아비아나는 그녀의 자녀들 사이에서 셀 수 있는 큰 포식 새처럼 아름답고 끔찍했다. 그녀는 어머니 나무인 기하니르의 높은 영 영역에서 살았지만 아제로스에 큰 날개로 된 여신의 형태로 나타났습니다."
rows["449:839151057"]="예상과 달리 이런 능력이 얼라이언스에게 있었군. 이제 호드 얼라이언스와 모두 안퀴라즈 전쟁에 필요한 준비를 마쳤네. 일전에 말한 대로 실리더스로 물자를 수송하는 중인데 $2113w일 내로 도착할 걸세. 그다음엔 누군가 흐르는 모래의 홀을 다시 결합하여 스카라베 제단에 있는 징을 울리고 안퀴라즈의 관문을 열 걸세. 바야흐로 전쟁이 시작되는 거지!"
rows["44:1083139620"]="소... 손대지 마세요...$b$b이게 대체 무슨 일이지요?!"
rows["44:108797913"]="수도원 남쪽에 있는 것 같네."
rows["44:1098195088"]="<목소리를 낮추라고 손짓하는 킬라그>"
rows["44:1110835606"]="<여사제 킬린 일디나레가 수상한 눈으로 당신을 바라봅니다.>"
rows["44:1167308568"]="황천의 비룡이 알았다는 듯 당신을 바라봅니다."
rows["44:1181435289"]="자네 주변에서 뭔가 동요가 느껴져..."
rows["44:1192303619"]="<인간 보병이 바짝 긴장한 듯 결의에 찬 표정으로 서 있습니다.>"
rows["44:1203320011"]="이 오래된 무덤은 흐트러짐 없이 평화로운 모습입니다."
rows["44:1288330979"]="그대의 연구에 어떤 도움을 드릴까요?"
rows["44:1334799148"]="저는 온갖 종류의 물건을 모두 취급하지만 보통은 희귀한 물건만을 팔고 있답니다."
rows["44:134739968"]="당신과 당신의 동전은 항상 환영합니다."
rows["44:1348875851"]="오늘은 바람이 어딘가 이상하구나. 참으로 이상해."
rows["44:1426670794"]="팁이라면 언제든 대환영입니다."
rows["44:1497472662"]="돈만 내면 당신이 원하는 것을 주겠소."
rows["44:1588434696"]="난 불꽃 관절의 능력을 존경한다."
rows["44:1594711582"]="우리 아직도 여기 서 있는 이유가 뭐야?"
rows["44:1612877221"]="조사할 거리가 끊이질 않는군."
rows["44:1641357183"]="실은 간단하다. 내가 요약해 주지..."
rows["44:1890490713"]="감독관에게 들키기 전에 어서 제자리로 돌아가세요."
rows["44:1903397187"]="초신료에 대해 가르칠 수 있어"
rows["44:1940597106"]="꼬마야, 집어쳐라. 난 다른 바쁜 일이 있어서..."
rows["44:1995672609"]="첫 번째 도전에 나설 준비는 되셨습니까?"
rows["44:2044493961"]="관심이 있다면 재봉술 과정에 대해서 세심하게 알려드리죠. 어떠십니까?"
rows["44:2085978057"]="반갑습니다. 쉴 곳이 필요하신지요?"
rows["44:2111957590"]="어떤 수업 트레이너를 찾고 계십니까?"
rows["44:2121024389"]="노예들이 널 보지 못하기 전에 여기서 나가!"
rows["44:290090815"]="딴 데 가서 알아보게. 나는 전사만 가르치니까."
rows["44:339664352"]="용의 위상들에게 가야 하네. 준비됐나?"
rows["44:413575263"]="알았네. 하지만 이번에는 조심하게!"
rows["44:505974438"]="교수대 근처에 잡아두고 있는 것 같네."
rows["44:508968455"]="자네는 스컬지가 아니군. 여기서 뭘 하는 건가?"
rows["44:511093776"]="역병을 써먹을 데는 많은데 시간이 부족하구나!"
rows["44:522709710"]="안녕하시오. 오늘은 기분이 좋아 보이는구려."
rows["44:607666968"]="그가 오는 소리가 들리는 것 같아! 서쪽을 보게!"
rows["44:730210567"]="제 직업은 폐기물 관리 전문가입니다."
rows["44:853246485"]="저는 귀하고 강력한 물품을 판매합니다."
rows["44:885865279"]="검은바위의 군주가 죽었다는 증거가 홍예문 위에 걸려 있다!"
rows["44:91283586"]="내 말을 알아들을 수 있나요? 난 당신 말을 알아들을 수 있어요!"
rows["450:869148004"]="죽음의 문은 다른 세계로 열리는 차원문입니다. 불타는 군단은 그곳에서 지옥사냥개 같은 짐승들을 기르지요. 그러니까, 그런 짐승들이 보인다면 죽음의 문을 통해서 나온 것이 분명하므로 가장 먼저 이곳을 지나갈 겁니다.$B$B최근 우리는 불타는 군단이 차원문을 통해 그 짐승들을 소환했다는 사실을 알아냈습니다.$B$B모든 것이 파괴되는 돌이킬 수 없는 지경에 이르기 전에 죽음의 문을 닫아야 합니다!"
rows["451:1114342558"]="잿빛 골짜기의 조람 해안에 위치한 검은심연 나락은 한때 나이트 엘프들의 달의 여신 엘룬에게 바쳐진 영광스러운 신전이었다고 합니다. 하지만 세계의 분리로 인해 신전이 파괴되어 장막의 바다의 물결 아래로 가라앉아 버렸지요. 그곳에 그 모습 그대로 남았는데, 나가와 사티로스가 그 고대 마력에 이끌려 등장하더니 신전의 비밀을 캐내기 시작했습니다. 전설에 의하면, 고대 괴물 아쿠마이가 그 신전의 폐허 안에 자리 잡고 있다고 합니다."
rows["451:396074398"]="라그나로스와의 전투에서 기회를 잡기 위해서는 화염된 타원지대에 기꺼이 용감하게 대처할 동맹군들을 모아야 합니다. 그리고 그러한 동맹군들을 우리 소장에 모집하기 전에 - 드루이드, 군인, 또는 단순한 공급자 -$b$b이 몇 개의 표지판을 가지고 있으면 우리 소리의 영웅이 될 수 있습니다 수백에 달하는 숫자를 모아 군대를 이끌게 될 것입니다$b$b계획이 보이시나요?"
rows["452:1748275224"]="십자군 사령관의 시험은 난이도가 더 높은 십자군의 시험이라고 할 수 있습니다. 모든 전투가 십자군의 시험 때보다 더 어려우며, 시험을 치를 수 있는 횟수도 제한되어 있습니다. 50번의 도전 기회를 다 쓰시면 일주일간 시험에 참가하실 수 없습니다. 십자군 사령관의 시험을 성공적으로 완료하시면, 추가 보상으로 공물함을 받으실 수 있고요. 시험을 치를 준비가 되셨습니까?"
rows["452:184091569"]="언제나 중립을 지키는 유명한 스팀휘들 무역회사를 대표해 수렁진흙탕에 온 걸 환영해! 우린 동부 왕국에서 해변 휴양지와 군대급 무기를 동시에 갖춘 유일한 회사지.$B$B남쪽에서는 사소한 전쟁이 일어나고 있을지 모르지, 하지만 이 벽 안은 재미와 여흥밖에 없어. 그러니 긴장 풀라고. 푹 쉬면서 술이나 한 두잔 걸치되 사고는 치지 말고 지내... 아니면 우리 투사들이 \"중립 지역\"의 뜻을 머리통에 확실히 새겨줄 테니까."
rows["452:239932782"]="호박색 비룡은 시간을 마음대로 조절해 피해를 주는 능력이 뛰어나지요. 충격의 창 기술을 사용하면, 적 주변에 흐르는 시간을 교란시킨 다음 즉시 피해를 줄 수 있어요. 충격 충전을 시전하면 그 위력을 극대화할 수도 있지요. 호박색 비룡은 위험에 처했을 때 잠시나마 적들의 시간을 멈출 수 있어요. 이런 시간 교란으로 효과를 받는 상대의 충격 에너지를 충격 충전의 형태로 축적하지요."
rows["452:638334653"]="탈출하겠다고? 좋아. 하지만 그전에 알아야 할 것들이 있어.$b$b우선 트롤에게 걸리지 말아야 해. 널 죽이진 않겠지만, 다시 이곳으로 던져 넣을 테니까.$b$b둘째로는 눈에 띄는 모든 랩터들에게 말을 걸어. 너에게 새로운 능력을 가르쳐주고 네 진행상황을 기억해 줄구룹을 더 쉽게 빠져나갈 수 있게 해 줄 거야.$b$b이미 질주 능력을 갖추고 있으니 위험한 순간에서 벗어날 때 사용하면 되겠군.$b$b아, 그리고 물에 가까이 다가가지 마.$b$b행운을 빈다!"
rows["452:740756115"]="에테리움은 점점 어둡고 교활하게 변해 갔소. 그들은 오직 복수만을 생각하고 자신의 길을 막거나 자신과 함께 뜻을 같이하지 않는 자들을 적으로 간주했소. 많은 이들은 에테리움이 점점 미쳐 가는 것을 보고 떠나 버렸지. 에테리움의 몇몇 연합왕자들은 에테리움을 떠나 다른 조직을 만들고 다른 뜻을 품었소. 무역연합이 그 한 예이자 우리 자유연합도 마찬가지라오..."
rows["453:1280590127"]="이 곳은 스톰윈드과 너무 다르지 않나요? 저는 공부를 그리워하지만, 이 곳은 별들을 너무 잘 볼 수 있게 해줍니다. 토르가 저와 함께 살라고 요청했을 때 저는 의박했지만, 이제, 제가 왔을 때 다행입니다. 오, 토르에 대해 이야기한다면... 그와 대화할 여유 있는 시간을 찾으면, 그에게 제가 그의 해마리를 빌려서 이 거친 오래된 래프를 고칠 것이라고 말해주세요."
rows["453:1313756916"]="북파일론은 노란색, 빨간색, 녹색 결정들을 받아들이고 있습니다.$B$B이 연구결과에서, 이 연구결과에서 연구결과에 대해 살펴보면, 이 연구결과에서 연구결과에 대해 연구결과에 대해 연구결과에 대해 알아볼 수 있는 몇 가지 방법이 있습니다. $B$B크리스탈 충전에는 빨간색과 노란색의 크리스탈이 필요합니다. 이것은 큰 폭발을 일으키고, 적들을 놀라게 할 것입니다.$B$B크리스탈 리스터레이션에는 노란색과 녹색의 크리스탈이 필요합니다."
rows["453:1355274733"]="그 들 이 자라는 나무 는 열매 를 맺었다. 처음에는 효과가 있었던 것 같았지만, 우르소크 는 다시 돌아왔고, 잠시 동안 기쁨 으로 가득 차 있었습니다.$B$B회복되면서 그는 그 사람이 아니었고, furbolg도 아니었음을 알았습니다.$B$B고대 드루이드들이 폭라시를 무너뜨리는 악은 무엇이든 새로운 나무에서 나타나서 모든 것을 피를 흘리는 괴물로 바꿨습니다.$B$B지금 그리즐리 힐스를 걷는 건 내 아버지가 아니고, 안식을 가져야 합니다."
rows["453:1493879933"]="처음 도착했을 때, 저는 마을의 동명인 사람을 만나기를 희망했습니다.$B$B로즈엘레스는 돌아다녔다.$B$B대부분의 젊은 고래들은 연습생으로 취임할 때 '나는 장교가 되고 싶다'라는 단계로 넘어갑니다.$B$B솔직히 말해서 저는 파스트라이더의 시대를 지나지 못했어요. 아무도 꿰매기 전문가가 되겠다는 꿈을 꾸지 못했지만, 우리 엄마는 말했듯이 파스트라이더들이 벌거벗은 채 달릴 수는 없어요."
rows["453:1769065778"]="저는 부서진 지팡이의 조각을 찾기 위해 아제로스 전역을 뒤지고 다녔어요. 그러던 중 지팡이를 다시 복원하려는 켈투자드의 계획을 알아냈지요. 그는 이미 지팡이 조각을 여러 개 모았습니다. 그가 가장 신뢰하는 부관들이 그 조각들을 보관하고 있어요.$B$B켈투자드의 손에 수호자의 지팡이가 들어가지 못하도록 막는 일은 너무나도 중요해요. 솔직히, 전 세계에 재앙이 일어나는 것은 물론이고 어떤 결과가 발생할지 저도 잘 모르겠습니다."
rows["454:1230522518"]="이 정보를 완전히 이해하기 위해서는 먼저 알아두어야 할 사실이 있습니다. 창조주는 자신이 떠난 후에도 오랫동안 이 세계의 발전에 중요한 역할을 해줄 종족을 창조하고자 했습니다. 그래서 장기적으로 아제로스 발전에 중요한 존재가 될 종족을 만들었습니다.$B$B참고로 \"토석인\"이라는 이름은 창조주가 토석인을 만들 때 사용한 구성 물질을 고려하여, 이 종족에게 적절하다고 판단되는 명칭을 직접 붙인 것입니다."
rows["454:1284512776"]="제 가슴은 기발한 디자인으로 2개의 열쇠가 필요해서 잠금을 풀 수 있습니다. 금과 은의 열쇠입니다.$B$B하지만 우리는 그들을 잃게 될 것이 되어 있었습니다. 다음 나가 공격 때 제 열쇠가 사라졌고, 그 다음 날 드립 매크루라가 우리를 공격하고 그를 깊은 곳으로 끌어들였을 때 제 첫 부하가 사라졌습니다.$B$B나가와 마크루라는 열쇠를 가지고 있다고 확신합니다. 저는 둘 다 적이기 때문에 그들을 공유하지 않을 것입니다."
rows["454:40054892"]="수정탑은 자료를 다른 곳으로 전송하는 것처럼 보입니다.$b$b수정탑을 더 자세히 조사해보니 작은 탁자에 붉은, 푸른, 녹색 수정이 일정한 구조를 이룬 듯 배열되어 있습니다.$B$B커다란 원형을 이룬 붉은 수정의 양쪽으로는 푸른 수정과 녹색 수정이 각각 작은 원 모양으로 배열되어 있습니다.$B$B당신은 조심스럽게 눈앞의 광경을 적으며, 이 발견을 매우 흥미로워할 어떤 사람을 떠올립니다."
rows["455:1850156010"]="채굴 현장에 있던 수리공들이 그 괴물을 조립해서 다시 '살려내고' 만 거죠.$B$B그리고 놈은 감사의 표시로, 놈이 말하는 '육체의 저주'에서 우릴 해방하고 있는 거예요.$B$B메카조드의 말에 따르면, 육체라는 건 티탄의 모든 창조물이 나쁜 형태로 변해버린 거래요! 바꿔 말하자면 우리는 원래 로봇 형태로 창조되었는데, 수천 년의 세월 동안 육체를 가진 존재로 변해갔다는 말이죠!$B$B웃기는 소리라는 건 저도 잘 알아요."
rows["455:860443803"]="이곳에서는 오래전 무시무시한 전투가 벌어졌습니다. 우리 네더가드와 은빛 여명회가 어둠의 문에서 끊임없이 밀어닥치는 악마들을 막아 냈습니다.$B$B피와 절망으로 얼룩진 진정 어두운 나날들이었지요...$B$B하지만, 아제로스의 왕국들이 가담했고 그 괴물들을 물리칠 수 있었습니다! 그런데 이제 전투는 반대편에서 벌어지고 있군요...$B$B이제 이곳은 고요하지만 저 지옥 같은 문 너머에 벌어지는 끔찍한 광경과는 너무 대조적이라서 두렵기까지 하답니다."
rows["456:142244775"]="북바다의 가장자리 일인 실버파인 숲에서, 해안에는 버려진 배가 있다. 이 곳의 서쪽에는 당신이 찾는 것이 있다. 너무 멀리 헤엄쳐서 바다는 피곤함으로 당신을 압도할 것이다. 그것은 바다 바닥에 잠금 상자에 놓여 있으며, 당신이 그것을 주장하기를 기다리고 있다.$B$B이렇게 깊은 곳에 잠수해 나갈 때 도움 없이 살아남을 수 있을 것 같아서, 용기를 좀 더 더 강하게 하라. 거품한 틈은 수중이 이 반을 찾는 사람들에게 숨을 쉬게 해줍니다. 현명하게 사용하세요."
rows["456:1784789947"]="우리는 키린 토르 출신입니다. 우리는 다라란에서 이 계곡의 마술을 연구하기 위해 왔습니다. 당신은 그것을 느꼈습니까? 이 땅에서 나오는 힘은 농민조차도 그것을 감지하고 목의 뒷부분에서 털이 올라가는 것을 느낄 정도로 강합니다.$b$b불행히도, 성원을 이끌고 있는 마녀는 특히 계곡의 비밀을 공유하고 싶지 않은 것 같습니다. 그리고...$b$b그녀의 순수한 공포...  "
rows["456:993613536"]="안녕, 귀여운, 난 마하르의 마트론 게야$B$B<할머니 게야가 기침을 하고 있다.>$B$B여기 있는다면 포털이 열렸다고 가정할 수 있을 겁니다. 이 곳의 오크들은 대부분 어렸을 적이나 병에 걸려 어둠의 포털을 기억할 수 없었죠.$B$B<조모 게아가 그녀의 주변 오크들을 가리키고 있다.>$B$B많은 사람들이 고아였거나 곧 고아일 것입니다. 네, 블랙핸드는 다른 방법이 없었을 것입니다. 아픈 사람들을 건강하지 않게하십시오. 강한 사람들만이 살아남을 것입니다."
rows["457:2079514372"]="다른 사람들이 스트라톨메에서 스컬지를 싸우는 것을 보는 것이 좋습니다. 왜냐하면 그들은 가장 강한 곳이기 때문입니다.$B$B안녕하세요. 저는 아우리우스입니다. 한때 은손의 paladin였지만, 다른 사람들처럼 그들의 믿음은 흔들렸어요. 저는 은혜에서 떨어졌습니다. 스컬지는 저를 유혹했고 거의 죽음의 기사로 변했습니다.$B$B마침내 내 위험을 감지하고, 이 예배당으로 도망쳤습니다. 그것은 신성한 장소입니다."
rows["457:80117543"]="좀 더 그럴듯한 변명 거리를 내놓아 보게.$B$B이봐, 누아르. 이런 얘기는 안 하려고 했는데, 어차피 자네도 연루될 테니 얘기하는 게 좋겠군. 막스나르가 루안 숲의 드루이드들에게 총공격을 계획하고 있네. 그는 이곳에서 그 세나리온 드루이드들을 완전히 몰아내고 싶어하지.$B$B우리는 볼더모크 오우거들과 싸우고 있기 때문에 전선이 확대되면 감당할 여력이 없네. 그래서 내가 루안 숲의 아라코아와 휴전 협정을 맺었지.$B$B자네 생각은 어떤가?"
rows["457:837249754"]="망명 전에, 죽음의 날개는 불순종한 자손을 만들고자 노력했습니다. 그들의 자연적인 능력과 능력에 면역이 있을 뿐만 아니라 죽음의 날개의 완전한 통제 아래있을 것입니다.$B$B네파리안은 아버지가 실패한 곳에서는 적어도 부분적으로 성공했을 것 같습니다.$B$B꿈의 모습의 아이세라가 이 혐오스러운 일을 보고 우리에게 행동을 강요했습니다."
rows["458:1068503187"]="우리는 furbolg 종족의 마지막입니다 Timbermaw 부족은 부패하지 않고 있지만 우리는 외부로부터 같은 적대적인 대우를 직면하고 있습니다 대부분의 사람들은 불가능하다고 믿습니다$B$B너무 빨리 적을 만들기 위해 노력하는 사람들에게 분노한 내 형제들은 이제 가까이 다가오는 모든 사람을 공격합니다. 그들은 아무도 믿지 않습니다.$B$B그러나 만일 당신 은 그들과 평화적 인 관계를 맺기 위해 노력 한다면, 그들은 당신 을 동맹자 로 간주 할 수 있을 것 입니다."
rows["458:1266315717"]="수정탑은 자료를 다른 곳으로 전송하는 것처럼 보입니다.$b$b수정탑을 더 자세히 조사해보니 작은 탁자에 노란, 붉은, 녹색 수정이 일정한 구조를 이룬 듯 배열되어 있습니다.$B$B커다란 원형을 이룬 노란 수정의 양쪽으로는 붉은 수정과 녹색 수정이 각각 작은 원 모양으로 배열되어 있습니다.$B$B당신은 조심스럽게 눈앞의 광경을 적으며, 이 발견을 매우 흥미로워할 어떤 사람을 떠올립니다.\010"
rows["458:149466286"]="한때 인간 땅의 금 생산 중심지였던 죽음의 폐광은 이제 데피아즈 결사단이 차지하고 그 어두운 굴을 자신들만의 성소로 만들어 버렸습니다. 소문에 의하면, 이 도적단은 똑똑한 고블린들을 징집해 폐광 바닥에서 뭔가 끔찍한 것을 만드는 걸 돕도록 했다고 합니다만, 그게 무엇인지는 아직 확실하지 않습니다. 들리는 얘기로는, 죽음의 폐광으로 내려가는 길이 조용하고 평온해 보이는 달빛시내 마을에 있다고 하더군요."
rows["459:153691606"]="뭐 원하는 게 있으면 사장 손에 몇 실버쯤 쥐여주지 그래요. 전 정말이지 이 일을 사랑합니다. 하지만 작은 폭탄 같은 스눌크가 이 항구에 다시 배정되게 할 수만 있다면... 그보다 더 좋을 순 없겠죠. 하여간 당신이 제 사업 때문에 여기 오신 건 확실히 아닐 테고. 언더시티로 가는 비행선을 타러 오신 거겠죠? 맞죠? 네, 비행선은 바로 제 뒤에 정박합니다. 참, 스눌크를 보면 제 얘기 좀 잘 해주십쇼. 알았죠?"
rows["459:274897686"]="실바나스 여인은 아제로스의 자연 현상들에 대한 조사를 지시했습니다. 그녀는 비밀스러운 과거로부터 배울 수 있는 위대한 것이 있다고 생각합니다.$B$B어떻게 그런 것들을 배웠는지 모르겠지만, 전 그녀를 완전히 신뢰하고 있어 최선을 다할 것입니다.$B$B저는 현재 썰매,  ⁇ 스 등을 연구하고 있습니다. 모든 생물들은 비슷한 메이크업이지만, 환경이 크게 영향을 미칩니다.$B$B내가 당신의 도움을 통해 생물의 샘플을 수집할 수 있습니다.."
rows["459:361889235"]="악마의 진짜 이름을 알면 그 악마를 능가하는 힘이 주어진다는 소문이 있지.$B$B저주받은 이름의 책에는 지금까지 존재했던 모든 악마들의 이름이 적혀 있다고 하네. 책의 모든 구절을 암기한 베레디스는 굴단의 해골에서 힘을 얻은 일리단에게 필적할 만한 힘의 원천을 발견했지.$B$B일리단의 요청에 따라 베레디스는 현재 자신을 가르친 3명의 스승과 함께 카라보르 폐허에 있는 훈련장을 운영하고 있네."
rows["459:617190057"]="수정탑은 자료를 다른 곳으로 전송하는 것처럼 보입니다.$b$b수정탑을 더 자세히 조사해보니 작은 탁자에 푸른, 노란, 녹색 수정이 일정한 구조를 이룬 듯 배열되어 있습니다.$B$B커다란 원형을 이룬 푸른 수정의 양쪽으로는 노란 수정과 녹색 수정이 각각 작은 원 모양으로 배열되어 있습니다.$B$B당신은 조심스럽게 눈앞의 광경을 적으며, 이 발견을 매우 흥미로워할 어떤 사람을 떠올립니다."
rows["45:1094087344"]="제 자신을 증명할 수 있는 건 제 발톱뿐이에요!"
rows["45:1167087234"]="<감정을 억누르고 마른 침을 삼키는 루스크>$B$B그게... 무슨 말씀이시오?"
rows["45:1179687772"]="어서 정신 차려라, 우리는 계속 나아가야 한다."
rows["45:119303147"]="만약에 제가 숨 안 쉬고 꾹 참으면요, 무슨 색깔 얼굴이 되나요?"
rows["45:1222687907"]="<군마가 전투에 참여하려는 굳은 의지를 보이며 당당하게 서 있습니다.>"
rows["45:1226019198"]="잠자리에 든 나를 방해하는 건 바보들뿐이다."
rows["45:1247895942"]=" ⁇ 스, 래븐하일드 마스터는  ⁇ 스 좋아하지 않는다."
rows["45:1247994088"]="장로 다크코어는 언더시티에서 찾을 수 있네."
rows["45:131454069"]="<이 로봇 고릴라는 큰 피해를 입은 듯합니다.>"
rows["45:1385219691"]="반가워, 친구. 내가 도와줄 일이라도 있어?"
rows["45:1389986925"]="마르코와 탈롤 예타린, 알고 있습니다. 그것은 알고 있습니다."
rows["45:1481261168"]="이번 파티는 정말 최고예요!"
rows["45:1506583114"]="벡터 코일을 파괴할 때가 되었소!"
rows["45:1560138489"]="악마는 뒤틀린 황천에서 왔잖아요. 그런데 악마가 죽으면 어디로 가나요?"
rows["45:1613142006"]="왜 이젠 아웃랜드를 드레노어라고 부르지 않는 거죠?"
rows["45:1622687673"]="검 제작자가 되고 싶으면 물어만 보세요."
rows["45:1641721900"]="룸프한테 말 건 이유 뭐야? 룸프 배고프다. 그게 전부다."
rows["45:1644541604"]="열쇠를 들고 자이로헬기를 타게!"
rows["45:1677453550"]="랩터에 대해서라면 물어보지도 말게. 그냥 물어보지 말게나."
rows["45:1693324358"]="관심이 있다면 환상적인 마법부여의 길을 열어드릴 수 있는데 어떠십니까?"
rows["45:1807828662"]="어떤 상급자나 전문가를 찾으셨나요?"
rows["45:1815714483"]="안녕하십니까. 필요한 게 있으면 말씀하십시오."
rows["45:1822989836"]="이봐요... 내가 편하게 술 좀 마쉬면 어디가 덧나요?"
rows["45:182433611"]="투어를 이끌러 오지 않는다면, 우리를 떠나라."
rows["45:1851985459"]="나루의 가호로 살아남은 당신과 저는 정말 운이 좋았어요!"
rows["45:187989572"]="뭘 쳐다보는 거야, 웃기게 생긴 친구!"
rows["45:1896169035"]="이제 여기서 나갈 수 있을 겁니다. 고맙습니다!"
rows["45:201624965"]="어떤 전투장에서 영광을 누릴 수 있을까요?"
rows["45:2029897570"]="내가 기계공학을 좀 알지. 내가 가르쳐 드릴까?"
rows["45:2044702204"]="예언의 영상이 먹구름이 낀 듯 흐릿하군... 여기 이 강물처럼."
rows["45:2078422275"]="누구시죠? 여기가 어디죠? 아... 힘이 다 빠졌어요..."
rows["45:2092038463"]="자유를 찾으면 폭풍의 복수가 어떤 건지 보여 주겠다!"
rows["45:212656516"]="너는 안에 두려움을 품고 있다, 필멸자여.$b$b난 느낄 수 있다."
rows["45:2129918467"]="음식 얘기를 들으니까 배고파지잖아!"
rows["45:220847435"]="마지막으로 봤을 때 장로 누르겐은 아졸네룹에 있었다네."
rows["45:262402397"]="목소리를 낮추고, 당신의 체취도 숨기시오."
rows["45:264956584"]="어떤 직업 트레이너를 찾고 있나요?"
rows["45:326858766"]="제임스 반 브런트 군사 지구 내곽에 있다."
rows["45:348237047"]="자 쓸데없는 말은 줄이고, 오우거에 집중하기요. 알겠소?"
rows["45:388124899"]="축하합니다. 이제 이중 전문화를 배우셨습니다."
rows["45:393805870"]="유해가 온통 파리와 구더기로 뒤덮여 있습니다."
rows["45:423836724"]="불타는 군단의 악마들이 곳곳에 깔렸소이다... 우리가 이번 일을 해결해야 하오!"
rows["45:471033440"]="<기대에 부푼 얼굴로 당신을 바라보는 죽음경비병 시머>"
rows["45:573851733"]="아, 존슨 말입니까? 어딘가 숨어있다고 들었는데..."
rows["45:722083090"]="마음의 눈을 뜨세요, 방랑자여. 그러면 시작하도록 하겠어요."
rows["45:766670243"]="이곳을 조성하는 데 비용은 얼마나 청구하셨나요?"
rows["45:821144892"]="내 부메랑으로 흠씬 두들겨 패기 전에 냉큼 꺼지라고!"
rows["45:841777"]="넌 누구냐? 우리 부족에게 원하는 게 뭐지?"
rows["460:1083296078"]="뭐 원하는 게 있으면 사장 손에 몇 실버쯤 쥐여주지 그래요. 전 정말이지 이 일을 사랑합니다. 하지만 작은 폭탄 같은 스눌크가 이 항구에 다시 배정되게 할 수만 있다면... 그보다 더 좋을 순 없겠죠. 하여간 당신이 제 사업 때문에 여기 오신 건 확실히 아닐 테고. 언더시티로 가는 비행선을 타러 오신 거겠죠? 맞죠? 네, 비행선은 바로 제 뒤에 정박합니다. 참, 스눌크를 보면 제 얘기 좀 잘 해주십쇼. 알았죠?"
rows["460:1964342950"]="이 자료의 기록과 비교해 여러분의 시간적 참조를 처리할 수 없습니다.$B$B트로그는 아제로스의 다양한 석기 핵 화합물의 일부 성분을 유지하지만 인지력의 손실은 이 변형을 창조자들에게 받아 들일 수 없게 만든다.$B$B트로그는 표준 바이오매스에 따라 번식한다. 기본적으로 타 트로그를 포함한 다른 모든 것을 소비한다. kanibalism는 창조자들에 의해 받아 들일 수 없다고 간주됩니다."
rows["460:262153227"]="사용자의 연대기적 발언을 본 자료의 기록에 비교하여 실행할 수 없습니다. 죄송합니다.$B$B드워프의 정신적인 부분은 아제로스의 돌 구성에 거의 비슷하게 맞추어져 있습니다. 그러나 살아 있는 생물 자원으로 퇴행한 결과, 퇴화한 모형이 주된 부분을 이루고 있습니다. 드워프는 다른 표준 생물에서 흔히 볼 수 있는 방법으로 영양분을 섭취하여 번식합니다.$B$B창조주는 나름대로 가치가 있는 만족스러운 변형체로 드워프를 인식하고 있습니다."
rows["460:491322260"]="그는 아라코아에게 알려진 자들 중에 가장 위대한 영웅이십니다.$B$B고대 시절엔 그가 자신의 발톱으로 스케티스를 건설했다고 전해집니다. 그는 우리의 가장 위대한 용사이자 수호자입니다. 하지만 우리가 루크마르를 존경하지 않자 우리를 떠났습니다.$B$B그래서 우리는 엄청난 힘과 우주에서의 지위를 약속한 새로운 주인을 숭배했지요.$B$B일부에서는 테로크와 루크마르가 같은 인물이라고 말하기도 합니다. 우리가 그에게 등을 돌리자 그는 모습을 감추었습니다."
rows["461:613301199"]="무한의 용군단은 평소와 다르게 치밀한 계획을 꾸몄어요. 그들은 아서스가 스트라솔름을 파괴하게 된 증거들을 숨기려 하고 있어요.$B$B무한의 용군단 요원이 스트라솔름 변두리로 가서, 역병에 오염된 곡식에 환영 마법을 사용해 보통 곡식처럼 보이게 했답니다.$B$B그렇게 숨겨진 곡식을 찾아내 이 마력 분열기를 사용해 주세요. 아서스의 부하들이 역병에 오염된 곡식을 열심히 찾고 있으니, 환영만 사라지면 금방 발견할 거예요."
rows["461:794220507"]="그러니까... 당신이 왕을 해치운 모양이군. 그 얼간이들이 당신을 새 왕으로 삼을 줄 알았다니까, 진짜! 그 멍청이들이 아는 거라고는 힘밖에 없거든.$B$B부하들을 많이 살려 둘수록 공물도 그만큼 많이 들어올 테니, 그것도 괜찮지. 재미있는 과제랄까... 당신이 떠나면 아마 왕 노릇은 계속 못 할 거야. 분명 그 촌뜨기 녀석들 중 하나가 나서서 당신 자리를 차지할 테니까.$B$B참, 혹시 내 열쇠 못 봤나?"
rows["462:120577190"]="이 새로운 힘들을 적용하는 데에 학회가 신중한 것이라고 말할 수 있을 것만 있습니다. 남아있는 몇 가지 기록은 그 곳의 마법사들이 미묘한 중독에 대해 걱정했다는 것을 나타냅니다. 오늘날까지 우리 인종이 겪고 있는 문제입니다.$B$B이러한 억제로 인해 메너르의 마법사들은 아즈하라 여왕과 그녀의 높은 지층의 래키에 대항하여 싸웠습니다. 그들은 점점 더 큰 권력을 원하고 야만적인 포기를 했고, 주의를 기울이고 예술의 점점 더 위험한 응용에 몰입했습니다."
rows["462:311806142"]="결국, 총감독 푸직 갤리윅스가 끼어들었고 그 나머지 독을 이곳 진흙 늪에 있는 자기 탑으로 가져왔소. 독의 불안정한 성질을 연구하기 위해서라고 둘러대고서 말이지. 그는 데피아즈 결사단에게 그 독의 비밀을 알려주는 대가로, 안정적인 독을 대량 공급받기로 결정했지.$B$B데피아즈 결사단에서는 클라벤 몰트웨이크가 잔질의 혼합물이 지닌 화학적 성질을 바꾸는 일을 맡게 되었소."
rows["462:355051812"]="빛의 결사단이 뭐냐고? 음... 우리는 뼛속까지 철저한 은빛십자군의 일원이오. 모두 도덕이나 죄의식, 쓸데없는 인간의 감정 따위에 결코 흔들리지 않소이다."
rows["462:787708438"]="검은바위 산의 불타는 내부를 깎아 만든 이 강대한 요새는 데스윙의 교활한 아들 네파리안이 첨탑의 상층을 점령하고 검은바위 산의 화산 심연에 있는 드워프들과 전쟁을 치르기 전까지는 수세기 동안 사악한 검은무쇠 드워프들이 차지하고 있었습니다. 강력한 불의 정령 라그나로스가 이 드워프들을 이끌고 있다는 사실을 깨달은 네파리안은 그의 적들을 제압하고 검은바위 산 전체를 손아귀에 둘 것을 맹세했습니다."
rows["463:922659574"]="그리고 결국 그들은 울림을 소환하는 데 성공했습니다.$B$B그들은 수많은 영혼을 희생시켜 강화한 속박과 침묵 마법을 사용했지만 울림을 마음대로 부리기는커녕 조금도 통제할 수 없었습니다.$B$B그들은 여러 가지 전략을 세웠지만 모두 실패했습니다. 그 과정에서 소환 의식의 힘이 약해졌고 결국 삽시간에 울림에게 걸린 봉인이 풀렸습니다.$B$B울림에게는 그 짧은 순간이면 충분했습니다."
rows["464:564643515"]="그러고 보니 어제 오후 뭔가 이상한 걸 본 것 같소.$B$B어제 여기서 남동쪽에 있는 고대 트롤 유적지를 달려가고 있었는데... 뭐, 달렸다기보다 팔짝거렸다고 해야 하나... 모래가 워낙 뜨거워서 말이오!$B$B어쨌든 유적지를 지나 뛰어가고 있었는데 그곳에 야영지가 하나 있었소이다. 야영을 하기에는 좀 이상한 장소였지... 그 미친 독수리 하나만 없었어도 좀 더 살펴볼 수 있었는데 말이오."
rows["464:745291041"]="그 바람은 이상한 일이 있었습니다. 그것은 멈추지 않았습니다. 몇 주 동안 땅 위로 날아가며, 점점 더 커지고, 점점 더 줄어들었지만, 멈추지 않았습니다. 그 모든 시간 동안 그 목소리가 계속되었습니다.$B$B외로운 시간 은 내 자신을 진정 하고 내 안을 들여다보는 법을 가르쳐 주었다. 이 는 내 정신 을 유지 하기 위해 해왔고. 그때 에 그 목소리 를 이해 하기 시작 했습니다."
rows["466:1118720486"]="서부 펠론은 빨간색, 녹색, 파란색 결정들을 받아들이고 있습니다.$B$B파이런은 빨간색 결정을 이용해 생성될 수 있는 에너지에 초점을 맞추고 있습니다. 두 가지 효과는 있습니다. 하나는 피해로부터의 보호를 증가시키고 다른 하나는 적의 방어력을 약화시킵니다.$B$B크리스탈 워드는 빨간색과 녹색의 크리스탈을 필요로 합니다.$B$B크리스탈 이이일드는 파란색과 빨간색 크리스탈을 필요로 합니다. 이것은 특정 목표의 갑옷을 낮추는 것입니다."
rows["467:1048395612"]="이 곳의 아름다움은 남들을 다치지 않고 남길 수 있는 곳이지$b$b저는 베이라입니다. 하로우 윈의 사제이자, 추종자의 오른손입니다. 그 사람이 칭호를 거부하거나,$b$b사찰의 6세기 역사에서 이런 일이 벌어진 적이 없습니다. 사장도 교회 내부에서 분열을 일으킬 것이라고 위협했습니다.  "
rows["467:1123510546"]="다음 선택일세.$B$B자네는 정예 부대의 일원인데 동생이 들어오고 싶어하네. 책임감과 충성심은 나무랄 데 없는 동생이지만 정예 부대의 어려운 임무를 수행할 능력이 있는지는 반신반의일세. 어쩌면 동생의 실수로 인해 부대원 전체가 위험에 처할 수도 있을 법하거든. 어쨌든 동생이 정예 부대에 걸맞은 능력을 갖췄는지는 확실치 않지만, 자네 말 한 마디로 동생의 입대가 결정될 것은 분명하네.$B$B자, 자네의 선택을 말해 보게."
rows["467:925672914"]="사실, 목마귀도 아마 아안키라지에서 벌어질 전쟁에 필요한 것들을 쌓는데 유용할 수 있습니다. 그것은 많은 용도로 사용되는데, 예를 들어, 시리투스 태양 아래 뜨거운 날 동안 아이스크림을 만드는 것, 일부 불쾌한 식물의 효과에 대한 연약, 물 아래에서 호흡하는 것, 피부를 단단히 하는 것, 당신을 빨리 만드는 것, 마력을 되찾는 것,$B$B어 ⁇ 든, 내가 거의 $2047w 여기, 그리고 저는 총 $2048w!"
rows["468:1030453995"]="그의 영혼은 충분히 밝으면 우주 창조 이전의 빛의 바다로 다시 올라갈 것입니다.$b$b우리의 감각은 의식의 해안을 휩쓸고 있는 빛의 바다의 희미한 반사일 뿐입니다.$b$b육체의 세계를 떠나 순결을 우회하는 것은 매우 어려운 일이지만 올바른 의식과 올바른 기도로 우리 교회의 사제들은 이 전환을 '연활하게' 할 수 있습니다."
rows["468:1414813362"]="본 정보 저장소에 보관된 자료 내용과 방금 말씀하신 예리한 발언은 분명히 유효한 상관관계가 있습니다.$B$B드워프를 이루는 구성 성분은 아제로스의 돌과 관련이 있습니다. 그러나 극한 환경에 처하면 토석인의 조합 모형 내에서 부작용이 발생해 표준 지하 생물 모형에서 볼 수 있는 기본적인 생물 자원으로 퇴화하게 됩니다.$B$B그러므로 미루어 짐작하고 계셨듯이, 드워프 변형체는 토석인 합성 모형이 퇴화한 결과물입니다."
rows["468:260259188"]="여기 착륙한 이후로 저는 끔찍한 일들을 보았습니다. 이전에는 가장 어두운 악몽만 सता곤 했었지만,$B$B무투오가 주면$B$B그 안개에서 우리로부터 몇 마일 떨어진 곳에  ⁇ 다르라는 유혈성 존재들이 있습니다. 안개에서 돌아온 사람은 아무도 없고 안개가 들어왔을 때 착륙했던 사람은 거의 없습니다."
rows["468:913536568"]="이 탑의 방어력은 매우 약해져 있소. 투자개발회사 순찰대원, 보초, 망꾼은 물론이고 갤리윅스마저 감염되었기 때문에 당신의 공격에 힘없이 무너질 거요.$B$B탑 안으로 들어가시오. 적을 모두 처치하고 나올 때는 잊지 말고 가방에 총감독 푸직 갤리윅스의 머리카락과 남아있는 혼합물을 담아오시오. 그것을 셴툴에게 가져다주시오. 아마도... 그라면 무엇을 해야 할지 알 것이오."
rows["469:259724737"]="조급해 하지 마세요!$B$B<살아 있는 자들은 참을성이 부족하다고 낮은 소리로 불평하는 보들리>$B$B앞서 말했듯이 군주 발타라크의 영혼과 강령술로 소환한 그의 암살자 유령들이 우리를 공격하기 시작했어요. 그때, 우리는 도저히 맞서 싸울 수 있는 상태가 아니었기에 달아나기 시작했죠. 아직도 생생히 기억나는군요. 우리 드루이드 중의 하나인 모르 그레이후프가 그만 미끄러져서 첨탑의 하층부로 떨어지고 말았답니다.$B$B나머지는 당신이 알고 있는 그대로고요."
rows["46:1048726739"]="놈리건은 던 모로 서쪽에 있습니다."
rows["46:1078111597"]="용감한 사람을 싸울 준비가 돼 있는지 확신하십니까?"
rows["46:108832010"]="활포포지 근처에서 제센 파란을 찾아라"
rows["46:1118047178"]="존슨? 이 근처 어딘가에 있을 텐데..."
rows["46:1277370582"]="아, 친구, 난 사냥꾼과 애완동물을 도와주는 것뿐이야."
rows["46:1388930782"]="공학에 대해 가르칠 수 있어"
rows["46:1514136552"]="아, 뭐 하나 날려 버리기에는 딱 좋은 날씨네!"
rows["46:151454633"]="여부가 있겠나. 내 지식을 공유해주겠다."
rows["46:152991993"]="이 하가스의 지식을 구하기 위해 온 건가?"
rows["46:1572257966"]="그가 정말로 가버렸군요. 그렇죠?$b$b느낄... 수 있어요."
rows["46:159365946"]="[서투른 공용어] 축제를 벌일 시간입니다."
rows["46:1754063221"]="빨리 말해, 내가 널 개구리로 만들지"
rows["46:1959137763"]="누가 날 찾아오는 일은 아주 드문데... 무슨 일로 왔나?"
rows["46:1963057548"]="정말 마상 전투를 벌일 준비가 되셨나요?"
rows["46:2069868799"]="내가 지금 수다나 떨고 있게 생겼소?"
rows["46:2082944470"]="어느 전장을 찾고 계십니까?"
rows["46:2088970747"]="지휘관님의 눈을 똑바로 쳐다봐서는 안 되네."
rows["46:300275980"]="공포마의 영혼이 격노하여 요동칩니다."
rows["46:341758858"]="명가에 대해 아시나요? 셴드랄라는요?"
rows["46:425778098"]="이봐, 이게 뭔가? 내가 바쁜 게 보이지 않는 건가?"
rows["46:441232071"]="길니아스를 되찾을 때가 다가왔습니다."
rows["46:46963862"]="오 이런, 오늘 펠릭스 일진이 안 좋군요."
rows["46:473605578"]="발란다르 브라이트스타가 절 구출하라고 그대를 보냈나요?"
rows["46:579484632"]="이건 또 뭐야? 내게 뭘 바라는 것이냐, 피라미야?"
rows["46:62680527"]="뭔가 고쳐야 돼?"
rows["46:647742429"]="대장 용품 때문에 왔나?"
rows["46:657370873"]="이런 열세를 뒤집은 팀은 없었지!"
rows["46:679809933"]="정말 훌륭하군요! 대단합니다! 굉장한 공연이에요!"
rows["46:710186144"]="<고개를 끄덕이는 대모 게야>$B$B내 아들을 알고 있나?"
rows["46:722267027"]="운 좋게도, 지금은 화장실이 비었습니다."
rows["46:785263350"]="$G왕:여왕;님 그론 죽였다! 이제 하늘에서 온 것이랑 싸울 건가?"
rows["46:862423893"]="안녕! 잘 지내? 우린 잘 지내... 그럼. 잘 지내고말고. 안녕!"
rows["46:869049436"]="마을은 무너졌어 우린 그들을 막을 수 없었어"
rows["46:888160798"]="쓰러진 자들의 피가 정의를 갈구하며 울부짖는군요."
rows["46:894238160"]="어떤 기술 전문가를 찾고 계셨나요?"
rows["46:931483795"]="아, 안녕하세요! 난 사라라고 해요. 뭐, 도와드릴 일이라도 있나요?"
rows["46:935960496"]="<바닥 위에서 꾸벅꾸벅 조는 기술자>"
rows["470:148978076"]="저는 위대한 힘의 마법사입니다. 저는 제 하루를 학습과 학습 능력의 보존에 관한 마음과 기억을 연구하는 데 보냈습니다. 밤에는 제 서비스가 필요하다는 것을 알려주는 위대한 목소리가 없었다면 지금도 제 연구를 완성하고 있습니다. 저는 짧은 시간 동안만 여기에 있을 것입니다. 여러분의 재능을 무료로 지우기 위해 제 능력을 제공 할 것입니다. 곧 다시 떠날 것입니다. 그리고 여러분은 다시 한 번 당신이 어떤 선택을 하게 되든에 갇히게 될 것입니다."
rows["470:396757648"]="이 요클들이 먹으려 할 때 내가 얻은 자료에 따르면... 여기 발견되는 모든 괴물들을 죽이는 것은 필요 없을 수도 있습니다.$B$B그 전 왕 은 그 의 뒤를 잇는 왕 을 죽였으며, 그 의 왕 을 대신 하였기 때문 에 그 의 장군 들 은 곧바로 그 새로운 왕 에게 충성 을 맹세 하였다.$B$B누가 알겠어요. 당신이 구원하는 괴물이 당신의 것이 될 수도 있습니다."
rows["470:463639008"]="놈들은 쉬지도 않나?!$B$B고난의 거리에 사는 이들의 미래를 생각한다면 어둠의 의회 놈들이 해골 무덤 사건보다 더 끔찍한 재앙을 일으키기 전에 놈들을 제거해야 하네!$B$B샤트라스 지도층에서 빨리 나설 리는 없기에 우리 같은 고난의 거리의 자유 시민들이 문제를 해결하고자 직접 뛰어든 것일세.$B$B그런데 우리 정찰병의 정체가 탄로나버렸지 뭔가. 우리는 어둠의 의회 요원들을 상대할 테니 그동안 자네는 그 미궁으로 잠입해서 정보를 캐내 오게."
rows["470:616129145"]="나는 한때 황혼의 망치단을 따랐었소. 고대 신들을 환생시키는 데 집착했던 나는 그 몹쓸 짐승 아쿠마이의 힘을 얻기 위해 이 깊은 굴속으로 들어왔지.$B$B수많은 무고한 생명이 제물로 바쳐지는 것을 보고서야 정신을 차리게 되었소.$B$B이제는 덫에서 풀려나 자유의 몸이 되었소! 하지만 고향인 카즈 모단은 너무나 멀리 있군.$B$B용감한 모험가여, 아쿠마이를 처치해 준 답례로 아주 특별한 땅으로 가는 길을 알려주겠소. 원한다면 다르나서스로 이동시켜주리다."
rows["471:1105951008"]="난 드루이드 아냐, 군대를 지휘하러 왔어 말푸리온이 전쟁지역 중간에 나무를 심으려고 했기 이상해 보이지만$b$b하지만, 제가 말씀드릴 것은, 그 불의 원자들에겐 그들의 고향의 한가운데에서 자라는 큰 잎겨드랑이 나무가 있다는 생각보다 더 큰 분노가 없습니다. 그 나무가 완전한 크기로 성장할 때,"
rows["471:1837291956"]="히알 산 전투는 이 시간대 중 가장 잘 지켜진 사건 중 하나입니다. 침입자가 그 결과를 바꾸면 그 영향은 역사의 모든 후속 순간으로 확대됩니다.$B$B아스펙트의 최우선 동료로서 다른 동위 용들보다 시간의 흐름에 더 잘 맞추어 있습니다. 최근 저는 하이달 산 전투를 둘러싼 사건에서 나오는 시간 속의 작은 파동을 감지했습니다. 누군가가 또는 무언가가 이 시간선을 바꾸려고 노력하고 있습니다. 그리고 그들은 멈춰야 합니다."
rows["471:779573611"]="베렌은 나로 하여금 브로크인의 지도 역할을 맡길 것을 권했지만 더 중요한 것은 모든 사람들에게 샤머니즘을 가르치라고 요청했었기 때문이었죠.$B$B우리는 그때부터 일부의 편견을 고려하여 이것이 가장 어려운 제안일 것이라는 것을 알고 있었습니다. 빛.$B$B어쨌든, 그건 내 이야기입니다."
rows["472:1604599242"]="뭐야? 여기가 어디죠? 말도 안 돼! 당신 꼴을 좀 보세요! 그리고 이곳은 정말! 목록에도 없는데! 어휴, 서류가 잔뜩 밀렸을 텐데...$b$b<조그만 공책에 미친 듯이 기록을 하는 고블린>$b$b이봐, 여기 이러고 서서 구경만 할 바에 내 사촌 덜렁발 큐이피를 찾아가 보는 게 어때요? 대도시 중 한 곳에 있을 거요. 그러니까, 오그리마, 스톰윈드, 썬더 블러프, 아이언포지, 언더시티, 다르나서스를 돌보고 있죠. 어서, 어서 가라니까요!"
rows["472:1929122868"]="그러네. 지금으로선 우리 종족에게 그리 많은 걸 가르쳐 줄 열망이 없네만, 그들은 우리를 도와 이 섬에서 생명을 번창하는 한 우릴 도와줄 걸세. 잘라제인이 죽고 나서 공크가 떠났을 때, 그는 만약 다른 로아들이 약속을 충실히 이행하지 않으면 우리에게 어떻게 그에게 연락을 취하는지 말해줬네.$B$B그런 일은 절대 일어나지 않길 바라지만... 만에 하나의 경우라면 우린 세나리온 의회와의 소통 창구를 열 걸세.$B$B<마구 탁탁 소리를 내는 젠타브라>$B$B으, 자네가 그 나이트 엘프의 얼굴을 봤어야 해..."
rows["473:1618668734"]="심문위원은 이 피의 엘프들이 나가란드에서 뭘 하고 있는지 알아내려고 합니다.$B$B의심의 여지없이 어떤 속임수적인 계획이나 조화로 사용...$B$B만약 당신이 우리의 원인을 돕고 이 피의 엘프들을 막으려 한다면, 지금 이 순간 해라에서 북서쪽으로 충돌이 일어나고 있습니다."
rows["473:1675961782"]="대족장님께서는 어둠의 문이 다시 열렸다는 소식을 듣자마자 조언자들을 불러모아 이 용감한 원정대를 조직하셨다네. 몇몇 의원들이 의문을 표하기도 했지만 스랄께서는 우리 종족의 역사를 밝힐 수 있다는 희망을 버리지 않으셨네. 스랄께서는 파괴된 이 세계 어딘가에 오크족에 대한 진실이 숨겨져 있을 거라 믿고 계시네.$B$B나 역시 가장 암울하던 시기에는... 오크족에 대한 진실이 밝혀지지 않으면 어쩌나 걱정을 했었다네."
rows["473:895389332"]="마력의 보물은 고대 구루바시 제국의 유물로서 우리 잔달라 부족이 찾고 있는 물건이지요. 우리에겐 가치가 엄청날 뿐 아니라 고대 제국에서 사용하던 마법의 힘이 잠들어 있다고 믿고 있습니다.$B$B줄구룹에서는 세 가지 보물을 발견하게 될 겁니다. 바로 주화와 장신구, 그리고 고대 전투 장비들이지요. 우리가 원하는 만큼 가져오면 상으로 잔달라 부족이 제작한 물건 중에서 가장 훌륭한 것을 받게 될 겁니다."
rows["474:145123269"]="블라스텐하이머 5000 초특급 대포는 사람을 쏘아 올리는 멋진 장치예요. 거의 용이 날아가는 속도로 탑승자를 발사하는 이 대포는 블라스텐하이머가의 자랑이자 기쁨으로, 그들의 위대한 업적을 전 세계에 알렸죠!$B$B새처럼 자유롭게 하늘로 날아오르고 싶다면 샤트라스에 있는 빛의 정원으로 가서 맥시마 블라스텐하이머를 찾아보세요. 그녀가 벽 너머 작은 연못으로 당신을 발사해 줄 거예요!"
rows["474:481050921"]="그거 안 물어보시면 어쩌나 했어요. 다크문 축제 상품권으로 특별한 선물을 살 수 있답니다.$b$b상품권은 월간 퀘스트를 완료하거나 축제에서 게임을 즐기면 획득할 수 있어요. 월간 퀘스트를 완료하면 축제 상품권을 대부분 모을 수 있지만, 게임을 매일 하면 더 좋은 결과가 있을 거예요.$b$b상품권을 충분히 모으면 다크문 축제에 있는 여러 상인에게 사용할 수 있답니다."
rows["474:583902047"]="이 요새의 아랫부분에서 가공하지 않은 승천의 인장을 습득한 녀석 하나를 찾아야 합니다. 그 물건을 취득하면 요새 위층으로 갈 수 있고, 또한 네파리안의 정예 경비대인 검은손부대의 일원이 되는 첫 걸음이니만큼 하급 생물이 이 물건을 취득하는 것은 크나큰 영광이지요. 그 물건을 찾아 제게 가져오시면 제가 그 물건의 성질을 조사하겠습니다. 인장을 다 조사하면 어떻게 해야 할지 알 수 있을 것입니다."
rows["474:741520401"]="많은 사람들이 이런 술집이나 축제에서 낭만적 인 관계를 추구한다는 것을 이해하지만 알코올은 감각을 둔화시키고 일상 생활의 어려움을 계산하는 것을 미묘하게 만듭니다!$b$b하지만 저는 해결책을 찾았습니다. 많은 시행착오를 겪으면서도, 술의 모든 장점을 가지고 단 한 가지 단점을도 하지 않고, 특별한 장치를 설계했습니다. 이 안경을 착용하면, 모든 사람이 매력적으로 보입니다.$b$b너 포함해 귀여운 내가 할인해"
rows["474:867431552"]="이것은 제가 조사에서 수집한 정보에서 얻은 것입니다.$B$B두 가지 주요 요금 캠프가 있습니다. 요금 캠프: 우리 서쪽 직후의 증오 캠프 및 요금 캠프: 두려움, 바로 남서쪽. 각 캠프에는 레지온 운송수단, 요금 하나 및 여러 마술 보호 탑이 있습니다. 또한, 캠프들은 화염 경호가 포를 탑재하고 있습니다. 마지막으로, 각 캠프에는 핏 로드 감독자가 있습니다.$B$B그럼 문제가 없겠죠$B$B<알트루이스 웃음>"
rows["475:211224069"]="그래. 검은용군단의 여왕이 속임수를 써서 스스로 인간 왕궁의 일원으로 가장했던 거야. 더 끔찍한 사실은 그 용이 현재 스톰윈드의 대영주 볼바르 폴드라곤을 마음대로 조종했다는 거지.$B$B그렇게 터무니없는 군사 전략을 취한 것도 이해가 가기는 한다네. 최근 얼라이언스의 움직임을 보면서 우리 모두 언제 일이 터질지 궁금해 했거든. 이제야 검은용군단이 얼라이언스의 내부부터 무너뜨리려고 했던 거라는 걸 알게 됐지."
rows["475:908395093"]=" ⁇ ,  ⁇ , 그 단서가 충분하지 않나요?$b$B<헤일다라의 목소리는 그녀가 작업하는 철처럼 강하다>$b$B아버지께 대한 존경심을 얻기 쉽다고 생각하지 마세요. 제가 아는 모든 것을, 이 직업과 삶에 대해, 그에게서 배웠어요.$b$B경보와 끈기가 저를 멀리까지 이끌었습니다. 모든 사람들은 그가 죽은 후 그의 유산을 계속할 수 있을지에 의심을 품었지만, 지금은 윈스웨프트 정상회담과 그늘샘에서 임무를 받습니다.$b"
rows["476:1223959266"]="블라스텐하이머 5000 초특급 대포는 한 사람을 쏘아 올리는 멋진 장치예요. 거의 용이 날아가는 속도로 탑승자를 발사하는 이 대포는 블라스텐하이머가의 자랑이자 기쁨으로, 그들의 위대한 업적을 전 세계에 알렸죠!$B$B새처럼 자유롭게 하늘로 날아오르고 싶다면 썬더 블러프 중앙 봉우리의 남쪽 가장자리로 가서 맥시마 블라스텐하이머를 찾아보세요. 그녀가 남쪽으로 멀리 수정 호수로 당신을 발사해 줄 거예요!"
rows["476:1254963716"]="아주 좋은 질문이로군요! 다크문 축제에서는 다양한 물건을 구입할 수 있어요. 음식과 음료가 필요하면 저쪽에 있는 스탬프나 실라니아의 전시장으로 가세요.\010\010좀 더 특이한 물건을 원하시면 라흐라를 찾아가세요. 그녀는 세계 각지에서 온 희귀한 물건을 전문으로 취급하고 있습니다.\010\010그리고 이 근처 어딘가에 돌아다니고 있을 플릭을 마주치면 공이랑 애완용 개구리도 살 수 있을 거예요."
rows["476:1329721488"]="지금 제가 아르헨티나 십자군 전쟁에 대해 하는 일은 의무의 이행으로만 볼 수 있습니다. 지불, 당신이 원한다면. 하이 ⁇ 로드는 저를 리치 왕의 포착에서 해방시키고 구원의 모든 길을 우리에게 제시했습니다. 그렇게 말하면서, 우리의 방법들이 매우 다르다는 것을 이해해야합니다. 나는 Ebon Blade의 기사들과 아르헨티나 십자군 전쟁의 기초를 얼음관 안에 세울 것을 도울 것입니다. 그리고 우리는 길을 갈라집니다. 지불은 완전히 이루어졌습니다.$B$B다른 운명이 우리를 기다리고 있습니다."
rows["476:175716781"]="아주 좋은 질문이군요.$B$B경치 좋은 야외에서 사냥하는 게 좋다면 역병지대, 아즈샤라, 불타는 평원, 악령숲, 실리더스, 여명의 설원에서 정령의 정수를 찾을 수 있어요. 아, 운고로 분화구도요.$B$B위험을 즐기는 편이라면 혈투의 전장으로 가보세요. 그곳에서 다양한 정령의 정수를 아주 많이 찾을 수 있다는 얘기를 들었답니다. 검은바위 나락의 검은무쇠 드워프들이 캐고 있는 정수를 찾아보셔도 좋을 거예요."
rows["476:1781794235"]="너 너한테 봐, 너 큰 거고 강하지 않아?$B$B< ⁇ 투자 웃음>$B$B아마 그럴지도 모르지만, 만약 당신이 당신의 힘을 시험하고 싶다면, 피의 반지는 남그란드와 장갈마르시를 나누는 산에 멀리 북쪽으로 있습니다."
rows["476:587875714"]="내 가장 어두운 시간, 내 존재의 최고상, 내가 실패했다고 믿겠니?$B$B우리를 압도하는 세력의 무단 파괴로부터 도망치면서, 내가 들을 수 있었던 유일한 소리들은 내 군인들의 외침과 내 자신의 심장 박동이었다.$B$B얼마 후, 저는 제 사람들을 구하고 제 명예를 회복할 수 있기를 희망하며 불탄한 땅으로 돌아왔습니다. 대신 저는 잡혀 죽기 까지 박혔습니다.$B$B제 심사위원과 그 후의 고문 과정에서 알게 된 것은 끔찍했습니다."
rows["477:1272055939"]="아탈라이 트롤들이 낳은 신이 이 일에 책임이 있습니다. 우리는 신의 물리적 모습을 파괴하고 성전을 침몰했지만 신은 우리가 예상했던 것보다 훨씬 강했습니다. 부패의 씨앗은 깊게 흘러들어갔고, 모든 것을 왜곡했습니다.$B$B에라니쿠스는 이 부패의 무지한 희생자였고, 우리는 그 힘을 과소평가하는 것 입니다."
rows["477:232127823"]="내 이야기? 부탁하는 건 친절한데요.$B$B오래전, 드레너 행성에서, 그 유적이 현재 아웃랜드로 알려져 있습니다. 드레네이족은 모두 평화롭게 살았지만, 그 다음에는 불타는 군단가 와서, 그들은 그들의 펠 마법을 통해 오크들을 부패시켰다.$B$B다른 선택의 여지가 없었고 살아남기 위해 싸웠지만 이 악성 에너지에 노출된 것은 우리 중 몇몇에게 끔찍한 영향을 미쳤고 시간이 지남에 따라 우리를 나 같은 깨진 사람으로 변시켰습니다.$B$B계속 해야겠어요?"
rows["478:1729567848"]="왜 내려다보죠?$B$B ⁇ 돌이족은 오랜 전통을 가진 유화족이라는 걸 알도록 하겠습니다.$B$B그래, 그건 말이야!$B$B아제로스의 모든 곳이나 그 밖의 곳에는 더 훌륭한 수학자 없습니다!$B$B저는 지금 연습생이라는 타이틀을 가지고 있을지도 모르지만, 제 능력은 그 누구보다 크지 않습니다.$B$B물론, 어쩌면 당신이 단지 나를 돕기 위해 여기에 왔을지도 몰라?$B$B<미미미성  ⁇ 은 자부심을 가지고 웃는다.>"
rows["478:1831327146"]="뭔가요? 이거 무슨 심문 같은 겁니까? 당신은 폴드링 대영주님의 내무부 소속은 아니군요. 그렇지요?$b$b글쎄요, 뭐 저는 숨길 게 없습니다. 일단 제 장부를 살펴보지요. 지난주에 마이너 부관님께 예복을 팔았는데, 조금 이상한 느낌이 들기는 했습니다. 또 다른 게... 비스프 님께서 가죽조끼를 12벌 사가셨는데, 이유는 말해주지 않으셨습니다. 아, 그리고 프라이어 벌링햄이 하드렌치 은신처에 여행 갈 때 쓴다며 수영복을 미리 사러 왔었습니다. 뭐 이 정도군요.$b$b자, 이제 죄송하지만 저는 이만 가보겠습니다. 손님이 오셔서요!"
rows["478:1877940158"]="우리가 알고 있던 모든 것, 우리가 알고 있던 모든 것, 우리가 알고 있을 모든 것$B$B결국 바로프 가족들과의 접촉이 끊어졌고 결국 가계로부터 분리되었습니다. 다른 종들은 무슨 일이 있었는지 몰랐지만, 외치는 소리들, 고문 외치는 소리들만 들었습니다.$B$B루시엔 과 저는 갈 곳 이 없다는 것을 알고서 방 에 숨어들게 되었습니다. 낮 에 학교 는 비교적 조용 할 때, 루시엔 은 음식 과 음료 를 찾아내기 위해 간구 로 밖으로 나갔습니다."
rows["47:1015114221"]="내가 충고 한마디 해 드릴까? 어둠은 가까이하지 않는 게 좋을 것이오."
rows["47:1041256440"]="좋습니다. 이제 재봉술의 여정을 시작해 봅시다."
rows["47:1112236036"]="참 바보로군. 내가 누군지 모르는가?"
rows["47:1118587588"]="조용히 하세요! 스승님이 말씀하시는 중이잖습니까?"
rows["47:1130008452"]="타우렌에게 랩터를 타고 다니는 법을 가르쳐 줄 수는 없어요"
rows["47:1148111271"]="떡대 아냐?! 난 야만스럽게 주먹이나 쓰는 사람과는 말을 나누지 않아요. 어딜 감히!"
rows["47:1156996087"]="나를 도우려고 여기 온 것이 아니라면 나가세요."
rows["47:1215366540"]="하루가 몇 시간만 더 길다면 좋을 텐데..."
rows["47:1263078609"]="머지않아, 우리 공연장은 아제로스 전역에 유명세를 떨칠 겁니다!"
rows["47:1290074870"]="하로우의 끝은 무서운 휴일이지만, 난 그것을 좋아한다!"
rows["47:1292366785"]="챔피언에 맞서 싸울 준비가 돼 있는지 확신하십니까?"
rows["47:1296758919"]="이 변위 장치는 정상적으로 작동하고 있는 듯합니다."
rows["47:1313194444"]="지금 일하느라 바쁜 게 안 보이나? 내 시간을 뺏으려면 그럴듯한 이유를 대야 할 걸세."
rows["47:132178993"]="나 여기서 나가야 해"
rows["47:1461065984"]="아직도 여기 계셨습니까? 어서 마을로 돌아가십시오!"
rows["47:1550872142"]="도달 아문 리다엘 보르모스! 보르모스! 보르모스!"
rows["47:1600148555"]="무기에 대한 기술을 배우고자 하신다면, 제가 알려드릴 수 있습니다."
rows["47:1629273848"]="조용, 아주 조용히. 늑대인간이 사방에 있다."
rows["47:1793572564"]="난 거인들이 지식을 훔치는 것 같아"
rows["47:1857312798"]="절대적인 헌신... 하지만 누가 그것을 판단할 수 있을까요?"
rows["47:1905282424"]="그게 무슨 말이오? 타레사가 위험에 처하기라도 한 것이오?"
rows["47:1918125123"]="화산 바위가 여기 있습니다! 고양이들이 아주 좋아하죠!"
rows["47:1971031032"]="아모드 부부가 우리에게 더 많은 것을 기대하는 것은 무엇일까요?"
rows["47:1993645418"]="너무 슬퍼요오... 과거는 돌이킬 수 없거든요..."
rows["47:1995611605"]="실바나스 여왕님의 뜻에 따라, 적은 파멸할 것입니다."
rows["47:2039561117"]="시간이 흐르면, 이 땅을 되살릴 수 있을 것이다."
rows["47:240345246"]="얼라이언스에서 당신을 필요로 한다. 영웅의 부름에 답하라!"
rows["47:256025897"]="이것만 조금 조절하면... 아, 됐다!"
rows["47:289197688"]="콧구멍 안에서 코딱지가 얼어붙으면 어떻게 돼요?"
rows["47:326615124"]="다 끝났어. 너랑 친구 안 할래!"
rows["47:363108873"]="안녕하시오, 친구여.$b$b숲에서 즐거운 시간을 보내고 있다고 믿소만?"
rows["47:369576646"]="이곳에선 모든 일이 순조롭게 진행되고 있네!"
rows["47:403437127"]="이 폭죽 발사대를 사용하세요. 멋지게 날아갈 겁니다!"
rows["47:438776936"]="계속해서 움직이시오. 여긴 위험한 것이 많으니까."
rows["47:482911356"]="간식거리와 기념품 사시는 것도 잊지 마세요!"
rows["47:487800833"]="뭐하고 있어? 내가 바쁘다는 걸 알 수 없어?"
rows["47:502575812"]="내 도움이 필요하다고? 좋아. 뭘 도와줄까?"
rows["47:511362438"]="안녕하시오, $c|1이여;여;. 서리바람 야영지에는 무슨 일로 오셨소?"
rows["47:541311654"]="<인간 창조술사가 먼 곳을 주시하면서 당당히 서 있습니다.>"
rows["47:567796549"]="<히포그리프는 출발하고 싶어 안달이 난 듯합니다!>"
rows["47:574750946"]="안녕하세요, 여행자님! 제 집에는 무슨 일로 오셨나요?"
rows["47:577999629"]="아, 돌아오셨군요! 뭘 도와드릴까요?"
rows["47:61064589"]="오늘은 당신에게 보여드릴 도안이 한두 가지 있을까요?"
rows["47:665652051"]="실바나스의 승리를 위하여! 이 땅은 우리 것이 되리라."
rows["47:772266536"]="우트가드 성채에서 장로 자르텐을 만날 수 있네."
rows["47:801105162"]="제 복제인간... 아니, 제 쌍둥이 형제를 만나 보셨나요?"
rows["47:91677309"]="부하들이 준비를 마쳤소. 오늘 브리쿨 놈들 피 좀 봅시다!"
rows["47:960362335"]="마이클 가레트? 상업 지구 위쪽에 있다."
rows["47:962511353"]="그대의 동물 친구를 돌봐줄 일손이 필요합니까?"
rows["47:996589461"]="사라져라, 필멸의 존재여! 이곳은 네 종족이 올 만한 곳이 아니다..."
rows["480:1010657172"]="아, 여기 계신다. 도움을 기대하라고 말씀드렸어요. 그래서 좀 더 자세히 들어보세요. 상황이 이렇습니다. 저는 아안키라지에서 임박하는 전쟁에 대비하기 위해 $2055w 보라색 낙엽을 모으는 일을 맡았습니다. 현재까지 우리는 $2054w를 가지고 있습니다.$B$B사실 들판에 가서 꽃을 모으는 것은 당신과 같은 사람들에게 달려 있습니다. 저는 여기 그들이 제대로 유지되고 있고, 실리티드와 다른 어떤 것에 대항하여 사용될 새로운 창의적인 응용을 찾기 위해 필요합니다."
rows["480:1318785079"]="피 엘프들은 어떤 이유로 우리를 막고 싶어$B$B<트레엘로스 관장님께서는 몇 초 더 정신을 차려주기 위해 노력합니다.>$B$B그들은 파손된 중 한 명을 보내서...$B$B그들은 죽었고, 그들은 모두 죽었습니다. 그들은 도망치려고 했습니다. 운이 좋은 사람들은 몰랐습니다.$B$B폭발의 가장자리에 있었을 거야 끔찍한 일이야$B$B<트레엘로스는 절망에 빠지고, 마치 당신이 없는 것처럼 바로 너로 바라보고 있다.>"
rows["480:73004465"]="지식을 찾아가면서 자연생활을 좇아 방랑하는 과정에서 더욱 놀라운 일들을 보며 우리 종족의 그 어떤 이보다 더 이상하고 신기한 종족을 만났네. 나는 고대 칼림도어를 좌우로, 남북으로 가로질러 더 볼 것이 없을 때까지, 지평선 너머로 새로운 땅이 더 나오지 않을 때까지 여행해 다녔네.$B$B그러나... 여행이 끝나감을 느꼈지만 아직도 알지 못하는 것이 많이 있었기에 눈물을 흘렸지.$B$B땅에 쓰러지고, 내 삶이 끝난 그때, 저들이 날 발견했다네."
rows["481:1728273113"]="제가 말했듯이, 우리가 보던 것은 설명에 도전하지 않았습니다.$B$B제 사람들은 어디에도 찾아볼 수 없었지만, 그들의 자리에 로봇과 안드로이드들이 있는 진정한 군대가 있었습니다.$B$B드로이드는 모두 거미처럼 생겼고 우리를 기다리고 있다고 말했어요. 사실, 그들의 이상한 방식으로, 그들은 우리를 알고 있는 것처럼 행동했습니다. 우리는 포위되었고 빠르게 펌프 스테이션의 꼭대기에 끌려갔습니다.$B$B그 곳에서 그들의 지도자를 보았고 생존한 기둥들에 대해 무엇을 했는지도 봤습니다!"
rows["481:1774285886"]="포고꾼 맥주통이 얼마나 큰지 아십니까? 언덕에서 한번 구르기 시작하면 절대 막을 수 없죠. 자비도 후회도 없고, 두려움도 없습니다.$B$B맥주가 사태를 일으킨 것처럼, 행복하게 죽기 딱 좋아요.$B$B맥주통은 언덕 아래 고아원에 부딪혀서 곧 폭발했고, 전 진흙 웅덩이 속으로 입을 벌린 채 뛰어들었습니다. 한 번 생각해 보십시오. 이 얘기가 어떻게 끝나는지는 기억이 잘 안 납니다. 문신이나 구경하실래요?$B$B<바지를 내리는 노친네 더러븐 피트>"
rows["483:1025180679"]="며칠씩 연락이 되지 않아 조사대를 파견해 봤죠. 하지만 그들은 돌아오지 않았어요.$B$B다음 날 다른 조사대를 파견했지만 결과는 마찬가지였고, 공중 정찰대에 속한 비행기도 몇 대 잃었다고요.$B$B결국 저는 도움을 요청하라고 스카이호퍼를 남쪽으로 보내고, 최악의 사태에 대비했지요. 최강의 전력을 갖추고 그곳으로 갈 수 있도록 무기와 방어구, 로봇을 열심히 만들었어요.$B$B그리고 며칠 전 그곳에 갔을 때, 우린 두 눈을 의심할 수밖에 없었어요!"
rows["483:1420366425"]="책장이 누렇게 변해 가는 일기장의 마지막 페이지가 펼쳐진 채로 있습니다.$B$B\"해럴드가 언데드로 변해버려 이제 무슨 일이 벌어질지 모르겠다. 안간힘을 써서 그를 가두고 문을 잠갔다. 열쇠를 감춰뒀는데, 효과가 있었으면 좋겠다...$B$B여기서 빠져나가고 싶지만 그러려면 돈이 든다. 우리 물건은 모두 장롱에 넣어 둔 것 같다... 그러고 보니 해럴드에게도 열쇠가 있지 않나?$B$B그건 일단 쉬고 나서 생각해야겠다. 너무 피곤하다.\""
rows["485:1087965374"]="우리의 가장 새로운 매력, 그리고 당신에게는 아무런 비용도 없이, 이 미니어 탱크, 또는 우리가 똑똑하게 이름 붙인 Tonks,$B$B모든 톤크는 장치들을 갖추고 있고, 적에 대한 특별한 힘을 발휘할 수 있습니다!$B$B친구들과 대전하고, 순항하거나, 아니면 혼란을 일으켜... 선택은 당신 몫이야!"
rows["485:124120517"]="다음 선택은 기다리고 있습니다.$B$B당신은 현재 당신과 전쟁 중인 잔인한 나라에 대한 당신의 의지를 위해 외교 임무에 있습니다. 전쟁은 양쪽에서 비용이 많이 들었습니다.$B$B외교식에서 상대국의 통치자가 당신의 친절한 신부에게 잔혹하게 욕을 당하는 것을 들게 되는데, 당신은 그 통치자가 당신의 귀에서 그것을 말하고자 했다는 것을 확신하지만, 그럼에도 불구하고 그는 당신의 신부 의 명예를 훼손했습니다.$B$B선택해"
rows["485:1305270420"]="우와, 절 우리에서 꺼내 주시다니 너무 감사한 게요 저는 여기 너무너무 오래 있었는데 여기선 양고기 저민 거 일주일은 햇볕에 내다 놓은 것 같은 냄새가 나고 저는 양고기 싫은데 왜냐하면 제가 작았을 때, 말하자면 더 작았을 때, 잠시 양이 됐던 적이 있어서 양이 된다는 게 어떤 기분인지 알고요 누구한테 잡아먹히기 싫고요 특히 고양이 분장을 한 성장 과잉 트롤한테 잡아먹히는 건 더 싫거든요...$b$b<깊이 숨을 몰아쉬는 아쉴리>$b$b제 머리 엉망이죠?"
rows["485:1471303020"]="'살살꾼'은 '무죄의 피'와 '크르톤오스'라는 어두운 주인에게 어떻게 그의 주인에게 진정시켜야 하는지 이야기했습니다.$B$B마침내 짐승은 그의 실험을 끝냈고, 우리는 모든 생명으로부터 지쳐졌고, 우리의 정신은 찢어졌다. 죽음의 달콤한 포옹이 우리 위에 있었고, 우리는 그것을 열리고 환영했습니다. 그러나 그의 무한한 잔인함으로, 가살꾼은 우리를 죽음의 문에서 부활시켰다.$B$B우린 살아있어야 하고 그의 맹렬한 괴물들에게 던져질 거야"
rows["485:1747180599"]="마력의 보물은 우리 잔달라 부족이 찾고 있는 고대 구루바시 제국의 유물입니다. 우리에겐 수집 가치가 엄청날 뿐 아니라 고대 제국에서 사용되던 모조의 가장 강력한 힘이 포함되어 있다고 믿고 있답니다.$B$B아마 줄구룹에서 세 가지 보물을 발견하게 될 텐데, 바로 주화와 장신구, 고대 전투 장비들이랍니다. 우리가 원하는 만큼 가져오면 우리 잔달라 부족이 제작해 온 물건들 중에서 가장 훌륭한 것들로 보상하도록 하겠습니다.$B$B약속하죠!"
rows["485:232062930"]="돌모아는 당신을 쳐다보고 있습니다. 마치 당신의 영혼을 들여다보고 있는 것처럼.$B$B제 딸 테라드라스는 테라모크의 크리스탈 동굴에서 깊은 곳에 숨어 사라진 사랑인 자에타르를 슬퍼하고 있었습니다.$B$B만약 내가 육체의 저주로 고통받는 존재에 신뢰할 이유가 있다면 그날 날 내게 빼앗겼고, 그럼에도 불구하고 네가 거만하고 계속 서있지$B$B언젠가는, 당신은 당신의 유용성을 넘을 것입니다."
rows["485:412890533"]="아즈갈로르 같은 동굴 주인을 죽이는 것은 작은 업적이 아닙니다. 우리가 더 많은 시간을 가졌다면, 당신과 당신의 동료들의 이야기를 듣고 싶습니다. 아치몬드는 우리에게 그 휴식을 주지 않을 것입니다. 그러나 내 스카우트는 이미 우리 캠프 밖에서 레지옹이 엄청난 힘을 축적하고 있다고 보고했습니다. 아치몬드는 세계 나무에 매우 가깝습니다. 우리는 레이디 프라우드무어의 도움으로 대피하고 있습니다. 당신은 즉시 세계 나무로 가야합니다. 우리의 세계의 운명은 여전히 결정되지 않습니다."
rows["486:1334785775"]="여기와 라저힐의 충돌은 맥주 흐름을 망쳤어$b$b도와주고 싶다면, 이럴게요.$b$b매번  ⁇ 을 가져오면, 몇 개의 토큰을 줄게 되는데,  ⁇ 을 더 오래 사용하게 해 줄게 되죠.$b$b하지만 일단 시작하면 내일까지 다시 할 수 없을 겁니다.$b$b이 일을 할 준비가 됐는지 확신하십니까?"
rows["486:233966556"]="우리는 항상 카르가트 블레이드피스트를 기억할 것입니다. 그는 한때 호드에 있었던 것 중 한 명이었습니다. 그는 지금까지 살았던 최고의 전사 중 한 명이었습니다. 얼라이언스도 이것을 인정합니다.$B$B카가스 탐험대는 그의 명예로 지명됐고, 우리는 그의 이름을 지키기로 계획하고 있습니다. 호드 그들은 마땅히 그들의 몫이 될 것입니다.$B$B타우리산에 대항해 전쟁장의 칼이 될 거야"
rows["486:605342571"]="우리 적들이 우리 코 아래에서 숨기려고 할 깊이에 대해 설명하는 것이 현명해지겠죠.$B$B우선, 우리 적은 그림자 협의회입니다. 제가 여러분에게 어떤 일을 맡겼든,$B$B회의 안에서 많은 신조들이 존재하지만 어리석은 사람들로부터 그들의 행동을 숨기기 위해서만$B$B타는 칼, 아구스 웨이크, 가려지는 칼 같은 그룹은 모두 협의회의 도구입니다."
rows["486:964705869"]="토석인이란 창조주가 합성한 종족의 하나로서 아제로스 세계의 초기 모태 종족 중 하나였습니다. 창조주는 이 세계의 기반을 만들 때 자신의 수고를 덜기 위하여 토석인을 창조했습니다.$B$B토석인은 창조주가 다른 세계에서 종족을 퍼뜨릴 때 사용한 지하 생물의 모형을 수정한 것입니다. 이들 원형 종족이 최초로 합성된 이후 다양한 변종이 태어났습니다."
rows["487:1009491376"]="아주 오래전, 엘드레탈라스는 마법의 집합소였고 그 성스러운 전당 안에 사는 자들은 모두 엄청난 힘을 소유하고 있었소. 그중 밀리센트 세레네라는 나이트 엘프가 있었는데, 자연의 힘을 자유자재로 부여해 강력한 물건을 만들어 내는 식물학자였지.$B$B그녀의 업적 중 으뜸가는 것이 바로 풍요의 열매였소... 보호와 성장의 오라를 불어넣은 희귀하고 생기 넘치는 덩굴을 특별히 준비한 달샘에다 길렀는데, 엘드레탈라스 전체가 그 덩굴로 우거졌었소."
rows["487:1811960054"]="합성에서의 지구인의 유일한 이상은 높은 스트레스 환경에서 사용되는 동안 매트릭스 불안정화 경향입니다.$B$B추가: 깊은 땅 조각은 자연스럽게 새로운 매트릭스 디자인에 적합했고 따라서 고 스트레스 환경의 복제 자격을 충족시키지 못했습니다.$B$B이 불안정화는 창조자들에게 지구인의 주요 서비스 순환에 이르기까지 발견되지 않았습니다. 창조자들은 회수 및 재합성에 비해 합성 후 수정 작업을 시작했습니다."
rows["487:2054917607"]="리치 왕의 전염병 의 비밀을 밝혀내기 위해 왕립 약학 협회 는 수년 동안 노력 해 왔으며, 마침내 이 일을 해냈습니다!$B$B역사의 이 전환점에도 불구하고 아직 발견할 일이 너무 많아요.$B$B적어도 저는 스컬지 네크로폴리에 대해 걱정할 필요가 없습니다. 얼라이언스는 그 문제를 다루고 있습니다. 이것은 전염병의 비밀을 깊이 파헤치고 내가 할 수 있는 것을 발견할 충분한 시간을 남겨줍니다."
rows["488:1885468148"]="향상된 인지 능력 덕분에, 전 제 종족 구성원들을 새로운 눈으로 바라볼 수 있게 됐어요. 그들은 자신의 힘을 대부분 신선한 먹이를 사냥하는 데 소모하고 있어요. 그래서 생각했죠. 왜 우리는 그 시간에 가축우리를 만들어 식량 공급 문제를 해결하지 않았을까?$B$B그러다 보니 자연스럽게 인간을 훌륭한 식자재로 쓸 수 있겠다는 생각에 이르렀어요. 빨리 자라는데다 살도 잘 찌고, 훈련을 시키면 수확 시기가 될 때까지 잡일을 시킬 수도 있을 텐데요. 흠..."
rows["488:751402040"]="얼마 전부터 아제로스 곳곳에서 정령이 소란을 일으키고 있다는 보고를 받고 있습니다. 분명히 자연적인 현상이 아님에도 저희는 아직 문제의 정확한 원인을 찾지 못했지요. 몇 가지 이론이 제기되었지만 모두 확실치 않습니다.$B$B정령들의 수상한 움직임에 주의를 기울여야 합니다. 그리고 혹시 유용한 정보를 발견하게 되면 우리 대지 고리회 사절에게 알려 주십시오. 저희 대지 고리회 사절은 아무 대도시에서나 찾을 수 있습니다.$B$B몸조심하십시오. 아무래도 곧 소동이 일어날 것 같습니다."
rows["489:1566029305"]="불타는 평원을 지나갈 때 습격을 받았소. 족히 백 명은 되어 보이는 검은무쇠 드워프들이 달려든 거요! 불타는 평원의 바위, 벽 가릴 것 없이 온갖 틈과 구석에서 기어 나왔소. 우리에게 몰려들어 경비병들은 물론 이번 임무에 우리를 도와 주기로 했던 몇몇 용감한 영웅들도 제압해 버렸소.$B$B단 한 가지 확실했던 건 아주 철저히 준비된 습격이었단 사실이오. 마치 우리가 움직이기도 전에 녀석들이 우리의 행동을 다 꿰뚫어보고 있기라도 한 것처럼..."
rows["489:205308810"]="크리스탈 포커스? 물론 설명할 수 있어요. 왜냐하면, 당신은 그것을 알아낼 수 있는 뇌의 절반밖에 없거든요.$B$B고전화 된 결정 중추는 간단한 과정으로 열 개의 절도 조각과 결합될 수 있으며, 이것은 충전 된 결정 중추를 생성합니다. 이 충전 된 광선은 치료 특성을 가지고 있지만, 더 중요한 것은 귀신으로 인해 사용하는 것입니다.$B$B보시다시피, 화력 집중력은 귀신에게 특별한 힘을 발휘할 수 있도록 사용될 수 있습니다. 만약 당신이 암흑자리를 가지고 있다면, 가크는 그것에 대해 이야기 할 것입니다."
rows["489:744019643"]="시청각 자료 2번의 설명을 시작하겠습니다...$B$B토석인 모형에서 변형된 두 번째 생물은 표준 지하 생물 모형과 비교해 볼 때 바람직한 요소를 많이 지니고 있습니다. 이 변형 생물의 일반 명칭은 \"드워프\"입니다.$B$B드워프는 토석인 고유의 체력을 지니고 있습니다. 어떤 경우 토석인 모형의 지적 처리 능력을 능가하기도 합니다. 그러나 드워프에게는 아제로스의 여러 가지 바위에서 추출한 핵심 성분이 전혀 없습니다."
rows["48:1014014720"]="테라모어 경비병과 함께 훈련을 받으러 온 거군요?"
rows["48:1032965402"]="벌레 같은 것이 감히 라벤홀트 장원에 발을 들여놓다니!"
rows["48:1056684706"]="충고 하나 해 드리지요. 노움은 절대 믿지 마십시오."
rows["48:1075529223"]="당신은 당신의 물건을 괴물에게 신뢰하는 것을 선호합니까?"
rows["48:1162686479"]="전국의 불꽃이 강하고 진다!"
rows["48:1262764425"]="이 보주를 사용하면 낙사나르 상층으로 가는 차원문이 열립니다."
rows["48:1380414180"]="무슨 용건인진 모르겠지만, 빨리해 주세요."
rows["48:1381856506"]="<경호가 지평선을 바라보고 있다.>"
rows["48:1403504623"]="모두 어떻게 된 걸까요? 추워요... 너무... 추워요."
rows["48:1453898350"]="왜 저 스컬지들은 자넬 그냥 돌아다니게 놔두는 거지?"
rows["48:1487757032"]="모두가 술을 마셔야 하지요. 어떤 술을 드릴까요?"
rows["48:1630416960"]="혈투의 전장의 폐허는 페랄라스 중심부에 있습니다."
rows["48:1635724607"]="장로 유라우크는 돌의 전당에서 만날 수 있다네."
rows["48:1651856170"]="그 무엇도 밴시 여왕님의 분노를 막을 수 없네."
rows["48:1660373141"]="관심이 있다면 대장기술을 전수해 드리지요. 어떠십니까?"
rows["48:1697950536"]="비행기가 아름답지 않습니까? 조종해 보고 싶으시지요?"
rows["48:1773985381"]="전 당신께 보석세공에 대해 알려드릴 수 있습니다. 관심 있으신가요?"
rows["48:1838991334"]="저는 에루낙을 따라가겠습니다... 혼자서라도요!"
rows["48:1906364256"]="보주에 있는 표시가 손에 찍힌 낙인과 일치합니다."
rows["48:1931083043"]="갚을게! 갚는다고! 으악! 제발 때리지 마!"
rows["48:1996338864"]="환영합니다. 이 땅의 불꽃을 이미 존중하셨나요?"
rows["48:2084361645"]="<고통 속에서 상처입은 구름몰이골록 점쟁이>"
rows["48:2092830645"]="아눕아락과의 전투 준비가 되셨습니까?"
rows["48:2099420228"]="죽음의 기사여, 우리는 그들에게서 모든 것을 앗아가리라."
rows["48:24624089"]="제가 아투이크입니다. 카마구아 칼루아크 부족 족장이지요."
rows["48:273740423"]="이 성소를 찾아온 자들은 많지만 성한 몸으로 떠난 자는 별로 없지요."
rows["48:284419258"]="제 부엌에 남을 자질이 있으신가요?"
rows["48:315927180"]="뭔가? 바쁜 거 안 보이나?"
rows["48:323937663"]="그 블러드 엘프들과 그들의 무모한 마법 때문에 미치겠어요!"
rows["48:457088179"]="제펠린은 방금 오그리마에 도달했을 것입니다."
rows["48:549826558"]="죄송합니다만 전 마법사에게만 편의를 제공합니다."
rows["48:589635671"]="밤의 안식처에 있는 자들은 진정 어떻게 축제를 즐기는지 아는군!"
rows["48:673616950"]="용건이 뭡니까? 저는 잡담이나 할 만큼 한가하지 않습니다."
rows["48:769471417"]="성궤는 바로 이 폐허 너머에 있소.$b$b어서 갑시다!"
rows["490:1839831993"]="이 평야를 지나다니면서 많은 계절을 보냈고, 큰 짐승을 사냥했고,$B$B오래전, 거대한 늑대는 타우렌의 동맹이었고, 불타는 군단에 맞서 용감하게 싸웠지만, 그는 악마에 의해 야만적으로 부상을 당했고, 그의 육체의 찢어지는 부분이 치유되지 않았습니다.$B$B이제 그는 고통 속에서 평야를 돌아다니며 고통의 종말을 찾고 있습니다."
rows["490:1971852153"]="난 죄수이야!$B$B날과 제 아름다운 젤펠린을 하늘에서 떨어뜨렸어 호드이건 새로운 건 아니잖아$B$B해적들을 폭격하기 위해 날 해프로 주위를 돌게 하고 난 그녀를 이렇게 유지할 수 있는 부품을 갖고 있지$B$B만약 당신이 그들을 도울 수 있도록 결심한다면, 그녀는 $3078w도 채 안 되는 시간 안에 항구에 도착할 것입니다.$B$B내가 말해주는 범죄야!"
rows["490:735273219"]="얼마 전부터 아제로스 곳곳에서 정령이 소란을 일으키고 있다는 보고를 받고 있습니다. 분명히 자연적인 현상이 아님에도 저희는 아직 문제의 정확한 원인을 찾지 못했지요. 몇 가지 이론이 제기되었지만 모두 확실치 않습니다.$B$B정령들의 수상한 움직임에 주의를 기울여야 합니다. 그리고 혹시 유용한 정보를 발견하게 되면 우리 대지 고리회 사절에게 알려 주십시오. 저희 대지 고리회 사절은 아무 대도시에서나 찾을 수 있습니다.$B$B몸조심하십시오. 아무래도 곧 소동이 일어날 것 같습니다."
rows["491:1034790830"]="자신들의 수명이 다하고 난 뒤에도 재산과 땅을 지키기 위해 켈투자드라는 강력한 인간 마법사와 거래를 했던 것 같아요.$B$B<몸서리치는 에바>$B$B그 거래로 인해 강령술 학교가 세워졌죠. 그 학교에서 저주받은 자들의 교단이 생겨났고 그 장소는 그들의 본거지가 되었습니다.$B$B바로브가는 점점 더 허물어져 갔어요.$B$B저택 곳곳에는 암흑의 존재가 자리를 잡기 시작했고 도저히 저택을 유지할 수 없게 되었죠. 너무 역겹기까지 했답니다."
rows["491:1353660501"]="모두 죽었어$B$B어드크블러드는 우리를 뚫고 지나가면서 내가 이해할 수 없는 무언가가 나를 붙잡았어. 말해줘, 네가 그토록 큰 분노를 느꼈어?$B$B<사우르팡의 눈은 잠시 동안 붉은빛을 띠고 있습니다.>$B$B내가 마지막 생존자였어 30 그 비전을 제외하고는 아무것도 기억하지 못해"
rows["492:1927427056"]="슬픈 이야기, 그 이야기도 좀 당황스럽네요$b$b내 사람들은 맥주 맛을 좋아하고 난 예외가 아니네$b$b그래서 내가 구 부드한테 달려갔는데, 그가 내로 갈 수 있는 모든 잔을 내로 내로 내로 내로 내로 내로 내로 갈 수 있는 모든 잔을 내로 내로 내로 내로 내로 갈 수 있는 모든 잔을 내로 내로 내로 내로 갈 수 있는 모든 잔을 내로 내로 내로 내로 내로 갈 수 있는 모든 잔을 내로 내로 내로 내로 갈 수 있는 모든 잔을 내로 내로 내로 내로 갈 수 있는 모든 잔을 내로 내로 내로 내로 내로 갈 수 있는 모든 잔을 내로 내로 내로 내로 갈 수 있는 모든 잔을 내로 내로 내로 내로 갈 수 있는 움직임을 후회하게 되었다$b$b어느 날 밤, 코도도를 떨어뜨릴 만큼의 녹음도 마셨는데, 저는 부드'의 밴드 오'나피트'를  ⁇ 아마에 따라 유혹받았습니다.$b$b내 기억이 나지 않는 마지막은 그  ⁇  안에 갇혀있기 때문이에요"
rows["492:672073494"]="에알디르족 은 단순한 민족 이 아니라 감정 이 되기 때문 이다. 이 나라 들 에서 많은 사람 들 이 공유 하는 믿음 은 스톰윈드 의 의심 을 증가 시키고 있다.$b$b스카데일드 주민들은 우리가 왕의 군대를 환영한다면 어떻게 반응할 것 같습니까? 그들은 침입과 강요로 간주할 것입니다.$b$b아니, 스카데일드의 문제들은 스카데일드에서만 남아있으면 좋겠어."
rows["493:605747427"]="좋아, 거래가 거래가 될거야$b$b우리는 모두  ⁇ 알만으로 들어가서 둘러봤던 밤이었습니다.$b$b나무를 지나가는 바람처럼 울리는 소리를 들릴 때까지는 조용한 곳이었죠. 우리가 알아차리기 전에, 우리는 야만과 애완동물들이 우리 주변에 있을 겁니다. 다음 날, 저는 여기 올라가서,$b$b하루가 지날수록, 죄수들이 죽어가고 있습니다.$b$b이 곳만 알고 있고 더 이상 알고 싶지 않아!"
rows["494:2111130310"]="자연의 모든 것들은 상호 연결된 네트워크에 존재합니다. 생태학입니다. 우리가 그것을 방해하지 않고 관찰하는 것에 주의한다면, 우리 주변의 다양한 생물들 사이의 복잡한 관계를 잘 파악할 수 있을 것입니다.$B$B우리가 그 이해를 한 후에는 모든 생물의 복지를 보장하기 위해 적절한 조치를 취할 수 있습니다. 그 지식이 없으면 개입하면 우리는 확실히 파괴를 일으킬 것입니다.$B$B저는 스포링과  ⁇ 밭주 사이의 복잡한 상호작용을 관찰하기 위해 왔습니다."
rows["494:417970603"]="누가 알겠어, 그게 내가 마지막으로 본 거야$B$B여기서 주제를 벗어나지 않으려고요. 왜냐하면, 제가 이 지휘관에게 맡은 일은 중요하다고 확신하지만, 아이언포지 군대가 아직까지 귀가  ⁇ 어있지 않아야, 우리가 왕국을 지키기엔 너무 무력해"
rows["494:662006589"]="빛의 또 다른 측면일 뿐인 샤머니즘의 길을 가르쳐주었습니다. 바람에 합류하는 것은 오아시스의 물, 내 캠프의 불, 그리고 내가 앉아 있던 땅이었습니다. 모두 말이 있었습니다.$B$B몇 년 동안 그들은 저에게 세상의 요소들과 하나가 되는 것을 가르쳐 주었습니다. 그리고 그들은 제게 하늘의 모든 별들의 세계들, 심지어 이 별들조차도, 이 요소들로 이루어져 있다고 말했습니다.$B$B하지만 나 는 떠나기 위해 충분히 배운 것 이라고 생각 할 때 어느 날 이었습니다."
rows["494:961863890"]="크리스탈 포커스? 물론 설명할 수 있어요. 왜냐하면, 당신은 그것을 알아낼 수 있는 뇌의 절반밖에 없거든요.$B$B고전화 된 결정 중추는 간단한 과정으로 열 개의 절도 조각과 결합될 수 있으며, 이것은 충전 된 결정 중추를 생성합니다. 이 충전 된 광선은 치료 특성을 가지고 있지만, 더 중요한 것은 귀신으로 인해 사용하는 것입니다.$B$B보시다시피, 충전된 초점이 집착된 악마가 특별한 힘을 발휘할 수 있도록 사용될 수 있습니다."
rows["495:1248240420"]="이봐요, 그렇게 재촉하지 마세요! 어쨌든 내 얘기는 거의 끝났어요.$B$B그래서 우리는 모두 그 거대한 방의 한가운데에서 아뮬렛을 놓고 싸우기 시작했답니다. 그 안이 얼마나 난장판이 되었을지 상상이 가시죠? 결국, 아뮬렛은 세 조각으로 부서졌고 그곳에는 제각기 서로 다른 목적으로 온 자들이 있었기에 우리는 주사위를 굴렸답니다.$B$B나머지 이야기는 좀 우울해요. 왜냐하면, 그때 즈음 발타라크의 영혼이 암살자 유령들을 소환하기로 결심했거든요."
rows["495:1855141353"]="이 염색체는 창조자들이 세계를 심는 데 사용하는 합성 매트릭스 중 하나입니다. 각 합성 매트릭스는 창조자의 목표를 달성하기 위해 사용됩니다. 아제로스에 대해, 지저계 존재 매트릭스는 이 변형의 결과로 깊은 지역 모양을 위한 친화성을 가진 더 높은 내구성을 가진 존재를 만들기 위해 수정되었습니다.$B$B지구인들은 창조자들에게 서비스를 제공한 후, 예상치 못한 변칙이 발견되었고, 고 스트레스 환경으로 인해 그들의 합성 매트릭스에 영향을 미쳤다."
rows["495:564765494"]="쉐이디 레스트 인에 대한 알려진 바는 거의 없습니다. 제임스 하이얼의 아내와 아이가 탈출하지 못했을 뿐이죠.$b$b제임스도 끌어내려냈지만 그 이후로 그는 변하지 않았습니다.$b$b우리는 많은 흔적을 가지고 있지만 증거는 많지 않습니다. 우리는 경비원들의 노력과 테라모어 주민들의 경호적인 도움으로 이 끔찍한 범죄를 풀 수 있기를 바랍니다.$b$b조사에 도움을 주고 싶다면 불모의 땅 국경에서 숙소의 잔해를 찾을 수 있습니다."
rows["496:1251222599"]="카타르토스는 나이가 많고, 그 종류 중 가장 오래된 것 중 하나이며, 고대 세계에서 가장 먼저 자라는 씨앗 중 하나입니다. 그는 수세기 동안 수시간 동안 잠에서 깨어납니다. 그럼에도 불구하고 우리는 그를 위해 깨어 있습니다.$b$b그는 어떤 의미에서 우리 아버지입니다. 카타르토스는 우리 원의 첫 번째 드루이드들을 모았고, 그들이 쫓겨나 금지되기 전에 위대한 독수리의 가르침을 공유했습니다. 우리는 그에게 우리의 정체성과 우리의 지혜를 빚지고 있습니다.$b$b"
rows["496:2010442273"]="마라우돈 안에 퍼져 있는 독이 내 정신에 스며들면서 나는 현실에 대한 감각을 잃어 가기 시작했네. 내 홀이 악한 목적에 사용될 것을 두려워한 내 드리아드 자매들은 내게서 홀을 빼앗아 두 조각 낸 다음 이 굴 속에 숨겨 두었지.$B$B그러나 곧 그들도 광기에 희생되었고 아무도 지키고 있지 않던 홀의 두 부분은 바일텅 녀석의 손에 들어가게 되었다네. 바일텅은 그중 하나는 녹시온이라는 사악한 정령에게 맡겼고, 나머지 하나는 지금까지 그가 지니고 있지."
rows["496:2091558331"]="난 죄수이야!$B$B날과 제 아름다운 젤펠린을 하늘에서 떨어뜨렸어 호드이건 새로운 건 아니잖아$B$B해적들을 폭격하기 위해 날 해프로 주위를 돌게 하고 난 그녀를 이렇게 유지할 수 있는 부품을 갖고 있지$B$B난 당신에게 무슨 일이 일어났는지 책임지지 않을거야 하지만 그녀가 떠나기 전에 배에 올라갈 수도 있어$B$B내가 말해주는 범죄야!"
rows["496:258090506"]="그 질문에 대답하려면 먼저 토석인에 대한 자세한 설명이 필요할 것 같습니다.$B$B처리 중...$B$B토석인에게 나타난 부작용을 이해하기 위해서는 먼저 토석인의 설계 목적을 이해하는 것이 중요합니다. 토석인은 지하 생물 모형의 생존 능력을 향상시키고자 하는 창조주의 뜻에 따라 설계된 것이며, 아제로스에 함유된 탄력적인 조성 물질을 지하 생물 모형에 더해 만들었습니다."
rows["496:628774241"]="아, 만세로군요. 여러분이 그 사악한 트롤을 제때에 해치우고 하릴없이 살해될뻔한 저를 구해주시고, 노예가 되어 아제로스를 삼키는 그들의 사악한 음모에 힘을 더할 뻔한 제 순결한 작은 영혼을 지켜주신데다 목숨을 걸고 완전히 죽을뻔한 저를 구해 내신 것을 보고나니 어떤 분이건 어디에서 오신 분이건 저를 여기에서 구해 내신 그 친절함에 보답을 해드려야 할 것이며 보답해드릴 방도를 찾고자 온 힘을 기울일 거예요...$B$B<숨을 깊게 들이마시는 아쉴리.>$B$B여러분이 사탕을 좋아하셨으면 좋겠는데요..."
rows["496:934034742"]="저는 요원 야식스와 함께 자유연합 사령관으로부터 울트리스에 있는 공허의 괴물들을 소탕하라는 명령을 받아서 빈틈없는 공격을 개시할 예정이었습니다. 우리의 최종 목표는 그 지역에서 모든 생명을 집어삼키는 공허의 군주 아르코누스를 처치하고 자유연합 경비초소로 돌아오는 것이었죠.$B$B하지만, 유감스럽게도 우리는 약간 늦게 도착했습니다. 전 살덩이괴물들과 전면전을 벌이던 중 야식스와 떨어지고 말았습니다. 지금 그는 안에 갇혀 적군에게 둘러싸여서 있습니다."
rows["497:1062141291"]="네, 젊은여, 이런 것에 대해 설득할 필요는 없어, 워시프와 나는 많은 역사를 가지고 있지만, 당신의 헌신은 주목된다.$B$B제가 말씀드렸듯이 랜드는 그의 사람들에게 새로운 집을 찾았고, 저는 그 사람들을 따를 수 있는 사람들 중 하나였습니다.$B$B한 전쟁에서 다른 전쟁도 생겨났고, 수많은 전쟁들이 일어났습니다. 블랙록 스파이어와 블랙록 족속의 전투에서 두 아들 모두 죽었습니다."
rows["497:174898598"]="가시덩굴 우리처럼 가시덩굴이 우거진 가시덩굴 구릉은 가시멧돼지의 전통적인 수도였습니다. 가시 덩굴이 얼기설기 퍼진 이 미궁에는 가시멧돼지 귀족들의 충실한 군대는 물론 대사제들 즉, 죽음의 머리교 일족이 살고 있습니다. 최근 이 조잡한 은신처에 기분 나쁜 그림자가 드리워지고 있습니다. 혹한의 암네나르가 이끄는 언데드 스컬지 요원들이 가시멧돼지를 지배하고 그들의 가시 미궁을 언데드 군단의 요새로 만든 것입니다."
rows["497:188184441"]="그래, 거기까지 했었죠.$B$B그래서 우리는 검은바위 첨탑의 상층부 깊숙한 곳까지 잠입했었죠. 그곳의 주인이자 사령관을 목표로 해서요. 바로 드라키사스 말입니다. 왜 그런 현명하지 못한 임무를 맡았느냐고 묻고 싶은 건가요? 당신이 만났던 우리 대장 안시온 하몬 님은 도전을 좋아하는 사람이었답니다.$B$B놀랍게도 발타라크의 뻣뻣하게 굳은 손가락이 마법책을 꺼낼 때까지는 모든 일이 순조롭게 진행되었죠. 하지만, 그 후로 일이 꼬이기 시작했어요.$B$B계속 얘기할 필요가 있을까요? 당신 눈이 가물가물하는 것 같은데..."
rows["497:371050826"]="두 사람이 같은 편에 싸우고 있다는 걸 보여주려면 방법을 찾아야 합니다.$B$B티머머무 포브롤그에 대한 공격은 동맹국으로서 그들을 얻는 기회를 크게 방해할 것이라는 것을 기억해야 합니다.$B$B시작하기에 좋은 곳은 펠우드의 많은 지역에서 발견되는 데드우드 포르볼그입니다. 이 포르볼그들은 템버마우 부족의 적이며, 그들을 죽이는 것은 템버마우족과의 지위를 크게 향상시킬 것입니다."
rows["497:669147180"]="저리 나는 톱니바닥에 떨어지고 있었고, 손잡고 다투고 있었는데, 날카로운 칼만 가지고 있었습니다. 지능 날 구하기 위해서$B$B갑자기 날 날 날 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로$B$B그리고 그들의 콧수염이 트로피로 남아있지만, 난 그 고통에서 감염된 지경을 받았어요."
rows["498:1469061833"]="당신은 Cenarius의 아들, Remulos와 Zaetar에게 물어.$B$B제 아버지 레무루스는 강하고 아름답고 제 삼촌인 자에타르는 매우 현명한 사람이었고, 거의 전혀 지형이 없었습니다.$B$B나랑 여동생들이 태어난 후, 질투로 맹인화된 자에타르는 동생을 능가하려고 노력했습니다. 그는 자신의 결말을 창조한 사람이었습니다."
rows["498:1703742615"]="드디어 이 감옥에서 나를 해방시킬 사람이 있어!$b$b하드레크 대검장이 우리를 보내서 요새에 대한 정보를 수집해$b$b하지만 늙은 마법사는 많은 트릭을 가지고 있어 마법의 요원이 우리를 발견했고,$b$b하드렉으로 돌아가서 조차 회고해야 하지만 먼저 너한테 궁전 문의 잠금을 뽑아줄게"
rows["498:799473294"]="제가 원래부터 더러븐 피트라 불린 건 아닙니다.$B$B젊고 거칠던 한때, 풍만하고 아름다운 벨리라는 처녀한테 멋진 조각을 선물해 깊은 인상을 심어주려고 했단 말입니다.$B$B벨리, 그녀는 뭔가 달라도 다른 여자였죠. 아주 단단하고 크지만, 가운데는 잘록했습니다.$B$B그래서 저는 그녀의 피부처럼 새하얀 석회암 덩어리를 구해다가 다듬고 조각하고, 소위 말하는 걸작을 만들어내는 작업을 시작했습니다. 하지만 비율 계산에 실패했지요, 아시겠습니까? 아주 거대한, 뭐라고 하더라? 엉덩이만 남았지요."
rows["499:1218920877"]="바로 그 봉인석을 파괴해야 우리 부하들을 해방킬 수 있소! 아까도 말했지만 키리스에게는 계획이 있었소.$B$B라젤리크의 하수인에겐 모두 약점이 있소. 봉인석 근처에 있는 육신을 계속 공격하면 하수인들이 분열 상태에 가까워진다오. 바로 그때 봉인석을 공격해야 하오. 하수인들이 다시 깨어나면 아무리 공격해도 소용이 없으니 서둘러서 봉인석을 파괴해야 하오."
rows["499:1321055581"]="$C|1이여;여;, 내 그리핀이 추락해 불타고 있을 때 녀석들이 날 조롱하는 목소리를 들었지.$B$B\"실도르! 너한테선 지독한 냄새가 나!\"라고 소리치더군.$B$B감히 이 실도르 님에게 그런 조롱을 퍼붓다니! 여기서 빠져나가도록 좀 도와줘! 정말로 냄새 나는 게 누군지 똑똑히 가르쳐 줄 수 있도록!"
rows["499:1550029764"]="<의심스러운 눈초리로 당신을 쏘아보다가 얘기를 계속하는 보들리>$B$B결국, 우리는 마법책을 손에 넣었지요. 그때 머리가 둘 달린 우리의 오우거 강령술사 코르모크의 네 개의 눈빛이 이상하게 변했어요. 정말 소름끼치는 장면이었죠. 두 번째 머리에 달린 눈은 꼭 죽은 자의 것과 같았거든요. 소의 눈처럼 말이에요. 상상이 가시죠? 그러다가 그가 갑자기 팔을 뻗어 발타라크가 걸고 있던 아뮬렛을 벗겨내지 뭐예요.$B$B나머지 동료는 난리가 났죠. 우리 중 일부는 아뮬렛을 그대로 두라고 외쳐댔지만... 아뮬렛을 독차지하려는 자들도 있었답니다."
rows["499:2003887595"]="탄력적인 조성 물질이란 종족 합성 시 사용되는 기본 성분을 말합니다. 창조주는 토석인을 합성하고자 일반적인 유기 조성 물질 대신 아제로스 지반을 구성하는 물질을 사용했습니다.$B$B창조주는 아제로스의 조성에 대해 연구한 끝에, 아제로스 본질의 탄력적인 전형이 될 수 있는 고급 생명체를 합성할 수 있다는 이론을 세웠습니다. 창조주는 그 이론에 따라 아제로스에 있는 다양한 바위의 핵심 성분을 기초로 하여 더욱 향상된 생명체를 만들었습니다."
rows["49:1001387862"]="엘룬의 축복을 그대에게... 전투 기술도 잘만 배우면 예술의 경지에 이를 수 있답니다."
