rows["81:1155456404"]="어둠과 철이 결합되면, 이 방법은 소로스의 기사의 길입니다."
rows["81:1169087542"]="찾아 주셔서 감사합니다. 여기서 당신이 원하는 물건을 찾으실 수 있을 거예요... 그 물건이 연금술용품이기만 하다면요."
rows["81:1253682277"]="자네가 불을 끄고 우리 배로 넘어오는 해적들을 막아 줄거지, 그렇지?"
rows["81:1324414891"]="표본 네 개를 넣었습니다. 이제 하나만 더 시험해볼 수 있습니다. 어느 표본을 시험하겠습니까?"
rows["81:1335645044"]="날 구해줘서 고마워요 하지만 페리한테 말해주세요"
rows["81:1346687075"]="한번 둘러보시고 관심 가는 물건이 있는지 확인해 보세요."
rows["81:1375861863"]="안녕하시오. 그래, 알고 있소. 다시 붙잡혔소.$B$B그 일에 대해서는 별로 이야기하고 싶지 않소.$B$B준비는 됐소?"
rows["81:1379669751"]="기계공학을 정말 제대로 아는 게 누군지 알기나 하는 거요? 오그리마로 가서 노그를 찾아보시오!"
rows["81:1400510604"]="도시 밖, 남동쪽에 있는 동쪽 비행선 탑승장을 찾아가게."
rows["81:1446713636"]="경주에서 오신 것을 환영합니다. 머무는 것을 즐기세요. 그리고 모든 돈을 한 곳에 내기 마세요."
rows["81:1455033072"]="언덕마루의 던홀드 요새에 비밀결사대의 보급품을 넣은 금고가 많이 있소이다."
rows["81:1505092041"]="이 달빛의 섬광이 스톰윈드로 이끌 겁니다. 준비가 되면 당신의 초대장을 사용하세요."
rows["81:1526793561"]="돌돌이가 주위를 뛰어다니며 기대에 찬 눈빛으로 당신을 올려다봅니다. 당신을 기억하고 있는 게 틀림없습니다."
rows["81:1537322389"]="오 이런, 누가 여기 왔다니 반갑군! 여긴 지금 미쳐 돌아가고 있어! 평소보다 더!"
rows["81:1559863532"]="용을 사냥하러 왔다면 내가 대접하겠소. 애도의 뜻은 어디로 전해야 하는 거요?"
rows["81:1598857347"]="안녕하십니까. 당신을 심오한 마법의 세계의 좀 더 깊은 곳으로 안내해 드리겠습니다."
rows["81:1601047670"]="브롬 킬리안 만나면, 반짝이는 돌을 캘 수 있어. 군사 지구 내곽에 있다."
rows["81:1640557172"]="검은창 부족이 당당히 하나의 세력으로 거듭나는 날까지, 내가 직접 움직이겠네."
rows["81:1648387337"]="자네가 찾는 시체는 데들로우 웜우드로군. 그는 주로 마을 남쪽 끝에 있다네."
rows["81:1657735409"]="내가 할 수 있는 모든 것을 하고, 신부로 훈련시켜야 해, 그게 네가 여기 온 이유라면."
rows["81:1729297127"]="장로 스타글레이드는 가시덤불 골짜기에 줄구룹으로 들어가는 문밖에서 찾을 수 있을 걸세."
rows["81:1796208630"]="마그니 국왕께서는 우리에게 이번 마상시합에서 승리를 거둬 자랑으로 여길 수 있길 기대하십니다. 우린 지지 않을 겁니다."
rows["81:1809080269"]="세상의 끝 선술집은 고난의 거리의 동쪽 끝에서 찾을 수 있습니다."
rows["81:1818006838"]="타락이 자연의 숲으로 스며들고 있습니다. 어떤 대가를 치르더라도 숲을 지켜야 합니다."
rows["81:1821326269"]="달라란 북서쪽, 마법사 교역소에서 각인사의 성소를 찾을 수 있습니다."
rows["81:1842284053"]="당신 덕분에 계획했던 대로 파랄론 폐허에서 작업을 시작할 수 있게 되었소이다."
rows["81:1967238164"]="샤트라스의 비행 조련사인 뉴트랄은 도시 중심부의 동쪽에서 찾을 수 있을 겁니다."
rows["81:2003493415"]="이곳의 야생 동물들을 보호할 수 있도록 도와주셔서 감사해요. 우리가 그리 늦지 않았길 바랄 뿐입니다."
rows["81:2033654674"]="당신이 찾는 전문가는 바로 둘비로군요. 그녀는 하늘 감시초소의 가운데에서 다른 자들을 훈련하고 있으니 그리로 가 보시기 바랍니다."
rows["81:2047705931"]="이제 자네는 한층 수준 높은 코도 통가죽 무두질을 배울 준비가 된 걸세. 시작하도록 하지..."
rows["81:2087832462"]="예언의 현신이여, 소식을 전해줘서 고맙소이다. 너울소나무 일족은 블러드 엘프 공격에 대비하여 만반의 준비를 할 것이오."
rows["81:347960421"]="좋아요, 당신에게 몇 가지 가르쳐 드리죠. 당신 솜씨나 한번 봅시다. 어쩌면 저를 놀라게 할 정도일지도 모르죠!"
rows["81:393641763"]="보석을 만드는 일은 제 인생의 전부랍니다. 제 열정을 담는 일에 동참하시겠습니까?"
rows["81:495801880"]="미안한데, 친구, 우리가 사용할 수 있는 모든 부품들을 사용했지"
rows["81:572382464"]="수렵의 봉우리에 있는 케르굴 블러드액스가 전쟁노래 협곡으로 가는 걸 도와 줄 겁니다."
rows["81:589434184"]="여행자님, 도시로 가시는 길이라면 중요한 일을 하나 맡아 주셔야겠어요!"
rows["81:646206416"]="달라란 남서쪽, 은빛 자치구 근처에서 왕사과라는 과일 상인을 만날 수 있습니다."
rows["81:656091471"]="<비전 수호병이 고난의 거리의 동쪽 끝 지역을 가리킵니다.>"
rows["81:7232832"]="아버지는 내게 전투 갑옷과 도끼를 물려주셨네. 머지않아 이것들을 사용할 때가 올 걸세."
rows["81:851800780"]="크리스토퍼 드라쿨은... 상업 지구 동쪽에."
rows["81:937378174"]="히드라시스가 더 많은 군인들을 모집한다면,"
rows["81:99154532"]="누가 뭐에서 벗어난 걸 축하한다고요? 흥, 누가 그런 걸 신경 쓰나요? 사탕이나 더 주시죠!"
rows["82:1009669615"]="어둠의 의회는 불타는 군단의 날카로운 감시 속에서 죽음의 괴철로를 운영하고 있네."
rows["82:1147910959"]="가장 황당무계한 꿈보다도 더 믿기 어려운 비밀이 이 전당 안에 숨어 있습니다."
rows["82:1180616977"]="하늘파괴자호가 얼음왕관을 순찰하고 있습니다. 전 지역에서 더 좋은 비행선은 찾아볼 수 없을 겁니다."
rows["82:1210029374"]="살금살금 거리며 숨기나 하고 말이야. 이 고르갈로 말할 것 같으면, 난 숨어다니거나 하지는 않는단 말씀이지."
rows["82:1334279900"]="이 보주를 사용하면 엔킬라 사원으로 가는 차원문이 열립니다."
rows["82:1360266393"]="잘 버텨내야 합니다. 북부감시 요새는 배수의 진이나 다름없으니까요!"
rows["82:1371190397"]="키린 토의 적들을 가둔 감옥인 보랏빛 요새는 달라란의 남동쪽에 있습니다."
rows["82:1425178953"]="이방인이여, 이곳을 떠나세요. 그렇지 않으면 그대도 다른 이들처럼 재가 되어버릴 것입니다."
rows["82:1459398336"]="모든 영혼은 그 종말을 맞이하며 수확자내가 가르쳐 줄게"
rows["82:1463180873"]="고르스는 죽음이 두렵지 않다! 포세이큰이 나를 다시 꼬매줄 거다."
rows["82:1490852403"]="열쇠가 필요하거든 도적 지구의 월터 소레프에게 가보게. 몸조심하고."
rows["82:1670412008"]="이 섬에서 유일하게 남은 멋진 곳이 여기예요... 화산 바로 옆이잖아요!"
rows["82:175459606"]="우리는 몇 주 동안 공부하고 훈련하고 기도했습니다. 아모드 아버지가 더 이상 무엇을 원할까요?"
rows["82:1765547553"]="호드 군대를 먹여 살리는 건 쉬운 일이 아닐세. 할 일이 너무 많아. 자네, 도와줄 시간이 있나?"
rows["82:1797142870"]="좋소. 말해 주겠소. 대신 나를 틸스에게 데려가지 않는다면 말이오!"
rows["82:1873739913"]="어스름 거리 외곽, 달라란 남쪽에 달라란 상업 은행이 있습니다."
rows["82:187797569"]="붉은마루 산맥에 있는 영원고요 호수로 가보시오. 오크들의 보급품이 든 금고가 여러 개 가라앉아 있소."
rows["82:189778435"]="<주변의 소동에 불안한 기색을 보이는 용매>"
rows["82:1995064931"]="시잠비를 만나고 싶으신게로군요.$B$B골짜기 가운데에 있는 높은 건물 안에 있습니다."
rows["82:2028069754"]="<국왕 레인의 지혜와 힘이 비록 체스 말의 모습이지만 밝게 빛납니다.>"
rows["82:253666781"]="<비전 수호병이 고난의 거리의 북동쪽 지역을 가리킵니다.>"
rows["82:271686798"]="이곳이 작고 궁벽하게 느껴질지 몰라도, 헬스크림 님께서 항상 자네를 지켜보고 계신다는 걸 잊지 말게."
rows["82:285766474"]="속삭이는 당신을 선택했습니다 이교도- 내가 듣도록 가르쳐줘서 대답해줄게"
rows["82:381400114"]="저 소리 들리나? 환호하는 소리가 들리냔 말이다, 친구? 다 이 럴크스터에게 응원을 보내고 있단 말이다!"
rows["82:406886296"]="안녕하십니까. 당신을 심오한 마법의 세계 좀 더 깊은 곳으로 안내해 드리겠습니다."
rows["82:422504425"]="칼리사, 아직 살아 있었구나! 숨을 곳을 찾아야 해. 이놈들... 끝이 없어!"
rows["82:43969958"]="엘윈 숲에는 직업 상급자가 꽤 많이 살고 있습니다. 어떤 직업 상급자를 찾으십니까?"
rows["82:458743695"]="멜빵 바지는 위에 달린 멜빵으로 바지를 올려 입는 건데 허리띠 넣는 구멍은 왜 있어요?"
rows["82:505498694"]="자네는 타운카가 아니군. 우리 전사들의 신성한 묘지에 무슨 일로 찾아왔는가?"
rows["82:722194453"]="돌수지자, 용감하고 충성하고 거저하며, 우리의 교리를 따르며 우리를 존중합니다."
rows["82:780579557"]="플러거 그 친구가 맥주통 하나를 너무 채운 모양이야. 곧 터질 것 같아!"
rows["82:846148905"]="데스윙의 더러운 흔적을 심원의 영지에서 깨끗하게 쓸어버리겠다. 황혼의 망치단 하수인들도 함께 말이지."
rows["82:935538041"]="새끼용이나 하급 고룡족과 같은 하급 오색용군단에게서 흔히 찾을 수 있다."
rows["83:116910226"]="제 최신 발명품 보셨어요? 대박을 터뜨릴지도 몰라요... 폭발하지만 않는다면 말이죠."
rows["83:1200801928"]="매일 열심히 훈련을 하게. 솜씨를 완벽하게 다듬은 후에 다시 날 찾아오도록 하고."
rows["83:1271149947"]="여기 광부는 군사 지구 내곽에서 일하지. 이름은 브롬 킬리안이라고 하네."
rows["83:1362444114"]="용기호는 이 항구에서 스톰윈드와 루테란 마을을 오간답니다."
rows["83:1363738538"]="우리 여관에 오신 걸 환영합니다. 저는 시드라고 합니다. 이곳에서 새로운 얼굴을 만나는 건 즐거운 일이 아닐 수 없지요. 뭘 도와드릴까요?"
rows["83:1561836342"]="내 물건은 호드에 판매되지 않습니다. 그것을 좋아하지 않는? Warchief에 그것을!"
rows["83:1663719258"]="포털 마지의 본질을 이해하기 위한 정신적인 면이 없다고 생각합니다."
rows["83:1671096985"]="처녀의 몽상호에 타신 것을 환영하는 바요. 항구까지 안전하고 편안하게 모실 것을 약속드리오."
rows["83:1684280195"]="바위투성이 길만 가득한 망할 동네 같으니! 난 갈 데가 많은데, 여긴 그중 하나가 아니란 말일세."
rows["83:1794608176"]="나와 얘기를 나누려고 오다니 친절하시구려. 어떤 방법으로든 부디 얼라이언스를 돕게나."
rows["83:1824161142"]=" ⁇ 이 ⁇ 이 ⁇ 이 ⁇ 이 ⁇ 의  ⁇ 이 ⁇ 에  ⁇ 이 ⁇ 이 ⁇ 은 ⁇ 의  ⁇ 의 독점에서"
rows["83:1875037487"]="아이고, 혹시 마차 몰 사람이 필요하면 여기 비질한테 시켜만 달라고."
rows["83:1899499649"]="노블가든 시간, 난 이미 많은 알을 찾았어 사냥에 좋은 날씨가 있어"
rows["83:2019773695"]="뭔가를 해 보려면 먼저 그 악마를 가두어 둘 감옥을 만들어야 하오."
rows["83:2027586472"]="군사 지구에서 전사들을 찾을 수 있네. 외곽 쪽을 찾아보게."
rows["83:2039864845"]="아직 야생이 숨 쉬고 있는 나그란드의 평야는 지금까지 제가 경험한 최고의 사냥터를 선사하고 있습니다."
rows["83:2079600599"]="당신은 우리 알도르 사제회에 대한 평판이 충분하지 않거나 사제회에 헌신하지 않는군요."
rows["83:2117208369"]="다르나서스에는 정말로 멋진 곳이 많이 있답니다. 어디로 가시기를 원하십니까?"
rows["83:222968679"]="비밀결사대는 그야말로 오합지졸입니다. 조직력은 물론이고 실력도 형편없는 데다가 게으르기까지 하니..."
rows["83:246002182"]="트롤을 더 많이 처치해야 해! 충분히 처치하면 트롤 두목에게로 통하는 문을 폭파해 주겠어!"
rows["83:24684874"]="붉은협곡 광부조합에서 북동쪽에 있는 명예의 골짜기에서 노그의 작업소를 찾게."
rows["83:32118104"]="지금은 뇌물을 먹이는 중이라 좀 바쁩니다. 나중에 다시 오십시오."
rows["83:35477965"]="후주와 센토가 도와줄 수 있겠군요.$B$B골짜기 가운데에 있는 건물로 가서 만나보십시오."
rows["83:369649199"]="우리는 그 어둠의 집단이 그란골바르 마을에서 무엇을 하고 있는지 알아내야 합니다!"
rows["83:416961299"]="난 떠나지 않겠어요. 가족들에게 내가 여기서 잘 지내고 있으니 가족들도 잘 지내라고 전해 주세요."
rows["83:520698035"]="으스러진 손은 스랄이 있기 전부터 존재했고 스랄이 죽은 후에도 존재할 것이다."
rows["83:525688984"]="여기 주민들은 상업 지구에 관을 쌓아 놓고는 거길 여관이라고 부르더군. 우체통은 그 옆에 있네."
rows["83:542773836"]="이 달빛 광선이 당신을 오그리마로 보내 줄 것이오. 가고 싶다면 당신의 초대장을 사용하시오."
rows["83:564420995"]="선택한 대로 해 주겠다. 스스로 선택했으니 죽고 사는 것은 이제 네게 달렸다."
rows["83:57781838"]="당신 실력은 참으로 현저히 좋아져 가고 있네요. 자, 이제 훈련을 계속해 볼까요?"
rows["83:639802147"]="진정으로 보람된 길을 걷고 싶다면 마법부여사가 되어 보세요!"
rows["83:920106701"]="여기에 있는 바람의 정령이 동요하고 있다. 조심하라... 그대를 순순히 보내지 않을 것이다."
rows["83:940422834"]="이미 이 동굴을 지긋지긋하게 봤습니다. 어서 카라노스로 돌아가고 싶어 못 견디겠군요."
rows["83:959166134"]="당신이 여기 도착했다는 말을 전해 들었습니다. 정말 이상한 존재로군요.$B$B저와 잠깐 이야기를 나누시겠습니까?"
