rows["93:1429761763"]="그런 걸 물어보시다니 제가 전문가라는 호칭을 사용할 만한 사람으로 보이지 않나 보군요. 흠..."
rows["93:1570664470"]="아훈네의 도끼가 드라카리에 최후를 안겨줄 걸세.$B$B내 도끼를 피한 놈이 있다면 자네가 처리해주게!"
rows["93:1594284131"]="오늘 같은 날은 드넓은 초원을 맘껏 거닐고 싶은 맘 간절하지만... 할 일이 있으니 어쩔 수 없지."
rows["93:1649268520"]="우린 대지 고리회에서 예상했던 것보다 훨씬 큰 무언가를 상대하고 있는 것 같군요."
rows["93:1651047220"]="전쟁마법사들이 이리로 오는 길이니 곧 도착할 겁니다.$b$b그들이 오면 내게 말해주십시오."
rows["93:1723400439"]="용군단의 친구이자 동맹이신 분이시여, 그대는 언제나 환영입니다. 여기에서 편히 쉬시기를."
rows["93:1779320834"]="지금보다 더 나아지기 위해 Nat Pagle를 Dustwallow Marsh에서 찾아야 할 거야"
rows["93:1855670317"]="안녕하십니까? 잘 오셨습니다. 전 웃는 데 서투르지만 당신을 손님으로 맞이하게 되어 기쁩니다."
rows["93:1923721993"]="마법부여 기술을 배우고 싶거든, 연금술 실험실 내곽의 라비니아 크로를 찾아가게."
rows["93:1956253464"]="내가 놈들을 처리하지 못할 줄 아셨나요? 작다고 무시하시면 곤란합니다. 어쨌든, 도와 주셔서 고맙습니다."
rows["93:197624857"]="전에 있던 곳으로 돌아가고 싶으세요? 구름의 입맞춤호를 타면 티리스팔 숲으로 우아하게 날아갈 수 있어요."
rows["93:1980609929"]="여기서 볼 일을 서둘러 마치세요! 무역왕이 우리 모두를 버리고 출발하기 전에 당장 항구로 가야 해요!"
rows["93:1987471929"]="누가 당신을 여기로 보냈소? 아직 가르침을 받을 준비가 덜 됐어! 때가 되면 누군가 말해줄 거요."
rows["93:2076361429"]="고구마라도 좀 있으면 모닥불에다가 구워 먹을 텐데... 음, 맛있겠다!"
rows["93:2117213338"]="안세크화의 지혜를 구하러 오셨군요. 썬더 블러프 봉우리 하층에 있는 썬더 블러프 무기점에서 그를 찾아보십시오."
rows["93:21713448"]="어떻게 고블린이 코도한테 짐을 지키게 할 수가 있나? 코도가 10배는 더 크다고!"
rows["93:218260886"]="<당신이 온 줄도 눈치채지 못한 채 똑바로 앞을 보고 꼿꼿이 서 있는 뮬란 그리핀 기수>"
rows["93:247190111"]="어느 전장으로 가시겠습니까? 전투모병관의 위치를 안내해 드리지요."
rows["93:330295186"]="새 무기 사용법을 배우러 온 거겠지? 내가 많이 바쁘니까 빨리 말해 보라고!"
rows["93:43092884"]="이 황무지에서 쉬고 있는 코도에게서는 아주 튼튼한 가죽을 얻을 수 있네."
rows["93:506626694"]="제 말을 믿는 게 좋을 겁니다! 이번에 여러분이 상대할 자는 아서스의 가장 강한 발키르 부관 둘이라고요!"
rows["93:520469285"]="이봐요, 가을 축제 동전을 갖고 계시군요. 제가 가을 축제 상품을 좀 판매하고 있으니 한번 둘러보시지요."
rows["93:570170363"]="블러드후프 마을 북서쪽 구석에 있는 큰 천막 안에서 욘 디프컷을 만나보시는 게 좋겠습니다."
rows["93:628919502"]="라비니아 크로가 이 지역 마법부여사일세. 연금술 실험실 내곽에 그녀의 상점이 있지."
rows["93:784424230"]="폐허가 된 도시 스트라솔름은 역병숲 북쪽에 있는 동부 역병지대에 있습니다."
rows["93:827671077"]="우리 다치면 꿰매주고 붕대 감아줘. 도적 지구 내곽에서."
rows["93:896332434"]="<야스퍼는 응답하지 않습니다. 방을 가득 채우는 유일한 소리 는 숨의 희미한 울림입니다.>"
rows["93:90596598"]="노력하는 건 좋지만, 나한테서 배우려면 경험이 좀 더 있어야겠군! 좀 더 경험을 쌓도록 하게나!"
rows["93:913211694"]="깨진엄니 마을에 잘 왔네. 나는 깨진엄니 트롤의 지도자인 주술사 톤터스크라고 하네."
rows["93:960672234"]="거대한 거북배, 파도의 여행자호가 여기서 용의 안식처에 있는 모아키 항구까지 이동합니다."
rows["940:273652122"]="< 포세이큰은 열광적으로 주둥이를 숙이고, 안경 (그리고 그 뒤에 있는 달팽은 눈) 을 높이 내려  ⁇ 습니다.>$b$b저는 그 조직의 가장 오랜 멤버 중 한 명입니다!$b$b제가 살아있을 때, 저는 수도에서 왕립 역사학자로서 로데론제 마지막 작품인 테레나스 왕의 생애는 어떤 군주도 기록한 최고의 역사로 꼽힌다. 물론 모든 찬사가 나에 속하지 않습니다. 운명 자체가 완벽한 결말을 내놓았습니다. 왕자 왕자, 자신의 아버지의 처형자. 사실상 스스로 쓴 이야기!$b$b아, 죄송합니다, 저는 퇴각합니다. 제가 말씀드렸듯이, 저는 오래전 유서 깊은 리그에 가입했습니다. 저는 거의 모든 탐험에 참여했습니다. 휘스퍼링 포스트 및 그 밖에도. 당신은 얼마나 많은 유적, 유적, 궁전을 복구해야 했는지 믿을 수 없을 것입니다. 그리고 아직 많은 일이 남아 있습니다.$b$b만약 당신의 길은 당신을 속삭이는 숲으로 데려다주면, 크래그스테드에서 있는 제 동료 셀도른을 찾아라. 그는 추가적인 손들을 환영합니다.$b$b"
rows["94:1024122091"]="우린 이 지역을 화재방습을 위해 마련해놨어"
rows["94:1082134857"]="왕을 공격하다니, 다른 오우거들은 바보야! 그래서 내가 아직 살아 있는 거야, 난 똑똑하니까!"
rows["94:1221130864"]="좀 더 수련을 한 뒤에 찾아오세요. 저쪽에 있는 랜달 워스에게 가면 당신을 도와드릴 거예요."
rows["94:1348614399"]="대지모신께 이르는 길은 여러 가지가 있습니다. 언제 어디에서 여행을 하든지 대지모신께서 그대를 지켜주시기를..."
rows["94:1413583641"]="쩝, 내 앞을 가릴 나뭇가지만 있어도 경비병들이 절대 날 보지 못할 텐데..."
rows["94:1501919962"]="우리가 도와주면 식물학자 태릭스가 우리 문제의 해결 방법을 찾을 수 있을 거라 확신합니다."
rows["94:1546984548"]="그 풋내기를 처리해버리자, 에볼. 영원히 말이야. 아즈샤라는 우리 둘 다 있기엔 너무 좁아!"
rows["94:1620508031"]="스톰윈드에 있는 형제들이 말하길 군대에는 절대 가지 말라고 그랬지... 그 말을 듣지 않길 잘한 것 같소!"
rows["94:1676949901"]="이 그리핀은 부상을 당한 듯합니다. 어쩌면 치유 주문이나 응급치료를 통해 그리핀을 일으킬 수 있을지도 모릅니다."
rows["94:1689383735"]="얼라이언스 전투모병관은 보통 도시 중심부의 북동쪽 계단에서 찾을 수 있으니 그리로 가보십시오."
rows["94:1753562879"]="우리는 이 항공선을 보호합니다 오그리마 스트랭글톤밸리에서 그롬골 기지 수용소로"
rows["94:1762311162"]="누가 알겠습니까?$b$b그 분은 이번 발굴 작업에서 핵심적인 인물이셨는데... 하지만 그걸로는 아무것도 알아낼 수 없습니다."
rows["94:1768594513"]="저주받은 기사가 공격하고 있어요! 어서 호드의 동지들을 도와 마을을 지켜주세요!"
rows["94:180041889"]="브론즈비어드 님이 또 사라지셨네! 당신 형님의 반만이라도 닮으셨다면 좋으련만..."
rows["94:1816704712"]="속세의 소유물은 봉우리 하층에 있는 썬더 블러프 은행에서 떨쳐 버리도록 하십시오."
rows["94:1856792687"]="그릇에서 나는 강한 향은 타는 머리와 여러 향료의 혼합물과 같은 냄새입니다."
rows["94:1876444280"]="전투모병관은 왕실에 있지. 알현실 벽 쪽을 돌아가며 찾아보게."
rows["94:195641629"]="아! 음... 안녕하세요. 저는 그냥 여기서 이 조개를 조사해요. 에이! 여기엔 볼 게 없군요!"
rows["94:1985970609"]="우리가 태양너울을 점령했소. 캘타스의 추종자들은 도망치고 있소... 이제 그자들을 편안히 잠들게 해 줄 때라오!"
rows["94:1990401612"]="모든 보상은 전쟁인도자 사르돈 트루슬라이스가 지급한다.$B$B청구서를 보내는 일이 없기를 바란다."
rows["94:2005392641"]="우리는 추호의 의심도 없이 빛을 위해 봉사합니다. 우리의 목적에 대해 좀 더 알고 싶지 않습니까?"
rows["94:2014978535"]="가뭄이 들어 고생을 할지언정 고기는 부족한 법이 없지! 내 물건을 한번 보겠나?"
rows["94:2062738948"]="<전문 기술은 최대 두 개까지 배울 수 있습니다. 다음에서 원하는 항목을 선택하십시오.>"
rows["94:219446269"]="우체통? 도시 중앙 상업 지구 위층에 있는 여관으로 가야겠군. 거기에 우체통이 있지."
rows["94:296240267"]="이곳은 고고학자에게는 꿈만 같은 곳이오!$b$b제대로 발굴 작업을 할 시간이 있으면 얼마나 좋았을까!"
rows["94:31621038"]="다른 날이었으면 이러지 않았겠지만... 오늘은 목도 마르고, 혼자 마시고 싶지도 않군요.$B$B건배!"
rows["94:321949503"]="크레스트마네의 새로운 얼굴 축하해 친구, 길을 가볍게 하기 위해 노래 좀 들려줄래?"
rows["94:342023167"]="프우르는 작은 스포어링들 좋아해. 프우르를 아껴주니까. 그들을 먹지는 않아.$B$B프우르는 나가를 싫어해. 프우르가 놈들 부숴버린다!"
rows["94:388696216"]="이런! 물건이 얼마 남지 않았네요. 저 지독한 고블린은 어쩜 저렇게 오래 버틸 수 있죠?"
rows["94:40030478"]="<보조 기술 훈련을 받을 수 있습니다. 다음에서 원하는 항목을 선택하십시오.>"
rows["94:404160705"]="이곳에 온 뒤로 먹지도 자지도 못했습니다.$b$b난 십자군에 어울리지 않아요..."
rows["94:4087815"]="성스러운 빛이 당신을 인도할 수 없다면 제가 당신을 돕겠습니다. 뭘 도와 드릴까요?"
rows["94:495921225"]="징검다리 거점은 저 같은 와일드해머 드워프를 위한 멋진 곳이지요. 공중에서 이렇게 오랜 시간을 있어본 적이 없어서 말입니다!"
rows["94:497654828"]="저는 당신에게 대장기술을 가르쳐 드릴 수 있고, 필요한 도구도 제공할 수 있습니다.$b$b어떻게 도와드릴까요?"
rows["94:57152162"]="도와줘!$B$B날 여기서 빠져나가게 해주면 줄파락의 두목이 있는 곳으로 통하는 문을 폭파해 버릴 수 있다고!"
rows["94:576162525"]="존재하는 것으로 추정. 상급 오색용혈족이나 오색용만이 이러한 등껍질을 보유할 수 있다."
rows["94:719206482"]="타운카들을 보호하고 작게나마 편의를 제공하는 일은 우리의 의무랍니다."
rows["94:725521205"]="<비전 수호병이 점술가 언덕 건너편의 여관 근처에 있는 우체통을 가리킵니다.>"
rows["94:732192918"]="힘의 골짜기, 하늘탑 남쪽에서 오그리마 은행을 찾아봐."
rows["94:773251674"]="제가 연구에 빠져 있는 동안에는 그대가 덩굴손에게 이 세계를 가르쳐줘야 할 거예요."
rows["94:810585628"]="이런 일을 하겠다고는 절대로 서명하지 않았어요! 소인족에 좀비라니... 호바트 박사님은 제 봉급을 엄청나게 올려주셔야 해요!"
rows["94:924549145"]="암흑갈기 일족과 피비늘 일족의 나가 지도자들에게 현상금이 걸려 있음을 알리는 벽보가 붙어 있습니다."
rows["94:945818520"]="이런... 중요한 일을 하던 중이었는데... 날 방해할 만큼 중요한 일이겠지요? 그래, 무슨 일이십니까?"
rows["94:95271368"]="우리의 마법부여사들은 수정 전당에 보석세공사들 맞은 편에 있습니다. 성스러운 빛이 함께하기를."
rows["94:973191378"]="지금 바쁜 게 안 보이십니까! 이러시면 왕자님이 돌아오시기 전에 공사를 완료하지 못할 겁니다!"
rows["95:1069599719"]="확실하지 않네, 캐리아 헤이스팅스한테 물어봐요.7."
rows["95:1073208949"]="모르고르 대족장님이 용아귀 부족을 다시 한번 영광의 길로 이끄실 것이다!$B$B한심한 너희 호드 따위는 필요 없다."
rows["95:1097350895"]="우리 아름다운 도시의 사제들은 선푸리 스파이어 안에 있습니다."
rows["95:1404441555"]="<타이렌이 멍한 눈동자로 바라봅니다. 타락한 볼드랏실을 정화하는 작업은 이 드루이드에게서 그에 상응하는 무언가를 빼앗아 갔습니다.>"
rows["95:1428001171"]="<버드가 웅크린 채로 몸을 앞뒤로 흔들며 트롤의 언어같이 들리는 말로 중얼댑니다.>"
rows["95:1601205831"]="정말 끝내주는 날 아닙니까? 이날이 가기 전에 불꽃놀이를 더 볼 수 있었으면 정말 좋겠습니다."
rows["95:1638909236"]="거대괴수의 힘에 감춰진 비밀을 밝힐 수만 있다면 과학에 일대 혁신이 일어날 거예요!"
rows["95:1750772733"]="우체통은 힘의 골짜기 중앙에 있는 오그리마 은행 바깥에 있다네."
